#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00

// Configuration register values
#define CONFIG_SINGLE_SHOT 0x8000  // Start a single conversion
#define CONFIG_MUX_AIN0_GND 0x4000 // AIN0, GND
#define CONFIG_PGA_4_096V 0x0200   // +/-4.096V
#define CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define CONFIG_DR_128SPS 0x0060    // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_ACT_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DIS 0x0003 // Disable comparator

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to configure the ADS1115
int configure_ads1115(int i2c_handle)
{
    uint16_t config = CONFIG_SINGLE_SHOT | CONFIG_MUX_AIN0_GND | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_ACT_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DIS;
    char buf[3];

    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register.\n");
        return -1;
    }

    return 0;
}

// Function to read the ADS1115 conversion result
int16_t read_ads1115_conversion(int i2c_handle)
{
    char buf[1];
    char data[2];
    int16_t conversion;

    buf[0] = ADS1115_REG_CONVERSION;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register.\n");
        return -1;
    }

    conversion = (data[0] << 8) | data[1];
    return conversion;
}

// Function to convert the raw ADC value to current in Amperes
float convert_to_amperes(int16_t raw_value)
{
    // Assuming a sensitivity of 10mV/A and a 4.096V range
    // 4.096V / 2 = 2.048V
    // 2.048V / 10mV = 204.8
    // 204.8 / 32768 = 0.0625
    // 0.0625 * raw_value = Amperes
    return (float)raw_value * 0.0625;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle) != 0) {
        fprintf(stderr, "ADS1115 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read conversion result
        int16_t raw_value = read_ads1115_conversion(i2c_handle);
        if (raw_value == -1) {
            fprintf(stderr, "Error reading ADC value.\n");
        } else {
            // Convert to Amperes
            float current = convert_to_amperes(raw_value);

            // Print the current value
            printf("Current: %.4f A\n", current);
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

