#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CE_PIN 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define temperature parameters
#define TEMP_MIN 0.0
#define TEMP_MAX 100.0
#define ADC_MIN 0
#define ADC_MAX 1023

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_flame_sensor();
int read_mcp3008();
float calculate_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int flame_pin;
    int ce_pin;
    int spi_channel;
    int spi_speed;
    int mcp_channel;
    char *log_file_name;
} config_t;

config_t config = {
    FLAME_SENSOR_PIN,
    MCP3008_CE_PIN,
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    "flame_data.csv"
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008();
        float temperature = calculate_temperature(adc_value);

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(config.flame_pin, PI_INPUT);
    gpioSetMode(config.ce_pin, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_flame_sensor() {
    return gpioRead(config.flame_pin);
}

int read_mcp3008() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | config.mcp_channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(config.ce_pin, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(config.ce_pin, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float calculate_temperature(int adc_value) {
    return TEMP_MIN + (TEMP_MAX - TEMP_MIN) * (float)(adc_value - ADC_MIN) / (float)(ADC_MAX - ADC_MIN);
}

int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

