int initialize_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
