    // Configure ADS1115 for single-ended AIN0, 4.096VFSR, 128 SPS
    unsigned char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0x43; // 0b01000011 (Single-ended AIN0, +/-4.096V, 128 SPS)
    config[2] = 0x83; // 0b10000011 (Start single conversion, ALERT/RDY active low, DRDY)

    int result = i2cWriteDevice(i2c_handle, (char *)config, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115: %d\n", result);
        return -1;
    }
    return 0;
}

