    int current_state = gpioRead(FLAME_SENSOR_GPIO);

    if (current_state != last_state) {
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay in microseconds
        current_state = gpioRead(FLAME_SENSOR_GPIO);
        if (current_state != last_state) {
