    return db_value;
}

// Function to calculate the average dB value from two microphones
double calculate_average_db(double db1, double db2) {
    return (db1 + db2) / 2.0;
}

// Function to log the timestamped average dB value to a file
void log_data(double average_db) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return;
        }
    }

    fprintf(log_file, "%s, %.2f dB\n", timestamp, average_db);
    fflush(log_file); // Ensure data is written to the file immediately
}

