    gpioSetMode(MIC1_GPIO, PI_INPUT);
    gpioSetMode(MIC2_GPIO, PI_INPUT);

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read data from microphones
        double db1 = read_microphone(MIC1_GPIO);
        double db2 = read_microphone(MIC2_GPIO);

        // Calculate the average dB value
        double average_db = calculate_average_db(db1, db2);

        // Log the data
        log_data(average_db);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

