#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL_0 0
#define SPI_CHANNEL_1 1
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define RMS_THRESHOLD 500
#define SAMPLE_RATE_MS 1
#define WINDOW_SIZE_MS 100
#define NUM_SAMPLES (WINDOW_SIZE_MS / SAMPLE_RATE_MS)
#define CSV_FILENAME "audio_events.csv"

// Global variables
int spi_handle_0 = -1;
int spi_handle_1 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
double calculate_rms(int16_t *data, int num_samples);
void log_data(FILE *fp, struct timespec ts, double rms1, double rms2);
void control_led(int gpio, int state);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS level
double calculate_rms(int16_t *data, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)data[i] * data[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to CSV file
void log_data(FILE *fp, struct timespec ts, double rms1, double rms2) {
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(fp, "%s.%09ld,%.2f,%.2f\n", timestamp, ts.tv_nsec, rms1, rms2);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to control LED state
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channels
    spi_handle_0 = spiOpen(SPI_CHANNEL_0, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle_0 < 0) {
        fprintf(stderr, "Error: SPI channel 0 open failed\n");
        gpioTerminate();
        return 1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, SPI_SPEED, 0); // CE1, 1MHz, Mode 0
    if (spi_handle_1 < 0) {
        fprintf(stderr, "Error: SPI channel 1 open failed\n");
        spiClose(spi_handle_0);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle_0);
        spiClose(spi_handle_1);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,RMS1,RMS2\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int16_t mic1_data[NUM_SAMPLES];
        int16_t mic2_data[NUM_SAMPLES];
        struct timespec ts;

        // Acquire audio samples
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int mic1_value = read_mcp3008(spi_handle_0, 0);
            int mic2_value = read_mcp3008(spi_handle_1, 0);

            if (mic1_value < 0 || mic2_value < 0) {
                fprintf(stderr, "Error: Failed to read ADC value\n");
                program_running = 0; // Exit loop on error
                break;
            }

            mic1_data[i] = (int16_t)mic1_value;
            mic2_data[i] = (int16_t)mic2_value;
            gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 1ms
        }

        if (!program_running) break; // Exit loop if error occurred

        // Calculate RMS levels
        double rms1 = calculate_rms(mic1_data, NUM_SAMPLES);
        double rms2 = calculate_rms(mic2_data, NUM_SAMPLES);

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log data
        log_data(log_file, ts, rms1, rms2);

        // Check RMS threshold and control LED
        if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
            control_led(LED_GPIO, 1); // Turn LED on
            gpioDelay(500 * 1000);    // Wait for 500ms
            control_led(LED_GPIO, 0); // Turn LED off
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(LED_GPIO, 0); // Turn LED off
    spiClose(spi_handle_0);
    spiClose(spi_handle_1);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

