#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CHANNEL_A0 0x4000 // Single-ended A0
#define ADS1115_MODE_SINGLE 0x8000 // Single-shot mode
#define ADS1115_DR_100SPS 0x0080   // 100 SPS
#define ADS1115_PGA_4_096V 0x0000  // +/-4.096V range
#define LED_GPIO 17
#define CURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int read_adc(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(float current);
float calculate_average();
void control_led(int on);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int led_gpio;
    float current_threshold;
    int buffer_size;
} config_t;

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_adc(int16_t *raw_value) {
    uint8_t config[3];
    uint8_t read_data[2];
    int result;

    // Configure ADS1115 for single-ended A0, 100 SPS, +/-4.096V
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CHANNEL_A0 | ADS1115_MODE_SINGLE | ADS1115_DR_100SPS | ADS1115_PGA_4_096V) >> 8;
    config[2] = (ADS1115_CHANNEL_A0 | ADS1115_MODE_SINGLE | ADS1115_DR_100SPS | ADS1115_PGA_4_096V) & 0xFF;

    result = i2cWriteDevice(i2c_handle, (char *)config, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 100SPS)
    gpioDelay(10); // Wait 10ms

    // Read the conversion register
    config[0] = ADS1115_REG_CONVERT;
    result = i2cWriteDevice(i2c_handle, (char *)config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C (read): %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, (char *)read_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *raw_value = (read_data[0] << 8) | read_data[1];
    return 0;
}

// Convert raw ADC value to current (Amperes)
float convert_to_current(int16_t raw_value) {
    // Assuming a sensitivity of 0.125 mV/A (4.096V range, 32768 counts)
    // and a 12-bit ADC (2^12 = 4096 counts)
    float current = (float)raw_value * 0.125 * 4.096 / 32768.0;
    return current;
}

// Add current reading to circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate the average of the current readings in the buffer
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control the LED (on or off)
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_value;
    float current;
    float average_current;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_adc(&raw_value) == 0) {
            // Convert to current
            current = convert_to_current(raw_value);

            // Add to buffer
            add_to_buffer(current);

            // Calculate average
            average_current = calculate_average();

            // Control LED based on threshold
            if (average_current > CURRENT_THRESHOLD) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }

            printf("Raw: %d, Current: %.4f A, Average Current: %.4f A\n", raw_value, current, average_current);
        } else {
            fprintf(stderr, "Error reading ADC, retrying...\n");
        }

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100);
    }

    // Cleanup
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

