#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A
#define TCS34725_ID 0x12

// Enable Register Values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

// Control Register Values
#define TCS34725_CONTROL_AGAIN_60X 0x03

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init();
int tcs34725_read_raw_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue);
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// TCS34725 Initialization function
int tcs34725_init() {
    int status;

    // Enable power and ALS
    status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN);
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }

    // Set integration time (ATIME) - Adjust as needed
    status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5); // 101ms integration time
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", status);
        return -1;
    }

    // Set gain (AGAIN) - Adjust as needed
    status = i2cWriteByteData(i2c_handle, TCS34725_CONTROL, TCS34725_CONTROL_AGAIN_60X); // 60x gain
    if (status < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %d\n", status);
        return -1;
    }

    return 0;
}

// TCS34725 Read Raw Data function
int tcs34725_read_raw_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    int status;

    status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %d\n", status);
        return -1;
    }
    *clear = (unsigned int)status;

    status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %d\n", status);
        return -1;
    }
    *red = (unsigned int)status;

    status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %d\n", status);
        return -1;
    }
    *green = (unsigned int)status;

    status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", status);
        return -1;
    }
    *blue = (unsigned int)status;

    return 0;
}

// Log Data function
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file);

    return 0;
}

int main() {
    int i2c_bus = 1; // I2C bus 1
    int retries = 0;
    unsigned int clear, red, green, blue;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(i2c_bus, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (sensor_id != 0x44) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", sensor_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw data
        if (tcs34725_read_raw_data(&clear, &red, &green, &blue) == 0) {
            // Log data
            log_data(clear, red, green, blue);
            retries = 0; // Reset retries on successful read
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
            retries++;
            if (retries >= 3) {
                fprintf(stderr, "Too many I2C retries, exiting...\n");
                break;
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

