// Define GPIO pins
#define SPI_CE0 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define MOTOR_ENABLE 17

// Define SPI channel
#define SPI_CHANNEL 0

// Define MCP3008 channel for MLX91211
#define MLX91211_CHANNEL 0

// Define ADC reference voltage
#define ADC_REF_VOLTAGE 3.3

// Define over-current threshold
#define OVER_CURRENT_THRESHOLD 10.0

// Define log file name
#define LOG_FILE "current_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_amperes(int adc_value);
void log_current(float current);
void handle_over_current(float current);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;
    int retries = 3;

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    while (retries > 0) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value
            adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI communication failed. Retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Error: SPI communication failed after multiple retries.\n");
    return -1; // Indicate error
}

// Function to convert ADC value to amperes
float adc_to_amperes(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * ADC_REF_VOLTAGE;
    // Assuming a 10mV/A sensitivity (0.01V/A)
    float current = voltage / 0.01;
    return current;
}

// Function to log current to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to handle over-current condition
void handle_over_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,OVER CURRENT,%.2f\n", timestamp, current);
    fflush(log_file);

    gpioWrite(MOTOR_ENABLE, 0); // Disable motor
    gpioDelay(1000); // Wait 1 second
    gpioWrite(MOTOR_ENABLE, 1); // Re-enable motor
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int adc_value;
    float current;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO17 as output for motor enable
    gpioSetMode(MOTOR_ENABLE, PI_OUTPUT);
    gpioWrite(MOTOR_ENABLE, 1); // Initially enable the motor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and add a header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Current (A)\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(MLX91211_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to amperes
        current = adc_to_amperes(adc_value);

        // Log current
        log_current(current);

        // Check for over-current condition
        if (current > OVER_CURRENT_THRESHOLD) {
            handle_over_current(current);
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(MOTOR_ENABLE, 1); // Ensure motor is enabled on exit
    gpioTerminate();

    printf("Current monitoring stopped.\n");
    return 0;
}

