    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read pressure from the sensor
float read_pressure() {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1.0; // Indicate error
    }

    // Convert raw data to pressure (example conversion, adjust as needed)
    int raw_pressure = (buf[0] << 8) | buf[1];
    float pressure_kPa = (float)raw_pressure * 0.01; // Example scaling

    return pressure_kPa;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp(char* timestamp_buffer) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp_buffer, 32, "%Y-%m-%dT%H:%M:%SZ", info);
    return timestamp_buffer;
}

