#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_ADDR 0x48
#define PRESSURE_CHANNEL 0
#define TEMPERATURE_CHANNEL 1
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0
#define SENT_START_BIT 0x01
#define SENT_DATA_BITS 12
#define SENT_FRAME_SIZE 16
#define SENT_CLOCK_FREQ 1000000 // 1 MHz
#define SENT_TIMEOUT_US 1000000 // 1 second

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sent_frame(uint8_t *frame, int max_retries);
int validate_sent_frame(const uint8_t *frame);
int16_t decode_pressure(const uint8_t *frame);
float decode_temperature(const uint8_t *frame);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(float raw_temperature);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for SENT frame
typedef struct {
    uint8_t data[SENT_FRAME_SIZE];
} sent_frame_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sent_frame_t frame;
        int16_t raw_pressure;
        float pressure_kPa;
        float temperature_C;

        // Read SENT frame
        if (read_sent_frame((uint8_t *)frame.data, 3) != 0) {
            fprintf(stderr, "Failed to read SENT frame\n");
            continue; // Retry
        }

        // Validate SENT frame
        if (validate_sent_frame((uint8_t *)frame.data) != 0) {
            fprintf(stderr, "Invalid SENT frame\n");
            continue; // Retry
        }

        // Decode pressure and temperature
        raw_pressure = decode_pressure((uint8_t *)frame.data);
        temperature_C = decode_temperature((uint8_t *)frame.data);

        // Convert pressure and temperature
        pressure_kPa = convert_pressure(raw_pressure);
        temperature_C = convert_temperature(temperature_C);

        // Control LED
        control_led(pressure_kPa);

        // Print pressure and temperature
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure_kPa, temperature_C);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read SENT frame from ADS1115
int read_sent_frame(uint8_t *frame, int max_retries) {
    int retries = 0;
    int bytes_read;
    uint8_t reg = 0x00; // Register to read from (AIN0)

    while (retries < max_retries) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, reg, (char *)frame, SENT_FRAME_SIZE);
        if (bytes_read == SENT_FRAME_SIZE) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, bytes_read);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }
    return -1; // Failure after retries
}

// Validate SENT frame
int validate_sent_frame(const uint8_t *frame) {
    // Check for start bit
    if ((frame[0] & 0x80) != 0x80) {
        fprintf(stderr, "Start bit missing\n");
        return -1;
    }

    // Check for valid data bits (example: check if all bits are 0 or 1)
    for (int i = 1; i < SENT_FRAME_SIZE; i++) {
        if ((frame[i] & 0xF0) != 0xF0 && (frame[i] & 0x0F) != 0x00) {
            fprintf(stderr, "Invalid data bits\n");
            return -1;
        }
    }

    return 0;
}

// Decode pressure from SENT frame
int16_t decode_pressure(const uint8_t *frame) {
    // Assuming pressure data is in the first 12 bits of the frame
    return ((int16_t)frame[1] << 4) | (frame[2] >> 4);
}

// Decode temperature from SENT frame
float decode_temperature(const uint8_t *frame) {
    // Assuming temperature data is in the last 4 bits of the frame
    return (float)(frame[15] & 0x0F);
}

// Convert raw pressure to kPa (example conversion)
float convert_pressure(int16_t raw_pressure) {
    // Replace with actual conversion formula from MLX90834 datasheet
    return (float)raw_pressure * 0.1; // Example scaling
}

// Convert raw temperature to Celsius (example conversion)
float convert_temperature(float raw_temperature) {
    // Replace with actual conversion formula from MLX90834 datasheet
    return (float)raw_temperature * 10.0; // Example scaling
}

// Control LED based on pressure
void control_led(float pressure_kPa) {
    if (pressure_kPa > PRESSURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received SIGINT, exiting...\n");
}

// Cleanup resources
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn LED off
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

