#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define OVERCURRENT_THRESHOLD 10.0 // Amps
#define SHUTDOWN_GPIO 27
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void shutdown_motor();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to current (Amps)
float adc_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // You'll need to calibrate this based on your sensor and circuit
    // This is a placeholder; replace with your actual calibration data
    float current = (float)adc_value * 0.01; // Example: 0.01 Amps per ADC unit
    return current;
}

// Function to log current reading with timestamp
void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, current);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to shut down the motor
void shutdown_motor() {
    gpioWrite(SHUTDOWN_GPIO, 1); // Set GPIO HIGH
    time_sleep(1.0); // Wait 1 second
    gpioWrite(SHUTDOWN_GPIO, 0); // Set GPIO LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for shutdown signal
    gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT);
    gpioWrite(SHUTDOWN_GPIO, 0); // Initialize to LOW

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            time_sleep(0.1); // Wait before retrying
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log current reading
        log_current(current);

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            fprintf(stderr, "OVERCURRENT detected! Current: %.2f A\n", current);
            fprintf(log_file, "OVERCURRENT detected! Current: %.2f A\n", current);
            fflush(log_file);
            shutdown_motor();
            break; // Exit loop after shutdown
        }

        // Wait 100 milliseconds
        time_sleep(0.1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioWrite(SHUTDOWN_GPIO, 0); // Ensure GPIO is LOW
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

