#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define SENSOR_SENSITIVITY 0.01 // kPa/V (Example value, calibrate your sensor)
#define SENSOR_OFFSET 0.0 // kPa (Example value, calibrate your sensor)
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int16_t read_pressure_raw();
float convert_to_pressure(int16_t raw_value);
int validate_pressure(float pressure);
char* get_iso8601_timestamp();
int log_pressure_data(float pressure, char* timestamp);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure ADS1115 for single-ended AIN0, 4.096VFS, 128 SPS
int configure_ads1115() {
    // Configuration register value:
    // Single-ended AIN0, +/-4.096V, 128 SPS, Disable comparator, Disable FIFO
    uint16_t config_value = 0x4083; //0b0100000010000011

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read raw pressure value from ADS1115
int16_t read_pressure_raw() {
    char buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    return raw_value;
}

// Convert raw ADC value to pressure in kPa
float convert_to_pressure(int16_t raw_value) {
    float voltage = (float)raw_value * ADS1115_FULL_SCALE_VOLTAGE / 32768.0; // 16-bit ADC
    float pressure = voltage * SENSOR_SENSITIVITY + SENSOR_OFFSET;
    return pressure;
}

// Validate pressure reading
int validate_pressure(float pressure) {
    if (pressure >= 0.0 && pressure <= 100.0) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log pressure data to file
int log_pressure_data(float pressure, char* timestamp) {
    log_file = fopen(LOG_FILE, "a");
