#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity, float temperature);
void signal_handler(int signal);

// Function to read data from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3208
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3208

    if (spi_result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", spi_result);
        return -1;
    }

    // Extract ADC value (12 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A datasheet formula
    float humidity = ((float)adc_value / 16383.0) * 100.0;
    return humidity;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    // HIH-4602-A datasheet formula
    float temperature = ((float)adc_value / 16383.0) * 165.0 - 40.0;
    return temperature;
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

// Function to send email alert
void send_email_alert(float humidity, float temperature) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Humidity Alert\n\nHumidity: %.2f%%, Temperature: %.2f°C\nTimestamp: %s\" | ssmtp recipient@example.com", humidity, temperature, timestamp);

    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error: Email alert failed (system() returned %d)\n", result);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3208 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (returned %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3208(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity, temperature);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Humidity monitoring stopped.\n");
    return 0;
}

