#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3208_CHANNEL 0
#define VREF 3.3
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define LOG_FILE "temperature_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float adc_to_celsius(int adc_value);
void log_temperature(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (adc_value * VREF) / 4095.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    int adc_value;
    float temperature;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to Celsius
        temperature = adc_to_celsius(adc_value);

        // Validate temperature
        if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
            fprintf(stderr, "Error: Temperature out of range (%.2f°C)\n", temperature);
            fprintf(log_file, "Error: Temperature out of range (%.2f°C)\n", temperature);
            fflush(log_file);
            continue; // Skip to the next iteration
        }

        // Log temperature
        log_temperature(temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Close SPI device and log file
    spiClose(spi_handle);
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

