int read_sensor_data(uint8_t *data) {
    int result = i2cWriteByte(i2c_handle, MEASUREMENT_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
    if (result != DATA_LENGTH) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

