#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1
#define SAMPLE_RATE 8000
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration parameters
typedef struct {
    int mic1_gain;
    int mic2_gain;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
int apply_noise_cancellation(int mic1_sample, int mic2_sample, int mic1_gain, int mic2_gain);
void print_csv(int sample);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Apply noise cancellation algorithm
int apply_noise_cancellation(int mic1_sample, int mic2_sample, int mic1_gain, int mic2_gain) {
    return (mic1_sample * mic1_gain - mic2_sample * mic2_gain);
}

// Print audio sample in CSV format
void print_csv(int sample) {
    printf("%d\n", sample);
}

// Cleanup resources before exiting
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    Config config;

    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <mic1_gain> <mic2_gain>\n", argv[0]);
        return 1;
    }

    config.mic1_gain = atoi(argv[1]);
    config.mic2_gain = atoi(argv[2]);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read microphone samples
        int mic1_sample = read_mcp3008(MIC1_CHANNEL);
        int mic2_sample = read_mcp3008(MIC2_CHANNEL);

        if (mic1_sample == -1 || mic2_sample == -1) {
            fprintf(stderr, "Error reading microphone samples, retrying...\n");
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Apply noise cancellation
        int processed_sample = apply_noise_cancellation(mic1_sample, mic2_sample, config.mic1_gain, config.mic2_gain);

        // Print to terminal in CSV format
        print_csv(processed_sample);

        // Delay to achieve desired sampling rate
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

