void signal_handler(int signal) {
    printf("Received signal %d, cleaning up...\n", signal);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

