#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_FLAGS 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 17
#define WATER_LEVEL_FILE "water_levels.json"
#define SAMPLE_INTERVAL_MS 5000 // 5 seconds
#define SLEEP_INTERVAL_MS 100

// Global variables
int spi_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_percentage(int adc_value);
char *get_iso8601_timestamp();
int write_json_entry(char *timestamp, float percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate water level percentage
float calculate_percentage(int adc_value) {
    // Assuming ADC range is 0-1023
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to get current timestamp in ISO 8601 format
char *get_iso8601_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    time_t t = ts.tv_sec;
    struct tm *tm_info = localtime(&t);

    static char timestamp[30]; //YYYY-MM-DDTHH:MM:SS.mmmZ
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ldZ", ts.tv_nsec / 1000000);

    return timestamp;
}

// Function to write JSON entry to file
int write_json_entry(char *timestamp, float percentage) {
    if (fp == NULL) {
        fprintf(stderr, "Error: File not opened for writing.\n");
        return -1;
    }

    fprintf(fp, "{\"timestamp\": \"%s\", \"percentage\": %.2f}\n", timestamp, percentage);
    fflush(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open JSON file for writing
    fp = fopen(WATER_LEVEL_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open file for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket for JSON array
    fprintf(fp, "[\n");
    fflush(fp);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate water level percentage
        float percentage = calculate_percentage(adc_value);

        // Get current timestamp
        char *timestamp = get_iso8601_timestamp();

        // Write JSON entry to file
        if (write_json_entry(timestamp, percentage) != 0) {
            fprintf(stderr, "Error: Failed to write JSON entry\n");
        }

        // Control LED based on water level percentage
        if (percentage > 75.0) {
            gpioWrite(LED_GPIO, 1); // Turn LED on
        } else if (percentage < 70.0) {
            gpioWrite(LED_GPIO, 0); // Turn LED off
        }

        // Sleep for 5 seconds
        for (int i = 0; i < SAMPLE_INTERVAL_MS / SLEEP_INTERVAL_MS && !terminate; ++i) {
            gpioDelay(SLEEP_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
        }
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Close SPI handle
    spiClose(spi_handle);

    // Write closing bracket for JSON array
    fprintf(fp, "]\n");

    // Close file
    fclose(fp);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

