#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    float min_moisture;
    float max_moisture;
    float moisture_threshold;
    int logging_interval;
    char *email_address;
    char *msmtp_config_path;
} Config;

// Global variables
int spi_handle;
Config config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value, float min_moisture, float max_moisture);
void log_data(float moisture_percentage);
void send_email_alert(float moisture_percentage);
void signal_handler(int signal);
int load_config(const char *filename, Config *config);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (spi_result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", spi_result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value, float min_moisture, float max_moisture) {
    float moisture_percentage = ((float)adc_value - min_moisture) / (max_moisture - min_moisture) * 100.0;
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }
    return moisture_percentage;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open plant_data.txt for writing\n");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
}

// Function to send email alert
void send_email_alert(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char command[512];
    snprintf(command, sizeof(command), "echo \"Subject: Plant Moisture Alert\n\nPlant moisture level is below threshold at %s. Current moisture: %.2f%%\" | msmtp -C %s %s",
             timestamp, moisture_percentage, config.msmtp_config_path, config.email_address);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not execute msmtp command\n");
        return;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp command failed with status %d\n", status);
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to load configuration from file
int load_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s\n", filename);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strcmp(key, "adc_channel") == 0) {
            config->adc_channel = atoi(value);
        } else if (strcmp(key, "min_moisture") == 0) {
            config->min_moisture = atof(value);
        } else if (strcmp(key, "max_moisture") == 0) {
            config->max_moisture = atof(value);
        } else if (strcmp(key, "moisture_threshold") == 0) {
            config->moisture_threshold = atof(value);
        } else if (strcmp(key, "logging_interval") == 0) {
            config->logging_interval = atoi(value);
        } else if (strcmp(key, "email_address") == 0) {
            config->email_address = strdup(value); // Duplicate the string to avoid issues with the config struct
        } else if (strcmp(key, "msmtp_config_path") == 0) {
            config->msmtp_config_path = strdup(value); // Duplicate the string to avoid issues with the config struct
        }
    }

    fclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize configuration with default values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_moisture = 0.0;
    config.max_moisture = 1023.0;
    config.moisture_threshold = 30.0;
    config.logging_interval = 60;
    config.email_address = strdup("your_email@example.com"); // Default email address
    config.msmtp_config_path = strdup("/etc/msmtprc"); // Default msmtp config path

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0 && i + 1 < argc) {
            if (load_config(argv[i + 1], &config) != 0) {
                fprintf(stderr, "Error: Failed to load configuration from file %s\n", argv[i + 1]);
                return 1;
            }
            i++;
        } else if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            config.spi_channel = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            config.adc_channel = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-m") == 0 && i + 1 < argc) {
            config.min_moisture = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-x") == 0 && i + 1 < argc) {
            config.max_moisture = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            config.moisture_threshold = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            config.logging_interval = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-e") == 0 && i + 1 < argc) {
            free(config.email_address);
            config.email_address = strdup(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-mtp") == 0 && i + 1 < argc) {
            free(config.msmtp_config_path);
            config.msmtp_config_path = strdup(argv[i + 1]);
            i++;
        } else {
            fprintf(stderr, "Usage: %s [-c config_file] [-s spi_channel] [-a adc_channel] [-m min_moisture] [-x max_moisture] [-t moisture_threshold] [-l logging_interval] [-e email_address] [-mtp msmtp_config_path]\n", argv[0]);
            return 1;
        }
    }

    // Print configuration
    printf("Configuration:\n");
    printf("  SPI Channel: %d\n", config.spi_channel);
    printf("  ADC Channel: %d\n", config.adc_channel);
    printf("  Min Moisture: %.2f\n", config.min_moisture);
    printf("  Max Moisture: %.2f\n", config.max_moisture);
    printf("  Moisture Threshold: %.2f\n", config.moisture_threshold);
    printf("  Logging Interval: %d\n", config.logging_interval);
    printf("  Email Address: %s\n", config.email_address);
    printf("  msmtp Config Path: %s\n", config.msmtp_config_path);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, 500000, 0); // CE0, 500kHz, SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(config.adc_channel);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value, config.min_moisture, config.max_moisture);
            log_data(moisture_percentage);

            if (moisture_percentage < config.moisture_threshold) {
                send_email_alert(moisture_percentage);
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        sleep(config.logging_interval);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();
    free(config.email_address);
    free(config.msmtp_config_path);

    return 0;
}

