        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Sampling every %d seconds. Press Ctrl+C to exit.\n", sample_interval);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            log_data(adc_value, moisture_percentage);
            printf("ADC Value: %d, Moisture: %.2f%%\n", adc_value, moisture_percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", sample_interval);
        }

        gpioDelay(sample_interval * 1000000); // Delay in microseconds
    }

    // Cleanup
    printf("Closing SPI, log file, and terminating pigpio...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

