// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define SENSOR_ABSENT_LOW_THRESHOLD 0.1
#define SENSOR_ABSENT_HIGH_THRESHOLD (VREF - 0.1)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float adc_to_pressure(int adc_value);
char* get_iso8601_timestamp();
void log_data(char* timestamp, float pressure);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to pressure (kPa)
float adc_to_pressure(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float pressure = (voltage / VREF) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE;
    return pressure;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to console
void log_data(char* timestamp, float pressure) {
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Pressure sensor data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to pressure
        float pressure = adc_to_pressure(adc_value);

        // Get timestamp
        char* timestamp = get_iso8601_timestamp();

        // Log data
        log_data(timestamp, pressure);

        // Free timestamp memory
        free(timestamp);

        // Validate sensor presence
        float voltage = (float)adc_value / 1023.0 * VREF;
        if (voltage < SENSOR_ABSENT_LOW_THRESHOLD || voltage > SENSOR_ABSENT_HIGH_THRESHOLD) {
            fprintf(stderr, "Warning: Sensor may be absent (Voltage: %.2f V)\n", voltage);
        }

        // Check for out-of-range pressure values
        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr, "Warning: Pressure value out of range (%.2f kPa)\n", pressure);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Pressure sensor data logger terminated.\n");

    return 0;
}

