#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PUMP_PIN 17
#define SPI_CE0 0
#define SPI_CE1 1

// Define SPI parameters
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define moisture thresholds
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600

// Define circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    int sensor1_value;
    int sensor2_value;
    int pump_state;
} SensorData;

// Circular buffer
SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int spi_handle1 = -1;
int spi_handle2 = -1;
int pump_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
void control_pump(int state);
void add_to_buffer(time_t timestamp, int sensor1_value, int sensor2_value, int pump_state);
void print_buffer();
void sample_sensors();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Invalid SPI handle.\n");
        return -1;
    }

    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel.\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d).\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    if (state != 0 && state != 1) {
        fprintf(stderr, "Error: Invalid pump state.\n");
        return;
    }

    gpioWrite(PUMP_PIN, state);
    pump_state = state;
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, int sensor1_value, int sensor2_value, int pump_state) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].sensor1_value = sensor1_value;
    circular_buffer[buffer_index].sensor2_value = sensor2_value;
    circular_buffer[buffer_index].pump_state = pump_state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        struct tm *timeinfo = localtime(&circular_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Sensor 1: %d, Sensor 2: %d, Pump: %s\n",
               timestamp_str, circular_buffer[index].sensor1_value, circular_buffer[index].sensor2_value,
               circular_buffer[index].pump_state == 1 ? "ON" : "OFF");
    }
    printf("------------------------\n");
}

// Function to sample sensors and control the pump
void sample_sensors() {
    time_t now = time(NULL);
    int sensor1_value = read_mcp3008(spi_handle1, 0);
    int sensor2_value = read_mcp3008(spi_handle2, 0);

    if (sensor1_value == -1 || sensor2_value == -1) {
        fprintf(stderr, "Error: Failed to read sensor data.\n");
        return;
    }

    add_to_buffer(now, sensor1_value, sensor2_value, pump_state);

    if (pump_state == 0 && (sensor1_value < LOW_THRESHOLD || sensor2_value < LOW_THRESHOLD)) {
        control_pump(1);
        printf("Pump turned ON\n");
    } else if (pump_state == 1 && (sensor1_value > HIGH_THRESHOLD && sensor2_value > HIGH_THRESHOLD)) {
        control_pump(0);
        printf("Pump turned OFF\n");
    }

    print_buffer();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off the pump
    control_pump(0);

    // Close SPI interfaces
    if (spi_handle1 != -1) {
        spiClose(spi_handle1);
    }
    if (spi_handle2 != -1) {
        spiClose(spi_handle2);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_PIN, PI_OUTPUT);

    // Open SPI interfaces
    spi_handle1 = spiOpen(SPI_CE0, SPI_SPEED, SPI_MODE);
    if (spi_handle1 < 0) {
        fprintf(stderr, "Error: SPI CE0 open failed (%d)\n", spi_handle1);
        gpioTerminate();
        return 1;
    }

    spi_handle2 = spiOpen(SPI_CE1, SPI_SPEED, SPI_MODE);
    if (spi_handle2 < 0) {
        fprintf(stderr, "Error: SPI CE1 open failed (%d)\n", spi_handle2);
        spiClose(spi_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        sample_sensors();
        gpioDelay(5000); // Sample every 5 seconds
    }

    return 0;
}

