#include <pigpio.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define PART_ID_REG 0xFE
#define PART_ID_VALUE 0x15
#define SPO2_THRESHOLD 95
#define HR_THRESHOLD 100
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int spo2;
    int hr;
} sensor_data_t;

// Function prototypes
int init_i2c();
int verify_sensor();
sensor_data_t read_sensor_data();
void log_health_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor presence by reading the Part ID register
int verify_sensor() {
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID register: %d\n", part_id);
        return -1;
    }

    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VALUE);
        return -1;
    }

    return 0;
}

