    if (data.spo2 < SPO2_THRESHOLD || data.hr > HR_THRESHOLD) {
        fprintf(log_file, "%s, SpO2: %d, HR: %d\n", timestamp, data.spo2, data.hr);
        fflush(log_file); // Ensure data is written to file immediately
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify sensor presence
    if (verify_sensor() != 0) {
        fprintf(stderr, "Sensor verification failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_health_data(data);
        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

