#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define LOG_FILE "/var/log/door_events.log"
#define NUM_CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define SAMPLE_DELAY_MS 200
#define RELAY_PULSE_MS 3000
#define THRESHOLD_MULTIPLIER 1.2

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_adc();
float calculate_baseline_average();
int is_door_open();
void control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_address;
    int relay_gpio;
    int door_sensor_gpio;
    char *log_file_path;
} config_t;

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Initialize I2C
int initialize_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read ADC value from ADS1115
int read_adc() {
    unsigned char config[3];
    unsigned char read_data[2];
    int16_t adc_value;

    // Configure ADS1115 for single-ended A0, 4.096V, continuous conversion
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC3; // 0b11000011
    config[2] = 0x83; // 0b10000011

    if (write(i2c_fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 125ms for 8 SPS)
    usleep(125000);

    // Read conversion register
    config[0] = ADS1115_REG_CONVERT;
    if (write(i2c_fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, read_data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    adc_value = (read_data[0] << 8) | read_data[1];
    return adc_value;
}

// Calculate baseline average
float calculate_baseline_average() {
    float sum = 0.0;
    int adc_value;

    printf("Calibrating...\n");
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC during calibration, using default value.\n");
            return 2000.0; // Default value
        }
        sum += adc_value;
        usleep(CALIBRATION_DELAY_MS * 1000);
    }
    return sum / NUM_CALIBRATION_SAMPLES;
}

// Check if door is open
int is_door_open() {
    return gpioRead(GPIO_DOOR_SENSOR) == 0; // Active low
}

// Control relay
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Log event to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s.%03ld: %s\n", timestamp, (long int)(t->tm_usec / 1000), message);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioSetMode(GPIO_DOOR_SENSOR, PI_INPUT);
    gpioSetPullUpDown(GPIO_DOOR_SENSOR, PI_PUD_UP); // Enable pull-up resistor

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Calibrate baseline
    float baseline_average = calculate_baseline_average();
    float threshold = baseline_average * THRESHOLD_MULTIPLIER;
    printf("Baseline average: %.2f, Threshold: %.2f\n", baseline_average, threshold);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            log_event("Error reading ADC, skipping.");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        if (adc_value < threshold) {
            printf("Distance below threshold, releasing lock.\n");
            control_relay(1); // Activate relay
            log_event("Door opened");
            usleep(RELAY_PULSE_MS * 1000);
            control_relay(0); // Deactivate relay
            log_event("Door not opened");
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

