#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for chip select
#define CS0 8
#define CS1 7
#define CS2 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define the CSV file name
#define CSV_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int chip_select_pin);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int sensor3_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int chip_select_pin) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value;

    // Construct the SPI message to send to the MCP3008
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (0 & 0x07)) << 4; // Single-ended mode, channel 0
    tx_buffer[2] = 0x00;

    gpioWrite(chip_select_pin, 0); // Select the chip
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3); // Transfer data
    gpioWrite(chip_select_pin, 1); // Deselect the chip

    // Extract the ADC value from the received data
    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log data to the CSV file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int sensor3_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, sensor3_value) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    int sensor1_value, sensor2_value, sensor3_value;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure chip select pins as output
    gpioSetMode(CS0, PI_OUTPUT);
    gpioSetMode(CS1, PI_OUTPUT);
    gpioSetMode(CS2, PI_OUTPUT);

    // Initialize SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for writing
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header to the CSV file if it's a new file
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(fp);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        sensor1_value = read_mcp3008(CS0);
        sensor2_value = read_mcp3008(CS1);
        sensor3_value = read_mcp3008(CS2);

        // Log the data
        if (log_data(fp, sensor1_value, sensor2_value, sensor3_value) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Close the SPI interface and CSV file
    spiClose(spi_handle);
    fclose(fp);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

