#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP 60
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
double threshold = DEFAULT_THRESHOLD;
int duration = DEFAULT_DURATION;
int sleep_interval = DEFAULT_SLEEP;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 3;
    int result = -1;

    while (retries > 0) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 0) {
            // Extract ADC value
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI read failed (attempt %d): %d\n", 4 - retries, result);
            log_message("Error: SPI read failed. Retrying...");
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }

    fprintf(stderr, "Error: SPI read failed after multiple retries.\n");
    log_message("Error: SPI read failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
double calculate_moisture(int adc_value) {
    return ((double)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[100];
    snprintf(message, sizeof(message), "Pump %s", state ? "ON" : "OFF");
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    char message[50];
    snprintf(message, sizeof(message), "Received signal %d. Shutting down...", signal);
    log_message(message);
    control_pump(0); // Turn off the pump
    spiClose(spi_handle); // Close SPI interface
    gpioTerminate(); // Terminate pigpio
    fclose(log_file); // Close log file
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started");

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            double moisture = calculate_moisture(adc_value);
            char message[100];
            snprintf(message, sizeof(message), "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);
            log_message(message);

            if (moisture < threshold) {
                log_message("Moisture below threshold. Activating pump.");
                control_pump(1); // Turn on pump
                gpioDelay(duration * 1000000); // Wait for specified duration
                control_pump(0); // Turn off pump
            }
        } else {
            log_message("Error: Failed to read ADC value. Skipping irrigation cycle.");
        }

        gpioDelay(sleep_interval * 1000000); // Wait before next check
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

