    moving_average_index = (moving_average_index + 1) % MOVING_AVG_WINDOW_SIZE;

    double sum = 0.0;
    for (int i = 0; i < MOVING_AVG_WINDOW_SIZE; i++) {
        sum += moving_average[i];
    }

    return sum / MOVING_AVG_WINDOW_SIZE;
}

