    fprintf(stderr, "Sound event detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate moving average
        double current_moving_average = calculate_moving_average(adc_value);

        // Calculate threshold
        threshold = calculate_threshold(current_moving_average);

        // Check for peak detection
        if (adc_value > threshold) {
            log_event(adc_value);
            fprintf(stderr, "Peak detected: ADC Value = %d, Threshold = %.2f\n", adc_value, threshold);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Sound event detection terminated.\n");
    return 0;
}

