#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and PCF8591 address
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCtrl+C pressed, closing I2C device...\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

// Function to read from the PCF8591 ADC
int read_pcf8591(int fd) {
    uint8_t control_byte = 0x40; // Control byte to select AIN0
    uint8_t read_buffer[1];
    int result;

    // Write the control byte to the PCF8591
    result = write(fd, &control_byte, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read a single byte from the PCF8591
    result = read(fd, read_buffer, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return (int)read_buffer[0];
}

int main() {
    // Install the signal handler
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Perform a dummy read to initialize the PCF8591
    if (read_pcf8591(i2c_fd) == -1) {
        fprintf(stderr, "Error during dummy read\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int adc_value = read_pcf8591(i2c_fd);
        if (adc_value != -1) {
            printf("ADC Value: %d\n", adc_value);
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        usleep(100000); // 100ms delay
    }

    // The program should never reach here due to the infinite loop,
    // but include close(i2c_fd) for completeness.
    close(i2c_fd);
    return 0;
}

