#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define THRESHOLD_GAUSS 500.0
#define GPIO_PIN 27
#define BUFFER_SIZE 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_adc(int16_t *raw_value);
float convert_to_voltage(int16_t raw_value);
float convert_to_gauss(float voltage);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_gpio(int state);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C bus");
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 128 SPS, +/- 4.096V
    uint16_t config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS, Disable comparator
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;      // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        log_message(LOG_ERR, "Failed to write configuration to ADS1115");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read ADC value
int read_adc(int16_t *raw_value) {
    char buf[1];
    char read_buf[2];

    buf[0] = ADS1115_REG_CONVERT;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_message(LOG_ERR, "Failed to write to conversion register");
        return -1;
    }

    gpioDelay(10); // Wait for conversion (adjust as needed)

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        log_message(LOG_ERR, "Failed to read conversion result");
        return -1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to convert raw ADC value to voltage
float convert_to_voltage(int16_t raw_value) {
    float voltage = (float)raw_value * ADS1115_FULL_SCALE_VOLTAGE / 32768.0;
    if (voltage < 0.0 || voltage > 3.3) {
        log_message(LOG_ERR, "Voltage out of range");
        return -1.0; // Indicate an error
    }
    return voltage;
}

// Function to convert voltage to Gauss
float convert_to_gauss(float voltage) {
    // Assuming a linear relationship between voltage and Gauss.
    // This needs to be calibrated for your specific sensor.
    // The following is a placeholder.
    float gauss = voltage * 100.0; // Example conversion
    return gauss;
}

// Function to add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to control GPIO
void control_gpio(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message(LOG_INFO, "Received signal, terminating...");
    terminate = 1;
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    openlog("honeywell_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    control_gpio(0); // Initialize to LOW

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer cb;
    init_circular_buffer(&cb);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "Honeywell sensor monitoring started");

    while (!terminate) {
        int16_t raw_value;
        if (read_adc(&raw_value) == 0) {
            float voltage = convert_to_voltage(raw_value);
            if (voltage >= 0.0) {
                float gauss = convert_to_gauss(voltage);
                add_to_buffer(&cb, gauss);
                float average_gauss = calculate_average(&cb);

                char log_buffer[100];
                snprintf(log_buffer, sizeof(log_buffer), "Gauss: %.2f, Average: %.2f", gauss, average_gauss);
                log_message(LOG_INFO, log_buffer);

                if (average_gauss > THRESHOLD_GAUSS) {
                    log_message(LOG_WARNING, "Threshold exceeded, shutting down motor");
                    control_gpio(1); // Set HIGH
                } else {
                    control_gpio(0); // Set LOW
                }
            }
        } else {
            log_message(LOG_ERR, "Failed to read ADC value");
        }

        gpioDelay(1000); // Sample at 1 Hz
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_gpio(0); // Set LOW
    gpioTerminate();
    log_message(LOG_INFO, "Honeywell sensor monitoring stopped");

    return 0;
}

