    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and watering system started.\n");

    while (program_running) {
        // Read soil moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            // Optionally add retry logic here
            gpioDelay(60000); // Wait 60 seconds before retrying
            continue;
        }

        // Check if watering is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold (%d < %d), activating pump.\n", moisture_level, MOISTURE_THRESHOLD);
            control_pump(1); // Turn on the pump
            log_event(moisture_level); // Log the event
            gpioDelay(PUMP_DURATION * 1000); // Wait for 10 seconds
            control_pump(0); // Turn off the pump
            printf("Pump deactivated.\n");
        }

        gpioDelay(60000); // Wait 60 seconds before next reading
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

