#include <getopt.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_REG_FULL_SCALE_RANGE 0x02
#define AIN0_CONFIG 0x4003 // Single-ended AIN0, +/-4.096V, Continuous, 128 SPS
#define LED_GPIO 17
#define THRESHOLD_DEFAULT 100.0
#define GAUSS_PER_VOLT 0.0002 // For SS49E
#define ADS1115_FULL_SCALE_VOLTAGE 4.096

// Global variables
int i2c_handle;
double threshold = THRESHOLD_DEFAULT;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int initialize_ads1115();
int16_t read_adc();
double calculate_gauss(int16_t adc_value);
void blink_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize ADS1115
int initialize_ads1115() {
    // Set the full-scale range to +/-4.096V
    char buf[3];
    buf[0] = ADS1115_REG_FULL_SCALE_RANGE;
    buf[1] = 0xC2; // 0xC2 for +/-4.096V
    buf[2] = 0x00;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to set full-scale range: %s\n", strerror(errno));
        return -1;
    }

    // Configure the ADC for single-ended input on AIN0, continuous conversion, and 128 SPS
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (AIN0_CONFIG >> 8) & 0xFF;
    buf[2] = AIN0_CONFIG & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to configure ADC: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read ADC value
int16_t read_adc() {
    char buf[1];
    char read_buf[2];
    int16_t adc_value;

    buf[0] = ADS1115_REG_CONVERT;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to conversion register: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read ADC value: %s\n", strerror(errno));
        return -1;
    }

    adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Calculate Gauss
double calculate_gauss(int16_t adc_value) {
    double voltage = (double)adc_value * ADS1115_FULL_SCALE_VOLTAGE / 32768.0;
    return voltage * GAUSS_PER_VOLT;
}

// Blink LED
void blink_led(int duration_ms) {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(50000);       // 50ms
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(50000);       // 50ms
    gpioDelay((duration_ms - 100) * 1000); // Delay the remaining time
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (initialize_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    printf("Monitoring magnetic field... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Calculate Gauss
        double gauss = calculate_gauss(adc_value);

        // Print Gauss value
        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        // Check threshold and blink LED
        if (gauss > threshold) {
            blink_led(1000); // Blink for 1 second
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

