#define MQTT_TOPIC_PUMP "pump_control"
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define SENSOR_PRESENT_THRESHOLD 500 // ADC value indicating sensor presence
#define SENSOR_ABSENT_THRESHOLD 100 // ADC value indicating sensor absence
#define SENSOR_ABSENT_READING 0
#define SPI_RETRY_COUNT 3

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int moisture_percentage);
void publish_moisture(int moisture_percentage);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int sig);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    int retry = 0;
    int result = -1;
    while (retry < SPI_RETRY_COUNT) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 0) {
            break; // Success
        } else {
            syslog(LOG_ERR, "SPI transfer failed (attempt %d): %d", retry + 1, result);
            gpioDelay(10000); // 10ms delay
            retry++;
        }
    }

    if (result != 0) {
        syslog(LOG_ERR, "Failed to read MCP3008 after %d retries.", SPI_RETRY_COUNT);
        return -1; // Indicate failure
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    if (adc_value < 0) {
        return -1.0; // Indicate error
    }

    // Map ADC value to moisture percentage (0-100%)
    // Assuming a linear relationship: 0 ADC = 100% moisture, 1023 ADC = 0% moisture
    float moisture_percentage = 100.0 - ((float)adc_value / 1023.0) * 100.0;

    // Clamp the value to the range 0-100%
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }

    return moisture_percentage;
}

// Function to control the pump
void control_pump(int moisture_percentage) {
    static int pump_state = 0; // 0 = off, 1 = on

    if (moisture_percentage < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
        // Turn pump on
        if (gpioWrite(PUMP_GPIO, 1) != 0) {
            syslog(LOG_ERR, "Failed to write to GPIO %d", PUMP_GPIO);
        } else {
            syslog(LOG_INFO, "Pump turned ON (Moisture: %d%%)", moisture_percentage);
            pump_state = 1;
        }
    } else if (moisture_percentage > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
        // Turn pump off
        if (gpioWrite(PUMP_GPIO, 0) != 0) {
            syslog(LOG_ERR, "Failed to write to GPIO %d", PUMP_GPIO);
        } else {
            syslog(LOG_INFO, "Pump turned OFF (Moisture: %d%%)", moisture_percentage);
            pump_state = 0;
        }
    }
}

// Function to publish moisture data to MQTT
void publish_moisture(int moisture_percentage) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", moisture_percentage);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC_MOISTURE, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(ret));
    } else {
        syslog(LOG_INFO, "Published moisture: %d%% to topic %s", moisture_percentage, MQTT_TOPIC_MOISTURE);
    }
}

// MQTT on_connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        // Subscribe to the pump control topic
        int ret = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP, 0);
        if (ret != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic %s: %s", MQTT_TOPIC_PUMP, mosquitto_strerror(ret));
        }
    } else {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(result));
    }
}

// MQTT on_message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "pump_on") == 0) {
            syslog(LOG_INFO, "Received pump_on command");
            gpioWrite(PUMP_GPIO, 1);
        } else if (strcmp(payload, "pump_off") == 0) {
            syslog(LOG_INFO, "Received pump_off command");
            gpioWrite(PUMP_GPIO, 0);
        } else {
            syslog(LOG_WARNING, "Received unknown command: %s", payload);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI initialisation failed: %d", spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture(adc_value);
            if (moisture_percentage >= 0.0) {
                control_pump((int)moisture_percentage);
                publish_moisture((int)moisture_percentage);
            } else {
                syslog(LOG_ERR, "Failed to calculate moisture percentage");
            }
        } else {
            syslog(LOG_ERR, "Failed to read ADC value");
        }

        sleep(60);
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(PUMP_GPIO, 0); // Turn off pump
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioTerminate();
    closelog();

    return 0;
}

