#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
        printf("SPI device closed.\n");
    }
    exit(0);
}

// Function to read from MCP3008 channel
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_MAX_SPEED_HZ;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return 1;
    }

    // Configure max speed Hz
    uint32_t speed = SPI_MAX_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set max speed Hz");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Exiting.\n");
            close(spi_fd);
            return 1;
        }

        // Calculate voltage
        float voltage = (adc_value * 3.3) / 1024.0;

        // Print results
        printf("Raw Value: %d, Voltage: %.2f V\n", adc_value, voltage);

        // Wait 500ms
        usleep(500000);
    }

    return 0;
}

