#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNELS 3
#define VREF 3.3
#define CSV_FILE "sensor_data.csv"

// Global variables
static volatile int keepRunning = 1;
static FILE *fp = NULL;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
char* get_timestamp();
int write_to_csv(char *timestamp, float voltage0, float voltage1, float voltage2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    keepRunning = 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to write data to CSV file
int write_to_csv(char *timestamp, float voltage0, float voltage1, float voltage2) {
    if (fp == NULL) {
        fprintf(stderr, "File pointer is NULL.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltage0, voltage1, voltage2) < 0) {
        fprintf(stderr, "File write failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (keepRunning) {
        int adc_value0 = read_mcp3008(0);
        int adc_value1 = read_mcp3008(1);
        int adc_value2 = read_mcp3008(2);

        if (adc_value0 == -1 || adc_value1 == -1 || adc_value2 == -1) {
            fprintf(stderr, "Failed to read ADC values.\n");
            continue; // Skip to the next iteration
        }

        float voltage0 = convert_to_voltage(adc_value0);
        float voltage1 = convert_to_voltage(adc_value1);
        float voltage2 = convert_to_voltage(adc_value2);

        char *timestamp = get_timestamp();

        if (write_to_csv(timestamp, voltage0, voltage1, voltage2) != 0) {
            fprintf(stderr, "Failed to write data to CSV.\n");
        }

        delay(5000); // Wait 5 seconds
    }

    // Cleanup
    if (fp != NULL) {
        fclose(fp);
    }

    printf("Program finished.\n");
    return 0;
}

