#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 10

// GPIO pins
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_speed(int gpio, int speed);
