#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define SOUND_THRESHOLD 60.0
#define LIGHT_THRESHOLD 500.0
#define LOG_FILE "tamper_log.csv"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_db(int adc_value);
int read_bh1750();
void log_data(float sound_level_db, int light_level_lux, int error_code);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to dB
float adc_to_db(int adc_value) {
    // Assuming a linear relationship between ADC value and dB
    // You'll need to calibrate this based on your specific setup
    float db = (float)adc_value * (100.0 / 1023.0); // Example: 0-100 dB range
    return db;
}

// Function to read from BH1750 sensor
int read_bh1750() {
    char buf[2];
    int light_level;

    if (i2cWriteByte(i2c_handle, 0x10) != 0) { // Start measurement in high resolution mode
        fprintf(stderr, "Error: BH1750 start measurement failed\n");
        return -1;
    }

    gpioDelay(180); // Wait 180ms

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: BH1750 read failed\n");
        return -1;
    }

    light_level = (buf[0] << 8) | buf[1];
    return light_level;
}

// Function to log data to CSV file
void log_data(float sound_level_db, int light_level_lux, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tamper detection system started. Logging to %s\n", LOG_FILE);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        int light_level = read_bh1750();
        float sound_level_db = -1.0;
        int error_code = 0;

        if (adc_value < 0) {
            error_code = 1; // ADC read error
        } else {
            sound_level_db = adc_to_db(adc_value);
        }

        if (light_level < 0) {
            error_code = 2; // I2C read error
        }

        log_data(sound_level_db, light_level, error_code);

        if (error_code == 0) {
            if (sound_level_db > SOUND_THRESHOLD || light_level > LIGHT_THRESHOLD) {
                printf("Tamper event detected! Sound: %.2f dB, Light: %d lux\n", sound_level_db, light_level);
            }
        } else {
            fprintf(stderr, "Error: Sensor read error (code %d)\n", error_code);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Tamper detection system stopped.\n");
    return 0;
}

