#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define DISTANCE_THRESHOLD 20 // cm
#define DEBOUNCE_DELAY 1 // seconds
#define LOG_FILE "door_events.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_distance(int adc_value);
void control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate distance from ADC value (using GP2Y0A21YK0F datasheet)
float calculate_distance(int adc_value) {
    // This is a simplified approximation.  A more accurate calibration
    // curve would be needed for accurate distance measurements.
    // The GP2Y0A21YK0F has a non-linear response, so a lookup table
    // or a more complex equation is recommended.
    // This is just a placeholder.
    if (adc_value == 0) return 100.0; // Avoid division by zero
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float distance = 100.0 / voltage; // Inverted relationship
    return distance;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Door monitoring started. Press Ctrl+C to exit.\n");

    int debounce_counter = 0;

    while (program_running) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        float distance = calculate_distance(adc_value);

        // Check if distance is below threshold and debounce
        if (distance < DISTANCE_THRESHOLD && debounce_counter == 0) {
            printf("Distance below threshold: %.2f cm\n", distance);
            log_event("Door opened");
            control_relay(1); // Activate relay
            gpioDelay(DEBOUNCE_DELAY * 1000000); // Debounce delay (microseconds)
            control_relay(0); // Deactivate relay
            debounce_counter = DEBOUNCE_DELAY; // Start debounce counter
        } else if (debounce_counter > 0) {
            debounce_counter--;
        }

        gpioDelay(100000); // Poll every 100ms (microseconds)
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

