// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Door monitoring started. Press Ctrl+C to exit.\n");

    int debounce_counter = 0;

    while (program_running) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate distance
        float distance = calculate_distance(adc_value);

        // Check if distance is below threshold and debounce
        if (distance < DISTANCE_THRESHOLD && debounce_counter == 0) {
            printf("Distance below threshold: %.2f cm\n", distance);
            log_event("Door opened");
            control_relay(1); // Activate relay
            gpioDelay(DEBOUNCE_DELAY * 1000000); // Debounce delay (microseconds)
            control_relay(0); // Deactivate relay
            debounce_counter = DEBOUNCE_DELAY; // Start debounce counter
        } else if (debounce_counter > 0) {
            debounce_counter--;
        }

        gpioDelay(100000); // Poll every 100ms (microseconds)
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

