    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value = -1; // Initialize to an invalid value
    int retries = 0;
    int delay_ms = RETRY_DELAY_BASE_MS;

    // Construct SPI command
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    while (retries < RETRY_COUNT) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value from response
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

            // Validate ADC value
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
                log_data(-1.0); // Log an error
                return -1; // Indicate failure
            }
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d).\n", retries + 1);
            log_data(-1.0); // Log an error
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure after all retries
}

