#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define SPI_CE 0 // Chip Enable 0 for MCP3008

// Define constants
#define SOUND_SPEED 34300 // cm/s
#define MIN_DISTANCE 2   // cm
#define MAX_DISTANCE 200  // cm
#define MIN_FREQUENCY 200  // Hz
#define MAX_FREQUENCY 2000 // Hz
#define MIN_VOLUME 0      // %
#define MAX_VOLUME 100    // %
#define TIMEOUT_US 50000  // 50ms timeout for HC-SR04

// Global variables
static volatile int running = 1;
static int spi_handle;
static float distance_offset = 0.0;
static float distance_scale = 1.0;
static float ldr_offset = 0.0;
static float ldr_scale = 1.0;

// Function prototypes
float get_distance();
int read_ldr();
float map_distance_to_frequency(float distance);
float map_ldr_to_volume(int ldr_value);
void generate_tone(float frequency, float volume);
void save_config();
void load_config();
void signal_handler(int signal);

// Function to get distance from HC-SR04 sensor
float get_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        if (timeout == 0) start_tick = gpioTick();
        timeout++;
        gpioDelay(1); // Check every microsecond
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: HC-SR04 timeout waiting for echo high\n");
        return -1.0; // Indicate error
    }

    // Wait for echo to go low with timeout
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1);
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: HC-SR04 timeout waiting for echo low\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * SOUND_SPEED) / 2.0; // Distance in cm

    return distance;
}

// Function to read LDR value from MCP3008
int read_ldr() {
    char tx_buf[3];
    char rx_buf[3];

    // MCP3008 command to read channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended mode, channel 0
    tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

