#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_speed(int adc_value);
void set_motor_speed(int motor, float speed);
void set_motor_direction(int motor, int direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map ADC value to speed (0-100%)
float map_adc_to_speed(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, float speed) {
    int gpio_pin;

    if (motor == 1) {
        gpio_pin = MOTOR1_ENABLE;
    } else if (motor == 2) {
        gpio_pin = MOTOR2_ENABLE;
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
        return;
    }

    if (speed < 0.0 || speed > 100.0) {
        fprintf(stderr, "Error: Invalid speed value %f\n", speed);
        return;
    }

    int pwm_value = (int)(speed / 100.0 * 255.0);
    gpioPWM(gpio_pin, pwm_value);
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    int gpio_pin;

    if (motor == 1) {
        gpio_pin = MOTOR1_DIRECTION;
    } else if (motor == 2) {
        gpio_pin = MOTOR2_DIRECTION;
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
        return;
    }

    gpioWrite(gpio_pin, direction);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM range for motor control
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from potentiometers
        int adc_value1 = read_mcp3008(0);
        int adc_value2 = read_mcp3008(1);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error: Failed to read ADC values, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        // Map ADC values to speed
        float speed1 = map_adc_to_speed(adc_value1);
        float speed2 = map_adc_to_speed(adc_value2);

        // Acceleration phase
        for (int i = 0; i <= 100; i++) {
            set_motor_speed(1, (float)i);
            set_motor_speed(2, (float)i);
            gpioDelay(20); // Delay for 20ms
        }

        // Constant speed phase
        gpioDelay(2000); // Hold for 2 seconds

        // Deceleration phase
        for (int i = 100; i >= 0; i--) {
            set_motor_speed(1, (float)i);
            set_motor_speed(2, (float)i);
            gpioDelay(20); // Delay for 20ms
        }

        // Pause
        gpioDelay(5000); // Pause for 5 seconds

        // Reverse direction
        set_motor_direction(1, 1); // Motor 1 forward
        set_motor_direction(2, 0); // Motor 2 backward

        // Acceleration phase (reverse)
        for (int i = 0; i <= 100; i++) {
            set_motor_speed(1, (float)i);
            set_motor_speed(2, (float)i);
            gpioDelay(20); // Delay for 20ms
        }

        // Constant speed phase (reverse)
        gpioDelay(2000); // Hold for 2 seconds

        // Deceleration phase (reverse)
        for (int i = 100; i >= 0; i--) {
            set_motor_speed(1, (float)i);
