#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_speed(int adc_value);
void set_motor_speed(int motor, float speed);
void set_motor_direction(int motor, int direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map ADC value to speed (0-100%)
float map_adc_to_speed(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, float speed) {
    int gpio_pin;

    if (motor == 1) {
        gpio_pin = MOTOR1_ENABLE;
    } else if (motor == 2) {
        gpio_pin = MOTOR2_ENABLE;
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
        return;
    }

    if (speed < 0.0 || speed > 100.0) {
        fprintf(stderr, "Error: Invalid speed value %f\n", speed);
        return;
    }

    int pwm_value = (int)(speed / 100.0 * 255.0);
    gpioPWM(gpio_pin, pwm_value);
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    int gpio_pin;

    if (motor == 1) {
        gpio_pin = MOTOR1_DIRECTION;
    } else if (motor == 2) {
        gpio_pin = MOTOR2_DIRECTION;
    } else {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
        return;
    }

    gpioWrite(gpio_pin, direction);
}

