        int adc_value1 = read_mcp3008(0);
        int adc_value2 = read_mcp3008(1);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error: Failed to read ADC values, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
