#define SPI_CE 8 // Chip Enable (CS)

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define calibration parameters
#define CALIBRATION_TIME 5 // seconds
#define NUM_CALIBRATION_SAMPLES 100

// Define threshold parameters
#define THRESHOLD_MULTIPLIER 1.5

// Global variables
int spi_handle;
double ambient_noise_level = 0.0;
int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int read_mcp3008(int channel);
double calibrate_noise_level(int num_samples);
int is_above_threshold(int sample, double threshold);
void set_led_state(int state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calibrate ambient noise level
double calibrate_noise_level(int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        int sample = read_mcp3008(0);
        if (sample == -1) return -1.0; // Propagate error
        sum += sample;
        gpioDelay(10); // Small delay between samples
    }
    return sum / num_samples;
}

// Function to check if sample is above threshold
int is_above_threshold(int sample, double threshold) {
    return (sample > threshold) ? 1 : 0;
}

// Function to set LED state
void set_led_state(int state) {
    if (state != led_state) {
        gpioWrite(LED_PIN, state);
        led_state = state;
        gpioDelay(10); // Debounce delay
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_led_state(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CE, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Calibrate ambient noise level
    printf("Calibrating ambient noise level for %d seconds...\n", CALIBRATION_TIME);
    ambient_noise_level = calibrate_noise_level(NUM_CALIBRATION_SAMPLES);
    if (ambient_noise_level < 0) {
        fprintf(stderr, "Error: Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    printf("Ambient noise level: %.2f\n", ambient_noise_level);

    // Calculate threshold
    double threshold = ambient_noise_level * THRESHOLD_MULTIPLIER;
    printf("Threshold: %.2f\n", threshold);

    // Main loop
    while (1) {
        int sample = read_mcp3008(0);
        if (sample == -1) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Continue to the next iteration
        }

        int above_threshold = is_above_threshold(sample, threshold);
        set_led_state(above_threshold);

        gpioDelay(10); // Small delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

