// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value, float vref);
float calculate_ppm(float voltage);
void log_data(float voltage, float ppm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate voltage
float calculate_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Function to calculate PPM (placeholder)
float calculate_ppm(float voltage) {
    // Placeholder: Replace with actual PPM calculation based on sensor datasheet
    return voltage * 100.0; // Example: Linear relationship
}

