void log_data(float voltage, float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.3f, %.3f\n", timestamp, voltage, ppm);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Propane leak detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        float voltage = 0.0;
        float ppm = 0.0;

        // Retry reading ADC value with exponential backoff
        for (int i = 0; i < 3; i++) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break; // Success, exit retry loop
            } else {
                gpioDelay(100 << i); // Exponential backoff (100ms, 200ms, 400ms)
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        // Calculate voltage and PPM
        voltage = calculate_voltage(adc_value, VREF);
        ppm = calculate_ppm(voltage);

        // Print to console
        printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);

        // Log data to file
        log_data(voltage, ppm);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

