#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define MCP3008_CS 8
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// ADXL335 sensitivity (300mV/g) and reference voltage (3.3V)
#define ADXL335_SENSITIVITY 0.00300
#define REFERENCE_VOLTAGE 3.3

// Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
float x_k = 0.0; // Estimated state
float P_k = 1.0; // Estimate error covariance

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_g(int adc_value);
float kalman_filter(float measurement);
void print_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to acceleration in g
float adc_to_g(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * REFERENCE_VOLTAGE;
    float acceleration = voltage / ADXL335_SENSITIVITY;
    return acceleration;
}

// Kalman filter implementation
float kalman_filter(float measurement) {
    // Prediction step
    float x_k_pred = x_k;
    float P_k_pred = P_k + PROCESS_NOISE;

    // Update step
    float K = P_k_pred / (P_k_pred + MEASUREMENT_NOISE);
    float x_k_new = x_k_pred + K * (measurement - x_k_pred);
    float P_k_new = (1 - K) * P_k_pred;

    // Update state
    x_k = x_k_new;
    P_k = P_k_new;

    return x_k_new;
}

// Print acceleration values
void print_acceleration(float x, float y, float z) {
    printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x, y, z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
