// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the magnetic field range
#define MIN_FIELD -100.0
#define MAX_FIELD 100.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read the digital state from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert the digital state to a magnetic field strength
float convert_to_magnetic_field(int digital_state) {
    return (float)digital_state * 3.3 * 1000.0; // Convert to millitesla
}

// Function to log the magnetic field values to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing\n", LOG_FILE);
        return -1; // Indicate an error
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Flush the buffer to ensure data is written immediately
    fclose(fp);
    return 0;
}

// Function to check if the magnetic field is within the defined range
int check_range(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    if (sensor1_mT < MIN_FIELD || sensor1_mT > MAX_FIELD) {
        fprintf(stderr, "Warning: Sensor 1 magnetic field value %.2f mT is outside the range %.2f to %.2f mT\n", sensor1_mT, MIN_FIELD, MAX_FIELD);
    }
    if (sensor2_mT < MIN_FIELD || sensor2_mT > MAX_FIELD) {
        fprintf(stderr, "Warning: Sensor 2 magnetic field value %.2f mT is outside the range %.2f to %.2f mT\n", sensor2_mT, MIN_FIELD, MAX_FIELD);
    }
    if (sensor3_mT < MIN_FIELD || sensor3_mT > MAX_FIELD) {
        fprintf(stderr, "Warning: Sensor 3 magnetic field value %.2f mT is outside the range %.2f to %.2f mT\n", sensor3_mT, MIN_FIELD, MAX_FIELD);
    }
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the digital state from each sensor
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);
        int sensor3_state = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reading
        if (sensor1_state == -1 || sensor2_state == -1 || sensor3_state == -1) {
            fprintf(stderr, "Error reading sensor data, skipping logging\n");
        } else {
            // Convert the digital states to magnetic field strengths
            float sensor1_mT = convert_to_magnetic_field(sensor1_state);
            float sensor2_mT = convert_to_magnetic_field(sensor2_state);
            float sensor3_mT = convert_to_magnetic_field(sensor3_state);

            // Check if the magnetic field values are within the defined range
            check_range(sensor1_mT, sensor2_mT, sensor3_mT);

            // Log the data to the file
            if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

