        // Wait for 60 seconds
        gpioDelay(60000); // pigpio's delay function (milliseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

