#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;
static int reconnection_delay = 1;

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    static char timestamp[20]; // Ensure buffer is large enough
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log messages with timestamp
void log_message(const char *message) {
    fprintf(stderr, "%s: %s\n", get_timestamp(), message);
}

// Function to parse JSON payload
int parse_json_payload(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        char error_message[256];
        snprintf(error_message, sizeof(error_message), "Error parsing JSON: %s", error.text);
        log_message(error_message);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        log_message("Error: led_state not found in JSON");
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(led_state_json)) {
        log_message("Error: led_state is not a boolean");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

// Function to set LED state
void set_led_state(int state) {
    gpioWrite(GPIO_PIN, state);
}

// MQTT message callback
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen && message->payload) {
        int led_state;
        if (parse_json_payload(message->payload, &led_state) == 0) {
            set_led_state(led_state);
        }
    }
}

// MQTT connect callback
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        log_message("MQTT connected");
        reconnection_delay = 1; // Reset reconnection delay on successful connection
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        char error_message[64];
        snprintf(error_message, sizeof(error_message), "MQTT connection error: %s", mosquitto_connack_string(result));
        log_message(error_message);
        // Exponential backoff reconnection
        sleep(reconnection_delay);
        reconnection_delay *= 2;
        if (reconnection_delay > 60) {
            reconnection_delay = 60;
        }
        mosquitto_reconnect(mosq);
    }
}

// MQTT disconnect callback
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        log_message("MQTT disconnected unexpectedly, attempting to reconnect...");
        mosquitto_reconnect(mosq);
    } else {
        log_message("MQTT disconnected cleanly");
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    running = 0;
    log_message("Signal received, exiting...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    set_led_state(0); // Turn off LED on startup

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message("Error: Out of memory.");
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        char error_message[64];
        snprintf(error_message, sizeof(error_message), "Error connecting to MQTT broker: %s", mosquitto_strerror(rc));
        log_message(error_message);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_message("MQTT loop error, attempting to reconnect...");
            mosquitto_reconnect(mosq);
        }
    }

    // Cleanup
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    set_led_state(0); // Turn off LED before exiting
    gpioTerminate();

    log_message("Exiting cleanly");
    return 0;
}

