#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input for sound sensor
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);

    // Set GPIO18 as output for alarm LED
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the digital value from the sound sensor
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        // Print the sound level to the console
        printf("Sound level: %d\n", sound_level);

        // Check if a sound event has occurred (sound_level == 0)
        if (sound_level == 0) {
            printf("Sound event detected! Triggering alarm.\n");

            // Turn on the alarm LED
            gpioWrite(ALARM_LED_PIN, 1);

            // Wait for 1 second
            gpioDelay(1000000); // 1 second = 1000000 microseconds

            // Turn off the alarm LED
            gpioWrite(ALARM_LED_PIN, 0);
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Cleanup GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

