    return p;
}

// Calculate altitude
double calculate_altitude(double pressure) {
    double seaLevelPressure = 101325.0; // Standard sea level pressure in Pa
    return 44330.0 * (1.0 - pow(pressure / seaLevelPressure, 0.1903));
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log altitude to file
int log_altitude(double altitude, char* timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, altitude);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure sensor (example: oversampling x1, normal mode)
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) { // Temperature and pressure oversampling x1, normal mode
        fprintf(stderr, "Failed to write control register\n");
        cleanup();
        return 1;
    }

    // Main loop
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure, altitude;
    char* timestamp;

    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = compensate_temperature(raw_temperature);
            pressure = compensate_pressure(raw_pressure, temperature);

            // Calculate altitude
            altitude = calculate_altitude(pressure);

            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log altitude
            if (log_altitude(altitude, timestamp) != 0) {
                fprintf(stderr, "Failed to log altitude\n");
            }

            free(timestamp); // Free the allocated memory

            printf("Altitude: %.2f m\n", altitude);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

