}

// Calculate altitude
double calculate_altitude(double pressure) {
    double seaLevelPressure = 101325.0; // Standard sea level pressure in Pa
    return 44330.0 * (1.0 - pow(pressure / seaLevelPressure, 0.1903));
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

