int log_altitude(double altitude, char* timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, altitude);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
    return 0;
}

