#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750(float *lux);
int read_mcp3008(int *adc_value);
int log_data(float lux, int adc_value);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float lux;
    int adc_value;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to initialize SPI
int init_spi() {
    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Configure SPI bits per word
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Configure SPI max speed
    int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read light level from BH1750
int read_bh1750(float *lux) {
    unsigned char buf[2];
    int result;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-resolution mode
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert to lux
    result = (buf[0] << 8) | buf[1];
    *lux = (float)result / 1.2;

    return 0;
}

// Function to read ADC value from MCP3008
int read_mcp3008(int *adc_value) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    *adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return 0;
}

// Function to log data to file
int log_data(float lux, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Light: %.2f lux, Sound: %d\n", timestamp, lux, adc_value);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_bh1750(&sensor_data.lux) != 0) {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
            sensor_data.lux = -1.0; // Indicate error
        }
        if (read_mcp3008(&sensor_data.adc_value) != 0) {
            fprintf(stderr, "Error reading MCP3008 sensor.\n");
            sensor_data.adc_value = -1; // Indicate error
        }

        // Log data
        log_data(sensor_data.lux, sensor_data.adc_value);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    return 0;
}

