    buf[0] = 0x10; // Continuous H-resolution mode
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert to lux
    result = (buf[0] << 8) | buf[1];
    *lux = (float)result / 1.2;

    return 0;
}

// Function to read ADC value from MCP3008
int read_mcp3008(int *adc_value) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    *adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return 0;
}

// Function to log data to file
int log_data(float lux, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Light: %.2f lux, Sound: %d\n", timestamp, lux, adc_value);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_bh1750(&sensor_data.lux) != 0) {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
            sensor_data.lux = -1.0; // Indicate error
        }
        if (read_mcp3008(&sensor_data.adc_value) != 0) {
            fprintf(stderr, "Error reading MCP3008 sensor.\n");
            sensor_data.adc_value = -1; // Indicate error
        }

        // Log data
        log_data(sensor_data.lux, sensor_data.adc_value);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    return 0;
}

