#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define I2C_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 0.5 // seconds

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_celsius(int adc_value);
int set_mcp4725(int i2c_handle, float voltage);
void log_data(float temperature, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (read_mcp3008): %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (adc_value * 3.3) / 1024.0;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to set MCP4725 DAC voltage
int set_mcp4725(int i2c_handle, float voltage) {
    if (voltage < 0.0 || voltage > 5.0) {
        fprintf(stderr, "Error: Invalid voltage: %f\n", voltage);
        return -1;
    }

    // Convert voltage to DAC value (12 bits)
    int dac_value = (int)(voltage / 5.0 * 4095.0);

    // Construct I2C message (MCP4725 datasheet)
    char i2c_tx_buf[3];
    i2c_tx_buf[0] = 0x40; // Command byte (Write DAC)
    i2c_tx_buf[1] = (dac_value >> 4) & 0xFF; // MSB
    i2c_tx_buf[2] = (dac_value << 4) & 0xF0; // LSB

    int result = i2cWriteDevice(i2c_handle, i2c_tx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed (set_mcp4725): %d\n", result);
        return -1;
    }

    return 0;
}

// Function to log data to file
void log_data(float temperature, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    int adc_value = (int)((voltage / 5.0) * 4095.0); //Estimate ADC value from voltage
    float celsius = (voltage - 0.5) * 100.0; //Estimate Celsius from voltage

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, celsius, voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, celsius, voltage);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert ADC value to Celsius
        float temperature = adc_to_celsius(adc_value);

        // Set DAC voltage
        float voltage = (temperature + 25.0) / 100.0 * 5.0; // Map temperature to 0-5V
        if (voltage < 0.0) voltage = 0.0;
        if (voltage > 5.0) voltage = 5.0;

        if (set_mcp4725(i2c_handle, voltage) != 0) {
            fprintf(stderr, "Error: Failed to set DAC voltage\n");
        }

        // Log data
        log_data(temperature, voltage);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

