#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI parameters
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor control parameters
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_STOP 2
#define MOTOR_DURATION 3 // seconds
#define PWM_RANGE 255
#define PWM_DUTY_FORWARD 150
#define PWM_DUTY_REVERSE 150

// Global variables
int spi_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_motor(int direction, int duty_cycle);
void log_data(int rain_level, int motor_direction);
void signal_handler(int signal);

// Function to read data from MCP3008
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to control the motor
void control_motor(int direction, int duty_cycle) {
    switch (direction) {
        case MOTOR_FORWARD:
            gpioWrite(MOTOR_IN1, 1);
            gpioWrite(MOTOR_IN2, 0);
            gpioPWM(MOTOR_ENA, duty_cycle);
            break;
        case MOTOR_REVERSE:
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 1);
            gpioPWM(MOTOR_ENA, duty_cycle);
            break;
        case MOTOR_STOP:
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 0);
            gpioPWM(MOTOR_ENA, 0);
            break;
        default:
            fprintf(stderr, "Invalid motor direction: %d\n", direction);
            break;
    }
}

// Function to log data to file
void log_data(int rain_level, int motor_direction) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Rain Level: %d, Motor Direction: %s\n",
            timestamp, rain_level,
            (motor_direction == MOTOR_FORWARD) ? "Forward" :
            (motor_direction == MOTOR_REVERSE) ? "Reverse" : "Stop");
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Open SPI device
    char spi_device_path[64];
    snprintf(spi_device_path, sizeof(spi_device_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);
    spi_fd = open(spi_device_path, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    // Configure SPI mode
    unsigned char mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read rain sensor value
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error reading rain sensor, exiting...\n");
            break;
        }

        // Determine motor direction
        int motor_direction = (rain_level > RAIN_THRESHOLD) ? MOTOR_REVERSE : MOTOR_FORWARD;

        // Control motor
        control_motor(motor_direction, (motor_direction == MOTOR_FORWARD) ? PWM_DUTY_FORWARD : PWM_DUTY_REVERSE);

        // Log data
        log_data(rain_level, motor_direction);

        // Wait for one second
        sleep(1);
    }

    // Stop motor
    control_motor(MOTOR_STOP, 0);

    // Close SPI device and log file
    close(spi_fd);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Rain sensor monitoring stopped.\n");

    return 0;
}

