#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define LED_GPIO 16
#define CLAP_THRESHOLD 500
#define DEBOUNCE_INTERVAL_MS 50
#define LED_ON_DURATION_MS 500

// Global variables
int spi_handle;
bool running = true;

// Function prototypes
int read_adc(int channel);
bool detect_clap(int adc_value);
void control_led(int duration_ms);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to detect clap event
bool detect_clap(int adc_value) {
    return adc_value > CLAP_THRESHOLD;
}

// Function to control LED
void control_led(int duration_ms) {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(LED_GPIO, 0); // Turn LED off
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = false;
    gpioWrite(LED_GPIO, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Clap detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Detect clap event
        if (detect_clap(adc_value)) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print detection message
            printf("%s: Clap detected! ADC value: %d\n", timestamp, adc_value);

            // Control LED
            control_led(LED_ON_DURATION_MS);

            // Debounce
            gpioDelay(DEBOUNCE_INTERVAL_MS * 1000); // Delay for debounce interval
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(LED_GPIO, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

