#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio17/value"
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 200 // mm
#define SLEEP_DURATION 1 // seconds

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to read the GPIO value
int read_gpio() {
    FILE *fp;
    char value;

    fp = fopen(GPIO_PATH, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening GPIO value file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    if (fread(&value, 1, 1, fp) != 1) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);

    if (value == '0') {
        return 0;
    } else if (value == '1') {
        return 1;
    } else {
        fprintf(stderr, "Error: Invalid GPIO value read: %c\n", value);
        return -1; // Indicate error
    }
}

// Function to log the distance to a file
void log_distance(int distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%s, Distance: %d mm\n", timestamp, distance);
    fclose(fp);
}

// Function to print the feeder status
void print_feeder_status(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin (if not already exported)
    char export_path[] = "/sys/class/gpio/export";
    FILE *export_file = fopen(export_path, "w");
    if (export_file == NULL) {
        fprintf(stderr, "Error opening GPIO export file: %s\n", strerror(errno));
        return 1;
    }
    fprintf(export_file, "%d", GPIO_PIN);
    fclose(export_file);

    // Set GPIO direction to input
    char direction_path[50];
    snprintf(direction_path, sizeof(direction_path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    FILE *direction_file = fopen(direction_path, "w");
    if (direction_file == NULL) {
        fprintf(stderr, "Error opening GPIO direction file: %s\n", strerror(errno));
        return 1;
    }
    fprintf(direction_file, "in");
    fclose(direction_file);

    printf("Monitoring Sharp GP2Y0A21YK0F distance sensor on GPIO%d...\n", GPIO_PIN);

    while (program_running) {
        int gpio_value = read_gpio();
        if (gpio_value == -1) {
            fprintf(stderr, "Error reading GPIO value, retrying in %d seconds...\n", SLEEP_DURATION);
            sleep(SLEEP_DURATION);
            continue;
        }

        int distance = (gpio_value == 0) ? 100 : 300; // Simulate distance based on GPIO value

        log_distance(distance);
        print_feeder_status(distance);

        sleep(SLEEP_DURATION);
    }

    // Unexport GPIO pin
    char unexport_path[] = "/sys/class/gpio/unexport";
    FILE *unexport_file = fopen(unexport_path, "w");
    if (unexport_file == NULL) {
        fprintf(stderr, "Error opening GPIO unexport file: %s\n", strerror(errno));
        return 1;
    }
    fprintf(unexport_file, "%d", GPIO_PIN);
    fclose(unexport_file);

    printf("GPIO%d unexported. Exiting.\n", GPIO_PIN);

    return 0;
}

