#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>

// Define GPIO pins
#define MCP3008_CS_PIN 8
#define DRV5055_VOUT_PIN 0

// Define SPI parameters
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz

// Define DRV5055 sensitivity (example value, check datasheet)
#define DRV5055_SENSITIVITY 0.002 // 2 mV/mT

// Define ADC parameters
#define ADC_VREF 3.3 // ADC reference voltage
#define ADC_RESOLUTION 1024 // 10-bit ADC

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(int bus, int device, int speed);
int read_mcp3008(int channel);
float adc_to_magnetic_field(int adc_value);
void log_data(float magnetic_field);
void signal_handler(int sig);

// SPI initialization function
int spi_init(int bus, int device, int speed) {
    char spi_device[20];
    sprintf(spi_device, "/dev/spidev%d.%d", bus, device);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;
    transfer[0].delay_usecs = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to magnetic field strength (mT)
float adc_to_magnetic_field(int adc_value) {
    float voltage = (float)adc_value / ADC_RESOLUTION * ADC_VREF;
    float magnetic_field = voltage / DRV5055_SENSITIVITY;
    return magnetic_field;
}

// Function to log data to file
void log_data(float magnetic_field) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, magnetic_field);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    terminate = 1;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set CS pin as output
    pinMode(MCP3008_CS_PIN, OUTPUT);
    digitalWrite(MCP3008_CS_PIN, HIGH); // Deselect MCP3008 initially

    // Initialize SPI
    if (spi_init(SPI_BUS, SPI_DEVICE, SPI_SPEED) == -1) {
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting magnetic field monitoring...\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(DRV5055_VOUT_PIN);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to magnetic field strength
        float magnetic_field = adc_to_magnetic_field(adc_value);

        // Log data
        log_data(magnetic_field);

        // Print magnetic field to console
        printf("Magnetic Field: %.2f mT\n", magnetic_field);

        // Wait 500ms
        delay(500);
    }

    // Cleanup
    printf("Cleaning up...\n");
    close(spi_fd);
    fclose(log_file);

    return 0;
}

