#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Function prototypes
int read_sensor(int gpio_pin);
int debounce(int gpio_pin);
void log_state(int sensor1_state, int sensor2_state);
void check_alert(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
        gpioTerminate();
        exit(0);
    }
}

// Function to read the sensor state
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        gpioTerminate();
        exit(1);
    }
    return value;
}

// Function to debounce the sensor
int debounce(int gpio_pin) {
    int count = 0;
    for (int i = 0; i < 5; i++) {
        if (read_sensor(gpio_pin) == 0) {
            count++;
        }
        gpioDelay(2000); // 2 ms delay
    }
    return (count >= 3) ? 0 : 1; // Return 0 if majority is 0, 1 otherwise
}

// Function to log the sensor state
void log_state(int sensor1_state, int sensor2_state) {
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);
}

// Function to check for alert condition
void check_alert(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int sensor1_state = debounce(SENSOR1_GPIO);
        int sensor2_state = debounce(SENSOR2_GPIO);

        log_state(sensor1_state, sensor2_state);
        check_alert(sensor1_state, sensor2_state);

        gpioDelay(1000000); // 1 second delay
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

