#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <driver_library.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
static volatile sig_atomic_t keep_running = 1;
static int spi_handle = -1;

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud_rate;
} spi_config_t;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        keep_running = 0;
        if (spi_handle != -1) {
            spi_close(spi_handle);
        }
        driver_library_terminate();
        exit(0);
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value = -1;

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    if (spi_transfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
        // Extract ADC value
        adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    } else {
        fprintf(stderr, "Error: SPI transfer failed. Retrying in 5 seconds.\n");
        sleep(5);
        return -1; // Indicate error
    }

    return adc_value;
}

// Function to calculate moisture level
double calculate_moisture_level(int adc_value) {
    double moisture_level = 0.0;

    // Ensure ADC value is within the expected range
    if (adc_value < MIN_ADC) {
        adc_value = MIN_ADC;
    } else if (adc_value > MAX_ADC) {
        adc_value = MAX_ADC;
    }

    // Calculate moisture level as a percentage
    moisture_level = 100.0 - ((double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC) * 100.0);

    return moisture_level;
}

// Function to log data to file
int log_data(double moisture_level) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s. Continuing...\n", LOG_FILE);
        return -1; // Indicate error
    }

    // Write data to log file
    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);

    // Close log file
    fclose(fp);

    return 0;
}

// Function to initialize SPI
int spi_setup(spi_config_t config) {
    int handle = spi_open(config.channel, config.baud_rate);
    if (handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d. Exiting...\n", config.channel);
        return -1; // Indicate error
    }
    return handle;
}

int main() {
    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD};
    int adc_value;
    double moisture_level;

    // Initialize driver library
    if (driver_library_initialize() != 0) {
        fprintf(stderr, "Error: Could not initialize driver library. Exiting...\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_handle = spi_setup(spi_config);
    if (spi_handle < 0) {
        driver_library_terminate();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read ADC value from MCP3008
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            continue; // Skip to the next iteration if SPI transfer failed
        }

        // Calculate moisture level
        moisture_level = calculate_moisture_level(adc_value);

        // Log data
        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Error: Could not log data. Continuing...\n");
        }

        // Print data to console
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        printf("%s,%.2f\n", timestamp, moisture_level);

        // Wait for the specified delay
        sleep(READ_DELAY);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spi_close(spi_handle);
    driver_library_terminate();

    return 0;
}

