#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define IMAGE_DIR "/home/pi/security_cam/"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT "JPEG"
#define IMAGE_QUALITY 85

// Global variables
static volatile int running = 1;
static int last_state = 0; // 0: no motion, 1: motion
static unsigned long last_change_time = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
int debounce(int current_state);
int capture_image();
int create_directory(const char *path);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    syslog(LOG_INFO, "GPIO initialized on pin %d", GPIO_PIN);
    return 0;
}

// Read sensor state
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Debounce function
int debounce(int current_state) {
    unsigned long now = gpioTick();
    if (now - last_change_time < DEBOUNCE_DELAY_MS * 1000) {
        return last_state; // Return the last confirmed state
    }

    // Re-read the sensor after the debounce delay
    int reread_state = read_sensor();
    if (reread_state == current_state) {
        last_state = reread_state;
        last_change_time = now;
        return reread_state;
    } else {
        return last_state; // Return the last confirmed state
    }
}

// Capture image using libcamera-still
int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[256];
    char timestamp[32];
    char command[512];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

