#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_DIR "./images"

// Structure to hold camera information
typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffer;
    size_t buffer_size;
    int image_count;
    char device_name[32];
} camera_t;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize a camera
int camera_init(camera_t *camera, const char *device_name) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    camera->fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (camera->fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    strncpy(camera->device_name, device_name, sizeof(camera->device_name) - 1);
    camera->device_name[sizeof(camera->device_name) - 1] = '\0'; // Ensure null termination

    if (ioctl(camera->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(camera->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(camera->fd);
        return -1;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Example width
    fmt.fmt.pix.height = 480; // Example height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY; // Grayscale
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(camera->fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    CLEAR(req);
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera->fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    CLEAR(camera->buf);
    camera->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->buf.memory = V4L2_MEMORY_MMAP;
    camera->buf.index = 0;

    if (ioctl(camera->fd, VIDIOC_QUERYBUF, &camera->buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    camera->buffer_size = camera->buf.length;
    camera->buffer = mmap(NULL, camera->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera->fd, camera->buf.m.offset);
    if (camera->buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(camera->fd);
        return -1;
    }

    return 0;
}

// Function to start streaming
int camera_start_streaming(camera_t *camera) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(camera->fd, VIDIOC_QBUF, &camera->buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(camera->fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to capture an image
int camera_capture(camera_t *camera) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(camera->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(camera->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(camera->fd, VIDIOC_DQBUF, &camera->buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to save an image to a PGM file
int save_image(const camera_t *camera, const void *image_data, size_t image_size) {
    char filename[64];
    snprintf(filename, sizeof(filename), "%s/image_%04d.pgm", IMAGE_DIR, camera->image_count);

    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P2\n"); // PGM format identifier
    fprintf(fp, "%d %d\n", 640, 480); // Image dimensions
    fprintf(fp, "255\n"); // Maximum gray value

    fwrite(image_data, 1, image_size, fp);

    if (ferror(fp)) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to stop streaming
int camera_stop_streaming(camera_t *camera) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(camera->fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to unmap the buffer
int camera_unmap_buffer(camera_t *camera) {
    if (munmap(camera->buffer, camera->buffer_size) < 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to close the device
int camera_close_device(camera_t *camera) {
    if (close(camera->fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    camera_t camera;
    const char *device_name = DEFAULT_DEVICE;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    if (argc > 1) {
        device_name = argv[1];
    }

    // Initialize the camera
    if (camera_init(&camera, device_name) < 0) {
        return EXIT_FAILURE;
    }

    // Start streaming
    if (camera_start_streaming(&camera) < 0) {
        camera_close_device(&camera);
        return EXIT_FAILURE;
    }

    // Main loop
    camera.image_count = 1;
    while (!terminate) {
        // Capture an image
        if (camera_capture(&camera) < 0) {
            fprintf(stderr, "Error capturing image, retrying...\n");
            continue; // Retry capturing the image
        }

        // Save the image
        if (save_image(&camera, camera.buffer, camera.buffer_size) < 0) {
            fprintf(stderr, "Error saving image, retrying...\n");
            continue; // Retry saving the image
        }

        camera.image_count++;

        // Queue the buffer back to the camera
        if (ioctl(camera.fd, VIDIOC_QBUF, &camera.buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            break; // Exit loop on error
        }
    }

    // Stop streaming
    if (camera_stop_streaming(&camera) < 0) {
        fprintf(stderr, "Error stopping streaming during cleanup\n");
    }

    // Unmap the buffer
    if (camera_unmap_buffer(&camera) < 0) {
        fprintf(stderr, "Error unmapping buffer during cleanup\n");
    }

    // Close the device
    if (camera_close_device(&camera) < 0) {
        fprintf(stderr, "Error closing device during cleanup\n");
    }

    return EXIT_SUCCESS;
}

