#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <poll.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define NUM_BUFFERS 4

// Structure to hold video device information
typedef struct {
    int fd;
    struct v4l2_buffer buffers[NUM_BUFFERS];
    void *buffer_start[NUM_BUFFERS];
    int buffer_length[NUM_BUFFERS];
    int num_buffers;
    int current_buffer;
    int frame_count;
    int running;
} video_device_t;

// Global variables
video_device_t video_device;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        video_device.running = 0;
    }
}

// Function to initialize the video device
int init_video_device(video_device_t *device) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int i;

    device->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (device->fd < 0) {
        perror("Error opening video device");
        return -1;
    }

    if (ioctl(device->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(device->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(device->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(device->fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Example width
    fmt.fmt.pix.height = 480; // Example height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(device->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(device->fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(device->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(device->fd);
        return -1;
    }

    device->num_buffers = req.count;

    for (i = 0; i < device->num_buffers; i++) {
        memset(&device->buffers[i], 0, sizeof(device->buffers[i]));
        device->buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        device->buffers[i].memory = V4L2_MEMORY_MMAP;
        device->buffers[i].index = i;

        if (ioctl(device->fd, VIDIOC_QUERYBUF, &device->buffers[i]) < 0) {
            perror("Error querying buffer");
            close(device->fd);
            return -1;
        }

        device->buffer_length[i] = device->buffers[i].length;
        device->buffer_start[i] = mmap(NULL, device->buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, device->fd, device->buffers[i].m.offset);

        if (device->buffer_start[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            close(device->fd);
            return -1;
        }
    }

    return 0;
}

// Function to start capturing video
int start_capturing(video_device_t *device) {
    int i;
    for (i = 0; i < device->num_buffers; i++) {
        if (ioctl(device->fd, VIDIOC_QBUF, &device->buffers[i]) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(device->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(video_device_t *device) {
    struct v4l2_buffer buf;
    struct timeval tv;
    char timestamp[30];

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(device->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    device->current_buffer = buf.index;

    gettimeofday(&tv, NULL);
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv.tv_sec, tv.tv_usec);

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file);

    if (ioctl(device->fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    device->frame_count++;
    return 0;
}

// Function to stop capturing video
int stop_capturing(video_device_t *device) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(device->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to uninitialize the video device
int uninit_video_device(video_device_t *device) {
    int i;

    for (i = 0; i < device->num_buffers; i++) {
        if (munmap(device->buffer_start[i], device->buffer_length[i]) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    if (close(device->fd) < 0) {
        perror("Error closing video device");
        return -1;
    }

    return 0;
}

int main() {
    struct pollfd pfd;
    int ret;

    // Initialize video device
    if (init_video_device(&video_device) < 0) {
        fprintf(stderr, "Failed to initialize video device. Exiting.\n");
        return EXIT_FAILURE;
    }
    video_device.running = 1;

    // Open log file
    log_file = fopen(FRAME_LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        uninit_video_device(&video_device);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(&video_device) < 0) {
        fprintf(stderr, "Failed to start capturing. Exiting.\n");
        fclose(log_file);
        uninit_video_device(&video_device);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Poll for events
    pfd.fd = video_device.fd;
    pfd.events = POLLPRI | POLLERR;

    printf("Capturing frames... Press Ctrl+C to stop.\n");

    while (video_device.running) {
        ret = poll(&pfd, 1, -1); // Wait indefinitely

        if (ret < 0) {
            perror("Error polling");
            break;
        }

        if (ret > 0) {
            if (pfd.revents & POLLPRI) {
                if (capture_frame(&video_device) < 0) {
                    fprintf(stderr, "Error capturing frame. Exiting.\n");
                    break;
                }
            } else if (pfd.revents & POLLERR) {
                fprintf(stderr, "Error: Poll returned error. Exiting.\n");
                break;
            }
        }
    }

    // Stop capturing
    if (stop_capturing(&video_device) < 0) {
        fprintf(stderr, "Failed to stop capturing.\n");
    }

    // Close log file
    if (fclose(log_file) < 0) {
        perror("Error closing log file");
    }

    // Uninitialize video device
    if (uninit_video_device(&video_device) < 0) {
        fprintf(stderr, "Failed to uninitialize video device.\n");
    }

    printf("Captured %d frames.\n", video_device.frame_count);

    return EXIT_SUCCESS;
}

