#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <sys/time.h>
#include <stdint.h>

#define DEVICE_NAME "/dev/video0"
#define IP_ADDRESS "127.0.0.1"
#define PORT 5000
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define NUM_BUFFERS 4
#define MAX_UDP_PACKET_SIZE 65000

// Structure to hold camera parameters
typedef struct {
    int fd;
    struct v4l2_buffer buffers[NUM_BUFFERS];
    void *buffer_start[NUM_BUFFERS];
    int buffer_length[NUM_BUFFERS];
    int frame_index;
    int running;
} camera_params_t;

// Structure to hold UDP parameters
typedef struct {
    int sockfd;
    struct sockaddr_in servaddr;
} udp_params_t;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
    // Add code here to release resources and stop streaming
    exit(signum);
}

// Function to initialize the camera
int init_camera(camera_params_t *params) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int i;

    params->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (params->fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(params->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(params->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(params->fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(params->fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(params->fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(params->fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(params->fd);
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(params->fd);
        return -1;
    }

    for (i = 0; i < NUM_BUFFERS; i++) {
        memset(&params->buffers[i], 0, sizeof(params->buffers[i]));
        params->buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        params->buffers[i].memory = V4L2_MEMORY_MMAP;
        params->buffers[i].index = i;

        if (ioctl(params->fd, VIDIOC_QUERYBUF, &params->buffers[i]) < 0) {
            perror("Error querying buffer");
            close(params->fd);
            return -1;
        }

        params->buffer_start[i] = mmap(NULL, params->buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, params->fd, params->buffers[i].m.offset);
        if (params->buffer_start[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            close(params->fd);
            return -1;
        }
        params->buffer_length[i] = params->buffers[i].length;
    }

    params->frame_index = 0;
    params->running = 1;

    return 0;
}

// Function to initialize the UDP socket
int init_udp_socket(udp_params_t *params) {
    params->sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (params->sockfd < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&params->servaddr, 0, sizeof(params->servaddr));
    params->servaddr.sin_family = AF_INET;
    params->servaddr.sin_port = htons(PORT);
    if (inet_pton(AF_INET, IP_ADDRESS, &params->servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(params->sockfd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(camera_params_t *params) {
    struct v4l2_buffer buf;
    int i;

    for (i = 0; i < NUM_BUFFERS; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(params->fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(params->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(params->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(params->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(params->fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return buf.index;
}

// Function to fragment a frame into UDP packets
int fragment_frame(camera_params_t *camera_params, udp_params_t *udp_params, int buffer_index) {
    unsigned char *frame_data = (unsigned char *)camera_params->buffer_start[buffer_index];
    int frame_size = camera_params->buffer_length[buffer_index];
    int total_fragments = (frame_size + MAX_UDP_PACKET_SIZE - 1) / MAX_UDP_PACKET_SIZE;
    int fragment_index = 0;
    int bytes_left = frame_size;
    int offset = 0;
    unsigned char header[12];
    unsigned char packet[MAX_UDP_PACKET_SIZE];
    int packet_size;

    while (bytes_left > 0) {
        // Construct the header
        memcpy(header, &camera_params->frame_index, sizeof(int));
        memcpy(header + sizeof(int), &fragment_index, sizeof(int));
        memcpy(header + 2 * sizeof(int), &total_fragments, sizeof(int));
        memcpy(header + 3 * sizeof(int), &frame_size, sizeof(int));

        // Determine the payload size for this packet
        packet_size = (bytes_left > MAX_UDP_PACKET_SIZE - 12) ? MAX_UDP_PACKET_SIZE - 12 : bytes_left;

        // Copy the header and payload into the packet
        memcpy(packet, header, 12);
        memcpy(packet + 12, frame_data + offset, packet_size);

