// Function to initialize the camera
int init_camera(camera_params_t *params) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int i;

    params->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (params->fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(params->fd, VIDIOC_QUERYCAP, &cap) < 0) {
