// Global camera information
camera_info_t camera_info;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("\nCaught signal %d, stopping streaming and cleaning up...\n", signum);

    // Stop streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera_info.fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF failed");
    }

    // Unmap buffers
    for (int i = 0; i < camera_info.n_buffers; ++i) {
        if (munmap(camera_info.buffer_start[i], camera_info.buffers[i].length) == -1) {
            perror("munmap failed");
        }
    }

    // Free buffer array
    free(camera_info.buffers);
    free(camera_info.buffer_start);

    // Close device file descriptor
    if (close(camera_info.fd) == -1) {
        perror("close failed");
    }

    exit(0);
