// Function to initialize the camera
int init_camera(camera_info_t *info) {
    info->fd = open(DEVICE_NAME, O_RDWR);
    if (info->fd == -1) {
        perror("open failed");
        return -1;
    }

    // Check device capabilities
    struct v4l2_capability cap;
    if (ioctl(info->fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP failed");
        close(info->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(info->fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(info->fd);
        return -1;
    }

    // Set pixel format
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 192; // Use the documented value
    fmt.fmt.pix.height = 192; // Use the documented value
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(info->fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT failed");
        close(info->fd);
        return -1;
    }

    // Request buffers
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(info->fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS failed");
        close(info->fd);
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(info->fd);
        return -1;
    }

    info->buffers = calloc(req.count, sizeof(*info->buffers));
    info->buffer_start = calloc(req.count, sizeof(*info->buffer_start));

    if (!info->buffers || !info->buffer_start) {
        perror("calloc failed");
        close(info->fd);
        free(info->buffers);
        free(info->buffer_start);
        return -1;
    }

    info->n_buffers = req.count;

    for (int i = 0; i < info->n_buffers; ++i) {
        memset(&info->buffers[i], 0, sizeof(info->buffers[i]));
        info->buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        info->buffers[i].memory = V4L2_MEMORY_MMAP;
        info->buffers[i].index = i;

        if (ioctl(info->fd, VIDIOC_QUERYBUF, &info->buffers[i]) == -1) {
            perror("VIDIOC_QUERYBUF failed");
            close(info->fd);
            free(info->buffers);
            free(info->buffer_start);
            return -1;
        }

        info->buffer_start[i] = mmap(NULL, info->buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, info->fd, info->buffers[i].m.offset);

        if (info->buffer_start[i] == MAP_FAILED) {
            perror("mmap failed");
            close(info->fd);
            free(info->buffers);
            free(info->buffer_start);
            return -1;
        }
    }

    // Queue buffers
    for (int i = 0; i < info->n_buffers; ++i) {
        if (ioctl(info->fd, VIDIOC_QBUF, &info->buffers[i]) == -1) {
            perror("VIDIOC_QBUF failed");
            close(info->fd);
            free(info->buffers);
            free(info->buffer_start);
            return -1;
        }
    }

    // Start streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(info->fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON failed");
        close(info->fd);
        free(info->buffers);
        free(info->buffer_start);
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(camera_info_t *info) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(info->fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    info->bytesused = buf.bytesused;

    if (ioctl(info->fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF failed");
        return -1;
    }

    return 0;
}

// Function to write the captured frame to a file
int write_frame_to_file(const camera_info_t *info) {
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        perror("fopen failed");
        return -1;
    }

    if (fwrite(info->buffer_start[0], 1, info->bytesused, fp) != info->bytesused) {
        perror("fwrite failed");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) == -1) {
        perror("fclose failed");
        return -1;
    }

    return 0;
}

