    for (int i = 0; i < info->n_buffers; ++i) {
        memset(&info->buffers[i], 0, sizeof(info->buffers[i]));
        info->buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        info->buffers[i].memory = V4L2_MEMORY_MMAP;
        info->buffers[i].index = i;

        if (ioctl(info->fd, VIDIOC_QUERYBUF, &info->buffers[i]) == -1) {
            perror("VIDIOC_QUERYBUF failed");
            close(info->fd);
            free(info->buffers);
            free(info->buffer_start);
            return -1;
        }

        info->buffer_start[i] = mmap(NULL, info->buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, info->fd, info->buffers[i].m.offset);

        if (info->buffer_start[i] == MAP_FAILED) {
            perror("mmap failed");
            close(info->fd);
            free(info->buffers);
            free(info->buffer_start);
            return -1;
        }
    }

    // Queue buffers
    for (int i = 0; i < info->n_buffers; ++i) {
        if (ioctl(info->fd, VIDIOC_QBUF, &info->buffers[i]) == -1) {
            perror("VIDIOC_QBUF failed");
            close(info->fd);
            free(info->buffers);
            free(info->buffer_start);
            return -1;
        }
    }

    // Start streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(info->fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON failed");
        close(info->fd);
        free(info->buffers);
        free(info->buffer_start);
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame(camera_info_t *info) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(info->fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    info->bytesused = buf.bytesused;

    if (ioctl(info->fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF failed");
        return -1;
    }

    return 0;
}

// Function to write the captured frame to a file
int write_frame_to_file(const camera_info_t *info) {
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        perror("fopen failed");
        return -1;
    }

    if (fwrite(info->buffer_start[0], 1, info->bytesused, fp) != info->bytesused) {
        perror("fwrite failed");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) == -1) {
        perror("fclose failed");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the camera
    if (init_camera(&camera_info) == -1) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    // Capture a single frame
    if (capture_frame(&camera_info) == -1) {
        fprintf(stderr, "Frame capture failed\n");
        signal_handler(SIGTERM); // Simulate a signal to clean up
        return 1;
    }

    // Write the frame to a file
    if (write_frame_to_file(&camera_info) == -1) {
        fprintf(stderr, "Failed to write frame to file\n");
        signal_handler(SIGTERM); // Simulate a signal to clean up
        return 1;
    }

    printf("Image captured and saved to %s\n", IMAGE_FILE);

    // Clean up resources (this part is reached only if the previous steps succeed)
    signal_handler(SIGTERM); // Call the signal handler to clean up

    return 0;
}

