// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// Define PWM parameters
#define PWM_FREQUENCY 50
#define PWM_PERIOD 20000 // 20ms in microseconds
#define PWM_MIN_WIDTH 1000 // 1ms in microseconds
#define PWM_MAX_WIDTH 2000 // 2ms in microseconds
#define PWM_RANGE 1000

// Define servo positions
#define SERVO_MID_POSITION 75
#define SERVO_MIN_POSITION 25
#define SERVO_MAX_POSITION 125

// Global variables
volatile sig_atomic_t terminate = 0;
int pan_position = SERVO_MID_POSITION;
int tilt_position = SERVO_MID_POSITION;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_servo_position(int pin, int position);
int read_button(int pin);
void update_pan_position(int direction);
void update_tilt_position(int direction);
void cleanup_gpio();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON, PI_PUD_UP);

    // Initialize servos to mid-position
    set_servo_position(PAN_SERVO_PIN, SERVO_MID_POSITION);
    set_servo_position(TILT_SERVO_PIN, SERVO_MID_POSITION);

    return 0;
}

// Set servo position
void set_servo_position(int pin, int position) {
    int pulse_width = PWM_MIN_WIDTH + (position - SERVO_MIN_POSITION) * (PWM_MAX_WIDTH - PWM_MIN_WIDTH) / (SERVO_MAX_POSITION - SERVO_MIN_POSITION);
    gpioPWM(pin, pulse_width);
}

// Read button state
int read_button(int pin) {
    return gpioRead(pin);
}

// Update pan position
void update_pan_position(int direction) {
    pan_position += direction;
    if (pan_position < SERVO_MIN_POSITION) {
        pan_position = SERVO_MIN_POSITION;
    } else if (pan_position > SERVO_MAX_POSITION) {
        pan_position = SERVO_MAX_POSITION;
    }
    set_servo_position(PAN_SERVO_PIN, pan_position);
}

// Update tilt position
void update_tilt_position(int direction) {
    tilt_position += direction;
    if (tilt_position < SERVO_MIN_POSITION) {
        tilt_position = SERVO_MIN_POSITION;
    } else if (tilt_position > SERVO_MAX_POSITION) {
        tilt_position = SERVO_MAX_POSITION;
    }
    set_servo_position(TILT_SERVO_PIN, tilt_position);
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Pan-Tilt control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read button states
        int tilt_up = read_button(TILT_UP_BUTTON);
        int tilt_down = read_button(TILT_DOWN_BUTTON);
        int pan_left = read_button(PAN_LEFT_BUTTON);
        int pan_right = read_button(PAN_RIGHT_BUTTON);

        // Update servo positions based on button presses
        if (tilt_up == 0) {
            update_tilt_position(1);
        }
        if (tilt_down == 0) {
            update_tilt_position(-1);
        }
        if (pan_left == 0) {
            update_pan_position(-1);
        }
        if (pan_right == 0) {
            update_pan_position(1);
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("Program terminated.\n");
    return 0;
}

