#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <jpeglib.h>
#include <setjmp.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define BLUR_SIZE 3

// Structure to hold camera parameters
typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *buffers[NUM_BUFFERS];
    size_t buffer_sizes[NUM_BUFFERS];
    int buffer_index;
    int streaming;
} camera_params_t;

// Global camera parameters
camera_params_t camera_params = {0};

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        // Stop streaming if it's running
        if (camera_params.streaming) {
            camera_params.buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            camera_params.buf.memory = V4L2_MEMORY_MMAP;
            if (ioctl(camera_params.fd, VIDIOC_STREAMOFF, &camera_params.buf) == -1) {
                perror("VIDIOC_STREAMOFF failed");
            }
            camera_params.streaming = 0;
        }

        // Unmap and free buffers
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (camera_params.buffers[i] != NULL) {
                if (munmap(camera_params.buffers[i], camera_params.buffer_sizes[i]) == -1) {
                    perror("munmap failed");
                }
                camera_params.buffers[i] = NULL;
            }
        }

        // Close device
        if (camera_params.fd != 0) {
            close(camera_params.fd);
        }

        exit(0);
    }
}

// Function to open the camera device
int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening camera device");
        return -1;
    }
    return fd;
}

// Function to set camera format
int set_camera_format(int fd, int width, int height) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting camera format");
        return -1;
    }

    // Verify the format is what we requested
    if (fmt.fmt.pix.width != width || fmt.fmt.pix.height != height || fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Warning: Camera format not fully supported.\n");
    }

    return 0;
}

// Function to request and map buffers
int request_and_map_buffers(int fd, void **buffers, size_t *buffer_sizes) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
        buffer_sizes[i] = buf.length;
    }

    return 0;
}

// Function to queue a buffer
int queue_buffer(int fd, void *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.length = buffer_size;
    buf.m.offset = (off_t)buffer;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting streaming");
        return -1;
    }
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    *buffer = camera_params.buffers[buf.index];
    *buffer_size = camera_params.buffer_sizes[buf.index];

    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping streaming");
        return -1;
    }
    return 0;
}

// Function to unmap and free buffers
int unmap_and_free_buffers(int fd, void **buffers, size_t *buffer_sizes) {
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (buffers[i] != NULL) {
            if (munmap(buffers[i], buffer_sizes[i]) == -1) {
                perror("Error unmapping buffer");
                return -1;
            }
            buffers[i] = NULL;
        }
    }
    return 0;
}

// Function to close the camera device
int close_camera(int fd) {
    if (close(fd) == -1) {
        perror("Error closing camera device");
        return -1;
    }
    return 0;
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    int i, j;
    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            unsigned char Y1 = yuyv[i * width * 2 + j * 2 + 0];
            unsigned char U = yuyv[i * width * 2 + j * 2 + 1];
            unsigned char Y2 = yuyv[i * width * 2 + j * 2 + 2];
            unsigned char V = yuyv[i * width * 2 + j * 2 + 3];

            int C = Y1 - 16;
            int D = U - 128;
            int E = V - 128;

            int R1 = (298 * C + 409 * E + 128) >> 8;
            int G1 = (298 * C - 100 * D - 208 * E + 128) >> 8;
            int B1 = (298 * C + 516 * D + 128) >> 8;

            int R2 = (298 * C + 409 * E + 128) >> 8;
            int G2 = (298 * C - 100 * D - 208 * E + 128) >> 8;
            int B2 = (298 * C + 516 * D + 128) >> 8;

            if (R1 < 0) R1 = 0; if (R1 > 255) R1 = 255;
            if (G1 < 0) G1 = 0; if (G1 > 255) G1 = 255;
            if (B1 < 0) B1 = 0; if (B1 > 255) B1 = 255;
            if (R2 < 0) R2 = 0; if (R2 > 255) R2 = 255;
            if (G2 < 0) G2 = 0; if (G2 > 255) G2 = 255;
            if (B2 < 0) B2 = 0; if (B2 > 255) B2 = 255;

            rgb[(i * width + j) * 3 + 0] = R1;
            rgb[(i * width + j) * 3 + 1] = G1;
            rgb[(i * width + j) * 3 + 2] = B1;
            rgb[(i * width + j + 1) * 3 + 0] = R2;
            rgb[(i * width + j + 1) * 3 + 1] = G2;
            rgb[(i * width + j + 1) * 3 + 2] = B2;
        }
    }
}

// Function to apply a blur filter
void blur_image(unsigned char *rgb, int width, int height) {
    unsigned char *temp = malloc(width * height * 3);
    if (temp == NULL) {
        perror("Failed to allocate memory for temp buffer");
        return;
    }

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int r = 0, g = 0, b = 0;
            int count = 0;

            for (int i = -BLUR_SIZE; i <= BLUR_SIZE; i++) {
                for (int j = -BLUR_SIZE; j <= BLUR_SIZE; j++) {
                    int nx = x + i;
                    int ny = y + j;

                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        r += rgb[(ny * width + nx) * 3 + 0];
                        g += rgb[(ny * width + nx) * 3 + 1];
                        b += rgb[(ny * width + nx) * 3 + 2];
                        count++;
                    }
                }
            }

            temp[(y * width + x) * 3 + 0] = r / count;
            temp[(y * width + x) * 3 + 1] = g / count;
            temp[(y * width + x) * 3 + 2] = b / count;
        }
    }

    memcpy(rgb, temp, width * height * 3);
    free(temp);
}

// Function to encode RGB24 image to JPEG
int encode_jpeg(unsigned char *rgb, int width, int height, const char *filename, int quality) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "can't open %s\n", filename);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
