#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl queryctrl;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        perror("Error opening device");
        return 1;
    }

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    printf("Device name: %s\n", cap.card);
    printf("Driver version: %s\n", cap.driver);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Capabilities: 0x%08x\n", cap.capabilities);

    // Enumerate supported formats
    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    printf("\nSupported Formats:\n");
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) != -1) {
        printf("  %d. %s\n", fmtdesc.index + 1, fmtdesc.description);
        fmtdesc.index++;
    }

    // Enumerate supported frame sizes
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Choose a format
    printf("\nSupported Frame Sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) != -1) {
        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %d. %dx%d\n", frmsize.index + 1, frmsize.discrete.width, frmsize.discrete.height);
            // Enumerate frame intervals
            frmival.index = 0;
            frmival.pixel_format = V4L2_PIX_FMT_YUYV; // Choose the same format
            frmival.width = frmsize.discrete.width;
            frmival.height = frmsize.discrete.height;
            printf("    Frame Intervals:\n");
            while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) != -1) {
                if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                    printf("      %d. %d/%d fps\n", frmival.index + 1, frmival.discrete.numerator, frmival.discrete.denominator);
                }
                frmival.index++;
            }
        } else if (frmsize.type == V4L2_FRMSIZE_TYPE_CONTINUOUS) {
            printf("  %d. Continuous mode: Min %dx%d, Max %dx%d\n", frmsize.index + 1, frmsize.continuous.min_width, frmsize.continuous.min_height, frmsize.continuous.max_width, frmsize.continuous.max_height);
        } else if (frmsize.type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            printf("  %d. Stepwise mode: Min %dx%d, Max %dx%d, Step %dx%d\n", frmsize.index + 1, frmsize.stepwise.min_width, frmsize.stepwise.min_height, frmsize.stepwise.max_width, frmsize.stepwise.max_height, frmsize.stepwise.step_width, frmsize.stepwise.step_height);
        }
        frmsize.index++;
    }

    // Check for autofocus capability
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("\nAutofocus Capability: Supported\n");
    } else {
        printf("\nAutofocus Capability: Not Supported\n");
    }

    close(fd);
    return 0;
}

