#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

// Global variables for pulse width
static volatile int pan_pulse_width = CENTER_PULSE_WIDTH;
static volatile int tilt_pulse_width = CENTER_PULSE_WIDTH;

// Function prototypes
void set_pan_pulse_width(int pulse_width);
void set_tilt_pulse_width(int pulse_width);
void handle_button_press(int button_pin, int *pulse_width, int increment);
void signal_handler(int signal);

// Function to set pan servo pulse width
void set_pan_pulse_width(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }
    gpioPWM(PAN_SERVO_PIN, pulse_width);
    pan_pulse_width = pulse_width; // Update global variable
}

// Function to set tilt servo pulse width
void set_tilt_pulse_width(int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }
    gpioPWM(TILT_SERVO_PIN, pulse_width);
    tilt_pulse_width = pulse_width; // Update global variable
}

// Function to handle button press
void handle_button_press(int button_pin, int *pulse_width, int increment) {
    if (gpioRead(button_pin) == 0) { // Button is pressed (active low)
        *pulse_width += increment;
        if (button_pin == UP_BUTTON_PIN || button_pin == DOWN_BUTTON_PIN) {
            set_tilt_pulse_width(*pulse_width);
        } else {
            set_pan_pulse_width(*pulse_width);
        }
        gpioDelay(100); // Debounce delay
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    gpioPWM(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set initial pulse widths
    set_pan_pulse_width(CENTER_PULSE_WIDTH);
    set_tilt_pulse_width(CENTER_PULSE_WIDTH);

    // Print startup message
    printf("Pan-Tilt Control Program\n");
    printf("Pan Servo: GPIO %d, Tilt Servo: GPIO %d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("UP: GPIO %d, DOWN: GPIO %d, LEFT: GPIO %d, RIGHT: GPIO %d\n", UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN);
    printf("Center Position: Pan = %d us, Tilt = %d us\n", CENTER_PULSE_WIDTH, CENTER_PULSE_WIDTH);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        handle_button_press(UP_BUTTON_PIN, &tilt_pulse_width, 10);
        handle_button_press(DOWN_BUTTON_PIN, &tilt_pulse_width, -10);
        handle_button_press(LEFT_BUTTON_PIN, &pan_pulse_width, -10);
        handle_button_press(RIGHT_BUTTON_PIN, &pan_pulse_width, 10);
        gpioDelay(50); // Delay for 50ms
    }

    return 0;
}

