            long time_diff_ms = (now.tv_sec - last_motion_time.tv_sec) * 1000 + (now.tv_nsec - last_motion_time.tv_nsec) / 1000000;

            if (current_state == 1) {
                if (time_diff_ms >= config.debounce_time) {
                    pthread_mutex_lock(&motion_mutex);
                    motion_detected = 1;
                    pthread_mutex_unlock(&motion_mutex);

                    if (capture_image(filename) == 0) {
                        if (get_iso8601_timestamp(timestamp) == 0) {
                            if (create_json_payload(filename, timestamp, "motion", "GPIO17", json_string) == 0) {
                                if (post_data(json_string, filename) != 0) {
                                    fprintf(stderr, "Error posting data.\n");
                                }
                            } else {
                                fprintf(stderr, "Error creating JSON payload.\n");
                            }
                        } else {
                            fprintf(stderr, "Error getting timestamp.\n");
                        }
                    } else {
                        fprintf(stderr, "Error capturing image.\n");
                    }
                }
            }
            last_state = current_state;
            clock_gettime(CLOCK_MONOTONIC, &last_motion_time);
        }

        gpioDelay(100); // Poll every 100ms
    }

    cleanup();
    return 0;
}

int init_config(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP address> <port>\n", argv[0]);
        return 1;
    }

    strncpy(config.ip_address, argv[1], sizeof(config.ip_address) - 1);
    config.ip_address[sizeof(config.ip_address) - 1] = '\0'; // Ensure null termination
    config.port = atoi(argv[2]);
    config.gpio_pin = GPIO_PIN;
    config.debounce_time = DEBOUNCE_TIME;
    config.image_quality = IMAGE_QUALITY;
    strncpy(config.capture_dir, MOTION_CAPTURE_DIR, sizeof(config.capture_dir) - 1);
    config.capture_dir[sizeof(config.capture_dir) - 1] = '\0';

    return 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.gpio_pin, PI_INPUT);
    gpioSetPullUpDown(config.gpio_pin, PI_PUD_DOWN);

    return 0;
}

int init_http() {
    // HTTP initialization is handled by libcurl during the first POST request
    return 0;
}

int capture_image(char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 100, "%Y%m%d_%H%M%S", timeinfo);
    char command[200];
    snprintf(command, sizeof(command), "libcamera-still -o %s/%s.jpg --width 640 --height 480 --quality %d", config.capture_dir, filename, config.image_quality);

    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return 1;
    }
    if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still exited with status %d\n", WEXITSTATUS(status));
        return 1;
    }

    return 0;
}

int create_json_payload(char *filename, char *timestamp, char *status, char *gpio_pin, char *json_string) {
    json_t *root = json_object();
    json_object_set_new(root, "filename", json_string(filename));
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "status", json_string(status));
    json_object_set_new(root, "gpio_pin", json_string(gpio_pin));

    size_t json_len = json_dumpb(root, json_string, 0, JSON_REAL_PRECISION(5));
    if (json_len == 0) {
        fprintf(stderr, "Error creating JSON string.\n");
        json_decref(root);
        return 1;
    }

    json_decref(root);
    return 0;
}

int post_data(char *json_string, char *filename) {
    CURL *curl;
    CURLcode res;
    char url[200];
    snprintf(url, sizeof(url), "http://%s:%d/upload", config.ip_address, config.port);

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        // Set Content-Type header to application/json
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        // Set the filename for the file upload
        char filepath[200];
        snprintf(filepath, sizeof(filepath), "%s/%s.jpg", config.capture_dir, filename);
        curl_easy_setopt(curl, CURLOPT_UPLOAD, 1L);
        curl_easy_setopt(curl, CURLOPT_READFUNCTION, NULL); // Use default read function
        curl_easy_setopt(curl, CURLOPT_INFILENAME, filepath);
        curl_easy_setopt(curl, CURLOPT_INFILESIZE, (long)1024); // Dummy size, libcurl will get the file size

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : 1;
}

int create_motion_capture_directory() {
    if (mkdir(config.capture_dir, 0777) == -1) {
        if (errno == EEXIST) {
            // Directory already exists, no error
            return 0;
        } else {
            perror("mkdir() failed");
            return 1;
        }
    }
    return 0;
}

int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 50, "%Y-%m-%dT%H:%M:%S", timeinfo);
    long milliseconds = 0; // Placeholder for microseconds
    snprintf(timestamp + strlen(timestamp), 50 - strlen(timestamp), ".%03ldZ", milliseconds);

    return 0;
}

void cleanup() {
    running = 0;
    gpioTerminate();
    pthread_mutex_destroy(&motion_mutex);
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Shutting down...\n", signal);
    cleanup();
    exit(0);
}

