#include <errno.h>

// Configuration
#define GPIO_PIN 17
#define SPI_DEVICE "/dev/spidev0.0"
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_DELAY_MS 50
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JPEG_QUALITY 85
#define CAPTURE_TIMEOUT_MS 2000
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
static volatile int running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_spi();
int capture_image(char *filename);
int log_message(const char *message);
int debounce();
int read_mcp3008(int channel);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor
    gpioSetAlertFunc(GPIO_PIN, debounce); // Set debounce function

    log_message("GPIO initialised");
    return 0;
}

// Initialize SPI
int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_message("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode and speed
    int mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        log_message("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        log_message("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    log_message("SPI initialised");
    return 0;
}

// Capture image using raspistill
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s/%s -w %d -h %d -q %d --timeout %d --nopreview", IMAGE_DIR, filename, IMAGE_WIDTH, IMAGE_HEIGHT, JPEG_QUALITY, CAPTURE_TIMEOUT_MS);

    log_message("Capturing image...");
    int status = system(command);

    if (status == 0) {
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Image captured: %s/%s", IMAGE_DIR, filename);
        log_message(log_message_buffer);
        return 0;
    } else {
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Failed to capture image (status %d)", status);
        log_message(log_message_buffer);
        return -1;
    }
}

// Log message with timestamp
int log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Debounce function
int debounce() {
    static unsigned int last_tick = 0;
    unsigned int current_tick = gpioTick();

    if (current_tick - last_tick < DEBOUNCE_DELAY_MS * 1000) {
        return 0; // Ignore the event
    }

    last_tick = current_tick;

    // Read light sensor value
    int light_level = read_mcp3008(0);
    if (light_level < 0) {
        log_message("Error reading light sensor");
        return 0;
    }

    // Generate filename
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[64];
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%03d.jpg", t);
    snprintf(filename + strlen(filename), 64 - strlen(filename), "%03d", light_level);

    // Capture image
    if (capture_image(filename) != 0) {
        log_message("Failed to capture image after debounce");
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Invalid MCP3008 channel");
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        log_message("SPI transfer failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    log_message("Starting motion capture program");

    // Initialize GPIO
    if (init_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program running, waiting for motion...");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup
    log_message("Cleaning up...");
    gpioTerminate();
    if (spi_fd != -1) {
        close(spi_fd);
    }
    fclose(log_file);

    log_message("Exiting");
    return 0;
}

