#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define FORMAT V4L2_PIX_FMT_YUYV
#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

static int fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;
static FILE *output_file = NULL;
static volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    stop_flag = 1;
    fprintf(stderr, "Signal received, stopping...\n");
}

int init_camera() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        close(fd);
        return -1;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(fd);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        munmap(buffer, buffer_size);
        close(fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        munmap(buffer, buffer_size);
        close(fd);
        return -1;
    }

    return 0;
}

int capture_frame() {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // 2-second timeout
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        perror("Error in select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (buf.length != buffer_size || buf.bytesused != buffer_size) {
        fprintf(stderr, "Frame size mismatch: length=%zu, bytesused=%u\n", buf.length, buf.bytesused);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

int crop_and_write() {
    unsigned char *src = (unsigned char *)buffer;
    unsigned char *dst = (unsigned char *)malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (dst == NULL) {
        perror("Error allocating memory for cropped frame");
        return -1;
    }

    // Crop YUYV data
    for (int i = 0; i < CROP_HEIGHT; i++) {
        memcpy(dst + i * CROP_WIDTH * 2, src + (i * WIDTH + (WIDTH - CROP_WIDTH) / 2) * 2, CROP_WIDTH * 2);
    }

    output_file = fopen("cropped.yuv", "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        free(dst);
        return -1;
    }

    size_t bytes_written = fwrite(dst, 1, CROP_WIDTH * CROP_HEIGHT * 2, output_file);
    if (bytes_written != CROP_WIDTH * CROP_HEIGHT * 2) {
        perror("Error writing to output file");
        fclose(output_file);
        free(dst);
        return -1;
    }

    free(dst);
    return 0;
}

int stop_camera() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    if (munmap(buffer, buffer_size) < 0) {
        perror("Error unmapping buffer");
        return -1;
    }

    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }

    if (output_file != NULL) {
        if (fclose(output_file) < 0) {
            perror("Error closing output file");
            return -1;
        }
    }

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_camera() < 0) {
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        if (capture_frame() < 0) {
            break;
        }

        if (crop_and_write() < 0) {
            break;
        }
    }

    if (stop_camera() < 0) {
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

