#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servo motors
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define neutral position (90 degrees)
#define NEUTRAL_POSITION 90

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define angle increment/decrement
#define ANGLE_INCREMENT 5

// Global variables for current angles
int pan_angle = NEUTRAL_POSITION;
int tilt_angle = NEUTRAL_POSITION;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int pin, int angle);
int read_input(int *pan_increment, int *tilt_increment);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set initial servo positions to neutral
    if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_POSITION) != 0) {
        fprintf(stderr, "Failed to set initial pan servo position\n");
        gpioTerminate();
        return 1;
    }
    if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_POSITION) != 0) {
        fprintf(stderr, "Failed to set initial tilt servo position\n");
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Set servo angle using pigpio
int set_servo_angle(int pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d)\n", angle);
        return 1; // Indicate failure
    }

    // Calculate pulse width (assuming 1000us - 2000us for 0-180 degrees)
    int pulse_width = (int)(1000 + (angle / 180.0) * 1000);

    // Set PWM duty cycle
    gpioPWM(pin, pulse_width);

    return 0; // Indicate success
}

// Read input from stdin
int read_input(int *pan_increment, int *tilt_increment) {
    int input;

    *pan_increment = 0;
    *tilt_increment = 0;

    input = getchar();

    switch (input) {
        case 'a': // Left arrow
            *pan_increment = -ANGLE_INCREMENT;
            break;
        case 'd': // Right arrow
            *pan_increment = ANGLE_INCREMENT;
            break;
        case 'w': // Up arrow
            *tilt_increment = ANGLE_INCREMENT;
            break;
        case 's': // Down arrow
            *tilt_increment = -ANGLE_INCREMENT;
            break;
        case 'q': // Quit
            return 1; // Indicate quit
        default:
            // Ignore other input
            break;
    }

    return 0; // Indicate continue
}

// Cleanup GPIO using pigpio
void cleanup_gpio() {
    // Set servos to neutral position
    set_servo_angle(PAN_SERVO_PIN, NEUTRAL_POSITION);
    set_servo_angle(TILT_SERVO_PIN, NEUTRAL_POSITION);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit with error code
    }

    int quit = 0;
    int pan_increment, tilt_increment;

    printf("Use arrow keys to control servos. Press 'q' to quit.\n");

    while (!quit) {
        // Read input
        if (read_input(&pan_increment, &tilt_increment) == 1) {
            quit = 1; // Quit if 'q' is pressed
            break;
        }

        // Update angles
        pan_angle += pan_increment;
        tilt_angle += tilt_increment;

        // Clamp angles to limits
        if (pan_angle < MIN_ANGLE) pan_angle = MIN_ANGLE;
        if (pan_angle > MAX_ANGLE) pan_angle = MAX_ANGLE;
        if (tilt_angle < MIN_ANGLE) tilt_angle = MIN_ANGLE;
        if (tilt_angle > MAX_ANGLE) tilt_angle = MAX_ANGLE;

        // Set servo angles
        if (set_servo_angle(PAN_SERVO_PIN, pan_angle) != 0) {
            fprintf(stderr, "Error setting pan servo angle\n");
        }
        if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) != 0) {
            fprintf(stderr, "Error setting tilt servo angle\n");
        }

        // Delay
        gpioDelay(100); // 100ms delay
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

