    if (i2c_write_command(fd, 0xD9) < 0) return -1; // Set pre-charge period
    if (i2c_write_command(fd, 0xF1) < 0) return -1; // --period
    if (i2c_write_command(fd, 0xDB) < 0) return -1; // Set VCOM deselect level
    if (i2c_write_command(fd, 0x40) < 0) return -1; // --level
    if (i2c_write_command(fd, 0xA4) < 0) return -1; // Display all points off
    if (i2c_write_command(fd, 0xA6) < 0) return -1; // Set normal display
    if (i2c_write_command(fd, 0xAF) < 0) return -1; // Display on
    return 0;
}

// SSD1306 clear display function
int ssd1306_clear_display(int fd) {
    for (int i = 0; i < SSD1306_WIDTH * (SSD1306_HEIGHT / 8); i++) {
        if (i2c_write_data(fd, 0x00) < 0) return -1;
    }
    return 0;
}

// SSD1306 display string function
int ssd1306_display_string(int fd, int x, int y, const char *string) {
    int i, j, k;
    unsigned char c;

    // Calculate the starting page and column
    int page = y / 8;
    int col = x;

    // Set the column and page address
    if (i2c_write_command(fd, 0xB0 + page) < 0) return -1; // Set page address
    if (i2c_write_command(fd, 0x00 + (col & 0x0F)) < 0) return -1; // Set lower column address
    if (i2c_write_command(fd, 0x10 + ((col >> 4) & 0x0F)) < 0) return -1; // Set higher column address

    // Display each character
    while (*string) {
        c = *string++;
        if (c < 32 || c > 126) c = 0; // Handle out-of-range characters
        c -= 32; // Adjust index to font array

        for (i = 0; i < FONT_WIDTH; i++) {
            unsigned char data = font[c][i];
            for (j = 0; j < FONT_HEIGHT; j++) {
                if ((data >> j) & 0x01) {
                    // Calculate the page and column for each pixel
                    int pixel_page = page + j;
                    int pixel_col = col + i;

                    // Set the page address
                    if (i2c_write_command(fd, 0xB0 + pixel_page) < 0) return -1;

                    // Set the column address
                    if (i2c_write_command(fd, 0x00 + (pixel_col & 0x0F)) < 0) return -1;
                    if (i2c_write_command(fd, 0x10 + ((pixel_col >> 4) & 0x0F)) < 0) return -1;

                    // Write the pixel data
                    if (i2c_write_data(fd, 0xFF) < 0) return -1;
                }
            }
        }
        col += FONT_WIDTH + 1; // Move to the next character position
    }
    return 0;
}

// Read CPU temperature function
int read_cpu_temp(float *temp) {
    int fd;
    char buffer[10];
    float temp_celsius;

    fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buffer, sizeof(buffer)) < 0) {
        fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);

    temp_celsius = atoi(buffer) / 1000.0;
    *temp = temp_celsius;

    return 0;
}

// Read CPU usage function
int read_cpu_usage(float *usage) {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0;
    static unsigned long long prev_idle_total = 0;
    float cpu_usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;

    if (prev_total != 0) {
        unsigned long long total_diff = total - prev_total;
        unsigned long long idle_diff = idle_total - prev_idle_total;

        cpu_usage = (float)(total_diff - idle_diff) / total_diff * 100.0;
        *usage = cpu_usage;
    } else {
        *usage = 0.0; // Initial value
    }

    prev_total = total;
    prev_idle_total = idle_total;

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

int main() {
    float cpu_temp, cpu_usage;
    char temp_str[20], usage_str[20];

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize SSD1306
    if (ssd1306_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing SSD1306\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        if (read_cpu_temp(&cpu_temp) < 0) {
            fprintf(stderr, "Error reading CPU temperature\n");
            snprintf(temp_str, sizeof(temp_str), "Temp: ERR");
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", cpu_temp);
        }

        // Read CPU usage
        if (read_cpu_usage(&cpu_usage) < 0) {
            fprintf(stderr, "Error reading CPU usage\n");
            snprintf(usage_str, sizeof(usage_str), "Usage: ERR");
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: %.1f%%", cpu_usage);
        }

        // Clear display
        if (ssd1306_clear_display(i2c_fd) < 0) {
            fprintf(stderr, "Error clearing display\n");
        }

        // Display text
        if (ssd1306_display_string(i2c_fd, 0, 0, temp_str) < 0) {
            fprintf(stderr, "Error displaying temperature\n");
        }
        if (ssd1306_display_string(i2c_fd, 0, 10, usage_str) < 0) {
            fprintf(stderr, "Error displaying usage\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    ssd1306_clear_display(i2c_fd);
    close(i2c_fd);

    return 0;
}

