#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Configuration
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27 // Replace with your LCD's I2C address
#define PULSES_PER_LITER 450.0
#define FLOW_RATE_UPDATE_INTERVAL 1 // seconds
#define LCD_UPDATE_INTERVAL 10      // seconds

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
double calculate_flow_rate();
void accumulate_volume(double flow_rate);
void log_data();
void update_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);

// LCD commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20
#define LCD_SETCGRAMADDR 0x40
#define LCD_SETDDRAMADDR 0x80

// Flags for display control
#define LCD_DISPLAYON 0x04
#define LCD_CURSORON 0x02
#define LCD_BLINKON 0x01

// Flags for entry mode
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

// Flags for function set
#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// LCD control bits
#define LCD_RS 0x01
#define LCD_RW 0x02
#define LCD_EN 0x04
#define LCD_BACKLIGHT 0x08
#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00

// Function to send a command to the LCD
void lcd_send_command(int handle, unsigned char cmd)
{
    char data_u, data_l;
    unsigned char data_t[4];
    data_u = (cmd & 0xF0);
    data_l = ((cmd << 4) & 0xF0);
    data_t[0] = data_u | LCD_BACKLIGHT;
    data_t[1] = data_u | LCD_EN | LCD_BACKLIGHT;
    data_t[2] = data_u | LCD_BACKLIGHT;
    data_t[3] = data_l | LCD_BACKLIGHT;
    data_t[4] = data_l | LCD_EN | LCD_BACKLIGHT;
    data_t[5] = data_l | LCD_BACKLIGHT;

    if (i2cWriteDevice(handle, data_t, 6) != 0) {
        fprintf(stderr, "Error writing to LCD\n");
    }
}

// Function to send data to the LCD
void lcd_send_data(int handle, unsigned char data)
{
    char data_u, data_l;
    unsigned char data_t[4];
    data_u = (data & 0xF0) | LCD_RS;
    data_l = ((data << 4) & 0xF0) | LCD_RS;
    data_t[0] = data_u | LCD_BACKLIGHT;
    data_t[1] = data_u | LCD_EN | LCD_BACKLIGHT;
    data_t[2] = data_u | LCD_BACKLIGHT;
    data_t[3] = data_l | LCD_BACKLIGHT;
    data_t[4] = data_l | LCD_EN | LCD_BACKLIGHT;
    data_t[5] = data_l | LCD_BACKLIGHT;

    if (i2cWriteDevice(handle, data_t, 6) != 0) {
        fprintf(stderr, "Error writing to LCD\n");
    }
}

// Function to initialize the LCD
int lcd_init(int handle)
{
    gpioDelay(50000); // Wait for LCD to power up
    lcd_send_command(handle, 0x33); // Initialize
    lcd_send_command(handle, 0x32); // Initialize
    lcd_send_command(handle, 0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_send_command(handle, 0x0C); // Display on, cursor off, blink off
    lcd_send_command(handle, 0x06); // Increment cursor, no shift
    lcd_send_command(handle, 0x01); // Clear display
    gpioDelay(2000); // Wait for clear display to complete
    return 0;
}

// Function to clear the LCD display
void lcd_clear(int handle)
{
    lcd_send_command(handle, LCD_CLEARDISPLAY);
    gpioDelay(2000); // Wait for clear display to complete
}

// Function to set the cursor position
void lcd_set_cursor(int handle, int row, int col)
{
    int addr;
    if (row == 0)
    {
        addr = 0x00 + col;
    }
    else
    {
        addr = 0x40 + col;
    }
    lcd_send_command(handle, LCD_SETDDRAMADDR | addr);
}

// Function to print a string to the LCD
void lcd_print(int handle, const char *str)
{
    while (*str)
    {
        lcd_send_data(handle, *str++);
    }
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt handler for the flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_callback, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init(i2c_handle) != 0)
    {
        fprintf(stderr, "LCD initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_flow_rate_time = 0;
    time_t last_lcd_update_time = 0;

    // Main loop
    while (1)
    {
        time_t current_time = time(NULL);

        // Update flow rate and total volume every FLOW_RATE_UPDATE_INTERVAL seconds
        if (current_time - last_flow_rate_time >= FLOW_RATE_UPDATE_INTERVAL)
        {
            double flow_rate = calculate_flow_rate();
            accumulate_volume(flow_rate);
            log_data();
            last_flow_rate_time = current_time;
        }

        // Update LCD every LCD_UPDATE_INTERVAL seconds
        if (current_time - last_lcd_update_time >= LCD_UPDATE_INTERVAL)
        {
            double flow_rate = calculate_flow_rate();
            update_lcd(flow_rate, total_volume);
            last_lcd_update_time = current_time;
        }

        gpioDelay(100000); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

// Callback function for pulse detection
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    pulse_count++;
}

// Function to calculate flow rate
double calculate_flow_rate()
{
    double flow_rate = (double)pulse_count / PULSES_PER_LITER / FLOW_RATE_UPDATE_INTERVAL * 60.0; // ml/min
    pulse_count = 0; // Reset pulse count
    return flow_rate;
}

// Function to accumulate total volume
void accumulate_volume(double flow_rate)
{
    total_volume += flow_rate / 60.0; // ml
}

// Function to log data to the console
void log_data()
{
    double flow_rate = calculate_flow_rate();
    printf("Flow Rate: %.2f ml/min, Total Volume: %.2f ml\n", flow_rate, total_volume);
}

// Function to update LCD display
void update_lcd(double flow_rate, double total_volume)
{
    char buffer[20];

    lcd_clear(i2c_handle);
    lcd_set_cursor(i2c_handle, 0, 0);
    sprintf(buffer, "Flow: %.2f ml/min", flow_rate);
    lcd_print(i2c_handle, buffer);

    lcd_set_cursor(i2c_handle, 1, 0);
    sprintf(buffer, "Vol: %.2f ml", total_volume);
    lcd_print(i2c_handle, buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

