#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Configuration
#define ANEMOMETER_PIN 17 // BCM GPIO 17
#define SPI_DEVICE "/dev/spidev0.0"
#define LCD_I2C_ADDR 0x27 // PCF8574 I2C address
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define WIND_SPEED_CALIBRATION_FACTOR 1.0 // Adjust as needed
#define WIND_DIRECTION_CALIBRATION_FACTOR 1.0 // Adjust as needed

// Global variables
volatile int pulse_count = 0;
int spi_fd = -1;
int lcd_fd = -1;
int running = 1;

// Function prototypes
void pulse_callback(void);
float calculate_wind_speed(int pulse_count);
int read_wind_direction();
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *text);
void lcd_send_command(unsigned char command);
void lcd_send_data(unsigned char data);
void signal_handler(int signal);

// Anemometer pulse callback function
void pulse_callback(void) {
    pulse_count++;
}

// Wind speed calculation function
float calculate_wind_speed(int pulse_count) {
    return (float)pulse_count * WIND_SPEED_CALIBRATION_FACTOR / (SAMPLE_WINDOW_MS / 1000.0);
}

// Wind direction reading function
int read_wind_direction() {
    unsigned char data[3];
    int adc_value;

    // MCP3008 configuration: Start bit, single-ended mode, channel 0, MSB first
    data[0] = 0x01; // Start bit
    data[1] = (0x08 | (0x00 & 0x07)) << 4; // Single-ended, channel 0
    data[2] = 0x00; // Don't care

    if (write(spi_fd, data, 3) != 3) {
        fprintf(stderr, "SPI write error: %s\n", strerror(errno));
        return -1;
    }

    if (read(spi_fd, data, 3) != 3) {
        fprintf(stderr, "SPI read error: %s\n", strerror(errno));
        return -1;
    }

    adc_value = ((data[1] & 0x03) << 8) + data[2];

    return adc_value;
}

// LCD initialization function
void lcd_init() {
    // Initialization sequence (refer to PCF8574 datasheet)
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(0x28); // 2 lines, 5x8 font
    lcd_send_command(0x0C); // Display on, cursor off, blink off
    lcd_send_command(0x06); // Increment cursor, no shift
    lcd_clear();
}

// LCD clear function
void lcd_clear() {
    lcd_send_command(0x01); // Clear display
    delay(2); // Wait for clear command to complete
}

// LCD set cursor function
void lcd_set_cursor(int row, int col) {
    int address;
    if (row == 0) {
        address = 0x00 + col;
    } else {
        address = 0x40 + col;
    }
    lcd_send_command(0x80 + address); // Set DDRAM address
}

// LCD print function
void lcd_print(const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        lcd_send_data(text[i]);
    }
}

// LCD send command function
void lcd_send_command(unsigned char command) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    data_u = (command & 0xF0);
    data_l = ((command << 4) & 0xF0);

    data_t[0] = data_u | 0x0C;  //en=1, rs=0
    data_t[1] = data_u | 0x08;  //en=0, rs=0
    data_t[2] = data_l | 0x0C;  //en=1, rs=0
    data_t[3] = data_l | 0x08;  //en=0, rs=0

    wiringPiI2CWrite(lcd_fd, data_t[0]);
    delayMicroseconds(1);
    wiringPiI2CWrite(lcd_fd, data_t[1]);
    delayMicroseconds(1);
    wiringPiI2CWrite(lcd_fd, data_t[2]);
    delayMicroseconds(1);
    wiringPiI2CWrite(lcd_fd, data_t[3]);
    delayMicroseconds(1);
}

// LCD send data function
void lcd_send_data(unsigned char data) {
    unsigned char data_u, data_l;
    unsigned char data_t[4];
    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    data_t[0] = data_u | 0x0D;  //en=1, rs=1
    data_t[1] = data_u | 0x09;  //en=0, rs=1
    data_t[2] = data_l | 0x0D;  //en=1, rs=1
    data_t[3] = data_l | 0x09;  //en=0, rs=1

    wiringPiI2CWrite(lcd_fd, data_t[0]);
    delayMicroseconds(1);
    wiringPiI2CWrite(lcd_fd, data_t[1]);
    delayMicroseconds(1);
    wiringPiI2CWrite(lcd_fd, data_t[2]);
    delayMicroseconds(1);
    wiringPiI2CWrite(lcd_fd, data_t[3]);
    delayMicroseconds(1);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        return 1;
    }

    unsigned char mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "SPI mode setting failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    unsigned int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "SPI speed setting failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Initialize I2C
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "I2C setup failed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt for anemometer
    if (wiringPiISR(ANEMOMETER_PIN, INT_EDGE_RISING, pulse_callback) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    time_t last_update_time = time(NULL);

    while (running) {
        // Reset pulse count
        int current_pulse_count = pulse_count;
        pulse_count = 0;

        // Calculate wind speed
        float wind_speed = calculate_wind_speed(current_pulse_count);

        // Read wind direction
        int wind_direction = read_wind_direction();
        if (wind_direction == -1) {
            fprintf(stderr, "Error reading wind direction.\n");
        }

        // Display data on LCD
        char speed_str[17];
        char direction_str[17];

        snprintf(speed_str, sizeof(speed_str), "Speed: %.2f m/s", wind_speed);
        snprintf(direction_str, sizeof(direction_str), "Dir: %d", wind_direction);

        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_print(speed_str);
        lcd_set_cursor(1, 0);
        lcd_print(direction_str);

        // Check for sensor absence conditions
        if (wind_direction == 0 || wind_direction == 1023) {
            fprintf(stderr, "Warning: Wind vane or ADC reading stuck at extreme value.\n");
        }

        // Update every 500ms
        time_t current_time = time(NULL);
        if (current_time - last_update_time >= 0.5) {
            last_update_time = current_time;
        }

        delay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Shutting down...");
    delay(500);
    lcd_clear();

    close(spi_fd);
    close(lcd_fd);

    return 0;
}

