#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27 // Replace with your LCD's I2C address
#define PULSES_PER_LITER 450.0
#define ZERO_PULSE_THRESHOLD 0.5 // Seconds
#define ZERO_PULSE_WINDOW 5      // Seconds

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
float calculate_flow_rate(int pulses);
void display_flow_rate(float flow_rate);
void lcd_init();
void lcd_clear();
void lcd_write_string(const char *string);
void lcd_set_cursor(int row, int col);
void signal_handler(int signal);

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
  if (level == PI_HIGH) {
    pulse_count++;
  }
}

// Calculate flow rate in L/min
float calculate_flow_rate(int pulses) {
  return (float)pulses / PULSES_PER_LITER * 60.0;
}

// Display flow rate on LCD
void display_flow_rate(float flow_rate) {
  char buffer[20];
  lcd_clear();
  lcd_set_cursor(0, 0);
  lcd_write_string("Flow Rate:");
  lcd_set_cursor(1, 0);
  snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
  lcd_write_string(buffer);
}

// LCD initialization
void lcd_init() {
  lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
  if (lcd_fd == -1) {
    fprintf(stderr, "Error: Failed to initialize LCD.\n");
    exit(EXIT_FAILURE);
  }

  // Initialization sequence (adjust based on your LCD's datasheet)
  delay(50); // Wait for LCD to power up
  wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x33); // Initialize
  delay(5);
  wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x32); // Initialize
  delay(5);
  wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x28); // 4-bit mode, 2 lines, 5x8 font
  delay(5);
  wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x0C); // Display on, cursor off, blink off
  delay(5);
  wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
  delay(5);
  wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x06); // Entry mode set: increment cursor, no shift
  delay(5);
}

// Clear LCD display
void lcd_clear() {
  wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
  delay(2); // Delay for clear command to complete
}

// Write string to LCD
void lcd_write_string(const char *string) {
  for (int i = 0; string[i] != '\0'; i++) {
    wiringPiI2CWriteReg8(lcd_fd, 0x40, string[i]); // Send data
  }
}

// Set LCD cursor position
void lcd_set_cursor(int row, int col) {
  int address;
  if (row == 0) {
    address = 0x80 + col;
  } else {
    address = 0xC0 + col;
  }
  wiringPiI2CWriteReg8(lcd_fd, 0x00, address);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
  program_running = 0;
  printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Error: pigpio initialisation failed.\n");
    return 1;
  }

  // Set GPIO mode for flow sensor
  gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
  gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

  // Set alert function for flow sensor
  if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
    fprintf(stderr, "Error: Failed to set alert function for flow sensor.\n");
    gpioTerminate();
    return 1;
  }

  // Initialize LCD
  lcd_init();

  // Set up signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  time_t last_pulse_time = time(NULL);
  int zero_pulse_count = 0;

  printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

  while (program_running) {
    sleep(1);

    // Calculate flow rate
    float flow_rate = calculate_flow_rate(pulse_count);

    // Display flow rate
    display_flow_rate(flow_rate);

    // Reset pulse count
    pulse_count = 0;

    // Check for sensor absence
    if (pulse_count == 0) {
      time_t current_time = time(NULL);
      if (difftime(current_time, last_pulse_time) >= ZERO_PULSE_THRESHOLD) {
        zero_pulse_count++;
        if (zero_pulse_count >= ZERO_PULSE_WINDOW) {
          lcd_clear();
          lcd_set_cursor(0, 0);
          lcd_write_string("Sensor Absent");
          fprintf(stderr, "Warning: No pulses detected for %d seconds.\n", ZERO_PULSE_WINDOW);
          zero_pulse_count = 0; // Reset the counter to avoid repeated warnings
        }
      }
    } else {
      zero_pulse_count = 0; // Reset the counter if pulses are detected
      last_pulse_time = time(NULL);
    }
  }

  // Cleanup
  gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL); // Disable alert function
  gpioTerminate();                                  // Terminate pigpio
  close(lcd_fd);                                     // Close I2C connection

  printf("Program terminated.\n");
  return 0;
}

