        return 1;
    }

    // Main loop: animate the wave indefinitely
    while (program_running) {
        animate_wave();
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initializes the pigpio library and sets the GPIO pins as output
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as output and set them HIGH (anode connection)
    for (int i = 0; i < num_rows; i++) {
        gpioSetMode(row_pins[i], PI_OUTPUT);
        gpioWrite(row_pins[i], 1);
    }

    // Set column pins as output and set them HIGH (cathode connection)
    for (int i = 0; i < num_cols; i++) {
        gpioSetMode(col_pins[i], PI_OUTPUT);
        gpioWrite(col_pins[i], 1);
    }

    return 0;
}

