void animate_wave() {
    for (int col = 0; col < num_cols; col++) {
        clear_matrix();
        set_column(col);
        for (int row = 0; row < num_rows; row++) {
            set_row(row);
            gpioDelay(150000); // 150ms delay
            gpioWrite(row_pins[row], 1); // Turn off the row after delay
        }
    }
}

// Signal handler to catch SIGINT and SIGTERM signals and terminate the program gracefully
void signal_handler(int signal) {
    printf("Caught signal %d. Terminating program...\n", signal);
    program_running = 0;
