#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L3CX_ADDR 0x29
#define VL53L3CX_MODEL_ID_REG 0x0000
#define VL53L3CX_MODEL_ID 0xB4
#define VL53L3CX_DISTANCE_REG 0x001E
#define VL53L3CX_TARGET_COUNT_REG 0x001F
#define VL53L3CX_MAX_TARGETS 4

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance[VL53L3CX_MAX_TARGETS];
    int target_count;
} sensor_data_t;

// Function prototypes
int init_vl53l3cx();
int read_sensor_data(sensor_data_t *data);
void print_data(const sensor_data_t *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize VL53L3CX sensor
int init_vl53l3cx() {
    int model_id;
    int status;

    // Check sensor model ID
    model_id = i2cReadByteData(i2c_handle, VL53L3CX_MODEL_ID_REG);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }

    if (model_id != VL53L3CX_MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L3CX_MODEL_ID);
        return -1;
    }

    // Placeholder for proprietary firmware download
    // In a real application, this would involve writing the firmware image to the sensor
    // using the appropriate register addresses and commands.
    // For this example, we just print a message indicating that the firmware download would occur.
    printf("Proprietary firmware download would occur here.\n");

    // Add more initialization steps here as needed based on the VL53L3CX datasheet.
    // This might involve writing to specific registers to configure the sensor.
    // For example, setting the ranging mode, inter-measurement period, etc.

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    int distance_data[2];
    int target_count;
    int i;
    int status;

    // Read target count
    target_count = i2cReadByteData(i2c_handle, VL53L3CX_TARGET_COUNT_REG);
    if (target_count < 0) {
        fprintf(stderr, "Error reading target count: %d\n", target_count);
        return -1;
    }

    if (target_count > VL53L3CX_MAX_TARGETS) {
        fprintf(stderr, "Too many targets detected (%d), maximum is %d\n", target_count, VL53L3CX_MAX_TARGETS);
        return -1;
    }

    data->target_count = target_count;

    // Read distance data for each target
    for (i = 0; i < target_count; i++) {
        // Read two bytes of distance data
        status = i2cReadI2CBlockData(i2c_handle, VL53L3CX_DISTANCE_REG + (i * 2), (char *)distance_data, 2);
        if (status < 0) {
            fprintf(stderr, "Error reading distance data for target %d: %d\n", i, status);
            return -1;
        }

        // Combine the two bytes into a single distance value
        data->distance[i] = (distance_data[0] << 8) | distance_data[1];
    }

    return 0;
}

// Print sensor data
void print_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int i;

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    // Print timestamp and target distances
    printf("%s", timestamp);
    for (i = 0; i < data->target_count; i++) {
        printf(", Target %d: %d mm", i + 1, data->distance[i]);
    }
    printf("\n");
}

int main() {
    sensor_data_t sensor_data;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L3CX sensor
    if (init_vl53l3cx() != 0) {
        fprintf(stderr, "VL53L3CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_sensor_data(&sensor_data);
        if (status == 0) {
            // Print data
            print_data(&sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

