#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Si1145 Registers
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02

#define REG_UCOEF0 0x13
#define REG_UCOEF1 0x14
#define REG_UCOEF2 0x15
#define REG_UCOEF3 0x16

#define REG_PARAM_WR 0x17
#define REG_COMMAND 0x18

#define REG_RESPONSE0 0x20
#define REG_RESPONSE1 0x21
#define REG_RESPONSE2 0x22
#define REG_RESPONSE3 0x23

#define REG_IRQ_ENABLE 0x03
#define REG_IRQ_MODE1 0x04
#define REG_IRQ_MODE2 0x05

#define REG_HW_KEY 0x07

#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09

#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0 0x24
#define REG_PS1_DATA1 0x25

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_proximity();
int read_ambient_light();
char* get_iso8601_timestamp();
int log_data(char *timestamp, int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize Si1145 sensor
int si1145_init() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE0, 0x08) < 0) return -1; // Measurement rate
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE1, 0x00) < 0) return -1;

    if (i2cWriteByteData(i2c_handle, REG_UCOEF0, 0x7B) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_UCOEF1, 0x6B) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_UCOEF2, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_UCOEF3, 0x00) < 0) return -1;

    if (i2cWriteByteData(i2c_handle, REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17) < 0) return -1;

    return 0;
}

// Read proximity value
int read_proximity() {
    int proximity = i2cReadWordData(i2c_handle, REG_PS1_DATA0);
    if (proximity < 0) {
        fprintf(stderr, "Error: Failed to read proximity data\n");
        return -1;
    }
    return proximity;
}

// Read ambient light value
int read_ambient_light() {
    int ambient_light = i2cReadWordData(i2c_handle, REG_ALS_VIS_DATA0);
    if (ambient_light < 0) {
        fprintf(stderr, "Error: Failed to read ambient light data\n");
        return -1;
    }
    return ambient_light;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(char *timestamp, int proximity, int ambient_light) {
    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (si1145_init() < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int proximity = read_proximity();
        int ambient_light = read_ambient_light();

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log data
        if (proximity >= 0 && ambient_light >= 0) {
            log_data(timestamp, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data, skipping log entry\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

