#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define SI1145_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_COMMAND 0x30
#define SI1145_RESET 0x01

// Global variables
int i2c_handle;
FILE *log_file;

// Function prototypes
int read_sensor_data(int i2c_handle, int *proximity, int *ambient_light);
int log_data(FILE *log_file, int proximity, int ambient_light);
void signal_handler(int signal);
int si1145_init(int i2c_handle);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si1145 sensor
int si1145_init(int i2c_handle) {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145 sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    // Enable ALS and PS1
    if (i2cWriteByteData(i2c_handle, 0x02, 0x07) < 0) return -1; // Enable channels
    if (i2cWriteByteData(i2c_handle, 0x03, 0x00) < 0) return -1; // PS LED select
    if (i2cWriteByteData(i2c_handle, 0x04, 0x00) < 0) return -1; // PS1 ADC config
    if (i2cWriteByteData(i2c_handle, 0x05, 0x00) < 0) return -1; // PS2 ADC config
    if (i2cWriteByteData(i2c_handle, 0x06, 0x00) < 0) return -1; // PS3 ADC config
    if (i2cWriteByteData(i2c_handle, 0x07, 0x00) < 0) return -1; // PS1 force
    if (i2cWriteByteData(i2c_handle, 0x08, 0x00) < 0) return -1; // PS2 force
    if (i2cWriteByteData(i2c_handle, 0x09, 0x00) < 0) return -1; // PS3 force
    if (i2cWriteByteData(i2c_handle, 0x0A, 0x00) < 0) return -1; // PS1 n
    if (i2cWriteByteData(i2c_handle, 0x0B, 0x00) < 0) return -1; // PS2 n
    if (i2cWriteByteData(i2c_handle, 0x0C, 0x00) < 0) return -1; // PS3 n
    if (i2cWriteByteData(i2c_handle, 0x0D, 0x00) < 0) return -1; // PS1 m
    if (i2cWriteByteData(i2c_handle, 0x0E, 0x00) < 0) return -1; // PS2 m
    if (i2cWriteByteData(i2c_handle, 0x0F, 0x00) < 0) return -1; // PS3 m
    if (i2cWriteByteData(i2c_handle, 0x10, 0x00) < 0) return -1; // PS1 offset
    if (i2cWriteByteData(i2c_handle, 0x11, 0x00) < 0) return -1; // PS2 offset
    if (i2cWriteByteData(i2c_handle, 0x12, 0x00) < 0) return -1; // PS3 offset
    if (i2cWriteByteData(i2c_handle, 0x13, 0x00) < 0) return -1; // PS1 gain
    if (i2cWriteByteData(i2c_handle, 0x14, 0x00) < 0) return -1; // PS2 gain
    if (i2cWriteByteData(i2c_handle, 0x15, 0x00) < 0) return -1; // PS3 gain
    if (i2cWriteByteData(i2c_handle, 0x16, 0x00) < 0) return -1; // PS1 select
    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) return -1; // PS2 select
    if (i2cWriteByteData(i2c_handle, 0x18, 0x00) < 0) return -1; // PS3 select
    if (i2cWriteByteData(i2c_handle, 0x19, 0x00) < 0) return -1; // PS1 valid
    if (i2cWriteByteData(i2c_handle, 0x1A, 0x00) < 0) return -1; // PS2 valid
    if (i2cWriteByteData(i2c_handle, 0x1B, 0x00) < 0) return -1; // PS3 valid
    if (i2cWriteByteData(i2c_handle, 0x1C, 0x00) < 0) return -1; // PS1 rate
    if (i2cWriteByteData(i2c_handle, 0x1D, 0x00) < 0) return -1; // PS2 rate
    if (i2cWriteByteData(i2c_handle, 0x1E, 0x00) < 0) return -1; // PS3 rate
    if (i2cWriteByteData(i2c_handle, 0x1F, 0x00) < 0) return -1; // PS1 filter
    if (i2cWriteByteData(i2c_handle, 0x20, 0x00) < 0) return -1; // PS2 filter
    if (i2cWriteByteData(i2c_handle, 0x21, 0x00) < 0) return -1; // PS3 filter

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int read_sensor_data(int i2c_handle, int *proximity, int *ambient_light) {
    int als_vis_low, als_vis_high, ps1_low, ps1_high;

    als_vis_low = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (als_vis_low < 0) {
        fprintf(stderr, "Error: Failed to read ALS_VIS_DATA0.\n");
        return -1;
    }

    als_vis_high = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0 + 1);
    if (als_vis_high < 0) {
        fprintf(stderr, "Error: Failed to read ALS_VIS_DATA1.\n");
        return -1;
    }

    ps1_low = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
    if (ps1_low < 0) {
        fprintf(stderr, "Error: Failed to read PS1_DATA0.\n");
        return -1;
    }

    ps1_high = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0 + 1);
    if (ps1_high < 0) {
        fprintf(stderr, "Error: Failed to read PS1_DATA1.\n");
        return -1;
    }

    *ambient_light = (als_vis_high << 8) | als_vis_low;
    *proximity = (ps1_high << 8) | ps1_low;

    return 0;
}

// Function to log the data to a file
int log_data(FILE *log_file, int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);

    return 0;
}

int main() {
    int proximity, ambient_light;
    int part_id;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    part_id = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Could not read PART_ID.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART_ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_handle, &proximity, &ambient_light) == 0) {
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        gpioDelay(1000); // 1 second delay
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

