    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) return -1; // PS2 select
    if (i2cWriteByteData(i2c_handle, 0x18, 0x00) < 0) return -1; // PS3 select
    if (i2cWriteByteData(i2c_handle, 0x19, 0x00) < 0) return -1; // PS1 valid
    if (i2cWriteByteData(i2c_handle, 0x1A, 0x00) < 0) return -1; // PS2 valid
    if (i2cWriteByteData(i2c_handle, 0x1B, 0x00) < 0) return -1; // PS3 valid
    if (i2cWriteByteData(i2c_handle, 0x1C, 0x00) < 0) return -1; // PS1 rate
    if (i2cWriteByteData(i2c_handle, 0x1D, 0x00) < 0) return -1; // PS2 rate
    if (i2cWriteByteData(i2c_handle, 0x1E, 0x00) < 0) return -1; // PS3 rate
    if (i2cWriteByteData(i2c_handle, 0x1F, 0x00) < 0) return -1; // PS1 filter
    if (i2cWriteByteData(i2c_handle, 0x20, 0x00) < 0) return -1; // PS2 filter
    if (i2cWriteByteData(i2c_handle, 0x21, 0x00) < 0) return -1; // PS3 filter

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int read_sensor_data(int i2c_handle, int *proximity, int *ambient_light) {
    int als_vis_low, als_vis_high, ps1_low, ps1_high;

    als_vis_low = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    if (als_vis_low < 0) {
        fprintf(stderr, "Error: Failed to read ALS_VIS_DATA0.\n");
        return -1;
    }

    als_vis_high = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0 + 1);
    if (als_vis_high < 0) {
        fprintf(stderr, "Error: Failed to read ALS_VIS_DATA1.\n");
        return -1;
    }

    ps1_low = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
    if (ps1_low < 0) {
        fprintf(stderr, "Error: Failed to read PS1_DATA0.\n");
        return -1;
    }

    ps1_high = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0 + 1);
    if (ps1_high < 0) {
        fprintf(stderr, "Error: Failed to read PS1_DATA1.\n");
        return -1;
    }

    *ambient_light = (als_vis_high << 8) | als_vis_low;
    *proximity = (ps1_high << 8) | ps1_low;

    return 0;
}

// Function to log the data to a file
int log_data(FILE *log_file, int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file);

    return 0;
}

int main() {
    int proximity, ambient_light;
    int part_id;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    part_id = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Could not read PART_ID.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART_ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_handle, &proximity, &ambient_light) == 0) {
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        gpioDelay(1000); // 1 second delay
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

