#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30ms timeout for echo rise and pulse width
#define MIN_DISTANCE 2.0       // Minimum valid distance (cm)
#define MAX_DISTANCE 400.0     // Maximum valid distance (cm)
#define WATER_PLANT_THRESHOLD 15.0 // Distance below which to water the plant (cm)
#define LOG_INTERVAL 60         // Logging interval (seconds)

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static volatile int program_running = 1;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(uint32_t pulse_width);
int log_distance(float distance);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            echo_start_tick = tick;
            echo_received = 1; // Flag that the echo pulse has started
        } else if (level == 0 && echo_received == 1) {
            echo_end_tick = tick;
            echo_received = 2; // Flag that the echo pulse has ended
        }
    }
}

// Function to send a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance in centimeters
float calculate_distance(uint32_t pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
int log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_log_time = time(NULL);

    // Main loop
    while (program_running) {
        echo_start_tick = 0;
        echo_end_tick = 0;
        echo_received = 0;

        trigger_pulse();

        // Wait for echo rise with timeout
        int timeout_counter = 0;
        while (echo_received == 0 && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Check every microsecond
            timeout_counter++;
        }

        if (echo_received == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Timeout waiting for echo rise\n", timestamp);
            fflush(log_file);
            continue; // Skip to the next iteration
        }

        // Wait for echo pulse width with timeout
        timeout_counter = 0;
        while (echo_received == 1 && timeout_counter < TIMEOUT_US) {
            gpioDelay(1); // Check every microsecond
            timeout_counter++;
        }

        if (echo_received == 1) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Timeout waiting for echo pulse width\n", timestamp);
            fflush(log_file);
            continue; // Skip to the next iteration
        }

        uint32_t pulse_width = echo_end_tick - echo_start_tick;
        float distance = calculate_distance(pulse_width);

        // Validate distance
        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            // Log distance every LOG_INTERVAL seconds
            time_t current_time = time(NULL);
            if (difftime(current_time, last_log_time) >= LOG_INTERVAL) {
                log_distance(distance);
                last_log_time = current_time;

                // Check if watering is needed
                if (distance < WATER_PLANT_THRESHOLD) {
                    time_t rawtime;
                    struct tm *timeinfo;
                    char timestamp[20];

                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                    fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
                    fflush(log_file);
                }
            }
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Invalid distance: %.2f cm\n", timestamp, distance);
            fflush(log_file);
        }

        gpioDelay(100); // Delay between measurements
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

