#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATAL 0x9C
#define APDS9960_PDATAH 0x9D

// Enable bits
#define APDS9960_PON 0x01
#define APDS9960_AEN 0x02
#define APDS9960_PEN 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_apds9960();
int read_proximity();
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t red, uint16_t green, uint16_t blue, int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the APDS9960 sensor
int initialize_apds9960() {
    // Enable power and ALS/proximity sensing
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, APDS9960_PON | APDS9960_AEN | APDS9960_PEN) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set ALS integration time
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) { // 2.78ms
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set proximity integration time
    if (i2cWriteByteData(i2c_handle, APDS9960_PTIME, 0xFF) < 0) { // 2.78ms
        fprintf(stderr, "Error writing to PTIME register\n");
        return -1;
    }

    // Set proximity pulse length and number of pulses
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) { // 16us, 8 pulses
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    // Set gain
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) { // 4x gain
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    return 0;
}

// Read proximity value from the sensor
int read_proximity() {
    int proximity_low, proximity_high;

    proximity_low = i2cReadByteData(i2c_handle, APDS9960_PDATAL);
    if (proximity_low < 0) {
        fprintf(stderr, "Error reading proximity low byte\n");
        return -1;
    }

    proximity_high = i2cReadByteData(i2c_handle, APDS9960_PDATAH);
    if (proximity_high < 0) {
        fprintf(stderr, "Error reading proximity high byte\n");
        return -1;
    }

    return (proximity_high << 8) | proximity_low;
}

// Read RGB color values from the sensor
int read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    int red_low, red_high, green_low, green_high, blue_low, blue_high;

    red_low = i2cReadByteData(i2c_handle, APDS9960_RDATAL);
    if (red_low < 0) {
        fprintf(stderr, "Error reading red low byte\n");
        return -1;
    }

    red_high = i2cReadByteData(i2c_handle, APDS9960_RDATAH);
    if (red_high < 0) {
        fprintf(stderr, "Error reading red high byte\n");
        return -1;
    }

    green_low = i2cReadByteData(i2c_handle, APDS9960_GDATAL);
    if (green_low < 0) {
        fprintf(stderr, "Error reading green low byte\n");
        return -1;
    }

    green_high = i2cReadByteData(i2c_handle, APDS9960_GDATAH);
    if (green_high < 0) {
        fprintf(stderr, "Error reading green high byte\n");
        return -1;
    }

    blue_low = i2cReadByteData(i2c_handle, APDS9960_BDATAL);
    if (blue_low < 0) {
        fprintf(stderr, "Error reading blue low byte\n");
        return -1;
    }

    blue_high = i2cReadByteData(i2c_handle, APDS9960_BDATAH);
    if (blue_high < 0) {
        fprintf(stderr, "Error reading blue high byte\n");
        return -1;
    }

    *red = (red_high << 8) | red_low;
    *green = (green_high << 8) | green_low;
    *blue = (blue_high << 8) | blue_low;

    return 0;
}

// Log data to the CSV file
void log_data(uint16_t red, uint16_t green, uint16_t blue, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%d\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the APDS9960 sensor
    if (initialize_apds9960() < 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
