#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x08
#define CSV_FILE "heartrate.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;

// Function prototypes
int initialize_i2c();
int read_proximity();
float calculate_bpm(int proximity);
char* get_iso8601_timestamp();
int write_to_csv(char* timestamp, float bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read proximity data from the sensor
int read_proximity() {
    int proximity = i2cReadByteData(i2c_handle, PROXIMITY_REG);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", proximity);
        return -1;
    }
    return proximity;
}

// Calculate BPM based on proximity data (simplified linear mapping)
float calculate_bpm(int proximity) {
    // Assuming proximity values range from 0 to 255
    // and BPM values range from 40 to 180
    float bpm = 40.0 + (float)proximity * (180.0 - 40.0) / 255.0;
    return bpm;
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Write data to CSV file
int write_to_csv(char* timestamp, float bpm) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file for writing\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, bpm);
    fflush(fp);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (running) {
        // Read proximity data
        int proximity = read_proximity();
        if (proximity >= 0) {
            // Calculate BPM
            float bpm = calculate_bpm(proximity);

            // Get timestamp
            char* timestamp = get_iso8601_timestamp();

            // Write to CSV file
            if (write_to_csv(timestamp, bpm) != 0) {
                fprintf(stderr, "Error writing to CSV file\n");
            }

            free(timestamp); // Free the allocated memory
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

