#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_IDENTIFICATION_REVISION_ID 0xC2
#define VL53L0X_REG_SYSRANGE_START 0x00
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x24
#define VL53L0X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x8A

// GPIO pin for interrupt
#define INTERRUPT_GPIO 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_sensor();
int read_distance(int *distance);
void log_distance(int distance);
void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    uint8_t i2c_address;
    int interrupt_gpio;
    int i2c_bus;
} sensor_config_t;

// Function to write a byte to a VL53L0X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L0X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L0X sensor
int init_sensor() {
    uint8_t model_id, revision_id;

    // Check sensor presence
    if (read_register(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (read_register(i2c_handle, VL53L0X_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set I2C address (optional, but recommended)
    if (write_register(i2c_handle, VL53L0X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L0X_ADDR) != 0) {
        fprintf(stderr, "Error setting I2C address\n");
        return -1;
    }

    // Recommended settings from datasheet
    if (write_register(i2c_handle, 0x88, 0x00) != 0) return -1;
    if (write_register(i2c_handle, 0x80, 0x01) != 0) return -1;
    if (write_register(i2c_handle, 0xFF, 0x01) != 0) return -1;
    if (write_register(i2c_handle, 0x00, 0x00) != 0) return -1;
    if (write_register(i2c_handle, 0x91, 0x01) != 0) return -1;
    if (write_register(i2c_handle, 0x00, 0x01) != 0) return -1;
    if (write_register(i2c_handle, 0xFF, 0x00) != 0) return -1;
    if (write_register(i2c_handle, 0x80, 0x00) != 0) return -1;

    // Start continuous ranging
    if (write_register(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance(int *distance) {
    uint8_t range_status;
    uint8_t msb, lsb;

    // Trigger a single measurement
    if (write_register(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for measurement to complete with timeout
    int timeout_count = 0;
    do {
        if (read_register(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
            fprintf(stderr, "Error reading range status\n");
            return -1;
        }
        gpioDelay(10000); // 10ms
        timeout_count++;
        if (timeout_count > 100) { // 100 * 10ms = 1 second timeout
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    } while ((range_status & 0x01) == 0);

    // Read distance
    if (read_register(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &msb) != 0) {
        fprintf(stderr, "Error reading MSB of distance\n");
        return -1;
    }
    if (read_register(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &lsb) != 0) {
        fprintf(stderr, "Error reading LSB of distance\n");
        return -1;
    }

    *distance = (msb << 8) | lsb;

    return 0;
}

// Function to log the distance to a file
void log_distance(int distance) {
