#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Si1182 Register Addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x18

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_register(int handle, uint8_t reg, uint8_t *value);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_proximity(int handle);
int read_ambient_light(int handle);
void log_data(FILE *fp, int proximity, int ambient_light);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read a single byte from a register with retries
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading register 0x%02X (attempt %d): %d\n", reg, retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to write a single byte to a register with retries
int write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing register 0x%02X (attempt %d): %d\n", reg, retries + 1, result);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to write register 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to read proximity data
int read_proximity(int handle) {
    uint8_t data[2];
    int result;

    result = i2cReadI2CBlockData(handle, REG_PS1_DATA0, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }

    return (data[1] << 8) | data[0];
}

// Function to read ambient light data
int read_ambient_light(int handle) {
    uint8_t data[2];
    int result;

    result = i2cReadI2CBlockData(handle, REG_ALS_VIS_DATA0, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ambient light data: %d\n", result);
        return -1;
    }

    return (data[1] << 8) | data[0];
}

// Function to log data to a file
void log_data(FILE *fp, int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stdout, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data;

        // Read sensor data
        sensor_data.proximity = read_proximity(i2c_handle);
        sensor_data.ambient_light = read_ambient_light(i2c_handle);

        // Log data
        if (sensor_data.proximity != -1 && sensor_data.ambient_light != -1) {
            log_data(log_file, sensor_data.proximity, sensor_data.ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stdout, "Program terminated cleanly.\n");
    return 0;
}

