#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xE1
#define DISTANCE_REG_L 0x58
#define DISTANCE_REG_H 0x59
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100 // mm
#define POLL_INTERVAL_MS 50

// Global variables
int i2c_handle;
int distance_threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void control_led(int distance);
void log_data(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set GPIO back to input
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the sensor
int initialize_sensor() {
    int who_am_i;

    // Verify WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch. Expected 0x%02X, got 0x%02X\n", WHO_AM_I_VALUE, who_am_i);
        return -1;
    }

    printf("Sensor initialized successfully. WHO_AM_I: 0x%02X\n", who_am_i);
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    int distance_low, distance_high;

    distance_low = i2cReadByteData(i2c_handle, DISTANCE_REG_L);
    if (distance_low < 0) {
        fprintf(stderr, "Error reading distance low byte: %d\n", distance_low);
        return -1;
    }

    distance_high = i2cReadByteData(i2c_handle, DISTANCE_REG_H);
    if (distance_high < 0) {
        fprintf(stderr, "Error reading distance high byte: %d\n", distance_high);
        return -1;
    }

    *distance = (distance_high << 8) | distance_low;
    return 0;
}

// Control the LED based on distance
void control_led(int distance) {
    if (distance < distance_threshold) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Log data to file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

int main(int argc, char *argv[]) {
    int distance;

    // Parse command-line argument for distance threshold
