#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define INTRUSION_THRESHOLD 1000 // mm
#define SAMPLE_DELAY_MS 100
#define NUM_SAMPLES 10

// Define command frame
const uint8_t command_frame[] = {0x01, 0x02, 0x03, 0x04};

// Define response frame header
const uint8_t response_header = 0x00;

// Global variables
int i2c_handle;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int send_command(const uint8_t *command, int command_len);
int read_response(uint8_t *response, int response_len);
int verify_header(uint8_t header);
int extract_distance(const uint8_t *response);
float calculate_average_distance(int *distances, int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int i2c_handle;
    FILE *log_file;
} ProgramState;

ProgramState state;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command frame to the sensor
int send_command(const uint8_t *command, int command_len) {
    int result = i2cWriteDevice(i2c_handle, (char *)command, command_len);
    if (result != command_len) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read response frame from the sensor
int read_response(uint8_t *response, int response_len) {
    int result = i2cReadDevice(i2c_handle, (char *)response, response_len);
    if (result != response_len) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify the header of the response frame
int verify_header(uint8_t header) {
    if (header != response_header) {
        fprintf(stderr, "Error: Invalid header byte: 0x%02X\n", header);
        return -1;
    }
    return 0;
}

// Extract the distance from the response frame
int extract_distance(const uint8_t *response) {
    return (response[11] << 8) | response[12];
}

// Calculate the average distance
float calculate_average_distance(int *distances, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Log intrusion event to file
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, average_distance);
    fclose(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint8_t response[15];
    int distances[NUM_SAMPLES];
    float average_distance;

    while (1) {
        // Sample the sensor
        for (int i = 0; i < NUM_SAMPLES; i++) {
            // Send command
            if (send_command(command_frame, sizeof(command_frame)) != 0) {
                fprintf(stderr, "Error sending command, retrying...\n");
                gpioDelay(10000); // 10ms delay
                continue;
            }

            // Wait for measurement
            gpioDelay(10000); // 10ms delay

            // Read response
            if (read_response(response, sizeof(response)) != 0) {
                fprintf(stderr, "Error reading response, retrying...\n");
                gpioDelay(10000); // 10ms delay
                continue;
            }

            // Verify header
            if (verify_header(response[0]) != 0) {
                fprintf(stderr, "Error verifying header, retrying...\n");
                gpioDelay(10000); // 10ms delay
                continue;
            }

            // Extract distance
            distances[i] = extract_distance(response);
        }

        // Calculate average distance
        average_distance = calculate_average_distance(distances, NUM_SAMPLES);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD) {
            if (log_intrusion(average_distance) != 0) {
                fprintf(stderr, "Error logging intrusion!\n");
            }
        }

        // Delay before next cycle
        gpioDelay(SAMPLE_DELAY_MS * 1000); // Convert ms to us
    }

    return 0;
}

