#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x24

// Expected model ID
#define VL53L0X_MODEL_ID 0xEEAA

// I2C handle
int i2c_handle;

// Signal handler flag
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read a byte from the VL53L0X sensor
int read_byte(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading byte from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a byte to the VL53L0X sensor
int write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing byte 0x%02X to register 0x%02X: %s\n", value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from the VL53L0X sensor
int read_word(int handle, uint8_t reg, uint16_t *value) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading word from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)result;
    return 0;
}

// Function to initialize the VL53L0X sensor
int init_vl53l0x(int handle) {
    uint8_t model_id;

    // Check sensor ID
    if (read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID.\n");
        return -1;
    }

    if (model_id != (VL53L0X_MODEL_ID & 0xFF)) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0x%02X).\n", model_id, VL53L0X_MODEL_ID & 0xFF);
        return -1;
    }

    // Basic initialization sequence (example, refer to datasheet for full details)
    if (write_byte(handle, 0x88, 0x00) != 0) return -1;
    if (write_byte(handle, 0x80, 0x01) != 0) return -1;
    if (write_byte(handle, 0xFF, 0x01) != 0) return -1;
    if (write_byte(handle, 0x00, 0x00) != 0) return -1;
    if (write_byte(handle, 0x91, 0x00) != 0) return -1;
    if (write_byte(handle, 0x00, 0x01) != 0) return -1;
    if (write_byte(handle, 0xFF, 0x00) != 0) return -1;
    if (write_byte(handle, 0x80, 0x00) != 0) return -1;

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int read_distance(int handle, int *distance) {
    uint16_t range_status;
    uint16_t distance_mm;

    // Read range status
    if (read_word(handle, VL53L0X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status.\n");
        return -1;
    }

    // Read distance
    if (read_word(handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_mm) != 0) {
        fprintf(stderr, "Error reading distance.\n");
        return -1;
    }

    *distance = (int)distance_mm;
    return 0;
}

// Function to print the distance with a timestamp
void print_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %d mm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(i2c_handle, &distance) == 0) {
            // Print distance
            print_distance(distance);
        } else {
            fprintf(stderr, "Error reading distance, continuing...\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

