#include <pigpio.h>

// Si1182 I2C address
#define SI1182_ADDR 0x60

// Si1182 register addresses
#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_ALS_VIS_DATA0 0x10
#define SI1182_REG_ALS_VIS_DATA1 0x11

// I2C handle
int i2c_handle;

// Function prototypes
int si1182_read_proximity();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t proximity;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read proximity data from Si1182
int si1182_read_proximity() {
    int result;
    uint8_t data[2];

    // Read two bytes from the ALS_VIS_DATA0 register
    result = i2cReadI2CBlockData(i2c_handle, SI1182_REG_ALS_VIS_DATA0, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    uint16_t proximity = (data[1] << 8) | data[0];
    return proximity;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check for Si1182 presence by reading the Part ID register
    int part_id = i2cReadByteData(i2c_handle, SI1182_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Si1182 not found (Part ID: 0x%02X)\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int proximity = si1182_read_proximity();
        if (proximity >= 0) {
            printf("Proximity: %d\n", proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data.\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    return 0;
}

