#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4A
#define DISTANCE_REG 0x00 // Example register address, adjust as needed

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

int setup_i2c(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X on bus %s: %s\n", address, bus, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int read_distance(int fd) {
    unsigned char data[2]; // Assuming 2 bytes for distance
    if (write(fd, &DISTANCE_REG, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int distance = (data[0] << 8) | data[1];
    return distance;
}

int main() {
    struct timespec sleep_time = {0, 500000000}; // 500 milliseconds

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = setup_i2c(I2C_BUS, MLX75030_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Verify sensor presence by reading a register (e.g., DISTANCE_REG)
    if (read_distance(i2c_fd) < 0) {
        fprintf(stderr, "Sensor not responding. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance. Continuing.\n");
        }

        if (nanosleep(&sleep_time, NULL) != 0) {
            fprintf(stderr, "nanosleep interrupted: %s\n", strerror(errno));
        }
    }

    // Cleanup
    close(i2c_fd);
    return 0;
}

