#include <errno.h>
#include <string.h>

// Define OPT3101 I2C address
#define OPT3101_ADDR 0x64

// Define OPT3101 register addresses
#define OPT3101_REG_CH0_DISTANCE 0x00
#define OPT3101_REG_CH0_AMBIENT 0x02
#define OPT3101_REG_ERROR_FLAGS 0x04

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
    int ambient_light;
    int error_flags;
} sensor_data_t;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to read a 16-bit register from the OPT3101
int read_register(int handle, uint8_t reg_addr, uint16_t *value) {
    char buf[1];
    buf[0] = reg_addr;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    uint16_t distance, ambient_light, error_flags;

    if (read_register(handle, OPT3101_REG_CH0_DISTANCE, &distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }
    data->distance = (int)distance;

    if (read_register(handle, OPT3101_REG_CH0_AMBIENT, &ambient_light) != 0) {
        fprintf(stderr, "Error reading ambient light\n");
        return -1;
    }
    data->ambient_light = (int)ambient_light;

    if (read_register(handle, OPT3101_REG_ERROR_FLAGS, &error_flags) != 0) {
        fprintf(stderr, "Error reading error flags\n");
        return -1;
    }
    data->error_flags = (int)error_flags;

    return 0;
}

// Function to log sensor data
void log_sensor_data(const sensor_data_t *data) {
    printf("Distance: %d, Ambient Light: %d, Error Flags: %d\n",
           data->distance, data->ambient_light, data->error_flags);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            log_sensor_data(&sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(500); // 500ms delay
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

