#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TIMEOUT_DURATION 200      // milliseconds
#define MAX_PULSE_DURATION 38     // milliseconds

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1); // Set trigger pin high
    gpioDelay(TRIGGER_PULSE_DURATION); // Wait for trigger pulse duration
    gpioWrite(TRIGGER_PIN, 0); // Set trigger pin low
}

// Function to measure the echo pulse duration
long measure_pulse_duration() {
    long start_tick, end_tick, pulse_duration;

    // Wait for the echo pin to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_DURATION * 1000) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= TIMEOUT_DURATION * 1000) {
