#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0 // meters
#define LOG_FILE "intrusion_log.csv"
#define MAGIC_WORD_SIZE 8
#define RANGE_PROFILE_SIZE 128
#define NUM_DISTANCE_BINS 64

// Global variables
int uart_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    char uart_device[20];
    int baud_rate;
    int gpio_led;
    float intrusion_threshold;
    char log_file[20];
} Config;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_range_profile(int uart_handle, unsigned char *buffer, int buffer_size);
int decode_range_profile(const unsigned char *buffer, float *distance_bins);
int check_intrusion(const float *distance_bins, float threshold);
int log_intrusion(const char *timestamp, float distance);
void activate_alert(int gpio_pin, int duration_ms);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    uart_handle = serOpen(device, baud_rate, 0); // Added flag 0
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", device);
        return -1;
    }
    return 0;
}

// Read range profile from UART
int read_range_profile(int uart_handle, unsigned char *buffer, int buffer_size) {
    int bytes_read = serRead(uart_handle, buffer, buffer_size);
    if (bytes_read != buffer_size) {
        fprintf(stderr, "Error reading from UART: Expected %d bytes, got %d\n", buffer_size, bytes_read);
        return -1;
    }
    return 0;
}

// Decode range profile data
int decode_range_profile(const unsigned char *buffer, float *distance_bins) {
    for (int i = 0; i < NUM_DISTANCE_BINS; i++) {
        unsigned short raw_value = (buffer[2 * i + 1] << 8) | buffer[2 * i];
        distance_bins[i] = (float)raw_value / 100.0; // Convert to meters
    }
    return 0;
}

// Check for intrusion
int check_intrusion(const float *distance_bins, float threshold) {
    for (int i = 0; i < NUM_DISTANCE_BINS; i++) {
        if (distance_bins[i] <= threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion
}

// Log intrusion event
int log_intrusion(const char *timestamp, float distance) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

// Activate alert LED
void activate_alert(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(gpio_pin, 0); // Turn LED off
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    gpioWrite(GPIO_LED, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize UART
    if (initialize_uart(UART_DEVICE, BAUD_RATE) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char range_profile_buffer[RANGE_PROFILE_SIZE];
    float distance_bins[NUM_DISTANCE_BINS];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    printf("Starting intrusion detection system...\n");

    while (!terminate) {
        // Read range profile
        if (read_range_profile(uart_handle, range_profile_buffer, RANGE_PROFILE_SIZE) == 0) {
            // Decode range profile
            if (decode_range_profile(range_profile_buffer, distance_bins) == 0) {
                // Check for intrusion
                if (check_intrusion(distance_bins, INTRUSION_THRESHOLD)) {
                    // Get current timestamp
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                    // Log intrusion
                    if (log_intrusion(timestamp, distance_bins[0]) == 0) { // Log distance of first bin
                        printf("Intrusion detected at %s, distance: %.2f meters\n", timestamp, distance_bins[0]);
                    } else {
                        fprintf(stderr, "Error logging intrusion\n");
                    }

                    // Activate alert
                    activate_alert(GPIO_LED, 2000);
                }
            } else {
                fprintf(stderr, "Error decoding range profile\n");
            }
        } else {
            fprintf(stderr, "Error reading range profile\n");
        }

        gpioDelay(10000); // Delay 10ms to avoid busy-waiting
    }

    cleanup();
    return 0;
}

