// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Define log file name
#define LOG_FILE "obstacle_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor();
void control_buzzer(int obstacle_detected);
void log_event(const char *event_type);
void signal_handler(int signal);

// Function to read the sensor value
int read_sensor() {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", sensor_value);
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to control the buzzer
void control_buzzer(int obstacle_detected) {
    int result = gpioWrite(BUZZER_PIN, obstacle_detected);
    if (result != 0) {
        fprintf(stderr, "Error writing to buzzer: %d\n", result);
    }
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", buf, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Release GPIO resources
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioSetMode(SENSOR_PIN, PI_INPUT); // Set sensor pin to input
    gpioSetMode(BUZZER_PIN, PI_INPUT); // Set buzzer pin to input

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int previous_state = -1; // Initialize to an invalid state

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value == -1) {
            // Error reading sensor, but continue running
            gpioDelay(100); // Wait before retrying
            continue;
        }

        int obstacle_detected = (sensor_value == 0); // Active low

        if (obstacle_detected != previous_state) {
            if (obstacle_detected) {
                log_event("Obstacle Detected");
            } else {
                log_event("Obstacle Removed");
            }
            previous_state = obstacle_detected;
        }

