#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses (example, refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0027
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT 0x0024
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(int *distance);
void log_distance(int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// VL53L1X initialization function
int vl53l1x_init() {
    int status;

    // Check sensor ID (example)
    char sensor_id;
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id, 1);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Example: Set some configuration registers (refer to datasheet for details)
    char config_data[2];

    // Set pre-range minimum signal rate limit
    config_data[0] = VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR;
    config_data[1] = 0x10; // Example value
    status = i2cWriteI2CBlockData(i2c_handle, config_data[0], &config_data[1], 1);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", config_data[0], status);
        return -1;
    }

    // Set final range minimum count rate return limit
    config_data[0] = VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT;
    config_data[1] = 0x08; // Example value
    status = i2cWriteI2CBlockData(i2c_handle, config_data[0], &config_data[1], 1);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", config_data[0], status);
        return -1;
    }

    // Set sequence config
    config_data[0] = VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG;
    config_data[1] = 0x40; // Example value
    status = i2cWriteI2CBlockData(i2c_handle, config_data[0], &config_data[1], 1);
    if (status < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", config_data[0], status);
        return -1;
    }

    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int *distance) {
    int status;
    char data[2];

    // Start a single measurement (refer to datasheet for details)
    char start_measurement_cmd[2];
    start_measurement_cmd[0] = 0x00; // Control register
    start_measurement_cmd[1] = 0x01; // Start bit
    status = i2cWriteI2CBlockData(i2c_handle, start_measurement_cmd[0], &start_measurement_cmd[1], 1);
    if (status < 0) {
        fprintf(stderr, "Error starting measurement: %d\n", status);
        return -1;
    }

    // Wait for measurement to complete (polling for ready status)
    int ready = 0;
    int timeout = 100; // Timeout after 100ms
    while (!ready && timeout > 0) {
        status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, data, 1);
        if (status < 0) {
            fprintf(stderr, "Error reading range status: %d\n", status);
            return -1;
        }
        if (data[0] & 0x01) {
            ready = 1;
        } else {
            gpioDelay(1); // Wait 1ms
            timeout--;
        }
    }

    if (!ready) {
        fprintf(stderr, "Timeout waiting for measurement\n");
        return -1;
    }

    // Read the distance
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance: %d\n", status);
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Logging function
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Parking guidance function
void print_guidance(int distance) {
    if (distance < 300) {
        printf("STOP\n");
    } else if (distance < 600) {
        printf("APPROACH\n");
    } else if (distance < 1200) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a+");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        status = vl53l1x_read_distance(&distance);
        if (status == 0) {
            log_distance(distance);
            print_guidance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

