int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor with retries
int read_distance() {
    int distance = -1;
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, 0x00); // Assuming register 0x00 holds the distance
        if (result >= 0) {
            distance = result; // Assuming the read value is the distance
