            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    if (distance == -1) {
        fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    }

    return distance;
}

// Calculate LED blink frequency based on distance
int calculate_frequency(int distance) {
    // Map distance (0-255) to frequency (1Hz - 10Hz)
    // Assuming distance 0 is very close and distance 255 is very far
    if (distance < 0) distance = 0;
    if (distance > 255) distance = 255;

    // Invert the distance to increase frequency as distance decreases
    int inverted_distance = 255 - distance;

    // Calculate frequency (linear mapping)
    float frequency = (float)inverted_distance / 255.0 * 9.0 + 1.0; // 1Hz to 10Hz

    return (int)frequency;
}

