    duty_cycle = (int)((10.0 - (float)frequency) / 10.0 * 500000.0); // Inverted linear mapping

    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;

    gpioPWM(LED_GPIO, duty_cycle / 10000); // pigpio uses range 0-255
