        // Read distance
        int distance = read_distance();

        if (distance != -1) {
            // Calculate frequency
            int frequency = calculate_frequency(distance);

            // Control LED
            control_led(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Skipping LED control and logging.\n");
        }

        // Delay for 100ms
        gpioDelay(BLINK_DELAY_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
