    int retries;
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (trigger_measurement() == 0) {
                if (read_distance(&distance) == 0) {
                    log_data(distance);
                    break; // Success, exit retry loop
                } else {
                    fprintf(stderr, "Retrying read... (%d/%d)\n", retries + 1, MAX_RETRIES);
                }
            } else {
                fprintf(stderr, "Retrying trigger... (%d/%d)\n", retries + 1, MAX_RETRIES);
            }
            retries++;
            gpioDelay(10000); // 10ms delay before retry
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for sampling interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

