#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_MS 50
#define POLL_DELAY_MS 10

// Structure to hold sensor state and last transition time
typedef struct {
    int state;
    long long last_transition_time;
} sensor_state_t;

// Global variables
FILE *log_file = NULL;
sensor_state_t sensor1_state = {0, 0};
sensor_state_t sensor2_state = {0, 0};

// Function prototypes
int read_sensor(int gpio);
int debounce(int gpio, int current_state, long long *last_transition_time);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce sensor readings
int debounce(int gpio, int current_state, long long *last_transition_time) {
    long long current_time = time(NULL) * 1000; // Get current time in milliseconds
    if (current_time - *last_transition_time >= DEBOUNCE_DELAY_MS) {
        *last_transition_time = current_time;
        return current_state;
    } else {
        return !current_state; // Return the opposite state during debounce
    }
}

// Function to log events to file
void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *utc_tm = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor 1
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        if (sensor1_value >= 0) {
            int debounced_sensor1_value = debounce(SENSOR_1_GPIO, sensor1_value, &sensor1_state.last_transition_time);
            if (debounced_sensor1_value != sensor1_state.state) {
                sensor1_state.state = debounced_sensor1_value;
                if (sensor1_state.state == 0) {
                    log_event(1, "DETECTED");
                } else {
                    log_event(1, "CLEARED");
                }
            }
        }

        // Read sensor 2
        int sensor2_value = read_sensor(SENSOR_2_GPIO);
        if (sensor2_value >= 0) {
            int debounced_sensor2_value = debounce(SENSOR_2_GPIO, sensor2_value, &sensor2_state.last_transition_time);
            if (debounced_sensor2_value != sensor2_state.state) {
                sensor2_state.state = debounced_sensor2_value;
                if (sensor2_state.state == 0) {
                    log_event(2, "DETECTED");
                } else {
                    log_event(2, "CLEARED");
                }
            }
        }

        gpioDelay(POLL_DELAY_MS * 1000); // Delay for 10ms
    }

    // The following lines will never be reached due to the infinite loop.
    fclose(log_file);
    gpioTerminate();
    return 0;
}

