                } else {
                    log_event(2, "CLEARED");
                }
            }
        }

        gpioDelay(POLL_DELAY_MS * 1000); // Delay for 10ms
    }

    // The following lines will never be reached due to the infinite loop.
    fclose(log_file);
    gpioTerminate();
    return 0;
}

