#include <linux/i2c-dev.h>

// Define the I2C bus and sensor address
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x50

// Define the register addresses
#define MEAS_STATUS 0x00
#define DISTANCE_MSB 0x01
#define DISTANCE_LSB 0x02

// Define the measurement status bits
#define MEAS_READY 0x01

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_write(int fd, unsigned char reg, unsigned char value);
int i2c_read(int fd, unsigned char reg, unsigned char *value, int len);
int read_distance(int fd, int *distance);
void signal_handler(int signal);

// Helper function to write a byte to an I2C register
int i2c_write(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Helper function to read bytes from an I2C register
int i2c_read(int fd, unsigned char reg, unsigned char *value, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int fd, int *distance) {
    unsigned char status;
    unsigned char msb, lsb;
    int retries = 3;

    while (retries > 0) {
        if (i2c_read(fd, MEAS_STATUS, &status, 1) != 0) {
            fprintf(stderr, "Error reading measurement status. Retries remaining: %d\n", retries);
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        if (status & MEAS_READY) {
            if (i2c_read(fd, DISTANCE_MSB, &msb, 1) != 0) {
                fprintf(stderr, "Error reading MSB. Retries remaining: %d\n", retries);
                retries--;
                usleep(10000); // Wait 10ms before retrying
                continue;
            }
            if (i2c_read(fd, DISTANCE_LSB, &lsb, 1) != 0) {
                fprintf(stderr, "Error reading LSB. Retries remaining: %d\n", retries);
                retries--;
                usleep(10000); // Wait 10ms before retrying
                continue;
            }

            *distance = (msb << 8) | lsb;
            return 0; // Success
        } else {
            fprintf(stderr, "Measurement not ready. Status: 0x%02X. Retries remaining: %d\n", status, retries);
            retries--;
            usleep(50000); // Wait 50ms before retrying
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }

    exit(0);
}

int main() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int distance;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the distance
        if (read_distance(i2c_fd, &distance) == 0) {
            // Get the current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log the data to the CSV file
            fprintf(log_file, "%s,%d\n", timestamp, distance);
            fflush(log_file);

            printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Failed to read distance. Skipping sample.\n");
        }

        // Wait 500ms
        usleep(500000);
    }

    // Close the I2C device and log file (should not reach here if signal handler works)
    close(i2c_fd);
    fflush(log_file);
    fclose(log_file);

    return 0;
}

