#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Define the I2C bus and sensor address
#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29

// Define register addresses (example, adjust based on datasheet)
#define REG_IDENTIFICATION_MODEL_ID 0x0000
#define REG_RANGING_MODE 0x001D
#define REG_START_RANGING 0x0008
#define REG_RESULT_RANGE_STATUS 0x0013
#define REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Define constants
#define NUM_ZONES 64
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor configuration
typedef struct {
    uint8_t ranging_mode;
} sensor_config_t;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to write a byte to an I2C register
int write_register(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int read_register(int fd, uint16_t reg, uint8_t *value) {
    uint8_t reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;        // LSB of register address

    if (write(fd, reg_buf, 2) != 2) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_sensor(int fd) {
    int retries = I2C_RETRY_COUNT;
    uint8_t model_id;

    // Check sensor ID
    while (retries > 0) {
        if (read_register(fd, REG_IDENTIFICATION_MODEL_ID, &model_id) == 0) {
            if (model_id == 0xE1) {
                printf("VL53L5CX sensor found!\n");
                break;
            } else {
                fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", model_id);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading sensor ID, retrying... (%d retries left)\n", retries - 1);
            usleep(10000); // Wait 10ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read sensor ID after multiple retries.\n");
        return -1;
    }

    // Configure sensor for 8x8 zone grid (example configuration)
    if (write_register(fd, REG_RANGING_MODE, 0x01) != 0) { // Example: Short distance mode
        fprintf(stderr, "Error writing ranging mode.\n");
        return -1;
    }

    if (write_register(fd, REG_START_RANGING, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging.\n");
        return -1;
    }

    return 0;
}

// Function to read zone data from the sensor
int read_zone_data(int fd, uint16_t *distances) {
    int i;
    uint8_t range_status;
    uint8_t msb, lsb;

    if (read_register(fd, REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status.\n");
        return -1;
    }

    if ((range_status & 0x1F) != 0) {
        fprintf(stderr, "Error: Invalid range status: 0x%02X\n", range_status);
        return -1;
    }

    for (i = 0; i < NUM_ZONES; i++) {
        if (read_register(fd, REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + (i * 2), &msb) != 0) {
            fprintf(stderr, "Error reading MSB for zone %d.\n", i);
            return -1;
        }
        if (read_register(fd, REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + (i * 2) + 1, &lsb) != 0) {
            fprintf(stderr, "Error reading LSB for zone %d.\n", i);
            return -1;
        }
        distances[i] = (msb << 8) | lsb;
    }

    return 0;
}

int main() {
    uint16_t distances[NUM_ZONES];
    int i;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read zone data
        if (read_zone_data(i2c_fd, distances) == 0) {
            // Print distances to console
            printf("Zone Distances: ");
            for (i = 0; i < NUM_ZONES; i++) {
                printf("%d: %dmm ", i, distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Error reading zone data.\n");
        }

        usleep(500000); // 500ms
    }

    // Clean up
    close(i2c_fd);

    return 0;
}

