#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the register addresses for distance reading
#define DISTANCE_MSB_REG 0x00
#define DISTANCE_LSB_REG 0x01

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read distance from the MLX75030 sensor
int read_distance(int i2c_handle, uint16_t *distance) {
    char buffer[2];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_MSB_REG, buffer, 2);
        if (result == 2) {
            // Combine the two bytes to form the distance value
            *distance = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (error code: %d), retrying...\n", result);
            gpioDelay(10); // Wait 10 milliseconds
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        uint16_t distance;
        struct timespec ts;

        // Read the distance from the sensor
        if (read_distance(i2c_handle, &distance) == 0) {
            // Get the current timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Log the distance and timestamp to the console
                printf("Distance: %u mm, Timestamp: %ld.%09ld\n", distance, ts.tv_sec, ts.tv_nsec);
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

