#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L4CX_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L4CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L4CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L4CX_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L4CX_REG_RESULT_INTERRUPT_STATUS 0x0083
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the VL53L4CX sensor
int init_vl53l4cx() {
    // Check sensor ID
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Configure sensor for short-range mode
    char data[2];

    // Set pre-range timeout
    data[0] = VL53L4CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI;
    data[1] = 0x01; // Example value
    if (i2cWriteI2CBlockData(i2c_handle, data[0], data + 1, 1) != 1) {
        fprintf(stderr, "Error writing pre-range timeout\n");
        return -1;
    }

    // Set final range timeout
    data[0] = VL53L4CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI;
    data[1] = 0x01; // Example value
    if (i2cWriteI2CBlockData(i2c_handle, data[0], data + 1, 1) != 1) {
        fprintf(stderr, "Error writing final range timeout\n");
        return -1;
    }

    // Set sequence config
    data[0] = VL53L4CX_REG_SYSTEM_SEQUENCE_CONFIG;
    data[1] = 0x01; // Example value
    if (i2cWriteI2CBlockData(i2c_handle, data[0], data + 1, 1) != 1) {
        fprintf(stderr, "Error writing sequence config\n");
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L4CX sensor
int read_distance() {
    char range_status;
    char distance_data[2];
    int distance;

    // Read range status
    if (i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_RANGE_STATUS, &range_status, 1) != 1) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Check for valid range status
    if ((range_status & 0x1B) != 0) {
        fprintf(stderr, "Invalid range status: 0x%02x\n", range_status);
        return -1;
    }

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance_data, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    distance = (distance_data[0] << 8) | distance_data[1];

    return distance;
}

// Function to get the current timestamp with microsecond precision
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 30, "%Y-%m-%d %H:%M:%S", &tm_info);
    sprintf(timestamp + strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (init_vl53l4cx() != 0) {
        fprintf(stderr, "VL53L4CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        char timestamp[30];
        char interrupt_status;

        // Read interrupt status
        if (i2cReadI2CBlockData(i2c_handle, VL53L4CX_REG_RESULT_INTERRUPT_STATUS, &interrupt_status, 1) != 1) {
            fprintf(stderr, "Error reading interrupt status\n");
            // Continue to the next cycle, but log the error
            get_timestamp(timestamp);
            fprintf(stderr, "%s Error reading interrupt status\n", timestamp);
            gpioDelay(500000); // 500ms
            continue;
        }

        // Check if a new measurement is available
        if (interrupt_status & 0x04) {
            int distance = read_distance();
            if (distance >= 0) {
                get_timestamp(timestamp);
                printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);

                // Clear interrupt
                char clear_interrupt[2];
                clear_interrupt[0] = VL53L4CX_REG_RESULT_INTERRUPT_STATUS;
                clear_interrupt[1] = 0x04;
                if (i2cWriteI2CBlockData(i2c_handle, clear_interrupt[0], clear_interrupt + 1, 1) != 1) {
                    fprintf(stderr, "Error clearing interrupt\n");
                    get_timestamp(timestamp);
                    fprintf(stderr, "%s Error clearing interrupt\n", timestamp);
                }
            } else {
                get_timestamp(timestamp);
                fprintf(stderr, "%s Error reading distance\n", timestamp);
            }
        } else {
            // No new measurement available
            //get_timestamp(timestamp);
            //printf("%s No new measurement available\n", timestamp);
        }

        gpioDelay(500000); // 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

