#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define BUZZER_DURATION 500 // ms

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Log error messages to a file
void log_error(const char *message) {
    FILE *fp = fopen("error.log", "a");
    if (fp != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    } else {
        perror("Error opening error.log");
    }
}

// Initialize the VL53L1X sensor
int vl53l1x_init() {
    // Check sensor ID (example)
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        log_error("Failed to read sensor ID");
        return -1;
    }
    if (model_id != 0xEA) {
        log_error("Incorrect sensor ID");
        return -1;
    }

    // Start continuous ranging mode
    char data[2];
    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01; // Start continuous ranging
    if (i2cWriteI2CBlockData(i2c_handle, data[0], &data[1], 1) != 1) {
        log_error("Failed to start continuous ranging");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int vl53l1x_read_distance(uint16_t *distance) {
    char range_status;
    char data[2];

    // Read range status
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status, 1) != 1) {
        log_error("Failed to read range status");
        return -1;
    }

    // Read distance
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        log_error("Failed to read distance");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Set GPIO high
}

// Deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // Set GPIO low
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("VL53L1X distance monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t distance;

        if (vl53l1x_read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer();
                gpioDelay(BUZZER_DURATION * 1000); // Delay in microseconds
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(500 * 1000); // Delay 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("VL53L1X distance monitoring stopped.\n");

    return 0;
}

