#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_MIN_ANGLE -90
#define SERVO_MAX_ANGLE 90

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
float calculate_distance(long pulse_width);
int map_distance_to_angle(float distance);
int set_servo_angle(int angle);
int log_data(float distance, int angle);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize servo to 0 degrees (center position)
    gpioServo(SERVO_PIN, 1500); // 1500 us is center for most servos
    gpioDelay(1000000); // Wait for servo to settle

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width
long measure_pulse_width() {
    long start_time = 0, end_time = 0;
    long pulse_width = 0;
    int timeout = 0;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        if (gpioTick() - start_time > TIMEOUT_US) {
            return -1; // Timeout
        }
    }

    // Wait for echo to go low
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        if (gpioTick() - end_time > TIMEOUT_US) {
            return -1; // Timeout
        }
    }

    pulse_width = end_time - start_time;
    return pulse_width;
}

// Calculate distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Map distance to servo angle
int map_distance_to_angle(float distance) {
    if (distance < 2.0) {
        return -90; // Too close
    } else if (distance > 400.0) {
        return 90; // Too far
    } else {
        return (int)(((distance - 2.0) / (400.0 - 2.0)) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE);
    }
}

// Set servo angle
int set_servo_angle(int angle) {
    if (angle < -90 || angle > 90) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return 1;
    }

    int pulse_width = (int)(((float)(angle - SERVO_MIN_ANGLE) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

// Log data to file
int log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d degrees\n", timestamp, distance, angle);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        float distance = calculate_distance(pulse_width);

        if (distance > 0) {
            // Map the distance to an angle
            int angle = map_distance_to_angle(distance);

            // Set the servo angle
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Error setting servo angle.\n");
            }

            // Log the data
            if (log_data(distance, angle) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        } else {
            fprintf(stderr, "Sensor timeout or error.\n");
        }

        // Wait 200ms
        gpioDelay(200000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

