#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/msg.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define MESSAGE_QUEUE_KEY 1234
#define DISTANCE_THRESHOLD 100 // mm
#define BUZZER_DURATION 500 // ms

// Global variables
int i2c_handle;
int message_queue_id;
volatile sig_atomic_t terminate = 0;

// Structure for message queue
struct message {
    long mtype; // Message type (must be > 0)
    int distance; // Distance in millimeters
};

// Function prototypes
int init_vl53l1x();
int read_distance();
void log_distance(int distance);
void activate_buzzer();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Implement VL53L1X initialization sequence here
    // This is a placeholder; refer to the VL53L1X datasheet for the correct sequence
    // Example: Writing to a register (replace with actual register and value)
    char data[2];
    data[0] = 0x00; // Register address
    data[1] = 0x01; // Value to write

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error writing to VL53L1X during initialization.\n");
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L1X sensor
int read_distance() {
    // Implement VL53L1X distance reading sequence here
    // This is a placeholder; refer to the VL53L1X datasheet for the correct sequence
    // Example: Reading from a register (replace with actual register)
    char reg = 0x14; // Register address for distance
    char buffer[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to VL53L1X during distance reading.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buffer, 2) != 0) {
        fprintf(stderr, "Error reading from VL53L1X during distance reading.\n");
        return -1;
    }

    // Combine the two bytes to form the distance value
    int distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

// Function to log distance to the message queue
void log_distance(int distance) {
    struct message msg;
    msg.mtype = 1; // Message type (must be > 0)
    msg.distance = distance;

    if (msgsnd(message_queue_id, &msg, sizeof(msg) - sizeof(long), 0) == -1) {
        perror("msgsnd");
        fprintf(stderr, "Error sending message to queue.\n");
    }
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(BUZZER_DURATION * 1000); // Delay for 500ms
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create message queue
    message_queue_id = msgget(MESSAGE_QUEUE_KEY, IPC_CREAT | 0666);
    if (message_queue_id == -1) {
        perror("msgget");
        fprintf(stderr, "Error creating message queue.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);
            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Error reading distance.\n");
        }

        gpioDelay(50 * 1000); // 50ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    gpioTerminate();
    msgctl(message_queue_id, IPC_RMID, NULL); // Remove message queue

    return 0;
}

