#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define MIN_DISTANCE 2.0        // cm
#define MAX_DISTANCE 400.0      // cm
#define BUZZER_THRESHOLD 30.0    // cm
#define TIMEOUT_US 50000         // microseconds (50ms)

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;
volatile int timeout_occurred = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int start_tick, unsigned int end_tick);
void control_buzzer(double distance);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
        timeout_occurred = 0; // Reset timeout flag
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int start_tick, unsigned int end_tick) {
    unsigned int diff = end_tick - start_tick;
    if (end_tick < start_tick) {
        diff = (0xFFFFFFFF - start_tick) + end_tick; // Handle tick wraparound
    }
    return (double)diff * 0.0343 / 2.0; // Speed of sound: 0.0343 cm/us
}

// Function to control the buzzer
void control_buzzer(double distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        trigger_sensor();

        // Wait for echo or timeout
        unsigned int start_time = gpioTick();
        while (!echo_received && !timeout_occurred) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                timeout_occurred = 1;
                break;
            }
            gpioDelay(1); // Small delay to avoid busy-waiting
        }

        // Process the reading
        if (echo_received) {
            double distance = calculate_distance(start_tick, end_tick);

            // Validate distance
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                printf("Distance: %.2f cm\n", distance);
                control_buzzer(distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }

        // Reset flags for next reading
        echo_received = 0;
        timeout_occurred = 0;

        // Delay before next reading
        gpioDelay(100000); // 100ms
    }

    return 0;
}

