#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define SERVO_OPEN_PULSE 1500
#define SERVO_CLOSE_PULSE 1000
#define SERVO_RANGE 1000
#define PWM_FREQUENCY 50
#define PWM_RANGE 20000
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void servo_open();
void servo_close();
void log_event(const char *message);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050


// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    int retries = 0;
    int status = -1;

    while (retries < MAX_RETRIES) {
        // Check sensor ID (example)
        char model_id = 0;
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
            log_event("Error reading VL53L1X model ID.");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        if (model_id != 0xEA) {
            log_event("Incorrect VL53L1X model ID.");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Start ranging (example)
        char start_ranging = 0x01;
        if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSRANGE_START, &start_ranging, 1) != 1) {
            log_event("Error starting VL53L1X ranging.");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        status = 0; // Initialization successful
        log_event("VL53L1X initialized successfully.");
        break;
    }

    if (status != 0) {
        log_event("VL53L1X initialization failed after multiple retries.");
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(int i2c_handle) {
    int retries = 0;
    int distance = -1;

    while (retries < MAX_RETRIES) {
        char range_status = 0;
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status, 1) != 1) {
            log_event("Error reading VL53L1X range status.");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (range_status & 0x01) { // Check for data ready
            char data[2];
            if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
                log_event("Error reading VL53L1X distance.");
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000);
                continue;
            }

            distance = (data[0] << 8) | data[1];
            log_event("VL53L1X distance read successfully.");
            break;
        } else {
            log_event("VL53L1X data not ready.");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
        }
    }

    if (distance == -1) {
        log_event("VL53L1X distance read failed after multiple retries.");
        return -1;
    }

    return distance;
}

