void servo_open() {
    gpioPWM(SERVO_PIN, SERVO_OPEN_PULSE);
    log_event("Servo opened.");
}

// Servo close function
void servo_close() {
    gpioPWM(SERVO_PIN, SERVO_CLOSE_PULSE);
    log_event("Servo closed.");
}

// Log event function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    printf("[%s] %s\n", timestamp, message); // Also print to console
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error opening I2C bus.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        log_event("VL53L1X initialization failed.");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure servo pin
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, PWM_RANGE);

    // Main loop
    while (program_running) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance > 0) {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Distance: %d mm", distance);
            log_event(log_message);

            if (distance < DISTANCE_THRESHOLD) {
                servo_open();
            } else {
                servo_close();
            }
        } else {
            log_event("Failed to read distance.");
        }

        gpioDelay(100 * 1000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

