#define SERVO_OPEN_PULSE 1500
#define SERVO_CLOSE_PULSE 1000
#define DISTANCE_THRESHOLD_OPEN 50 // cm
#define DISTANCE_THRESHOLD_CLOSE 60 // cm
#define LOG_FILE "parking_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void servo_open();
void servo_close();
void log_event(const char *event, int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint8_t reg, uint8_t data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02x\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint8_t reg, uint8_t *data) {
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02x\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02x\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int handle, uint8_t reg, uint16_t *data) {
    char buf[1];
    char read_buf[2];
    buf[0] = reg;

    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02x\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02x\n", reg);
        return -1;
    }

    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// VL53L1X initialization function
int vl53l1x_init() {
    uint8_t model_id;

    // Check if the sensor is present by reading the model ID
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading VL53L1X model ID\n");
        return -1;
    }

    if (model_id != 0xea) {
        fprintf(stderr, "Incorrect VL53L1X model ID: 0x%02x\n", model_id);
        return -1;
    }

    // Add more initialization steps here based on the VL53L1X datasheet
    // For example, setting timing budget, inter-measurement period, etc.

    return 0;
}

