int vl53l1x_read_distance() {
    uint16_t distance;
    uint8_t ready;

    // Check if a new measurement is ready
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY, &ready) != 0) {
        fprintf(stderr, "Error reading measurement ready status\n");
        return -1;
    }

    if (!ready) {
        return -1; // No new measurement available
    }

    // Read the distance in millimeters
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    return (int)distance;
}

// Servo open function
void servo_open() {
    gpioServo(SERVO_PIN, SERVO_OPEN_PULSE);
    gpioDelay(500); // Allow time for the servo to move
}

