void log_event(const char *event, int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d - %s - Distance: %d cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    int distance;
    int gate_open = 0; // 0 = closed, 1 = open

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Parking gate control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        distance = vl53l1x_read_distance();

        if (distance > 0) {
            if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
                printf("Object detected within %d cm, opening gate.\n", distance);
                servo_open();
                log_event("Gate opened", distance);
                gate_open = 1;
            } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
                printf("Object outside %d cm, closing gate.\n", distance);
                servo_close();
                log_event("Gate closed", distance);
                gate_open = 0;
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

