        return -1;
    }

    // Set timing budget
    char timing_budget_data[2];
    timing_budget_data[0] = (TIMING_BUDGET >> 8) & 0xFF; // MSB
    timing_budget_data[1] = TIMING_BUDGET & 0xFF;      // LSB

