#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define TRIGGER_PIN 24

// Define I2C bus
#define I2C_BUS 1

// Define VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// Define distance thresholds
#define FORWARD_THRESHOLD 100
#define BACKWARD_THRESHOLD 300

// Define motor states
typedef enum {
    STOPPED,
    FORWARD,
    BACKWARD
} MotorState;

// Global variables
int i2c_handle;
volatile int running = 1;
MotorState current_motor_state = STOPPED;

// Function prototypes
int vl53l1x_soft_reset(int i2c_handle);
int vl53l1x_start_measurement(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void control_motor(int distance);
void trigger_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050


// VL53L1X soft reset sequence
int vl53l1x_soft_reset(int i2c_handle) {
    char data[2];
    int retries = 3;
    int delay_ms = 10;

    // VL53L1X soft reset sequence (example, adjust as needed)
    data[0] = 0x00; // Register address
    data[1] = 0x01; // Reset command

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, data, 2) == 0) {
            gpioDelay(1000); // Wait 1ms
            return 0; // Success
        } else {
            fprintf(stderr, "Error: VL53L1X soft reset failed, retrying...\n");
            retries--;
            gpioDelay(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }
    fprintf(stderr, "Error: VL53L1X soft reset failed after multiple retries.\n");
    return -1; // Failure
}

// VL53L1X start measurement sequence
int vl53l1x_start_measurement(int i2c_handle) {
    char data[2];
    int retries = 3;
    int delay_ms = 10;

    data[0] = VL53L1X_REG_SYSRANGE_START;
    data[1] = 0x01; // Start measurement

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, data, 2) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: VL53L1X start measurement failed, retrying...\n");
            retries--;
            gpioDelay(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }
    fprintf(stderr, "Error: VL53L1X start measurement failed after multiple retries.\n");
    return -1; // Failure
}

// VL53L1X read distance sequence
int vl53l1x_read_distance(int i2c_handle) {
    char data[1];
    char buffer[2];
    int distance = -1;
    int retries = 3;
    int delay_ms = 10;

    // Read range status
    data[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error: VL53L1X write for range status failed.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buffer, 1) != 1) {
        fprintf(stderr, "Error: VL53L1X read for range status failed.\n");
        return -1;
    }

    // Check data ready bit (bit 0 of range status)
    if (!(buffer[0] & 0x01)) {
        fprintf(stderr, "Error: VL53L1X data not ready.\n");
        return -1;
    }

    // Read distance
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Error: VL53L1X write for distance failed.\n");
        return -1;
    }

    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, buffer, 2) == 2) {
            distance = (buffer[0] << 8) | buffer[1];
            return distance;
        } else {
            fprintf(stderr, "Error: VL53L1X read distance failed, retrying...\n");
            retries--;
            gpioDelay(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }
    fprintf(stderr, "Error: VL53L1X read distance failed after multiple retries.\n");
    return -1; // Failure
}

// Control motor based on distance
void control_motor(int distance) {
    MotorState new_state = STOPPED;

    if (distance < FORWARD_THRESHOLD) {
        new_state = FORWARD;
    } else if (distance > BACKWARD_THRESHOLD) {
        new_state = BACKWARD;
    }

    if (new_state != current_motor_state) {
        switch (new_state) {
            case FORWARD:
                gpioWrite(MOTOR_FORWARD_PIN, 1);
                gpioWrite(MOTOR_BACKWARD_PIN, 0);
                printf("Motor: Forward\n");
                break;
            case BACKWARD:
                gpioWrite(MOTOR_FORWARD_PIN, 0);
                gpioWrite(MOTOR_BACKWARD_PIN, 1);
                printf("Motor: Backward\n");
                break;
            case STOPPED:
                gpioWrite(MOTOR_FORWARD_PIN, 0);
                gpioWrite(MOTOR_BACKWARD_PIN, 0);
                printf("Motor: Stopped\n");
                break;
        }
        current_motor_state = new_state;
    }
}

// Trigger callback function
void trigger_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) { // Rising edge
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            control_motor(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance. Stopping motor.\n");
            gpioWrite(MOTOR_FORWARD_PIN, 0);
            gpioWrite(MOTOR_BACKWARD_PIN, 0);
            current_motor_state = STOPPED;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // VL53L1X initialization
    if (vl53l1x_soft_reset(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_start_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X start measurement failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up trigger callback
    gpioSetAlertFuncEx(TRIGGER_PIN, trigger_callback, NULL);

    printf("VL53L1X motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

