void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPR121 sensor
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100000); // Wait for reset to complete (100ms)

    // Configure electrode sensitivity and release thresholds
    // Example configuration (adjust as needed)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0F) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x0A) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    return 0;
}

