    gpioWrite(LED_PIN_0, (pattern >> 0) & 1);
    gpioWrite(LED_PIN_1, (pattern >> 1) & 1);
    gpioWrite(LED_PIN_2, (pattern >> 2) & 1);
    gpioWrite(LED_PIN_3, (pattern >> 3) & 1);
}

