    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED_PIN_0, PI_OUTPUT);
    gpioSetMode(LED_PIN_1, PI_OUTPUT);
    gpioSetMode(LED_PIN_2, PI_OUTPUT);
    gpioSetMode(LED_PIN_3, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    uint8_t led_pattern = 0;

    // Main loop
    while (program_running) {
        if (mpr121_read_touch_status(&touch_status) == 0) {
            for (int i = 0; i < 12; i++) {
                if ((touch_status >> i) & 1) {
                    log_event(i);
                    led_pattern = (led_pattern + 1) % 16; // Cycle through patterns
                    set_led_pattern(led_pattern);
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status in main loop\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Clean up resources
    set_led_pattern(0); // Turn off LEDs
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

