// MPR121 register addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ELE0_L 0x41
#define MPR121_ELE0_H 0x42
#define MPR121_ELE1_L 0x43
#define MPR121_ELE1_H 0x44
#define MPR121_ELE2_L 0x45
#define MPR121_ELE2_H 0x46
#define MPR121_ELE3_L 0x47
#define MPR121_ELE3_H 0x48
#define MPR121_ELE4_L 0x49
#define MPR121_ELE4_H 0x4A
#define MPR121_ELE5_L 0x4B
#define MPR121_ELE5_H 0x4C
