#define MPR121_ELE9_H 0x54
#define MPR121_ELE10_L 0x55
#define MPR121_ELE10_H 0x56
#define MPR121_ELE11_L 0x57
#define MPR121_ELE11_H 0x58
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// GPIO pin for LED
#define LED_PIN 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
int mpr121_set_register(uint8_t reg, uint8_t value);
int mpr121_get_register(uint8_t reg, uint8_t *value);
void log_proximity_event();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Verify device ID
    uint8_t device_id;
    if (mpr121_get_register(MPR121_CONFIG1, &device_id) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (device_id != 0x1E) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Configure MPR121 registers
    if (mpr121_set_register(MPR121_CONFIG2, 0x01) != 0) return -1; // Exit from stop mode
    if (mpr121_set_register(MPR121_MHDR, 0x01) != 0) return -1;
    if (mpr121_set_register(MPR121_NHDR, 0x01) != 0) return -1;
    if (mpr121_set_register(MPR121_NCLR, 0x0E) != 0) return -1;
    if (mpr121_set_register(MPR121_FDLR, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_MHDF, 0x01) != 0) return -1;
    if (mpr121_set_register(MPR121_NHDF, 0x01) != 0) return -1;
    if (mpr121_set_register(MPR121_NCLF, 0x0E) != 0) return -1;
    if (mpr121_set_register(MPR121_FDLF, 0x00) != 0) return -1;

    // Set electrode sensitivity and release thresholds
    if (mpr121_set_register(MPR121_ELE0_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE0_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE1_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE1_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE2_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE2_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE3_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE3_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE4_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE4_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE5_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE5_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE6_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE6_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE7_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE7_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE8_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE8_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE9_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE9_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE10_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE10_H, 0x00) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE11_L, 0x30) != 0) return -1;
    if (mpr121_set_register(MPR121_ELE11_H, 0x00) != 0) return -1;

    // Enable all electrodes
    if (mpr121_set_register(MPR121_CONFIG1, 0x10) != 0) return -1; // Enable all electrodes

    return 0;
}

// Function to read touch status from MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status\n");
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to set a register on the MPR121
int mpr121_set_register(uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
