// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TRIGGER_PULSE_DURATION 10 // us
#define TRIGGER_HOLD_DURATION 5  // us
#define ECHO_TIMEOUT 30         // ms

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
double calculate_distance(long pulse_width);
int validate_distance(double distance);
char* get_iso8601_timestamp();
int log_distance(char *timestamp, double distance);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // 1ms delay

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(TRIGGER_HOLD_DURATION);
}

// Measure the echo pulse width
long measure_pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout_count = 0;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        timeout_count++;
        if (timeout_count > ECHO_TIMEOUT * 1000) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Wait for echo to go low
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        timeout_count++;
        if (timeout_count > ECHO_TIMEOUT * 1000) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return end_time - start_time;
}

// Calculate distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Validate distance
int validate_distance(double distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log distance to file
int log_distance(char *timestamp, double distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    printf("Starting distance measurement...\n");

    while (running) {
        // Trigger sensor
        trigger_sensor();

        // Measure pulse width
        long pulse_width = measure_pulse_width();

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Validate distance
        if (distance > 0 && validate_distance(distance)) {
            // Get timestamp
            char *timestamp = get_iso8601_timestamp();

            // Log distance
            if (log_distance(timestamp, distance) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

