#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define MAX_PULSE_WIDTH 25000      // microseconds (25ms)
#define MIN_PULSE_WIDTH 58         // microseconds
#define SOUND_SPEED 34300          // cm/s
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile unsigned int pulse_start = 0;
static volatile unsigned int pulse_end = 0;
static volatile int echo_active = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
  gpioWrite(TRIG_PIN, 1);
  gpioDelay(TRIGGER_PULSE_DURATION);
  gpioWrite(TRIG_PIN, 0);
}

// Interrupt service routine for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
  if (level == 1) {
    pulse_start = tick;
    echo_active = 1;
  } else if (level == 0 && echo_active) {
    pulse_end = tick;
    echo_active = 0;
  }
}

