#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for XSHUT
#define XSHUT_PIN 27

// I2C bus
#define I2C_BUS 1

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_SPAD_NB 0x0022
#define VL53L1X_REG_RESULT_DISTANCE 0x001E

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID (example)
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        syslog(LOG_ERR, "Failed to read model ID");
        return -1;
    }
    if (model_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect model ID: 0x%02x", model_id);
        return -1;
    }

    // Start continuous ranging (example)
    char start_data[2] = {0x01, 0x00}; // Example values, adjust based on datasheet
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSRANGE_START, start_data, 2) != 2) {
        syslog(LOG_ERR, "Failed to start continuous ranging");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_DISTANCE, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Log data to syslog
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (status == 0) {
        syslog(LOG_INFO, "%s Distance: %d mm", timestamp, distance);
    } else {
        syslog(LOG_ERR, "%s Error reading distance", timestamp);
    }
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set XSHUT pin as output and set high
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1);

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        syslog(LOG_ERR, "Failed to initialize VL53L1X sensor");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "VL53L1X sensor initialized successfully");

    // Main loop
    int distance;
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_data(distance, 0);
        } else {
            log_data(0, -1);
        }
        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

