#define GPIO_GATE 24
#define DISTANCE_THRESHOLD 20 // cm
#define GATE_OPEN 1
#define GATE_CLOSED 0
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance();
float convert_to_cm(int distance);
int control_gate(float distance);
void log_data(int distance, int gate_state, const char *error_message);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the VL53L1X sensor
int initialize_sensor() {
    // Implement VL53L1X initialization sequence here
    // This is a placeholder; refer to the VL53L1X datasheet for the correct sequence
    // Example: Writing to a register (replace with actual register and value)
    char init_data[] = {0x00, 0x01}; // Example: Register 0x00, Value 0x01
    int result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    // Implement VL53L1X distance reading sequence here
    // This is a placeholder; refer to the VL53L1X datasheet for the correct sequence
    // Example: Reading from a register (replace with actual register)
    char read_command[] = {0x01}; // Example: Register to read from
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, read_command, sizeof(read_command));
    if (result != 0) {
        fprintf(stderr, "Error writing to sensor for reading: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buffer, sizeof(buffer));
    if (result != sizeof(buffer)) {
        fprintf(stderr, "Error reading from sensor: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int distance = (buffer[0] << 8) | buffer[1];
    return distance;
}

