    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GPIO_GATE, PI_OUTPUT);
    gpioWrite(GPIO_GATE, GATE_CLOSED); // Initialize gate to closed

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance < 0) {
            log_data(0, GATE_CLOSED, "Error reading distance");
        } else {
            float distance_cm = convert_to_cm(distance);
            int gate_state = control_gate(distance_cm);
            log_data(distance, gate_state, NULL);
        }
        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_GATE, GATE_CLOSED); // Ensure gate is closed on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

