#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TRIGGER_PERIOD 100        // milliseconds
#define TIMEOUT_DURATION 30       // milliseconds
#define SPEED_OF_SOUND 34300.0    // cm/s
#define DEFAULT_SERVO_ANGLE 90    // degrees

// Define moving average filter size
#define MOVING_AVERAGE_SIZE 5

// Global variables
volatile int pulse_width = 0;
volatile int new_pulse = 0;
volatile sig_atomic_t program_running = 1;

// Moving average filter buffer
float distance_buffer[MOVING_AVERAGE_SIZE];
int buffer_index = 0;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
float moving_average_filter(float new_distance);
void set_servo_angle(int angle);
void log_data(float distance, int servo_angle);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
  gpioWrite(TRIGGER_PIN, 1);
  gpioDelay(TRIGGER_PULSE_DURATION);
  gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
  static uint32_t start_tick = 0;
  static uint32_t end_tick = 0;

  if (level == 1) {
    start_tick = tick;
  } else if (level == 0) {
    end_tick = tick;

    // Calculate pulse width in microseconds
    int pulse = end_tick - start_tick;
    if (pulse < 0) {
      pulse += 0xFFFFFFFF; // Handle wrap-around
    }

    // Store pulse width
    pulse_width = pulse;
    new_pulse = 1;
  }
}

// Function to calculate distance in centimeters
float calculate_distance(int pulse_width) {
  if (pulse_width > 0 && pulse_width < TIMEOUT_DURATION * 1000) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
  } else {
    return -1.0; // Indicate error
  }
}

// Function to implement a moving average filter
float moving_average_filter(float new_distance) {
  // Update buffer with new distance
  distance_buffer[buffer_index] = new_distance;
  buffer_index = (buffer_index + 1) % MOVING_AVERAGE_SIZE;

  // Calculate sum of distances in the buffer
  float sum = 0.0;
  for (int i = 0; i < MOVING_AVERAGE_SIZE; i++) {
    sum += distance_buffer[i];
  }

  // Calculate average distance
  return sum / MOVING_AVERAGE_SIZE;
}

// Function to set the servo angle using pigpio
void set_servo_angle(int angle) {
  if (angle >= 0 && angle <= 180) {
    gpioServo(SERVO_PIN, angle * 1000 / 180 + 500); // Convert angle to pulse width (500-2500)
  } else {
    fprintf(stderr, "Error: Invalid servo angle: %d\n", angle);
  }
}

// Function to log data to a CSV file
void log_data(float distance, int servo_angle) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[20];

  time(&rawtime);
  timeinfo = localtime(&rawtime);
  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

  fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, servo_angle);
  fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
  program_running = 0;
  printf("Caught signal %d, stopping program...\n", signal);
}

int main() {
  // Initialize pigpio library
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  // Set GPIO modes
  gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
  gpioSetMode(ECHO_PIN, PI_INPUT);
  gpioSetMode(SERVO_PIN, PI_OUTPUT);

  // Set pull-down resistor on echo pin to avoid floating values
  gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

  // Register interrupt callback for echo pin
  if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
    fprintf(stderr, "Failed to register interrupt callback\n");
    gpioTerminate();
    return 1;
  }

  // Open log file
  log_file = fopen("distance_log.csv", "a");
  if (log_file == NULL) {
    fprintf(stderr, "Failed to open log file\n");
    gpioTerminate();
    return 1;
  }

  // Write header row if the file is newly created
  fseek(log_file, 0, SEEK_END);
  long file_size = ftell(log_file);
  if (file_size == 0) {
    fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
  }

  // Initialize moving average filter
  for (int i = 0; i < MOVING_AVERAGE_SIZE; i++) {
    distance_buffer[i] = 0.0;
  }

  // Set default servo angle
  set_servo_angle(DEFAULT_SERVO_ANGLE);

  // Register signal handler for Ctrl+C
  signal(SIGINT, signal_handler);

  printf("Program started. Press Ctrl+C to exit.\n");

  // Main loop
  while (program_running) {
    // Trigger the ultrasonic sensor
    trigger_pulse();

    // Wait for a short period to allow the echo to return
    gpioDelay(TRIGGER_PERIOD);

    // Read pulse width and calculate distance
    if (new_pulse) {
      int pulse = pulse_width;
      new_pulse = 0;
      float distance = calculate_distance(pulse);

      // Validate distance reading
      if (distance > 2.0 && distance < 400.0) {
        // Apply moving average filter
        float filtered_distance = moving_average_filter(distance);

        // Determine servo angle based on distance
        int servo_angle = (int)((filtered_distance - 2.0) / (400.0 - 2.0) * 180.0);
        if (servo_angle < 0) servo_angle = 0;
        if (servo_angle > 180) servo_angle = 180;

        // Set servo angle
        set_servo_angle(servo_angle);

        // Log data
        log_data(filtered_distance, servo_angle);
      } else {
        // Log error and set default servo angle
        log_data(-1.0, DEFAULT_SERVO_ANGLE);
        set_servo_angle(DEFAULT_SERVO_ANGLE);
      }
    } else {
      // Log error and set default servo angle
      log_data(-1.0, DEFAULT_SERVO_ANGLE);
      set_servo_angle(DEFAULT_SERVO_ANGLE);
    }
  }

  // Stop the servo
  set_servo_angle(0);

  // Close log file
  fclose(log_file);

  // Terminate pigpio library
  gpioTerminate();

  printf("Program finished.\n");
  return 0;
}

