#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_INTERRUPT 27
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int threshold = DEFAULT_THRESHOLD;
int i2c_address = DEFAULT_I2C_ADDRESS;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int i2c_address);
int init_gpio(int gpio_pin);
int init_sensor(int i2c_handle);
int read_proximity(int i2c_handle);
void log_data(int proximity_value, int threshold);
void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata);
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c(int i2c_address) {
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(gpio_pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting GPIO pull-down resistor\n");
        return -1;
    }
    return 0;
}

// Function to initialize the Si1102 sensor
int init_sensor(int i2c_handle) {
    // Example initialization sequence (replace with actual Si1102 init)
    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) { // Reset
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    gpioDelay(10); // Delay after reset

    if (i2cWriteByteData(i2c_handle, 0x18, 0x0F) < 0) { // Enable proximity
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) { // Set measurement mode
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    return 0;
}

// Function to read proximity value from the sensor
int read_proximity(int i2c_handle) {
    int proximity_value = i2cReadWordData(i2c_handle, 0x24); // Example register
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    return proximity_value;
}

// Function to log data to file
void log_data(int proximity_value, int threshold) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, ", timestamp, proximity_value);
    if (proximity_value <= threshold) {
        fprintf(log_file, "SAFE\n");
    } else {
        fprintf(log_file, "ALERT\n");
    }
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    int proximity_value = read_proximity(i2c_handle);
    if (proximity_value >= 0) {
        log_data(proximity_value, threshold);
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_INTERRUPT) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_INTERRUPT, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Proximity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioSetISRFuncEx(GPIO_INTERRUPT, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

