#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0       // Minimum distance in cm
#define MAX_DISTANCE 200.0      // Maximum distance in cm
#define MIN_FREQUENCY 200.0     // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0    // Maximum frequency in Hz
#define TIMEOUT_US 200000       // Timeout in microseconds (200ms)

// Global variables
static volatile int running = 1;
static volatile unsigned int last_tick = 0;
static volatile double last_frequency = 440.0; // Default frequency

// Function prototypes
double measure_distance();
double map_distance_to_frequency(double distance);
void generate_pwm(double frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
double measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    unsigned int start_tick = 0, end_tick = 0;
    int timeout = TIMEOUT_US;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every microsecond
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    timeout = TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1);
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate pulse duration in microseconds
    unsigned int pulse_duration = end_tick - start_tick;

    // Calculate distance in centimeters
    double distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

