double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    }

    // Logarithmic mapping
    double log_min_distance = log10(MIN_DISTANCE);
    double log_max_distance = log10(MAX_DISTANCE);
    double log_distance = log10(distance);

    double frequency_range = MAX_FREQUENCY - MIN_FREQUENCY;
    double distance_range = log_max_distance - log_min_distance;

    double frequency = MIN_FREQUENCY + (frequency_range * (log_distance - log_min_distance) / distance_range);

    return frequency;
}

// Function to generate PWM signal
void generate_pwm(double frequency) {
    int duty_cycle = 128; // 50% duty cycle (0-255)
    int period = 1000000 / frequency; // Period in microseconds
    int pulse_width = period / 2; // Half the period for a square wave

    gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency);
    gpioPWM(SPEAKER_PIN, duty_cycle);
}

