    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(SPEAKER_PIN, 255);

    // Set PWM frequency (initial value)
    gpioSetPWMfrequency(SPEAKER_PIN, 440);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("HC-SR04 Ultrasonic Sensor and 8-ohm Speaker\n");
    printf("Press Ctrl+C to exit\n");

    while (running) {
        double distance = measure_distance();

        if (distance > 0) {
            double frequency = map_distance_to_frequency(distance);
            generate_pwm(frequency);
            last_frequency = frequency;
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            // Error occurred, use the last valid frequency
            generate_pwm(last_frequency);
            fprintf(stderr, "Error: Invalid distance reading, using last valid frequency\n");
        }

        gpioDelay(50); // Delay between readings
    }

    // Cleanup (should not reach here if signal handler works)
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM
    gpioTerminate();         // Terminate pigpio

    return 0;
}

