// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout

// Global variable for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure the duration of the echo pulse
long measure_pulse_duration() {
    long start_time = 0, end_time = 0;
    long pulse_duration = -1; // Initialize to -1 to indicate error
    int timeout_count = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo start\n");
        return -1; // Timeout
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1);
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo end\n");
        return -1; // Timeout
    }

    end_time = gpioTick();

    pulse_duration = end_time - start_time;

    return pulse_duration;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to validate the distance
int validate_distance(double distance) {
    return (distance >= 2.0 && distance <= 400.0);
}

// Function to print the distance with error handling
void print_distance(double distance) {
    if (distance < 0) {
        fprintf(stderr, "Invalid reading\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
        if (distance < 10.0) {
            printf("Too close!\n");
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us pulse
        gpioWrite(TRIGGER_PIN, 0);

        // Measure the pulse duration
        long pulse_duration = measure_pulse_duration();

        // Calculate the distance
        double distance = calculate_distance(pulse_duration);

        // Validate and print the distance
        if (validate_distance(distance)) {
            print_distance(distance);
        } else {
            fprintf(stderr, "Invalid reading\n");
        }

        // Wait before the next measurement
        gpioDelay(500); // 500 ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

