#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1175_ADDR 0x60
#define ALS_VISIBLE_REG 0x22
#define LOG_FILE "proximity_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int read_als_visible(uint16_t *als_value);
char *format_timestamp(char *timestamp_str, size_t timestamp_str_size);
int write_to_log(const char *timestamp, uint16_t als_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ALS Visible value from the sensor
int read_als_visible(uint16_t *als_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_VISIBLE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS Visible data: %d\n", result);
        return -1;
    }

    *als_value = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

// Format the current timestamp in ISO 8601 format
char *format_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Write the timestamp and ALS Visible value to the log file
int write_to_log(const char *timestamp, uint16_t als_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        uint16_t als_value;
        char timestamp[32];

        // Read ALS Visible value
        if (read_als_visible(&als_value) == 0) {
            // Format timestamp
            format_timestamp(timestamp, sizeof(timestamp));

            // Write to log file
            if (write_to_log(timestamp, als_value) != 0) {
                fprintf(stderr, "Error writing to log file.\n");
            }
        } else {
            fprintf(stderr, "Failed to read ALS Visible value.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper resource cleanup in case the loop were to terminate.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

