#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 Register Addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_PS1_DATA0 0x24
#define SI1120_REG_COMMAND 0x30
#define SI1120_REG_HW_KEY 0x07

// Si1120 Commands
#define SI1120_CMD_RESET 0x01

// Si1120 Part ID
#define SI1120_PART_ID 0x20

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to read a register from the Si1120 with retries
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to write a register to the Si1120 with retries
int write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing register 0x%02X: %d. Retrying...\n", reg, result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to write register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to initialize the Si1120 sensor
int initialize_sensor(int handle) {
    uint8_t part_id;

    // Reset the sensor
    if (write_register(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1120 sensor.\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Verify Part ID
    if (read_register(handle, SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Si1120 Part ID.\n");
        return -1;
    }

    if (part_id != SI1120_PART_ID) {
