int init_i2c(const char *bus, int addr);
int verify_sensor(int fd, int expected_part_id);
int configure_sensor(int fd, int meas_rate);
int read_sensor_data(int fd, int *lux, int *proximity);
void log_data(FILE *fp, int lux, int proximity);
void print_data(int lux, int proximity);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// Initialize I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Verify sensor by reading part ID
int verify_sensor(int fd, int expected_part_id) {
    unsigned char part_id;
    if (read(fd, &part_id, 1) != 1) {
        perror("Error reading part ID");
        return -1;
    }

    if (part_id != expected_part_id) {
        fprintf(stderr, "Error: Incorrect part ID. Expected 0x%02X, got 0x%02X\n", expected_part_id, part_id);
        return -1;
    }

    return 0;
}

// Configure sensor measurement rate
int configure_sensor(int fd, int meas_rate) {
    unsigned char buf[2];
    buf[0] = SI1182_MEAS_RATE_REG;
    buf[1] = meas_rate;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to measurement rate register");
        return -1;
    }

    return 0;
}

