    if (read(fd, als_data, 2) != 2) {
        perror("Error reading ambient light data");
        return -1;
    }
    *lux = (als_data[1] << 8) | als_data[0];

    // Read proximity data
    if (read(fd, ps_data, 2) != 2) {
        perror("Error reading proximity data");
        return -1;
    }
    *proximity = (ps_data[1] << 8) | ps_data[0];

    return 0;
}

// Log data to file
void log_data(FILE *fp, int lux, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03d", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, lux, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Print data to stdout
void print_data(int lux, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03d", &tm);

    printf("%s,%d,%d\n", timestamp, lux, proximity);
}

