    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, SI1182_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Verify sensor
    if (verify_sensor(i2c_fd, SI1182_PART_ID) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_fd, 0x0A) < 0) { // Example: Set measurement rate to 0x0A
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    int lux, proximity;
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &lux, &proximity) == 0) {
            // Log data
            log_data(log_file, lux, proximity);

            // Print data
            print_data(lux, proximity);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait 100 milliseconds
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    return 0;
}

