#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TRIGGER_PULSE_DURATION 10 // us
#define DISTANCE_THRESHOLD 20.0 // cm

// Global variables
volatile static unsigned int start_tick = 0;
volatile static unsigned int end_tick = 0;
volatile static int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
void set_buzzer(int state);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Flag that rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 2; // Flag that falling edge has been received
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to set the buzzer state
void set_buzzer(int state) {
    gpioWrite(BUZZER_PIN, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo pulse to be received
        int timeout = 100; // Timeout after 100ms
        while (echo_received != 2 && timeout > 0) {
            gpioDelay(1); // Wait 1ms
            timeout--;
        }

        if (echo_received != 2) {
            fprintf(stderr, "Timeout waiting for echo\n");
            echo_received = 0; // Reset flag for next attempt
            continue;
        }

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;

        // Calculate distance
        float distance = calculate_distance(pulse_width);

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Control buzzer
        if (distance < DISTANCE_THRESHOLD) {
            set_buzzer(1); // Turn buzzer on
        } else {
            set_buzzer(0); // Turn buzzer off
        }

        // Reset echo_received flag
        echo_received = 0;

        // Wait for 1 second
        gpioDelay(1000);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

