#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 200000       // 200ms timeout

// Global variables
volatile int running = 1;

// Function prototypes
float measure_distance();
void set_servo_angle(float distance);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0;
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0;
    }

    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000 for us to s conversion and 2 for one-way distance

    return distance;
}

// Function to set servo angle based on distance
void set_servo_angle(float distance) {
    int pulse_width;

    // Map distance to pulse width (0-180 degrees)
    if (distance > 200.0) {
        pulse_width = 500; // 0°
    } else if (distance < 20.0) {
        pulse_width = 2500; // 180°
    } else {
        pulse_width = 500 + (int)((200.0 - distance) / (200.0 - 20.0) * (2500.0 - 500.0));
    }

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        float distance = measure_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            set_servo_angle(distance);
        } else {
            fprintf(stderr, "Error: Could not measure distance\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup (should not reach here if signal handler works)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio

    return 0;
}

