#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_SERVO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // µs
#define DISTANCE_REG 0x0089 // Distance register
#define MODEL_ID_REG 0x00C0 // Model ID register
#define MODEL_ID_VALUE 0xEACC // Expected Model ID value
#define TIMING_BUDGET_REG 0x001D // Timing budget register
#define TIMING_BUDGET_VALUE 0x4E24 // 33ms timing budget

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void set_servo_pulse_width(int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Check Model ID
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, MODEL_ID_REG, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading Model ID\n");
        return -1;
    }
    if (model_id != MODEL_ID_VALUE) {
        fprintf(stderr, "Incorrect Model ID: 0x%02X (expected 0x%02X)\n", model_id, MODEL_ID_VALUE);
        return -1;
    }
    printf("Model ID verified\n");

    // Program Timing Budget
    char timing_budget[2];
    timing_budget[0] = TIMING_BUDGET_VALUE & 0xFF;
    timing_budget[1] = (TIMING_BUDGET_VALUE >> 8) & 0xFF;
    if (i2cWriteI2CBlockData(i2c_handle, TIMING_BUDGET_REG, timing_budget, 2) != 2) {
        fprintf(stderr, "Error writing Timing Budget\n");
        return -1;
    }
    printf("Timing Budget programmed\n");

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char distance_data[2];
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, distance_data, 2) != 2) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    int distance = (distance_data[0] << 8) | distance_data[1];
    return distance;
}

// Set servo pulse width
void set_servo_pulse_width(int pulse_width) {
    gpioPWM(GPIO_SERVO, pulse_width);
}

// Log event to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

