#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms
#define TRIGGER_PULSE_US 10    // 10us
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define DISTANCE_MIN 2.0
#define DISTANCE_MAX 400.0
#define DISTANCE_THRESHOLD 20.0

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
float measure_distance();
int map_distance_to_angle(float distance);
void set_servo_angle(int angle);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) // Rising edge
    {
        echo_start_tick = tick;
        echo_received = 1; // Indicate rising edge received
    }
    else if (level == 0) // Falling edge
    {
        echo_end_tick = tick;
    }
}

// Function to send a trigger pulse
void trigger_pulse()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance
float measure_distance()
{
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_received = 0;

    trigger_pulse();

    uint32_t start_time = gpioTick();
    while (!echo_received && (gpioTick() - start_time) < TIMEOUT_US)
    {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (!echo_received)
    {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1.0;
    }

    start_time = gpioTick();
    while (echo_received && (gpioTick() - start_time) < TIMEOUT_US)
    {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (!echo_end_tick)
    {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1.0;
    }

    uint32_t diff = echo_end_tick - echo_start_tick;
    float time_taken = (float)diff / 1000000.0; // Convert to seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    return distance;
}

// Function to map distance to servo angle
int map_distance_to_angle(float distance)
{
    int angle;

    if (distance < DISTANCE_MIN)
    {
        angle = 0;
    }
    else if (distance > DISTANCE_MAX)
    {
        angle = 180;
    }
    else
    {
        angle = (int)(((distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN)) * 180.0);
    }

    return angle;
}

// Function to set the servo angle
void set_servo_angle(int angle)
{
    if (angle < 0 || angle > 180)
    {
        fprintf(stderr, "Invalid angle: %d\n", angle);
        return;
    }

    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + ((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Ctrl+C pressed. Stopping servo and exiting.\n");
    set_servo_angle(0); // Set servo to 0 degrees
    gpioTerminate();     // Terminate pigpio
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement and servo control\n");

    while (1)
    {
        float distance = measure_distance();
        int angle;

        if (distance < 0)
        {
            printf("Timeout, distance: -1.0 cm\n");
            angle = 0; // Set to 0 angle on timeout
        }
        else
        {
            angle = map_distance_to_angle(distance);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        set_servo_angle(angle);
        gpioDelay(100); // Pause 100ms
    }

    return 0;
}

