#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si7005 I2C address
#define SI7005_ADDR 0x40

// Si7005 register addresses
#define SI7005_TEMP_REG 0x00
#define SI7005_HUMID_REG 0x01
#define SI7005_CONFIG_REG 0x02

// Configuration register value (example: continuous mode, 14-bit resolution)
#define SI7005_CONFIG_VALUE 0x00

// I2C bus number
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the Si7005 sensor
int initialize_si7005()
{
    // Write the configuration register
    int result = i2cWriteByteData(i2c_handle, SI7005_CONFIG_REG, SI7005_CONFIG_VALUE);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for configuration to take effect
    return 0;
}

// Function to read temperature and humidity data from the Si7005
int read_si7005(float *temperature, float *humidity)
{
    uint16_t raw_temperature, raw_humidity;
    int result;

    // Read temperature
    result = i2cWriteByte(i2c_handle, SI7005_TEMP_REG);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature register address: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for conversion
    result = i2cReadWordData(i2c_handle, SI7005_TEMP_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    raw_temperature = (uint16_t)result;

    // Read humidity
    result = i2cWriteByte(i2c_handle, SI7005_HUMID_REG);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity register address: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for conversion
    result = i2cReadWordData(i2c_handle, SI7005_HUMID_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    raw_humidity = (uint16_t)result;

    // Convert raw data to temperature (Celsius) and humidity (%)
    *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si7005 sensor
    if (initialize_si7005() != 0) {
        fprintf(stderr, "Si7005 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_si7005(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting to re-initialize...\n");
            i2cClose(i2c_handle);
            gpioDelay(100); // Small delay before re-initialization
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (initialize_si7005() != 0) {
                    fprintf(stderr, "Si7005 re-initialization failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

