#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 measurement command (High Repeatability)
#define SHT40_MEASURE_CMD 0xFD

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// CRC initial value
#define CRC_INITIAL 0xFF

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht40(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
void log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    uint8_t cmd = SHT40_MEASURE_CMD;
    uint8_t buffer[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (calculate_crc(buffer, 2) != buffer[2] || calculate_crc(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temperature_raw = (buffer[0] << 8) | buffer[1];
    uint16_t humidity_raw = (buffer[3] << 8) | buffer[4];

    data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to console
void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, data->temperature, data->humidity);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Initialize I2C
        if (init_i2c() != 0) {
            fprintf(stderr, "Failed to initialize I2C, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        // Read sensor data
        if (read_sht40(&sensor_data) == 0) {
            // Log data
            log_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying in 1 second...\n");
        }

        // Close I2C bus
        i2cClose(i2c_handle);
        i2c_handle = -1; // Reset handle

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

