#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_temperatures();
float convert_to_celsius(unsigned int raw_temp);
char* get_timestamp();
int log_data(sensor_data_t data, char* timestamp);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperatures from the sensor
sensor_data_t read_temperatures() {
    sensor_data_t data;
    unsigned char buffer[2];
    int result;

    // Read ambient temperature
    result = i2cReadI2CBlockData(i2c_handle, AMBIENT_TEMP_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ambient temperature: %d\n", result);
        data.ambient_temp = -273.15; // Return absolute zero on error
    } else {
        unsigned int raw_ambient = (buffer[1] << 8) | buffer[0];
        data.ambient_temp = convert_to_celsius(raw_ambient);
    }

    // Read object temperature
    result = i2cReadI2CBlockData(i2c_handle, OBJECT_TEMP_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading object temperature: %d\n", result);
        data.object_temp = -273.15; // Return absolute zero on error
    } else {
        unsigned int raw_object = (buffer[1] << 8) | buffer[0];
        data.object_temp = convert_to_celsius(raw_object);
    }

    return data;
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(unsigned int raw_temp) {
    // The MLX90614 returns a 16-bit value, with the least significant bit
    // representing 0.0078125 degrees Celsius.
    return (float)raw_temp * 0.0078125;
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static to preserve the string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log data to a file
int log_data(sensor_data_t data, char* timestamp) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.ambient_temp, data.object_temp);
    fclose(log_file);
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler for Ctrl+C
