#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define LOG_FILE "pressure_log.csv"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, unsigned short command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int count);
sensor_data_t process_data(const char *buffer);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8 polynomial and initialization value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Function to calculate CRC-8
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, unsigned short command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate CRC-8
int validate_crc(const char *data, int count) {
    unsigned char crc = crc8((unsigned char *)data, count - 1);
    if (crc != (unsigned char)data[count - 1]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }
    return 0;
}

// Function to process the raw data
sensor_data_t process_data(const char *buffer) {
    sensor_data_t data;
    // Extract raw values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t raw_scale_pressure = (buffer[6] << 8) | buffer[7];
    int16_t raw_scale_temperature = (buffer[8] << 8) | buffer[9];

    // Validate CRC for pressure
    if (validate_crc(buffer, 3) != 0) {
        data.pressure = -999.0; // Indicate error
    } else {
        // Convert to Pascals
        float scale_pressure = (float)raw_scale_pressure;
        data.pressure = (float)raw_pressure / scale_pressure;
    }

    // Validate CRC for temperature
    if (validate_crc(buffer + 3, 3) != 0) {
        data.temperature = -999.0; // Indicate error
    } else {
        // Convert to Celsius
        float scale_temperature = (float)raw_scale_temperature;
        data.temperature = (float)raw_temperature / scale_temperature;
    }

    return data;
}

// Function to log the data to a file
int log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    // Check if the file is empty and add a header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor for continuous measurement
    if (send_command(i2c_handle, MEASURE_CMD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[10];

        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(1); // Wait at least 1ms

        // Read data
        if (read_data(i2c_handle, buffer, 10) != 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Process data
        sensor_data_t data = process_data(buffer);

        // Log data
        if (data.pressure != -999.0 && data.temperature != -999.0) {
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Invalid sensor data, not logging\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

