#include <string.h>
#include <unistd.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (high repeatability)
#define MEASURE_CMD 0xFD

// CRC polynomial
#define CRC_POLY 0x31

// CRC initial value
#define CRC_INIT 0xFF

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int sht40_read_data(int i2c_handle, uint8_t *data);
int sht40_validate_data(const uint8_t *data);
void sht40_convert_data(const uint8_t *data, float *temperature, float *humidity);
void log_data(float temperature, float humidity, FILE *log_file);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SHT40 sensor
int sht40_read_data(int i2c_handle, uint8_t *data) {
    if (i2cWriteByte(i2c_handle, MEASURE_CMD) != 0) {
        fprintf(stderr, "Error writing measurement command to I2C.\n");
        return -1;
    }

    gpioDelay(10); // Wait for measurement (at least 10ms)

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading data from I2C.\n");
        return -1;
    }

    return 0;
}

// Function to validate the CRC of the received data
int sht40_validate_data(const uint8_t *data) {
    uint8_t temp_crc = crc8(data, 2);
    if (temp_crc != data[2]) {
        fprintf(stderr, "Temperature CRC validation failed.\n");
        return -1;
    }

    uint8_t humidity_crc = crc8(data + 3, 2);
    if (humidity_crc != data[5]) {
        fprintf(stderr, "Humidity CRC validation failed.\n");
        return -1;
    }

    return 0;
}

// Function to convert the raw data to temperature and humidity
void sht40_convert_data(const uint8_t *data, float *temperature, float *humidity) {
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)humidity_raw / 65535.0;
}

// Function to log the temperature and humidity data to a file
void log_data(float temperature, float humidity, FILE *log_file) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[6];
    float temperature, humidity;

    // Main loop
    while (1) {
        // Read data from SHT40
        if (sht40_read_data(i2c_handle, data) == 0) {
            // Validate data
            if (sht40_validate_data(data) == 0) {
                // Convert data to temperature and humidity
                sht40_convert_data(data, &temperature, &humidity);

                // Log data
                log_data(temperature, humidity, log_file);
            } else {
                fprintf(stderr, "Data validation failed.\n");
            }
        } else {
            fprintf(stderr, "Failed to read data from SHT40.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

