#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define DATA_LENGTH 9
#define LOG_FILE "airflow_data.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *bus, int address);
int i2c_write_command(int fd, uint16_t command);
int i2c_read_data(int fd, uint8_t *data, int length);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write command function
int i2c_write_command(int fd, uint16_t command) {
    uint8_t data[2];
    data[0] = (command >> 8) & 0xFF;
    data[1] = command & 0xFF;

    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C bus");
        return -1;
    }

    return 0;
}

// I2C read data function
int i2c_read_data(int fd, uint8_t *data, int length) {
    if (read(fd, data, length) != length) {
        perror("Error reading from I2C bus");
        return -1;
    }

    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Data processing function
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    // Scale factors from the datasheet
    float pressure_scale_factor = 0.1; // Example value, check datasheet
    float temperature_scale_factor = 0.01; // Example value, check datasheet

    sensor_data.pressure = (float)raw_pressure * pressure_scale_factor;
    sensor_data.temperature = (float)raw_temperature * temperature_scale_factor;

    return sensor_data;
}

// Data logging function
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C setup
    i2c_fd = i2c_setup(I2C_BUS, SDP800_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed, exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint8_t data[DATA_LENGTH];
        sensor_data_t sensor_data;

        // Send continuous measurement command
        if (i2c_write_command(i2c_fd, CONTINUOUS_MEASUREMENT_COMMAND) < 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        usleep(45000); // Wait 45ms

        // Read sensor data
        if (i2c_read_data(i2c_fd, data, DATA_LENGTH) < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(data, 3) || !validate_crc(data + 3, 3) || !validate_crc(data + 6, 3)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Process sensor data
        sensor_data = process_sensor_data(data);

        // Log data
        if (log_data(log_file, sensor_data) < 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        usleep(100000); // Log data every 100ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

