int init_i2c();
int read_temperature(float *temperature);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from the sensor
int read_temperature(float *temperature) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buf[3];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }

    gpioDelay(15); // Wait for conversion

    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        log_error("Failed to read temperature data");
        return -1;
    }

    // CRC validation
    uint8_t crc = calculate_crc((uint8_t *)buf, 2);
    if (crc != buf[2]) {
        log_error("CRC mismatch");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = -45.0 + (175.0 * raw_temp / 65535.0);

    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

