    fprintf(error_fp, "%s,%s\n", timestamp, message);
    fflush(error_fp); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

