#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define LOG_FILE "sht40_log.txt"
#define MEASUREMENT_DELAY_US 8500 // 8.5 ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
SensorData process_sensor_data(const uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, int len);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from SHT40
int read_sensor_data(uint8_t *data) {
    if (i2cWriteByte(i2c_handle, MEASURE_HIGH_REPEATABILITY) != 0) {
        fprintf(stderr, "Error writing to I2C.\n");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C.\n");
        return -1;
    }

    return 0;
}

// Process sensor data and validate CRC
SensorData process_sensor_data(const uint8_t *data) {
    SensorData sensor_data;
    uint8_t temp_data[2] = {data[0], data[1]};
    uint8_t humidity_data[2] = {data[3], data[4]};

    // CRC validation
    if (crc8(temp_data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        uint16_t temp_raw = (data[0] << 8) | data[1];
        sensor_data.temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    }

    if (crc8(humidity_data, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        sensor_data.humidity = -999.0; // Indicate error
    } else {
        uint16_t humidity_raw = (data[3] << 8) | data[4];
        sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;
    }

    return sensor_data;
}

// Log data to file
int log_data(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data.temperature == -999.0 || data.humidity == -999.0) {
        fprintf(log_file, "%s, ERROR, Temperature: Invalid CRC, Humidity: Invalid CRC\n", timestamp);
    } else {
        fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    }
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[6];
    SensorData processed_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            processed_data = process_sensor_data(sensor_data);
            log_data(processed_data);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

