#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define DATA_LENGTH 6
#define FILENAME "airflow_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(const char *data, int length);
sensor_data_t process_data(const char *buffer);
char* get_timestamp();
int write_data_to_file(const char *timestamp, float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Function to calculate CRC8
uint8_t crc8(const char *data, int length) {
    uint8_t crc = CRC8_INITIAL;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(log_file, "%s I2C open failed: %d\n", get_timestamp(), i2c_handle);
        fflush(log_file);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(log_file, "%s I2C write failed: %d\n", get_timestamp(), result);
        fflush(log_file);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(log_file, "%s I2C read failed: %d\n", get_timestamp(), result);
        fflush(log_file);
        return -1;
    }
    return 0;
}

// Function to validate CRC
int validate_crc(const char *data, int length) {
    uint8_t crc_calculated = crc8(data, length - 1);
    uint8_t crc_received = data[length - 1];
    if (crc_calculated != crc_received) {
        fprintf(log_file, "%s CRC validation failed: calculated 0x%02X, received 0x%02X\n", get_timestamp(), crc_calculated, crc_received);
        fflush(log_file);
        return -1;
    }
    return 0;
}

// Function to process the raw data
sensor_data_t process_data(const char *buffer) {
    sensor_data_t data;
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data.pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    data.temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return data;
}

// Function to get the current timestamp
