#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define I2C_RETRIES 3

// Data structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
} BufferEntry;

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer
BufferEntry temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void control_fan(float temperature);
void add_to_buffer(float temperature);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from Si7021
int read_temperature(float *temperature) {
    char cmd = 0xE3; // Command for temperature measurement
    char buf[2];
    int retries = I2C_RETRIES;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", result);
            retries--;
            gpioDelay(1000); // Wait 1ms before retry
            continue;
        }

        gpioDelay(20000); // Wait 20ms for measurement

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            uint16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %d\n", result);
            retries--;
            gpioDelay(1000); // Wait 1ms before retry
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", I2C_RETRIES);
    return -1; // Failure
}

// Function to control the fan
void control_fan(float temperature) {
    static int fan_on = 0; // Track fan state

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Temperature: %.2f°C)\n", temperature);
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Temperature: %.2f°C)\n", temperature);
    }
}

// Function to add temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    time_t now = time(NULL);
    temperature_buffer[buffer_index].timestamp = now;
    temperature_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Correct order
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&temperature_buffer[index].timestamp));
        printf("[%s] Temperature: %.2f°C\n", timestamp_str, temperature_buffer[index].temperature);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    time_t last_buffer_print = time(NULL);

    // Main loop
    while (program_running) {
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f°C\n", temperature);
            control_fan(temperature);
            add_to_buffer(temperature);

            // Print buffer every 60 seconds
            time_t now = time(NULL);
            if (difftime(now, last_buffer_print) >= 60) {
                print_buffer();
                last_buffer_print = now;
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

