#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define SCD40_CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define SCD40_CMD_READ_MEASUREMENT 0xec05
#define SCD40_CMD_STOP_PERIODIC_MEASUREMENT 0x3f86

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_measurement(sensor_data_t *data);
int stop_periodic_measurement();
int log_data(sensor_data_t data);
uint8_t crc8(const uint8_t *data, size_t len);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (SCD40_CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD40_CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }

    return 0;
}

// Read measurement
int read_measurement(sensor_data_t *data) {
    char buf[1];
    buf[0] = (SCD40_CMD_READ_MEASUREMENT >> 8) & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %d\n", result);
        return -1;
    }

    char read_buf[9];
    result = i2cReadDevice(i2c_handle, read_buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // CRC check
    for (int i = 0; i < 3; i++) {
        uint8_t data_to_check[2];
        data_to_check[0] = read_buf[2 * i];
        data_to_check[1] = read_buf[2 * i + 1];
        uint8_t crc = read_buf[6 + i];
        uint8_t calculated_crc = crc8(data_to_check, 2);
        if (calculated_crc != crc) {
            fprintf(stderr, "CRC check failed for byte %d\n", i);
            return -1;
        }
    }

    // Extract data
    data->co2 = (read_buf[0] << 8) | read_buf[1];
    data->temperature = -45 + 175 * ((float)((read_buf[3] << 8) | read_buf[4])) / 65535;
    data->humidity = 100 * ((float)((read_buf[6] << 8) | read_buf[7])) / 65535;

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (SCD40_CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = SCD40_CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

