uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize SCD40 sensor
int init_scd40() {
    // Stop periodic measurement
    char stop_cmd[2] = {0x3F, 0x86};
    if (i2cWriteDevice(i2c_handle, stop_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to stop periodic measurement during initialization.\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Reinit sensor
    char reinit_cmd[2] = {0x36, 0x46};
    if (i2cWriteDevice(i2c_handle, reinit_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to reinitialize SCD40.\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Start periodic measurement
    char start_cmd[2] = {0x21, 0xB1};
    if (i2cWriteDevice(i2c_handle, start_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement.\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(float *co2, float *temperature, float *humidity) {
    char read_cmd[2] = {0xEC, 0x05};
    char buffer[9];

    if (i2cWriteDevice(i2c_handle, read_cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send read measurement command.\n");
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    if (i2cReadDevice(i2c_handle, buffer, 9) != 9) {
        fprintf(stderr, "Error: Failed to read measurement data.\n");
        return -1;
    }

    // CRC check
    if (crc8((uint8_t *)buffer, 2) != buffer[2] ||
        crc8((uint8_t *)buffer + 3, 2) != buffer[5] ||
        crc8((uint8_t *)buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "Error: CRC check failed.\n");
        return -1;
