#include <pigpio.h>

#define GPIO_PIN 4
#define TIMEOUT_US 50000 // 50ms
#define LOG_FILE "temperature_log.txt"

static volatile int running = 1;
static int consecutive_failures = 0;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read temperature from TMP05 sensor
float read_temperature() {
    int start_time, end_time, pulse_width, cycle_width;
    int high_time = 0;
    int low_time = 0;

    // Wait for the start of the cycle (falling edge)
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 1 && (gpioTick() - start_time) < TIMEOUT_US) {
        // Wait for falling edge
    }
    if (gpioRead(GPIO_PIN) == 1) {
        fprintf(stderr, "Timeout waiting for falling edge.\n");
        return -1000.0; // Indicate timeout error
    }

    // Measure the high time (rising edge)
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 0 && (gpioTick() - start_time) < TIMEOUT_US) {
        // Wait for rising edge
    }
    if (gpioRead(GPIO_PIN) == 0) {
        fprintf(stderr, "Timeout waiting for rising edge.\n");
        return -1000.0; // Indicate timeout error
    }
