#include <math.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define LOG_FILE "environmental_data.txt"
#define RETRY_DELAY_SEC 1
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sht35(int i2c_handle, float *temperature, float *humidity);
int validate_crc(const unsigned char *data, int len, unsigned char checksum);
void convert_data(unsigned int raw_temperature, unsigned int raw_humidity, float *temperature_celsius, float *humidity_percent);
void add_offset(float *temperature_celsius, float *humidity_percent, time_t timestamp);
void log_data(FILE *log_file, float temperature_celsius, float humidity_percent);
void signal_handler(int signal);

// CRC-8-Maxim algorithm
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SHT35 sensor
int read_sht35(int i2c_handle, float *temperature, float *humidity) {
    unsigned char data[6];
    unsigned int raw_temperature, raw_humidity;
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASUREMENT_COMMAND >> 8, MEASUREMENT_COMMAND & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 15ms)
    gpioDelay(15000); // 15ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Validate CRC for temperature
    if (!validate_crc(data, 2, data[2])) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Validate CRC for humidity
    if (!validate_crc(data + 3, 2, data[5])) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Combine MSB and LSB for temperature and humidity
    raw_temperature = (data[0] << 8) | data[1];
    raw_humidity = (data[3] << 8) | data[4];

    // Convert raw data to temperature and humidity
    convert_data(raw_temperature, raw_humidity, temperature, humidity);

    return 0;
}

// Function to validate CRC checksum
int validate_crc(const unsigned char *data, int len, unsigned char checksum) {
    unsigned char calculated_crc = crc8(data, len);
    return (calculated_crc == checksum);
}

// Function to convert raw data to temperature and humidity
void convert_data(unsigned int raw_temperature, unsigned int raw_humidity, float *temperature_celsius, float *humidity_percent) {
    *temperature_celsius = -45.0 + (175.0 * (float)raw_temperature / 65535.0);
    *humidity_percent = 100.0 * (float)raw_humidity / 65535.0;
}

// Function to add sinusoidal offset
void add_offset(float *temperature_celsius, float *humidity_percent, time_t timestamp) {
    double time_in_hour = difftime(timestamp, time(NULL));
    *temperature_celsius += 2.0 * sin(time_in_hour * M_PI / 3600.0);
    *humidity_percent += 5.0 * sin(time_in_hour * M_PI / 3600.0);
}

// Function to log data to file
void log_data(FILE *log_file, float temperature_celsius, float humidity_percent) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature_celsius, humidity_percent);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float temperature, humidity;
    int retries;
    time_t start_time, current_time;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Get start time
    start_time = time(NULL);

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries <= MAX_RETRIES) {
            if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
                // Add offset
                add_offset(&temperature, &humidity, start_time);

                // Log data
                log_data(log_file, temperature, humidity);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(RETRY_DELAY_SEC * 1000); // Delay in milliseconds
            }
        }

        if (retries > MAX_RETRIES) {
            // Log NaN values
            time_t now = time(NULL);
            struct tm *utc_time = gmtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
            fprintf(stderr, "Max retries reached, logging NaN values\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

