#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5
#define RESET_CMD 0xFE
#define LOG_FILE "environment.log"
#define POLL_INTERVAL_MS 100
#define TIMEOUT_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int handle, unsigned char command, unsigned char *data, int bytes);
float convert_temperature(unsigned int raw_temp);
float convert_humidity(unsigned int raw_humidity);
int verify_crc(unsigned char data[], int bytes);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Function to calculate CRC-8
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data with timeout
int read_sensor_data(int handle, unsigned char command, unsigned char *data, int bytes) {
    int result, count;
    unsigned int start_time = gpioTick();

    result = i2cWriteByte(handle, command);
    if (result != 0) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }

    while (1) {
        count = i2cReadDevice(handle, (char *)data, bytes);
        if (count == bytes) {
            return 0; // Success
        } else if (count < 0) {
            fprintf(stderr, "Error reading data: %d\n", count);
            return -1;
        } else {
            unsigned int current_time = gpioTick();
            if (current_time - start_time > TIMEOUT_MS * 1000) {
                fprintf(stderr, "Timeout reading data\n");
                return -1;
            }
            gpioDelay(POLL_INTERVAL_MS);
        }
    }
}

// Function to convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Function to convert raw humidity to percentage
float convert_humidity(unsigned int raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Function to verify CRC checksum
int verify_crc(unsigned char data[], int bytes) {
    unsigned char crc = crc8(data, bytes - 1);
    if (crc != data[bytes - 1]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }
    return 0;
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
