#define MEASURE_CMD 0x362F
#define SAMPLE_RATE_MS 1000 // 1 Hz
#define FILENAME "airflow.dat"

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int validate_crc(uint8_t data[], int count, uint8_t checksum);
int convert_data(char *buffer, sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int count, uint8_t checksum) {
    uint8_t calculated_crc = crc8(data, count);
    if (calculated_crc != checksum) {
        fprintf(stderr, "CRC validation failed. Calculated: 0x%02X, Expected: 0x%02X\n", calculated_crc, checksum);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
int convert_data(char *buffer, sensor_data_t *data) {
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    // Scale factors (from datasheet)
    float pressure_scale = 60.0f; // Example value, check datasheet
    float temperature_scale = 200.0f; // Example value, check datasheet

    data->pressure = (float)raw_pressure / pressure_scale;
    data->temperature = (float)raw_temperature / temperature_scale;

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    if (fwrite(&data.pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&data.temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open data file
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        cleanup();
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASURE_CMD) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    char buffer[9];
    sensor_data_t data;
    struct timespec sleep_time = {SAMPLE_RATE_MS / 1000, (SAMPLE_RATE_MS % 1000) * 1000000};

    while (!terminate) {
        // Read data
        if (read_data(i2c_handle, buffer, 9) == 0) {
            // Validate CRC
            if (validate_crc((uint8_t *)buffer, 2, buffer[2]) == 0 &&
                validate_crc((uint8_t *)buffer + 3, 2, buffer[5]) == 0) {
                // Convert data
                if (convert_data(buffer, &data) == 0) {
                    // Log data
                    if (log_data(data) != 0) {
                        fprintf(stderr, "Error logging data\n");
                    }
                } else {
                    fprintf(stderr, "Error converting data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Error reading data\n");
        }

        // Sleep for the specified sample rate
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

