#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_S 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
