#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, float *pressure);
float convert_pressure(int raw_value);
void set_fan_speed(int gpio_pin, float flow_rate);
void log_data(FILE *log_file, float pressure);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Read sensor data
int read_sensor(int i2c_handle, float *pressure) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    int16_t raw_value = (buffer[0] << 8) | buffer[1];
    *pressure = convert_pressure(raw_value);
    return 0;
}

// Convert raw sensor value to pressure (Pa)
float convert_pressure(int raw_value) {
    // Assuming a linear relationship between raw value and pressure
    // Adjust the scaling factor and offset based on the sensor's datasheet
    float pressure = (float)raw_value * 0.1; // Example scaling
    return pressure;
}

// Set fan speed using PWM
void set_fan_speed(int gpio_pin, float flow_rate) {
    // Map flow rate to PWM duty cycle (0-100%)
    float duty_cycle = flow_rate / 10.0; // Example mapping
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;

    int pwm_value = (int)(duty_cycle * 255.0 / 100.0); // pigpio PWM range is 0-255
    gpioPWM(gpio_pin, pwm_value);
}

// Log data to file
void log_data(FILE *log_file, float pressure) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.2f\n", now, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255); // Set PWM range to 0-255

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure;

    // Main loop
    while (!terminate) {
        if (read_sensor(i2c_handle, &pressure) == 0) {
            set_fan_speed(FAN_GPIO, pressure);
            log_data(log_file, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

