#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

// SCD30 I2C address
#define SCD30_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// GPIO pin for ventilation control
#define VENT_GPIO 18

// I2C handle
int i2c_handle;

// Log file pointer
FILE *log_file;

// Signal handler flag
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_gpio();
int init_scd30();
int read_scd30_data(sensor_data_t *data);
int write_log(const sensor_data_t *data);
int control_ventilation(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();
unsigned char crc8(const unsigned char *data, int len);

// CRC8 checksum function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD30_ADDR, 0); // Bus 1, address 0x61, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(VENT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize SCD30
int init_scd30() {
    // Set measurement interval to 5 seconds
    unsigned char interval_data[2];
    interval_data[0] = (5 >> 8) & 0xFF;
    interval_data[1] = 5 & 0xFF;

    if (i2cWriteDevice(i2c_handle, (char *)interval_data, 2) != 0) {
        fprintf(stderr, "Error setting measurement interval\n");
        return -1;
    }

    // Start periodic measurement
    unsigned char start_cmd[2];
    start_cmd[0] = (SCD30_CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    start_cmd[1] = SCD30_CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, (char *)start_cmd, 2) != 0) {
        fprintf(stderr, "Error starting periodic measurement\n");
        return -1;
    }

    gpioDelay(1000); // Wait for the sensor to start

    return 0;
}

// Read SCD30 data
int read_scd30_data(sensor_data_t *data) {
    unsigned char read_cmd[2];
    read_cmd[0] = (SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF;
    read_cmd[1] = SCD30_CMD_READ_MEASUREMENT & 0xFF;

    if (i2cWriteDevice(i2c_handle, (char *)read_cmd, 2) != 0) {
        fprintf(stderr, "Error writing read measurement command\n");
        return -1;
    }

    gpioDelay(1); // Small delay before reading

    unsigned char buffer[18];
    if (i2cReadDevice(i2c_handle, (char *)buffer, 18) != 18) {
        fprintf(stderr, "Error reading measurement data\n");
        return -1;
    }

    // CRC Check
    for (int i = 0; i < 6; i++) {
        unsigned char data_to_check[2];
        data_to_check[0] = buffer[i * 3];
        data_to_check[1] = buffer[i * 3 + 1];
        if (crc8(data_to_check, 2) != buffer[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch at data point %d\n", i);
            return -1;
        }
    }

    // Convert data
    data->co2 = (float)((buffer[0] << 8) | buffer[1]);
    data->temperature = (float)((buffer[3] << 8) | buffer[4]);
    data->humidity = (float)((buffer[6] << 8) | buffer[7]);

    // Scale data
    data->temperature /= 65535.0;
    data->temperature *= 175.0;
    data->temperature -= 45.0;
    data->humidity /= 65535.0;
    data->humidity *= 100.0;

    return 0;
}

// Write data to log file
int write_log(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data->co2, data->temperature, data->humidity);
    fflush(log_file);

    return 0;
}

// Control ventilation based on CO2 level
int control_ventilation(const sensor_data_t *data) {
    if (data->co2 < 800.0) {
        gpioWrite(VENT_GPIO, 0); // OFF
        printf("Ventilation: OFF\n");
    } else if (data->co2 >= 800.0 && data->co2 <= 1199.0) {
        gpioWrite(VENT_GPIO, 1); // LOW
        printf("Ventilation: LOW\n");
    } else {
        gpioWrite(VENT_GPIO, 1); // HIGH
        printf("Ventilation: HIGH\n");
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Stop periodic measurement
    unsigned char stop_cmd[2];
    stop_cmd[0] = (SCD30_CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    stop_cmd[1] = SCD30_CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    i2cWriteDevice(i2c_handle, (char *)stop_cmd, 2);
    gpioDelay(1000);

    // Close I2C
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize SCD30
    if (init_scd30() != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_scd30_data(&sensor_data) == 0) {
            // Write data to log file
            if (write_log(&sensor_data) != 0) {
                fprintf(stderr, "Error writing to log file\n");
            }

            // Control ventilation
            control_ventilation(&sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

