// Control ventilation based on CO2 level
int control_ventilation(const sensor_data_t *data) {
    if (data->co2 < 800.0) {
        gpioWrite(VENT_GPIO, 0); // OFF
        printf("Ventilation: OFF\n");
    } else if (data->co2 >= 800.0 && data->co2 <= 1199.0) {
        gpioWrite(VENT_GPIO, 1); // LOW
        printf("Ventilation: LOW\n");
    } else {
        gpioWrite(VENT_GPIO, 1); // HIGH
        printf("Ventilation: HIGH\n");
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Stop periodic measurement
    unsigned char stop_cmd[2];
    stop_cmd[0] = (SCD30_CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    stop_cmd[1] = SCD30_CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;
    i2cWriteDevice(i2c_handle, (char *)stop_cmd, 2);
    gpioDelay(1000);

    // Close I2C
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    // Initialize SCD30
    if (init_scd30() != 0) {
        fprintf(stderr, "SCD30 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_scd30_data(&sensor_data) == 0) {
            // Write data to log file
            if (write_log(&sensor_data) != 0) {
                fprintf(stderr, "Error writing to log file\n");
            }

            // Control ventilation
            control_ventilation(&sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

