volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
sensor_data_t process_sensor_data(const uint8_t *data);
void log_data(const sensor_data_t *data);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, int len);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(45000); // Wait 45ms

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure, raw_temperature;
    uint8_t pressure_crc, temperature_crc;

    // Extract raw values
    raw_pressure = (data[0] << 8) | data[1];
    pressure_crc = data[2];
    raw_temperature = (data[3] << 8) | data[4];
    temperature_crc = data[5];

    // CRC check for pressure
    uint8_t pressure_data[2] = {data[0], data[1]};
    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "CRC check failed for pressure data\n");
        sensor_data.pressure = -999.0; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    }

    // CRC check for temperature
    uint8_t temperature_data[2] = {data[3], data[4]};
    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "CRC check failed for temperature data\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        sensor_data.temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet
    }

    return sensor_data;
}

