void log_data(const sensor_data_t *data) {
    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", data->pressure, data->temperature);
}

int main() {
    uint8_t sensor_data[9];
    sensor_data_t processed_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log data
            log_data(&processed_data);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

