#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// Define the I2C bus and device address
#define I2C_BUS 1
#define HDC1000_ADDR 0x40

// Define the register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the HDC1000 sensor
int init_hdc1000() {
    // Configure the sensor for temperature and humidity measurement
    // with 14-bit resolution and default values for other settings.
    uint16_t config_value = 0x0000; // Default configuration
    uint8_t config_data[3];
    config_data[0] = CONFIGURATION_REG;
    config_data[1] = (config_value >> 8) & 0xFF;
    config_data[2] = config_value & 0xFF;

    if (write(i2c_fd, config_data, 3) != 3) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
