// Define the I2C address of the MLX90833 sensor
#define MLX90833_I2C_ADDR 0x60

// Define the register addresses for pressure and temperature data
#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library and I2C bus
int initialize() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, MLX90833_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read pressure data from the sensor
int read_pressure(float *pressure) {
    char buf[2];
    int result;

    // Read two bytes from the pressure register
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read pressure data: %d\n", result);
        return -1;
    }

    // Convert the raw data to a pressure value (example conversion, adjust as needed)
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    *pressure = (float)raw_pressure * 0.1; // Example scaling

    return 0;
}

// Function to read temperature data from the sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    // Read two bytes from the temperature register
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    // Convert the raw data to a temperature value (example conversion, adjust as needed)
    int16_t raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temperature * 0.01 - 40.0; // Example scaling

    return 0;
}

// Function to log the sensor data with a timestamp
void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read pressure and temperature data
        if (read_pressure(&sensor_data.pressure) == 0 && read_temperature(&sensor_data.temperature) == 0) {
            // Log the data
            log_data(sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 us
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

