#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICP10101_ADDR 0x69
#define MEASURE_CMD 0x06
#define DEFAULT_TEMP 0x8000
#define DEFAULT_PRESS 0x800000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(unsigned char *data);
sensor_data_t process_sensor_data(const unsigned char *data);
void print_data(sensor_data_t data);
void error_handler(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, 0x00, MEASURE_CMD);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Process sensor data
sensor_data_t process_sensor_data(const unsigned char *data) {
    sensor_data_t sensor_data;
    int raw_temp = (data[0] << 8) | data[1];
    int raw_press = (data[2] << 16) | (data[3] << 8) | data[4];

    if (raw_temp == DEFAULT_TEMP && raw_press == DEFAULT_PRESS) {
        sensor_data.temperature = -999.0; // Indicate error
        sensor_data.pressure = -999.0;    // Indicate error
        return sensor_data;
    }

    sensor_data.temperature = (float)raw_temp / 10.0;
    sensor_data.pressure = (float)raw_press;

    return sensor_data;
}

// Print data
void print_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (data.temperature == -999.0 && data.pressure == -999.0) {
        fprintf(stderr, "%s - Sensor error: Default values detected\n", timestamp);
    } else {
        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, data.temperature, data.pressure);
    }
}

// Error handler
void error_handler(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        error_handler("I2C initialization failed");
        return 1;
    }

    unsigned char data[6];
    sensor_data_t sensor_data;

    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() < 0) {
            error_handler("Failed to trigger measurement");
        } else {
            gpioDelay(7000); // Wait 7 ms

            // Read sensor data
            if (read_sensor_data(data) < 0) {
                error_handler("Failed to read sensor data");
            } else {
                // Process sensor data
                sensor_data = process_sensor_data(data);

                // Print data
                print_data(sensor_data);
            }
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup
    cleanup();

    return 0;
}

