#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 45000 // 45ms

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int len);
SensorData process_sensor_data(uint8_t data[]);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (Sensirion polynomial)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger a single measurement
int trigger_measurement() {
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int len) {
    for (int i = 0; i < len - 1; i += 3) {
        uint8_t crc = crc8(&data[i], 2);
        if (crc != data[i + 2]) {
            fprintf(stderr, "CRC validation failed at byte %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Process sensor data
SensorData process_sensor_data(uint8_t data[]) {
    SensorData sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data.pressure = (float)raw_pressure / 240.0; // Pa
    sensor_data.temperature = (float)raw_temperature / 200.0; // °C

    return sensor_data;
}

// Log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[9];
    SensorData processed_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(SAMPLE_INTERVAL_US);

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Validate CRC
        if (validate_crc(sensor_data, 9) != 0) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Process sensor data
        processed_data = process_sensor_data(sensor_data);

        // Log data
        log_data(processed_data);

        // Wait before next measurement
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

