    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    fseek(log_file, 0, SEEK_END);

    printf("Starting pressure monitoring...\n");

    while (!terminate) {
        retry = 0;
        do {
            if (read_pressure(&sensor_data.pressure_kPa) == 0) {
                sensor_data.timestamp = time(NULL);

                // Log data
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }

                // Check pressure range
                if (sensor_data.pressure_kPa < PRESSURE_MIN || sensor_data.pressure_kPa > PRESSURE_MAX) {
                    fprintf(stderr, "Warning: Pressure out of range: %.2f kPa\n", sensor_data.pressure_kPa);
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Failed to read pressure, retrying... (%d/%d)\n", retry + 1, RETRY_COUNT);
                i2cClose(i2c_handle);
                gpioTerminate();
                sleep(1); // Wait before retrying
                if (initialize_i2c() != 0) {
                    fprintf(stderr, "I2C re-initialization failed\n");
                    break; // Exit retry loop if re-initialization fails
                }
                retry++;
                sleep(1);
            }
        } while (retry < RETRY_COUNT && !terminate);

        if (terminate) break; // Exit loop if termination signal is received

        sleep(1); // Read every second
    }

    cleanup();
    printf("Exiting\n");
    return 0;
}

