#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1MB
#define MEASUREMENT_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_data(uint8_t *data);
sensor_data_t process_data(uint8_t *data);
char* get_iso8601_timestamp();
int log_data(sensor_data_t data, char *timestamp);
void roll_log_file();
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    int result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    gpioDelay(40); // Wait for measurement (40ms)
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Validate data
int validate_data(uint8_t *data) {
    // Check status bits (bits 7 and 6 of byte 0)
    int status = (data[0] >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Sensor status error: %d\n", status);
        return -1;
    }
    return 0;
}

// Process data
sensor_data_t process_data(uint8_t *data) {
    sensor_data_t processed_data;
    // Extract humidity and temperature from the data
    uint16_t humidity_raw = ((data[0] & 0x3F) << 8) | data[1];
    uint16_t temperature_raw = (data[2] << 6) | (data[3] >> 2);

    // Convert to float values
    processed_data.humidity = ((float)humidity_raw / 16383) * 100;
    processed_data.temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return processed_data;
}

// Get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(sensor_data_t data, char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fclose(fp);
    return 0;
}

// Roll log file
void roll_log_file() {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for rolling\n");
        return;
    }

    fclose(fp);

    // Truncate the file
    fp = fopen(LOG_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for truncation\n");
        return;
    }
    fclose(fp);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("Environmental data logger started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t data[4];
        sensor_data_t sensor_data;
        char *timestamp;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Sensor data read failed, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate data
        if (validate_data(data) != 0) {
            fprintf(stderr, "Sensor data validation failed, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Process data
        sensor_data = process_data(data);

        // Get timestamp
        timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(sensor_data, timestamp) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        free(timestamp); // Free the allocated memory

        // Check log file size and roll if necessary
        FILE *fp = fopen(LOG_FILE, "r");
        if (fp != NULL) {
            fseek(fp, 0, SEEK_END);
            long file_size = ftell(fp);
            fclose(fp);
            if (file_size > LOG_FILE_SIZE_LIMIT) {
                roll_log_file();
            }
        }

        // Wait for the next measurement
        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup resources
    cleanup();

    printf("Environmental data logger stopped.\n");
