#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "pressure_log.txt"
#define TIMEOUT_US 100000 // 100ms timeout

// Structure to hold SENT frame data
typedef struct {
    unsigned char status;
    unsigned char data1;
    unsigned char data2;
    unsigned char data3;
    unsigned char checksum;
} SENTFrame;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sent_frame(SENTFrame *frame);
int decode_nibble(int pulse_width);
int validate_checksum(const SENTFrame *frame);
float calculate_pressure(const SENTFrame *frame);
int log_pressure_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Function to read a single SENT frame
int read_sent_frame(SENTFrame *frame) {
    int i, pulse_width;
    unsigned int start_time, end_time;

    // Wait for the synchronization pulse
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Synchronization pulse timeout\n");
            return -1;
        }
    }

    // Read the synchronization pulse width
    start_time = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            fprintf(stderr, "Error: Synchronization pulse timeout (low)\n");
            return -1;
        }
    }
    end_time = gpioTick();
    pulse_width = end_time - start_time;

    if (pulse_width < 55 || pulse_width > 65) {
        fprintf(stderr, "Error: Invalid synchronization pulse width: %d\n", pulse_width);
        return -1;
    }

    // Read the status nibble
    frame->status = 0;
    for (i = 0; i < 4; i++) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Error: Status nibble timeout (high)\n");
                return -1;
            }
        }
        end_time = gpioTick();
        pulse_width = end_time - start_time;

        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Error: Status nibble timeout (low)\n");
                return -1;
            }
        }
        end_time = gpioTick();
        pulse_width = end_time - start_time;

        int decoded_nibble = decode_nibble(pulse_width);
        if (decoded_nibble < 0) {
            fprintf(stderr, "Error: Invalid status nibble pulse width: %d\n", pulse_width);
            return -1;
        }
        frame->status |= (decoded_nibble << (6 - (i * 2)));
    }

    // Read the data nibbles
    for (i = 0; i < 12; i++) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Error: Data nibble timeout (high)\n");
                return -1;
            }
        }
        end_time = gpioTick();
        pulse_width = end_time - start_time;

        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Error: Data nibble timeout (low)\n");
                return -1;
            }
        }
        end_time = gpioTick();
        pulse_width = end_time - start_time;

        int decoded_nibble = decode_nibble(pulse_width);
        if (decoded_nibble < 0) {
            fprintf(stderr, "Error: Invalid data nibble pulse width: %d\n", pulse_width);
            return -1;
        }

        if (i < 4) {
            frame->data1 |= (decoded_nibble << (6 - (i * 2)));
        } else if (i < 8) {
            frame->data2 |= (decoded_nibble << (6 - ((i - 4) * 2)));
        } else {
            frame->data3 |= (decoded_nibble << (6 - ((i - 8) * 2)));
        }
    }

    // Read the checksum nibble
    frame->checksum = 0;
    for (i = 0; i < 4; i++) {
        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Error: Checksum nibble timeout (high)\n");
                return -1;
            }
        }
        end_time = gpioTick();
        pulse_width = end_time - start_time;

        start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Error: Checksum nibble timeout (low)\n");
                return -1;
            }
        }
        end_time = gpioTick();
        pulse_width = end_time - start_time;

        int decoded_nibble = decode_nibble(pulse_width);
        if (decoded_nibble < 0) {
            fprintf(stderr, "Error: Invalid checksum nibble pulse width: %d\n", pulse_width);
            return -1;
        }
        frame->checksum |= (decoded_nibble << (6 - (i * 2)));
    }

    return 0;
}

// Function to decode a nibble from pulse width
int decode_nibble(int pulse_width) {
    if (pulse_width >= 36 && pulse_width <= 813) {
        return (pulse_width - 36) / 40;
    } else {
        return -1; // Invalid pulse width
    }
}

// Function to validate the checksum
int validate_checksum(const SENTFrame *frame) {
    unsigned char calculated_checksum = 0;
    calculated_checksum |= (frame->status >> 2);
    calculated_checksum |= (frame->data1 >> 4);
    calculated_checksum |= (frame->data2 >> 6);
    calculated_checksum |= (frame->data3 >> 8);

    if (calculated_checksum != frame->checksum) {
        fprintf(stderr, "Error: Checksum mismatch: calculated = %02X, received = %02X\n", calculated_checksum, frame->checksum);
        return -1;
    }
    return 0;
}

// Function to calculate the pressure from the SENT frame
float calculate_pressure(const SENTFrame *frame) {
    // Placeholder for pressure calculation based on the SENT frame data
    // Replace with the actual calculation from the MLX90824 datasheet
    // This is a linear approximation for demonstration purposes
    float pressure = (float)((frame->data1 << 8) | (frame->data2)) * 0.1; // Example scaling
    return pressure;
}

// Function to log the pressure data to a file
int log_pressure_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    SENTFrame frame;
    float pressure;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_sent_frame(&frame) == 0) {
            if (validate_checksum(&frame) == 0) {
                pressure = calculate_pressure(&frame);
                if (log_pressure_data(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure data\n");
                }
            } else {
                fprintf(stderr, "Error: Checksum validation failed\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read SENT frame\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

