#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int read_sht40(float *temperature, float *humidity);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the I2C interface
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity from the SHT40 sensor
int read_sht40(float *temperature, float *humidity) {
    char cmd[1] = {MEASURE_HIGH_PRECISION};
    uint8_t data[6];

    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        fprintf(stderr, "Failed to write command to SHT40\n");
        return -1;
    }

    gpioDelay(8500); // Wait 8.5 ms

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Failed to read data from SHT40\n");
        return -1;
    }

    // CRC validation
    if (calculate_crc(data, 2) != data[2] || calculate_crc(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    *humidity = 100.0 * (float)hum_raw / 65535.0;

    return 0;
}

// Function to calculate the CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log the temperature and humidity data to a file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read temperature and humidity
        if (read_sht40(&sensor_data.temperature, &sensor_data.humidity) == 0) {
            // Log the data
            if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    return 0;
}

