#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 commands
#define SHTC3_MEASURE_NORMAL 0x7866

// CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Temperature and humidity ranges
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define HUMID_MIN 0.0
#define HUMID_MAX 100.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_shtc3(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
int validate_data(sensor_data_t data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SHTC3 sensor
int read_shtc3(sensor_data_t *data) {
    uint8_t cmd[2] = {(SHTC3_MEASURE_NORMAL >> 8) & 0xFF, SHTC3_MEASURE_NORMAL & 0xFF};
    uint8_t raw_data[6];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Failed to write command to SHTC3\n");
        return -1;
    }

    gpioDelay(12000); // Wait 12.4 ms

    if (i2cReadDevice(i2c_handle, (char *)raw_data, 6) != 6) {
        fprintf(stderr, "Failed to read data from SHTC3\n");
        return -1;
    }

    // CRC check
    if (crc8(raw_data, 2) != raw_data[2] || crc8(raw_data + 3, 2) != raw_data[5]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int32_t temp_raw = (raw_data[0] << 8) | raw_data[1];
    int32_t humid_raw = (raw_data[3] << 8) | raw_data[4];

    data->temperature = 175.0 * temp_raw / 65535.0 - 45.0;
    data->humidity = 100.0 * humid_raw / 65535.0;

    return 0;
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate temperature and humidity data
int validate_data(sensor_data_t data) {
    if (data.temperature < TEMP_MIN || data.temperature > TEMP_MAX) {
        fprintf(stderr, "Temperature out of range: %.2f\n", data.temperature);
        return -1;
    }
    if (data.humidity < HUMID_MIN || data.humidity > HUMID_MAX) {
        fprintf(stderr, "Humidity out of range: %.2f\n", data.humidity);
        return -1;
    }
    return 0;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("Received SIGINT, cleaning up...\n");
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_shtc3(&sensor_data) == 0) {
            if (validate_data(sensor_data) == 0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
                log_data(sensor_data);
            }
        }
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

