    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        data->temperature = NAN;
    } else {
        // Convert raw data to temperature (example conversion, adjust as needed)
        int raw_temp = (buf[0] << 8) | buf[1];
        data->temperature = (float)raw_temp * 0.001; // Example scaling
    }

    return 0;
}

