    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Temperature reading function
float read_temperature() {
    int raw_temp;
    float temperature;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temp >= 0) {
            // Convert raw temperature to Celsius
            temperature = (float)raw_temp * TEMP_SCALE;
            return temperature;
        } else {
            fprintf(stderr, "Error reading temperature (attempt %d): %d\n", retries + 1, raw_temp);
            retries++;
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1000.0; // Indicate error with a very low temperature
}

// Logging function
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    FILE *fp;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping logging.\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Temperature logging stopped.\n");
    return 0;
}

