            if (read_sensor_data(sensor_data) == 0) {
                flow = extract_flow(sensor_data);
                temperature = extract_temperature(sensor_data);
                log_data(flow, temperature);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/3)\n", retry_count + 1);
                retry_count++;
                gpioDelay(100); // Wait before retrying
