                fprintf(stderr, "I2C re-initialization failed\n");
                break; // Exit main loop if re-initialization fails
            }
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

