#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define LOG_FILE "dht11_readings.txt"
#define ERROR_LOG_FILE "dht11_errors.txt"
#define MIN_INTERVAL 2 // seconds

static volatile int running = 1;
static FILE *log_fp = NULL;
static FILE *error_fp = NULL;
static time_t last_read_time = 0;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char *buf = malloc(21 * sizeof(char)); // YYYY-MM-DDTHH:MM:SSZ\0
    if (buf == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }
    strftime(buf, 21, "%Y-%m-%dT%H:%M:%SZ", tstruct);
    return buf;
}

// Function to log data to file
void log_data(const char *timestamp, int humidity_int, int temperature_int, int checksum) {
    if (log_fp == NULL) return;
    fprintf(log_fp, "%s,%d,%d,%d\n", timestamp, humidity_int, temperature_int, checksum);
    fflush(log_fp); // Ensure data is written immediately
}

// Function to log errors to file
void log_error(const char *timestamp, const char *message, int status_code) {
    if (error_fp == NULL) return;
    fprintf(error_fp, "%s,%s,%d\n", timestamp, message, status_code);
    fflush(error_fp);
}

// Function to read DHT11 data
int read_dht11(int gpio, int *humidity_int, int *temperature_int, int *checksum) {
    int data[40];
    int i, j;

    // Check if enough time has passed since the last read
    time_t now = time(NULL);
    if (difftime(now, last_read_time) < MIN_INTERVAL) {
        return -1; // Not ready yet
    }
    last_read_time = now;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 30us

    // Switch to input and measure response
    gpioSetMode(gpio, PI_INPUT);
    gpioDelay(80); // 80us

    if (gpioRead(gpio) == 1) {
        log_error(get_iso8601_timestamp(), "DHT11 not responding", 1);
        return -1;
    }

    gpioDelay(80); // 80us

    if (gpioRead(gpio) == 0) {
        log_error(get_iso8601_timestamp(), "DHT11 not responding", 1);
        return -1;
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        // Wait for low
        int timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1); // 1us
            timeout++;
            if (timeout > 100) {
                log_error(get_iso8601_timestamp(), "Timeout waiting for low signal", 2);
                return -1;
            }
        }

        // Measure high pulse width
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1); // 1us
            timeout++;
            if (timeout > 100) {
                log_error(get_iso8601_timestamp(), "Timeout waiting for high signal", 3);
                return -1;
            }
        }

        data[i] = timeout;
    }

    // Decode data
    int humidity = 0;
    int temperature = 0;
    int check = 0;

    for (i = 0; i < 8; i++) {
        humidity <<= 1;
        if (data[i] > 40) humidity |= 1; // Assuming threshold of 40us
    }

    for (i = 8; i < 16; i++) {
        temperature <<= 1;
        if (data[i] > 40) temperature |= 1;
    }

    for (i = 16; i < 24; i++) {
        check <<= 1;
        if (data[i] > 40) check |= 1;
    }

    // Verify checksum
    if ((humidity & 0xFF) + (temperature & 0xFF) != check) {
        log_error(get_iso8601_timestamp(), "Checksum failure", 4);
        return -1;
    }

    *humidity_int = humidity;
    *temperature_int = temperature;
    *checksum = check;

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int humidity_int, temperature_int, checksum;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (error_fp == NULL) {
        perror("Failed to open error log file");
        fclose(log_fp);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("DHT11 reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (read_dht11(DHT11_GPIO, &humidity_int, &temperature_int, &checksum) == 0) {
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                log_data(timestamp, humidity_int, temperature_int, checksum);
                free(timestamp);
            }
        }
        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_fp);
    fclose(error_fp);
    gpioTerminate();

    return 0;
}

