    // Close I2C handles
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to read data from a sensor
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[6];
    int result;

    // Read 6 bytes from the sensor (R, G, B channels)
    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1; // Indicate failure
    }

    // Convert the data to 16-bit integers (assuming little-endian)
    *red = (uint16_t)((buffer[1] << 8) | buffer[0]);
    *green = (uint16_t)((buffer[3] << 8) | buffer[2]);
    *blue = (uint16_t)((buffer[5] << 8) | buffer[4]);

    return 0; // Indicate success
}

// Function to calculate CCT from sensor data
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float ratio_r = (float)red / (float)green;
    float ratio_b = (float)blue / (float)green;

    // Use the ratio to estimate CCT (example formula, adjust as needed)
    float cct = A * ratio_r + B * ratio_b + CCT_OFFSET;

    return cct;
}

// Function to log CCT data to a file
int log_cct_data(FILE *fp, float cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to file
    fprintf(fp, "%s,%.2f\n", timestamp, cct);
    fflush(fp); // Ensure data is written immediately

    return 0;
