    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read data from sensor 1
        result = read_sensor_data(i2c_handle1, &red1, &green1, &blue1);
        if (result != 0) {
            fprintf(stderr, "Error reading sensor 1 data, skipping this cycle\n");
            continue; // Skip to the next iteration
        }

        // Read data from sensor 2
        result = read_sensor_data(i2c_handle2, &red2, &green2, &blue2);
        if (result != 0) {
            fprintf(stderr, "Error reading sensor 2 data, skipping this cycle\n");
            continue; // Skip to the next iteration
        }

        // Calculate CCT for each sensor
        cct1 = calculate_cct(red1, green1, blue1);
        cct2 = calculate_cct(red2, green2, blue2);

        // Calculate average CCT
        average_cct = (cct1 + cct2) / 2.0;

        // Log the average CCT
        log_cct_data(log_file, average_cct);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // The following lines will never be reached because of the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

