#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define LED_GPIO 17
#define TEMP_HIGH_THRESHOLD 28.0
#define TEMP_LOW_THRESHOLD 27.0
#define TEMP_SCALE 0.0625
#define TEMP_OFFSET 0.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
double read_temperature();
void control_led(double temperature);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int led_pin;
    double high_temp;
    double low_temp;
} config_t;

config_t config = {LED_GPIO, TEMP_HIGH_THRESHOLD, TEMP_LOW_THRESHOLD};

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(config.led_pin, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read temperature from STTS2004
double read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        log_error("Failed to read temperature data");
        return -1000.0; // Indicate error with a very low temperature
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 4; // Shift right by 4 bits

    return (double)raw_temp * TEMP_SCALE + TEMP_OFFSET;
}

// Control LED based on temperature
void control_led(double temperature) {
    static int led_state = 0; // 0 = off, 1 = on

    if (temperature > config.high_temp && led_state == 0) {
        if (gpioWrite(config.led_pin, 1) != 0) {
            log_error("Failed to write to GPIO");
        } else {
            led_state = 1;
            printf("Temperature: %.2f°C, LED ON\n", temperature);
        }
    } else if (temperature < config.low_temp && led_state == 1) {
        if (gpioWrite(config.led_pin, 0) != 0) {
            log_error("Failed to write to GPIO");
        } else {
            led_state = 0;
            printf("Temperature: %.2f°C, LED OFF\n", temperature);
        }
    }
}

// Log errors with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: %s: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message, strerror(errno));
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(config.led_pin, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO and I2C
    if (init_gpio() != 0 || init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            printf("Temperature: %.2f°C\n", temperature);
            control_led(temperature);
        } else {
            log_error("Failed to read temperature, retrying...");
        }
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

