#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_HUMIDITY_CMD 0xE5
#define MEASURE_TEMPERATURE_CMD 0xE3
#define READ_TEMP_PREV_HUMIDITY_CMD 0xE0
#define LOG_FILE "environment.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char buf[2];
    int result;
    int retries = 0;

    // Measure Humidity
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_HUMIDITY_CMD);
        if (result == 0) break; // Success
        fprintf(stderr, "Error writing humidity command (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write humidity command after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    gpioDelay(20000); // Wait 20ms

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) break; // Success
        fprintf(stderr, "Error reading humidity data (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read humidity data after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    unsigned int humidity_raw = (buf[0] << 8) | buf[1];
    *humidity = (100.0 * humidity_raw) / 65536.0;

    // Measure Temperature
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_TEMPERATURE_CMD);
        if (result == 0) break; // Success
        fprintf(stderr, "Error writing temperature command (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write temperature command after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    gpioDelay(20000); // Wait 20ms

    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) break; // Success
        fprintf(stderr, "Error reading temperature data (attempt %d): %d\n", retries + 1, result);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read temperature data after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    unsigned int temperature_raw = (buf[0] << 8) | buf[1];
    *temperature = (175.72 * temperature_raw) / 65536.0 - 46.85;

    return 0;
}

// Function to log data to a file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

