int validate_data(const sensor_data_t *data) {
    if (data->pressure_Pa < -500.0 || data->pressure_Pa > 500.0) {
        fprintf(stderr, "Pressure out of range: %.2f Pa\n", data->pressure_Pa);
        return -1;
    }
    if (data->temperature_C < -50.0 || data->temperature_C > 150.0) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", data->temperature_C);
        return -1;
    }
    return 0;
}

// Function to log the sensor data to a file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data->pressure_Pa, data->temperature_C);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sdp810(&sensor_data) == 0) {
            if (validate_data(&sensor_data) == 0) {
                log_data(&sensor_data);
            } else {
                fprintf(stderr, "Data validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

