#include <pthread.h>
#include <sys/stat.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

// SCD40 Commands
#define CMD_START_PERIODIC 0x21B1
#define CMD_STOP_PERIODIC 0x3F86
#define CMD_READ_MEASUREMENT 0xE4B8

// Data structure for sensor readings
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_sensor_data(sensor_data_t *data);
int stop_periodic_measurement();
void buffer_init(circular_buffer_t *buffer);
int buffer_add(circular_buffer_t *buffer, sensor_data_t data);
int buffer_get(circular_buffer_t *buffer, sensor_data_t *data, int index);
int write_to_csv(const char *filename, const circular_buffer_t *buffer);
void log_error(const char *message);
void *logging_thread(void *arg);
void signal_handler(int signal);
int create_directory(const char *path);

// CRC-8 calculation (as per SCD40 datasheet)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    buffer_init(&buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create logging directory if it doesn't exist
    if (create_directory(LOG_DIR) != 0) {
        log_error("Failed to create log directory");
        running = 0; // Stop the main loop
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        log_error("Failed to start periodic measurement");
        running = 0; // Stop the main loop
    }

    // Wait at least one second after issuing the start command
    sleep(1);

    // Main loop
    sensor_data_t data;
    pthread_t log_thread;
    int log_interval = 60; // Log every 60 seconds
    time_t last_log_time = time(NULL);

    if (pthread_create(&log_thread, NULL, logging_thread, &buffer) != 0) {
        log_error("Failed to create logging thread");
        running = 0;
    }

    while (running) {
        if (read_sensor_data(&data) == 0) {
            buffer_add(&buffer, data);
        }

        time_t current_time = time(NULL);
        if (difftime(current_time, last_log_time) >= log_interval) {
            pthread_join(log_thread, NULL);
            char filename[100];
            struct tm *tm_info = localtime(&current_time);
            strftime(filename, sizeof(filename), LOG_DIR "%Y-%m-%d_%H-%M-%S.csv", tm_info);
            if (write_to_csv(filename, &buffer) != 0) {
                log_error("Failed to write to CSV file");
            }
            last_log_time = current_time;
            if (pthread_create(&log_thread, NULL, logging_thread, &buffer) != 0) {
                log_error("Failed to create logging thread");
                running = 0;
            }
        }
        sleep(5);
    }

    // Stop periodic measurement
    stop_periodic_measurement();

    // Join logging thread
    pthread_join(log_thread, NULL);

    // Flush remaining data to a final CSV file
    char filename[100];
    time_t current_time = time(NULL);
    struct tm *tm_info = localtime(&current_time);
    strftime(filename, sizeof(filename), LOG_DIR "%Y-%m-%d_%H-%M-%S_final.csv", tm_info);
    if (write_to_csv(filename, &buffer) != 0) {
        log_error("Failed to write to final CSV file");
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int start_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

int read_sensor_data(sensor_data_t *data) {
    char buf[2];
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    char read_buf[9];
    result = i2cReadDevice(i2c_handle, read_buf, 9);
    if (result != 9) {
        log_error("Failed to read sensor data");
        return -1;
    }

    // CRC Check
    if (crc8((unsigned char *)read_buf, 2) != read_buf[2] ||
        crc8((unsigned char *)read_buf + 3, 2) != read_buf[5] ||
        crc8((unsigned char *)read_buf + 6, 2) != read_buf[8]) {
        log_error("CRC check failed");
        return -1;
    }

    // Convert data
    unsigned int co2_raw = (read_buf[0] << 8) | read_buf[1];
    unsigned int temperature_raw = (read_buf[3] << 8) | read_buf[4];
    unsigned int humidity_raw = (read_buf[6] << 8) | read_buf[7];

    data->co2 = (float)co2_raw;
    data->temperature = -45 + 175 * ((float)temperature_raw / 65535.0);
    data->humidity = 100 * ((float)humidity_raw / 65535.0);

    return 0;
}

int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

int buffer_add(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

int buffer_get(circular_buffer_t *buffer, sensor_data_t *data, int index) {
    pthread_mutex_lock(&buffer->mutex);
    if (index < 0 || index >= buffer->count) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Invalid index
    }
    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    *data = buffer->data[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

int write_to_csv(const char *filename, const circular_buffer_t *buffer) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        log_error("Failed to open CSV file for writing");
        return -1;
    }

    fprintf(fp, "CO2,Temperature,Humidity\n");

    sensor_data_t data;
    for (int i = 0; i < buffer->count; i++) {
        if (buffer_get((circular_buffer_t *)buffer, &data, i) == 0) {
            fprintf(fp, "%.2f,%.2f,%.2f\n", data.co2, data.temperature, data.humidity);
        } else {
            log_error("Failed to get data from buffer");
        }
    }

    fclose(fp);
    return 0;
}

void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

void *logging_thread(void *arg) {
    circular_buffer_t *buffer = (circular_buffer_t *)arg;
    // This thread is just a placeholder.  The actual logging is done in the main loop.
    // The purpose of this thread is to demonstrate multithreading and signal handling.
    pthread_exit(NULL);
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        running = 0;
    }
}

int create_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == -1) {
        if (mkdir(path, 0777) != 0) {
            perror("mkdir");
            return -1;
        }
    }
    return 0;
}

