#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C address of the ICP-10110 sensor
#define ICP10110_ADDR 0x69

// Define the I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the filename for logging data
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int initialize_sensor();
sensor_data_t read_sensor_data();
char* format_data(sensor_data_t data);
int write_to_log(char *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to initialize the ICP-10110 sensor
int initialize_sensor() {
    // Placeholder for sensor initialization sequence
    // Replace with actual initialization commands from the datasheet
    // For example, writing to specific registers to configure the sensor
    // This is a simplified example
    char init_data[] = {0x00, 0x01}; // Example initialization data
    int result = i2cWriteDevice(i2c_handle, init_data, sizeof(init_data));
    if (result != 0) {
        fprintf(stderr, "Sensor initialization failed: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // Wait 10ms after initialization
    return 0;
}

// Function to read temperature and pressure data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    // Placeholder for reading sensor data
    // Replace with actual I2C read commands from the datasheet
    // This is a simplified example
    char read_cmd[] = {0x01}; // Example command to trigger a measurement
    char buffer[4]; // Example buffer to store the data
    int result;

    result = i2cWriteDevice(i2c_handle, read_cmd, sizeof(read_cmd));
    if (result != 0) {
        fprintf(stderr, "Failed to write read command: %d\n", result);
        data.temperature = -999.0; // Indicate error
        data.pressure = -999.0;
        return data;
    }

    gpioDelay(10000); // Wait 10ms for measurement

