#include <unistd.h>
#include <stdbool.h>

// Define constants
#define I2C_BUS 1
#define ICP_10125_ADDR 0x69 // I2C address of ICP-10125
#define GPIO_LED 17          // GPIO pin for the LED
#define PRESSURE_THRESHOLD 95000 // Pressure threshold in Pa

// Global variables
int i2c_handle;
bool running = true;

// Function prototypes
int read_sensor_data(int i2c_handle, uint8_t *data);
bool verify_crc(const uint8_t *data);
void control_led(int gpio_pin, int blink_rate);
void signal_handler(int signal);

// CRC polynomial (from ICP-10125 datasheet)
#define CRC_POLYNOMIAL 0x31

// Function to calculate CRC checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to verify CRC checksum
bool verify_crc(const uint8_t *data) {
    uint8_t crc_calculated = crc8(data, 4);
    uint8_t crc_received = data[4];
    return (crc_calculated == crc_received);
}

// Function to control the LED
void control_led(int gpio_pin, int blink_rate) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(blink_rate * 1000); // Delay in microseconds
    gpioWrite(gpio_pin, 0); // Turn LED off
    gpioDelay(blink_rate * 1000); // Delay in microseconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Release GPIO
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ICP_10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Install signal handler
    signal(SIGINT, signal_handler);

    uint8_t sensor_data[6];
    int pressure_pa;
    int temperature_c;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data) == 0) {
            // Verify CRC
            if (verify_crc(sensor_data)) {
                // Extract pressure and temperature
                pressure_pa = (sensor_data[0] << 8) | sensor_data[1];
                temperature_c = (sensor_data[2] << 8) | sensor_data[3];

                // Control LED based on pressure threshold
                if (pressure_pa < PRESSURE_THRESHOLD) {
                    control_led(GPIO_LED, 200); // 5 Hz
                } else {
                    control_led(GPIO_LED, 1000); // 1 Hz
                }

                // Print sensor data (optional)
                printf("Pressure: %d Pa, Temperature: %d C\n", pressure_pa, temperature_c);
            } else {
                fprintf(stderr, "CRC verification failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay
        gpioDelay(20000); // 20 ms
    }

    // Cleanup (should not reach here if signal handler is working)
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Release GPIO
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

