        raw_data = i2cReadWordData(i2c_handle, reg);
        if (raw_data >= 0) {
            *temperature = (float)raw_data * 0.02 - 273.15;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading temperature from register 0x%02X: %d, retry %d\n", reg, raw_data, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature from register 0x%02X after %d retries\n", reg, RETRY_COUNT);
    return -1; // Failure
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Object Temp: %.2f C)\n", object_temp);
    } else if (object_temp < TEMP_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Object Temp: %.2f C)\n", object_temp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    TemperatureData temp_data;

    // Main loop
    while (!terminate) {
        // Read temperatures
        if (read_temperature(AMBIENT_TEMP_REG, &temp_data.ambient_temp) == 0 &&
            read_temperature(OBJECT_TEMP_REG, &temp_data.object_temp) == 0) {

            // Log temperatures
            log_temperature(temp_data.ambient_temp, temp_data.object_temp);

            // Control fan
            control_fan(temp_data.object_temp);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping logging and fan control\n");
        }

        gpioDelay(2000000); // Wait 2 seconds (2000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

