#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define PORT 8080
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
int server_fd;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sht40(SensorData *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
void handle_client(int client_socket);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHT40 sensor
int read_sht40(SensorData *data) {
    char cmd = MEASURE_HIGH_PRECISION;
    char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, &cmd, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        gpioDelay(10000); // Wait at least 10ms

        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Convert raw data
        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_humidity = (buf[3] << 8) | buf[4];

        data->temperature = convert_temperature(raw_temp);
        data->humidity = convert_humidity(raw_humidity);

        // Clamp humidity to 0-100%
        if (data->humidity < 0.0) data->humidity = 0.0;
        if (data->humidity > 100.0) data->humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * (raw_temp / 65535.0);
}

// Convert raw humidity data to percentage
float convert_humidity(uint16_t raw_humidity) {
    return -6.0 + 125.0 * (raw_humidity / 65535.0);
}

// Handle client connection and send data
void handle_client(int client_socket) {
    SensorData sensor_data;
    char buffer[1024];
    int bytes_read;

    if (read_sht40(&sensor_data) == 0) {
        snprintf(buffer, sizeof(buffer), 
               "HTTP/1.1 200 OK\r\n" \
               "Content-Type: text/html\r\n" \
               "\r\n" \
               "<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body>" \
               "<h1>Temperature: %.2f &deg;C</h1>" \
               "<h1>Humidity: %.2f %%</h1>" \
               "</body></html>",
               sensor_data.temperature, sensor_data.humidity);
    } else {
        snprintf(buffer, sizeof(buffer), 
               "HTTP/1.1 500 Internal Server Error\r\n" \
               "Content-Type: text/html\r\n" \
               "\r\n" \
               "<!DOCTYPE html><html><head><title>Error</title></head><body>" \
               "<h1>Error reading sensor data</h1>" \
               "</body></html>");
    }

    send(client_socket, buffer, strlen(buffer), 0);
    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to port 8080
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Main loop
    while (1) {
        int client_socket;
        struct sockaddr_in client_address;
        int addrlen = sizeof(client_address);

        // Accept incoming connection
        client_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (client_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for other connections
        }

        // Handle client connection
        handle_client(client_socket);
    }

    // Cleanup (should not reach here under normal circumstances due to the signal handler)
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

