#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define CSV_FILE "temperature_log.csv"

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_temperature();
char* format_timestamp();
int write_to_csv(const char* timestamp, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp102_address;
    const char* csv_filename;
} config_t;

config_t config = {I2C_BUS, TMP102_ADDR, CSV_FILE};

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    i2c_handle = i2cOpen(config.i2c_bus, config.tmp102_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature from TMP102
float read_temperature() {
    int raw_data = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    // The TMP102 returns a 12-bit temperature value, left-aligned.
    // Shift right by 4 bits to get the correct value.
    int16_t temp_raw = (raw_data >> 4) & 0x0FFF; // Mask to keep only 12 bits

    // Check if the temperature is negative (MSB is set)
    if (temp_raw & 0x0800) {
        // Convert from two's complement to signed integer
        temp_raw |= 0xF000; // Sign extend
    }

    float temperature = (float)temp_raw * 0.0625;
    return temperature;
}

// Format timestamp
char* format_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for timestamp
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Write to CSV file
int write_to_csv(const char* timestamp, float temperature) {
    FILE *fp = fopen(config.csv_filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleaned up resources.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for read error
            // Format timestamp
            char* timestamp = format_timestamp();
            if (timestamp != NULL) {
                // Write to CSV
                if (write_to_csv(timestamp, temperature) != 0) {
                    fprintf(stderr, "Failed to write to CSV file.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Failed to format timestamp.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature, skipping entry.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

