#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SSR_GPIO 17
#define PWM_RANGE 1000
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define TARGET_TEMP_HYSTERESIS 0.5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for PID parameters
typedef struct {
    float Kp;
    float Ki;
    float Kd;
} PIDParams;

// Structure for PID controller state
typedef struct {
    float integral;
    float previous_error;
} PIDState;

// Function prototypes
int read_max6675(int spi_handle);
float calculate_pid(float setpoint, float actual_temperature, PIDParams pid_params, PIDState *pid_state);
void set_ssr_duty_cycle(int gpio_pin, float duty_cycle);
void log_data(FILE *log_file, float temperature, float setpoint, float duty_cycle);
int load_target_temperature(const char *filename, float *target_temperature);
void signal_handler(int signal);

// Function to read temperature from MAX6675
int read_max6675(int spi_handle) {
    char tx_buf[2] = {0x00, 0x00};
    char rx_buf[2];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    int raw_data = ((rx_buf[0] << 8) | rx_buf[1]) >> 3;

    if (raw_data & 0x0004) {
        fprintf(stderr, "Thermocouple fault detected!\n");
        return -1; // Indicate fault
    }

    return raw_data;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, PIDParams pid_params, PIDState *pid_state) {
    float error = setpoint - actual_temperature;
    pid_state->integral += error;
    float derivative = error - pid_state->previous_error;
    float output = pid_params.Kp * error + pid_params.Ki * pid_state->integral + pid_params.Kd * derivative;
    pid_state->previous_error = error;
    return output;
}

// Function to set SSR duty cycle using PWM
void set_ssr_duty_cycle(int gpio_pin, float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int pwm_value = (int)(duty_cycle * PWM_RANGE);
    gpioPWM(gpio_pin, pwm_value);
}

// Function to log data to file
void log_data(FILE *log_file, float temperature, float setpoint, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, setpoint, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load target temperature from file
int load_target_temperature(const char *filename, float *target_temperature) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening profile file: %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from profile file: %s\n", filename);
        fclose(fp);
        return -1;
    }

    char *token = strtok(line, ",");
    if (token == NULL) {
        fprintf(stderr, "Invalid profile file format: %s\n", filename);
        fclose(fp);
        return -1;
    }

    // Skip the time column
    token = strtok(NULL, ",");
    if (token == NULL) {
        fprintf(stderr, "Invalid profile file format: %s\n", filename);
        fclose(fp);
        return -1;
    }

    *target_temperature = strtof(token, NULL);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set SSR GPIO as output
    gpioSetMode(SSR_GPIO, PI_OUTPUT);
    gpioSetPWMrange(SSR_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(SSR_GPIO, 1000); // 1 kHz

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load target temperature from file
    float target_temperature;
    if (load_target_temperature(PROFILE_FILE, &target_temperature) != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // PID parameters
    PIDParams pid_params = {0.5, 0.01, 0.1};
    PIDState pid_state = {0.0, 0.0};

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature from MAX6675
        int raw_temp = read_max6675(spi_handle);
        if (raw_temp < 0) {
            fprintf(stderr, "Error reading temperature, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        float temperature = (float)raw_temp * 0.25; // Convert to Celsius

        // PID control
        float pid_output = calculate_pid(target_temperature, temperature, pid_params, &pid_state);

        // Hysteresis
        if (temperature > target_temperature + TARGET_TEMP_HYSTERESIS) {
            pid_output = 0.0; // Turn off heater
        } else if (temperature < target_temperature - TARGET_TEMP_HYSTERESIS) {
            pid_output = 1.0; // Turn on heater
        }

        // Limit PID output to 0.0 to 1.0
        if (pid_output < 0.0) pid_output = 0.0;
        if (pid_output > 1.0) pid_output = 1.0;

        // Set SSR duty cycle
        set_ssr_duty_cycle(SSR_GPIO, pid_output);

        // Log data
        log_data(log_file, temperature, target_temperature, pid_output);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
