#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define LOG_FILE "greenhouse.log"
#define MAX_SENSORS 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static char sensor_ids[MAX_SENSORS][20];
static int num_sensors = 0;
static float setpoint = 25.0; // Default setpoint
static float Kp = 1.0;        // Default proportional gain
static float Ki = 0.1;        // Default integral gain
static float Kd = 0.01;       // Default derivative gain

// PID variables
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
int read_sensor(const char *sensor_id, float *temperature);
int validate_crc(const char *data);
float calculate_pid(float setpoint, float average_temperature);
void set_heater_state(int state);
void set_pwm_duty_cycle(float duty_cycle);
void log_data(float average_temperature, float setpoint, float pid_output, float duty_cycle);
void signal_handler(int signal);
int discover_sensors();

// CRC-8-H2F checksum calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        unsigned char byte = data[i];
        for (int j = 0; j < 8; j++) {
            unsigned char mix = (crc ^ byte) & 0x01;
            crc >>= 1;
            if (mix)
                crc ^= 0x8C;
            byte >>= 1;
        }
    }
    return crc;
}

// Function to read temperature from a DS18B20 sensor
int read_sensor(const char *sensor_id, float *temperature) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "%s%s/%s", W1_DEVICES_DIR, sensor_id, W1_SLAVE_FILE);

    FILE *fp = fopen(filepath, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening sensor file: %s, %s\n", filepath, strerror(errno));
        return -1;
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error reading sensor data: %s\n", filepath);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Validate CRC
    if (!validate_crc(line2)) {
        fprintf(stderr, "CRC check failed for sensor: %s\n", sensor_id);
        return -1;
    }

    // Extract temperature
    char *token = strstr(line2, "t=");
    if (token == NULL) {
        fprintf(stderr, "Temperature data not found in sensor: %s\n", sensor_id);
        return -1;
    }

    long temp_raw = strtol(token + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0;

    return 0;
}

// Function to validate CRC checksum
int validate_crc(const char *data) {
    char *crc_start = strstr(data, "crc=");
    if (crc_start == NULL) {
        fprintf(stderr, "CRC data not found\n");
        return 0;
    }

    unsigned char crc_calculated = crc8((unsigned char *)data, strlen(data));
    unsigned char crc_read = strtol(crc_start + 4, NULL, 16);

    return (crc_calculated == crc_read);
}

// Function to calculate PID output
float calculate_pid(float setpoint, float average_temperature) {
    float error = setpoint - average_temperature;
    integral += error;
    float derivative = error - previous_error;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp the output to the range 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to set the heater state (ON/OFF)
void set_heater_state(int state) {
    gpioWrite(HEATER_GPIO, state);
}

// Function to set the PWM duty cycle
void set_pwm_duty_cycle(float duty_cycle) {
    int pwm_range = gpioGetPWMrange(PWM_GPIO);
    int pwm_value = (int)(duty_cycle / 100.0 * pwm_range);
    gpioPWM(PWM_GPIO, pwm_value);
}

// Function to log data to file
void log_data(float average_temperature, float setpoint, float pid_output, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, average_temperature, setpoint, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to discover DS18B20 sensors
int discover_sensors() {
    DIR *dir;
    struct dirent *ent;
    int sensor_count = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("opendir");
        return -1;
    }

    while ((ent = readdir(dir)) != NULL && sensor_count < MAX_SENSORS) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strncpy(sensor_ids[sensor_count], ent->d_name, sizeof(sensor_ids[sensor_count]) - 1);
            sensor_ids[sensor_count][sizeof(sensor_ids[sensor_count]) - 1] = '\0'; // Ensure null termination
            sensor_count++;
        }
    }

    closedir(dir);
    return sensor_count;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Discover sensors
    num_sensors = discover_sensors();
    if (num_sensors <= 0) {
        fprintf(stderr, "No DS18B20 sensors found\n");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, 1000); // Set PWM range to 1000 for percentage calculation

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Greenhouse control system started. Setpoint: %.2f, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", setpoint, Kp, Ki, Kd);

    while (running) {
        float total_temperature = 0.0;
        int valid_sensor_count = 0;

        // Read temperature from each sensor with retries
        for (int i = 0; i < num_sensors; i++) {
            float temperature;
            int retries = 0;
            int read_success = 0;

            while (retries < MAX_RETRIES && !read_success) {
                if (read_sensor(sensor_ids[i], &temperature) == 0) {
                    total_temperature += temperature;
                    valid_sensor_count++;
                    read_success = 1;
                } else {
                    fprintf(stderr, "Failed to read sensor %s, retrying...\n", sensor_ids[i]);
                    gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                    retries++;
                }
            }

            if (!read_success) {
                fprintf(stderr, "Failed to read sensor %s after multiple retries\n", sensor_ids[i]);
            }
        }

        // Calculate average temperature
        float average_temperature = 0.0;
        if (valid_sensor_count > 0) {
            average_temperature = total_temperature / valid_sensor_count;
        }

        // Calculate PID output
        float pid_output = calculate_pid(setpoint, average_temperature);

        // Set heater and PWM duty cycle
        set_heater_state(1); // Always turn on the heater
        set_pwm_duty_cycle(pid_output);

        // Log data
        log_data(average_temperature, setpoint, pid_output, pid_output);

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup
    set_heater_state(0); // Turn off heater
    set_pwm_duty_cycle(0); // Set PWM to 0

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    return 0;
}

