#define AHT20_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_aht20(float *humidity);
void control_relay(int state);
void log_humidity(float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read humidity from AHT20 sensor
int read_aht20(float *humidity) {
    unsigned char buf[6];
    int retries = 0;
    int status;

    // Trigger measurement
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0xAC, 0x33);
        if (status == 0) break; // Success
        fprintf(stderr, "Error triggering measurement (attempt %d): %d\n", retries + 1, status);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to trigger measurement after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buf, 6);
        if (status == 6) break; // Success
        fprintf(stderr, "Error reading data (attempt %d): %d\n", retries + 1, status);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read data after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Verify status
    if ((buf[0] & 0x80) != 0) {
        fprintf(stderr, "Sensor busy or not calibrated.\n");
        return -1;
    }

    // Calculate humidity
    uint32_t humidity_raw = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
    *humidity = ((float)humidity_raw / 0x100000) * 100;

    return 0;
}

