    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("AHT20 Humidity Monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_aht20(&humidity) == 0) {
            log_humidity(humidity);

            if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                control_relay(1); // Activate relay
            } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                control_relay(0); // Deactivate relay
            }
        } else {
            fprintf(stderr, "Failed to read humidity.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    cleanup();
    return 0;
}

