#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_humidity();
char* format_json(float humidity);
int post_data(const char* json_data);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Reads humidity from HTU21D sensor
float read_humidity() {
    unsigned char buf[3];
    int result;
    float humidity = -1.0f; // Default error value

    // Trigger humidity measurement
    result = i2cWriteByteData(i2c_handle, 0, TRIGGER_HUMID_MEASURE);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement: %d", result);
        return -1.0f;
    }

    // Wait for measurement to complete (at least 50ms)
    gpioDelay(50000); // 50ms

    // Read humidity data
    result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %d", result);
        return -1.0f;
    }

    // CRC check
    unsigned char crc = buf[2];
    unsigned char data[2] = {buf[0], buf[1]};
    unsigned char crc_calculated = 0xFF; // Initialize to an invalid value

    // CRC calculation (from HTU21D datasheet)
    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                crc_calculated = (crc_calculated << 1);
            }
        }
    }

    if (crc != crc_calculated) {
        syslog(LOG_ERR, "CRC mismatch: received 0x%02X, calculated 0x%02X", crc, crc_calculated);
        return -1.0f;
    }

    // Convert to humidity
    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    raw_humidity &= 0xFFFC; // Clear status bits
    humidity = -6.0f + 125.0f * (raw_humidity / 65536.0f);

    return humidity;
}

// Formats humidity reading as a JSON document
char* format_json(float humidity) {
    char* json_data = (char*)malloc(100 * sizeof(char)); // Allocate memory
    if (json_data == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON data");
        return NULL;
    }
    snprintf(json_data, 100, "{\"humidity\": %.2f}", humidity);
    return json_data;
}

// Sends JSON data to the API endpoint via HTTP POST
int post_data(const char* json_data) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[1024];
    int len;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80); // Assuming HTTP port 80

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "api.example.com", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address / Address not supported: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr*)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Construct HTTP POST request
    snprintf(buffer, sizeof(buffer), 
             "POST /humidity HTTP/1.1\r\n" 
             "Host: api.example.com\r\n" 
             "Content-Type: application/json\r\n" 
             "Content-Length: %ld\r\n" 
             "Connection: close\r\n" 
             "\r\n" 
             "%s", strlen(json_data), json_data);

    // Send request
    len = send(sockfd, buffer, strlen(buffer), 0);
    if (len < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Receive response (optional)
    memset(buffer, 0, sizeof(buffer));
    len = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (len < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
    } else {
        syslog(LOG_INFO, "Received response: %s", buffer);
    }

    close(sockfd);
    return 0;
}

int main() {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting humidity monitor...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float humidity = read_humidity();
        if (humidity >= 0.0f) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            char* json_data = format_json(humidity);
            if (json_data != NULL) {
                if (post_data(json_data) == 0) {
                    syslog(LOG_INFO, "Data posted successfully");
                } else {
                    syslog(LOG_ERR, "Failed to post data");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(POLL_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    syslog(LOG_INFO, "Exiting...");
    closelog();
    return 0;
}

