#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define LOG_FILE_PATH "/var/log/environmental_data.csv"
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3

// Global variables
int i2c_handle_tmp117 = -1;
int i2c_handle_aht20 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_tmp117(int i2c_handle, float *temperature);
int read_aht20(int i2c_handle, float *humidity);
int read_pir_sensor(int gpio_pin);
int log_data(FILE *fp, float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// TMP117 temperature reading function
int read_tmp117(int i2c_handle, float *temperature) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (Celsius)
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading TMP117 (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// AHT20 humidity reading function (simplified, requires proper initialization and periodic measurement)
int read_aht20(int i2c_handle, float *humidity) {
    // This is a placeholder.  AHT20 requires specific initialization and periodic measurement.
    // Refer to the AHT20 datasheet for the correct sequence.
    // For this example, we'll return a dummy humidity value.
    *humidity = 50.0 + (rand() % 30); // Dummy humidity between 50 and 80
    return 0;
}

// PIR sensor reading function
int read_pir_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Data logging function
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C devices
    i2c_handle_tmp117 = initialize_i2c(I2C_BUS, TMP117_ADDR);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "TMP117 initialization failed.\n");
    }

    i2c_handle_aht20 = initialize_i2c(I2C_BUS, AHT20_ADDR);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "AHT20 initialization failed.\n");
    }

    // Open log file
    log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        fflush(log_file);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int motion_detected;
    time_t last_midnight = 0;
    time_t current_time;

    // Main loop
    while (!terminate) {
        // Check for midnight and create a new log file if necessary
        time(&current_time);
        struct tm tm_current = *localtime(&current_time);
        time_t current_midnight = mktime(&tm_current);
        tm_current.tm_hour = 0;
        tm_current.tm_min = 0;
        tm_current.tm_sec = 0;
        current_midnight = mktime(&tm_current);

        if (current_midnight > last_midnight) {
            printf("Creating new log file...\n");
            fclose(log_file);
            log_file = fopen(LOG_FILE_PATH, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
                cleanup();
                return 1;
            }
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
            fflush(log_file);
            last_midnight = current_midnight;
        }

        // Read sensor data
        if (i2c_handle_tmp117 >= 0) {
            if (read_tmp117(i2c_handle_tmp117, &temperature) != 0) {
                temperature = -999.0; // Indicate error
            }
        } else {
            temperature = -999.0; // Indicate missing sensor
        }

        if (i2c_handle_aht20 >= 0) {
            if (read_aht20(i2c_handle_aht20, &humidity) != 0) {
                humidity = -999.0; // Indicate error
            }
        } else {
            humidity = -999.0; // Indicate missing sensor
        }

        motion_detected = read_pir_sensor(PIR_GPIO);

        // Log data
        if (log_data(log_file, temperature, humidity, motion_detected) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

