#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control parameters
#define MOTOR_FORWARD_TIME 5 // seconds
#define MOTOR_STEP_DELAY 100 // milliseconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction, int duration);
void stop_motor();
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received signal, stopping motor and exiting...");
    stop_motor();
    gpioTerminate();
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_detected = gpioRead(RAIN_SENSOR_PIN);
    if (rain_detected < 0) {
        log_message("Error reading rain sensor");
        return -1; // Indicate error
    }
    return rain_detected;
}

// Function to control the motor
void control_motor(int direction, int duration) {
    if (direction == 1) { // Forward
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioWrite(MOTOR_ENA_PIN, 1);
        log_message("Motor: Forward");
    } else if (direction == -1) { // Backward
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 1);
        gpioWrite(MOTOR_ENA_PIN, 1);
        log_message("Motor: Backward");
    } else {
        stop_motor();
        log_message("Motor: Stopped");
        return;
    }

    gpioDelay(duration * 1000); // Convert seconds to milliseconds
    stop_motor();
    log_message("Motor: Stopped after duration");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Program started");

    // Main loop
    while (program_running) {
        int rain_status = read_rain_sensor();
        if (rain_status == 0) { // Rain detected (active low)
            log_message("Rain detected!");
            control_motor(1, MOTOR_FORWARD_TIME); // Move forward for 5 seconds
        } else if (rain_status < 0) {
            log_message("Error reading rain sensor, exiting...");
            break;
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup
    log_message("Program exiting");
    stop_motor();
    gpioTerminate();

    return 0;
}

