#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Structure to hold CPU statistics
typedef struct {
    unsigned long user;
    unsigned long nice;
    unsigned long system;
    unsigned long idle;
    unsigned long iowait;
    unsigned long irq;
    unsigned long softirq;
    unsigned long steal;
    unsigned long guest;
    unsigned long guest_nice;
} cpu_stats_t;

// Global variables
volatile sig_atomic_t program_running = 1;
cpu_stats_t prev_stats, current_stats;

// Function prototypes
int read_cpu_stats(cpu_stats_t *stats);
float calculate_cpu_load(const cpu_stats_t *prev_stats, const cpu_stats_t *current_stats);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(cpu_stats_t *stats) {
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        perror("Error reading /proc/stat");
        return -1;
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fclose(fp);
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        return -1;
    }

    if (sscanf(line, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &stats->user, &stats->nice, &stats->system, &stats->idle,
               &stats->iowait, &stats->irq, &stats->softirq, &stats->steal,
               &stats->guest, &stats->guest_nice) != 10) {
        fclose(fp);
        fprintf(stderr, "Error parsing CPU stats\n");
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load percentage
float calculate_cpu_load(const cpu_stats_t *prev_stats, const cpu_stats_t *current_stats) {
    unsigned long prev_idle = prev_stats->idle + prev_stats->iowait;
    unsigned long current_idle = current_stats->idle + current_stats->iowait;

    unsigned long prev_non_idle = prev_stats->user + prev_stats->nice + prev_stats->system + prev_stats->irq + prev_stats->softirq + prev_stats->steal;
    unsigned long current_non_idle = current_stats->user + current_stats->nice + current_stats->system + current_stats->irq + current_stats->softirq + current_stats->steal;

    unsigned long prev_total = prev_idle + prev_non_idle;
    unsigned long current_total = current_idle + current_non_idle;

    unsigned long totald = current_total - prev_total;
    unsigned long idled = current_idle - prev_idle;

    float cpu_load = (float)(totald - idled) / totald * 100.0;
    return cpu_load;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read initial CPU statistics
    if (read_cpu_stats(&prev_stats) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read current CPU statistics
        if (read_cpu_stats(&current_stats) != 0) {
            break; // Exit loop on error
        }

        // Calculate CPU load
        float cpu_load = calculate_cpu_load(&prev_stats, &current_stats);

        // Map CPU load to RGB color values
        int red, green, blue;
        if (cpu_load <= 50.0) {
            green = 255;
            red = 0;
            blue = 0;
            green = (int)(255.0 * (1.0 - cpu_load / 50.0));
        } else {
            green = 0;
            red = 255;
            blue = 0;
            red = (int)(255.0 * (cpu_load / 100.0));
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Update previous CPU statistics
        prev_stats = current_stats;

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Turn off LED (set all channels to full off)
    set_led_color(255, 255, 255);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

