#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define FAN_PIN 18 // BCM GPIO 18
#define PWM_RANGE 255
#define BUFFER_SIZE 20

// Structure for circular buffer entry
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} BufferEntry;

// Global variables
volatile sig_atomic_t program_running = 1;
BufferEntry circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_max31855(float *temperature);
int calculate_duty_cycle(float temperature);
void update_fan(int duty_cycle);
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    unsigned char data[4];
    int result;

    result = wiringPiSPIDataRW(SPI_CHANNEL, data, 4);
    if (result == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1;
    }

    // Check for fault bits
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault detected!\n");
        return -1;
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature >= 25.0 && temperature < 40.0) {
        duty_cycle = (int)((temperature - 25.0) / (40.0 - 25.0) * 128.0);
    } else if (temperature >= 40.0 && temperature < 60.0) {
        duty_cycle = 128 + (int)((temperature - 40.0) / (60.0 - 40.0) * 128.0);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Function to update fan speed using PWM
void update_fan(int duty_cycle) {
    pwmWrite(FAN_PIN, duty_cycle);
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t timestamp = circular_buffer[i].timestamp;
        float temperature = circular_buffer[i].temperature;
        int duty_cycle = circular_buffer[i].duty_cycle;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
        printf("[%d] Timestamp: %s, Temperature: %.2f °C, Duty Cycle: %d\n", i, time_str, temperature, duty_cycle);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Stop the PWM signal
    pwmWrite(FAN_PIN, 0);

    // Close the SPI interface
    // No explicit SPI close function in wiringPi, but we can reset the pin
    pinMode(8, INPUT); // Reset CE0 pin to input
    pinMode(FAN_PIN, INPUT); // Reset fan pin to input

    // Print the contents of the circular buffer
    print_buffer();

    // Terminate the wiringPi library
    wiringPiSetup(); // Reinitialize to avoid errors
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Configure PWM on GPIO18 (BCM)
    pinMode(FAN_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(PWM_RANGE);
    pwmSetClock(192); // Adjust clock for 1 kHz PWM frequency

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    float temperature;
    int duty_cycle;
    time_t current_time;

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature from MAX31855
        if (read_max31855(&temperature) == 0) {
            // Calculate PWM duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Update fan speed
            update_fan(duty_cycle);

            // Get current timestamp
            current_time = time(NULL);

            // Add data to circular buffer
            add_to_buffer(current_time, temperature, duty_cycle);

            printf("Temperature: %.2f °C, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping fan update.\n");
        }

        // Wait for 1 second
        delay(1000);
    }

    return 0;
}

