#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define OSS 3

// GPIO pin for interrupt
#define INTERRUPT_GPIO 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t logging_enabled = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_temperature(int32_t raw_temperature);
float calculate_pressure(int32_t raw_pressure, int32_t raw_temperature);
void log_data(float temperature, float pressure);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// Function to read a 16-bit value from the I2C bus
int read_i2c_word(int handle, uint8_t reg, int16_t *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to read an unsigned 16-bit value from the I2C bus
int read_i2c_uword(int handle, uint8_t reg, uint16_t *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int32_t *raw_temperature)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms (minimum)

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (OSS << 6); // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(26000); // Wait 25.5ms (OSS = 3)

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char data[3];
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate the temperature in degrees Celsius
float calculate_temperature(int32_t raw_temperature)
{
    int32_t X1 = ((raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    float temperature = ((B5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate the pressure in Pascals
float calculate_pressure(int32_t raw_pressure, int32_t raw_temperature)
{
    int32_t X1 = ((raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) >> 12) >> 11;
    int32_t X4 = ((int32_t)ac2 * B6) >> 11;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << OSS) + 2) >> 2;

    uint32_t X1_pressure = ((uint32_t)ac3 * B6) >> 13;
    uint32_t X2_pressure = ((uint32_t)b1 * ((B6 * B6) >> 12)) >> 16;
    uint32_t X3_pressure = ((X1_pressure + X2_pressure + 2) >> 2);
    uint32_t B4 = ((uint32_t)ac4 * (X3_pressure + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);

    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    float pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure;
}

// Function to log the data to a CSV file
void log_data(float temperature, float pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    logging_enabled = !logging_enabled;
    printf("Logging toggled to: %s\n", logging_enabled ? "ON" : "OFF");
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL);
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_OFF);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode and pull-up
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler
    gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        if (logging_enabled) {
            int32_t raw_temperature, raw_pressure;

            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                float temperature = calculate_temperature(raw_temperature);
                float pressure = calculate_pressure(raw_pressure, raw_temperature);
                log_data(temperature, pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        gpioDelay(1000000); // 1 second
    }

    return 0;
}

