int init_spi();
int read_max31865(int ce_pin, unsigned char reg_addr, unsigned char *data, int len);
int write_max31865(int ce_pin, unsigned char reg_addr, unsigned char data);
float read_temperature(int ce_pin);
void log_data(float temp1, float temp2);
void signal_handler(int signal);
void cleanup();

// Callendar-Van Dusen equation coefficients for Pt100
const float a = 3.9083e-3;
const float b = -5.775e-7;
const float c = 1.5875e-12;

// Function to calculate temperature from RTD resistance using the Callendar-Van Dusen equation
float calculate_temperature(float rtd_resistance) {
    float temperature = (rtd_resistance - RREF) / a;
    temperature = temperature + (b * temperature * temperature);
    temperature = temperature + (c * temperature * temperature * temperature);
    return temperature;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temp1 = read_temperature(CE0_PIN);
        float temp2 = read_temperature(CE1_PIN);

        log_data(temp1, temp2);

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize SPI interface
int init_spi() {
