    char tx_buf[1];
    char rx_buf[len];
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation

    gpioWrite(ce_pin, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, rx_buf, len + 1); // Send register address and read data
    gpioWrite(ce_pin, 1); // Deselect the chip

    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return 1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

