    char tx_buf[2];
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    gpioWrite(ce_pin, 0); // Select the chip
    int result = spiXfer(spi_handle, tx_buf, NULL, 2); // Send register address and data
    gpioWrite(ce_pin, 1); // Deselect the chip

    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return 1;
    }
    return 0;
}

