    unsigned char rtd_msb, rtd_lsb, fault_reg;
    int rtd_raw;
    float rtd_resistance;
    float temperature;

    // Read RTD MSB and LSB
    if (read_max31865(ce_pin, MAX31865_RTD_MSB_REG, &rtd_msb, 1) != 0) {
        fprintf(stderr, "Error reading RTD MSB\n");
        return -273.15; // Return absolute zero on error
    }
    if (read_max31865(ce_pin, MAX31865_RTD_LSB_REG, &rtd_lsb, 1) != 0) {
        fprintf(stderr, "Error reading RTD LSB\n");
        return -273.15; // Return absolute zero on error
    }

    // Combine MSB and LSB to get the raw RTD value
    rtd_raw = ((rtd_msb << 8) | rtd_lsb) >> 1; // Remove fault bit

    // Check for fault
    if (read_max31865(ce_pin, MAX31865_FAULT_REG, &fault_reg, 1) != 0) {
        fprintf(stderr, "Error reading fault register\n");
        return -273.15; // Return absolute zero on error
    }

    if (fault_reg != 0) {
        fprintf(stderr, "Fault detected: 0x%02X\n", fault_reg);
        return -273.15; // Return absolute zero on error
    }

    // Check for sensor absent
    if ((rtd_msb & 0x01) != 0) {
        fprintf(stderr, "Sensor absent\n");
        return -273.15; // Return absolute zero on error
    }

    // Calculate RTD resistance
    rtd_resistance = ((float)rtd_raw / 32768.0) * RREF;

    // Calculate temperature
    temperature = calculate_temperature(rtd_resistance);

    return temperature;
}

// Log data to file
void log_data(float temp1, float temp2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

