#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0 = ultra low power)
#define BMP180_OSS 0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temp);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
void log_data(double temperature, double pressure);
void timer_interrupt_handler();
void signal_handler(int signal);

// Structure to hold calibration data
typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_calibration_data_t;

// Function to read a 16-bit value from the I2C bus
int read_i2c_word(int handle, uint8_t reg, int16_t *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address: %d\n", reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register: %d\n", reg);
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to read an unsigned 16-bit value from the I2C bus
int read_i2c_uword(int handle, uint8_t reg, uint16_t *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address: %d\n", reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register: %d\n", reg);
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to read a 32-bit value from the I2C bus
int read_i2c_long(int handle, uint8_t reg, int32_t *value)
{
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address: %d\n", reg);
        return -1;
    }
    char data[4];
    if (i2cReadDevice(handle, data, 4) != 4) {
        fprintf(stderr, "Error reading 32-bit value from register: %d\n", reg);
        return -1;
    }
    *value = (data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3];
    return 0;
}


int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer interrupt
    if (gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up timer interrupt\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop (wait for termination signal)
    while (!terminate) {
        sleep(1);
    }

    // Clean up
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

int init_i2c()
{
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int read_calibration_data()
{
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

    // Basic validation (check for reasonable values)
    if (ac1 < -32768 || ac1 > 32767 || ac2 < -32768 || ac2 > 32767 ||
        ac3 < -32768 || ac3 > 32767 || b1 < -32768 || b1 > 32767 ||
        b2 < -32768 || b2 > 32767 || mb < -32768 || mb > 32767 ||
        mc < -32768 || mc > 32767 || md < -32768 || md > 32767 ||
        ac4 < 0 || ac4 > 65535 || ac5 < 0 || ac5 > 65535 ||
        ac6 < 0 || ac6 > 65535) {
        fprintf(stderr, "Error: Invalid calibration data. Check sensor connection.\n");
        return -1;
    }

    return 0;
}

int read_raw_temperature(int32_t *raw_temp)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    return read_i2c_long(i2c_handle, BMP180_REG_MSB, raw_temp);
}

int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    return read_i2c_long(i2c_handle, BMP180_REG_MSB, raw_pressure);
}

double calculate_temperature(int32_t raw_temp)
{
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

double calculate_pressure(int32_t raw_pressure, int32_t raw_temp)
{
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) >> 12) >> 11;
    int32_t X4 = ((int32_t)ac2 * B6) >> 11;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;

    uint32_t X1_pressure = ((uint32_t)ac3 * B6) >> 13;
    uint32_t X2_pressure = ((uint32_t)b1 * ((B6 * B6) >> 12)) >> 16;
    uint32_t X3_pressure = ((X1_pressure + X2_pressure + 2) >> 2);
    uint32_t B4 = ((uint32_t)ac4 * (X3_pressure + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);

    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure;
}

void log_data(double temperature, double pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

void timer_interrupt_handler()
{
    int32_t raw_temp, raw_pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        double temperature = calculate_temperature(raw_temp);
        double pressure = calculate_pressure(raw_pressure, raw_temp);
        log_data(temperature, pressure);
    } else {
        fprintf(stderr, "Error reading sensor data in interrupt handler\n");
    }
}

void signal_handler(int signal)
{
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

