#define GPIO_PIN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = 0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert to degrees Celsius
}

// Function to map temperature to PWM duty cycle
int map_temp_to_duty_cycle(int temperature) {
    if (temperature < 40) {
        return 0;
    } else if (temperature > 70) {
        return 255;
    } else {
        return (int)(((float)(temperature - 40) / 30.0) * 255.0);
    }
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(int temperature, int duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Temperature: %d°C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

int main() {
    int temperature, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, 25000);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using previous value\n");
        } else {
            // Map temperature to duty cycle
            duty_cycle = map_temp_to_duty_cycle(temperature);

            // Set PWM duty cycle
            if (set_pwm_duty_cycle(duty_cycle) != 0) {
                fprintf(stderr, "Error setting PWM duty cycle, using previous value\n");
            }

            // Log data
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Stop PWM
    gpioPWM(GPIO_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Fan control program stopped.\n");
    return 0;
}

