// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76
#define BMP280_I2C_ADDR_ALT 0x77

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
static int i2c_fd = -1;
static int bmp280_address = BMP280_I2C_ADDR;
static FILE *data_file = NULL;
static FILE *error_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data
static uint16_t dig_T1;
static int16_t dig_T2;
static int16_t dig_T3;
static uint16_t dig_P1;
static int16_t dig_P2;
static int16_t dig_P3;
static int16_t dig_P4;
static int16_t dig_P5;
static int16_t dig_P6;
static int16_t dig_P7;
static int16_t dig_P8;
static int16_t dig_P9;

// Function prototypes
int init_i2c(int address);
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
int write_data_to_file(double temperature, double pressure);
void signal_handler(int signal);
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Log error messages to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    if (error_file != NULL) {
        fprintf(error_file, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
        fflush(error_file);
    }
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        log_error("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read calibration data from the sensor
int read_calibration_data() {
    uint8_t buffer[26];
    if (read(i2c_fd, buffer, 26) != 26) {
        log_error("Failed to read calibration data");
        return -1;
    }

    dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
