#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
int i2c_handle;
pthread_mutex_t buffer_mutex;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
double running_average = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
double read_temperature();
void update_buffer(double temperature);
double calculate_average();
void control_led(double average_temperature);
void *alert_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from LM75
double read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    double temperature = raw_temp * 0.125;
    return temperature;
}

// Function to update the circular buffer
void update_buffer(double temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the running average
double calculate_average() {
    pthread_mutex_lock(&buffer_mutex);
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    double average = sum / BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
    return average;
}

// Function to control the LED
void control_led(double average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Alert thread function
void *alert_thread(void *arg) {
    while (!terminate) {
        double average_temperature = calculate_average();
        control_led(average_temperature);
        usleep(500000); // Check every 0.5 seconds
    }
    return NULL;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Release GPIO
    pthread_mutex_destroy(&buffer_mutex);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0); // Initially turn off the LED

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Create alert thread
    pthread_t alert_thread_id;
    if (pthread_create(&alert_thread_id, NULL, alert_thread, NULL) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            update_buffer(temperature);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, calculate_average());
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting...\n");
                terminate = 1; // Exit the main loop
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    // Join alert thread
    pthread_join(alert_thread_id, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

