#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration structure
typedef struct {
    float target_temperature;
    float kp;
    float ki;
    float kd;
} PIDConfig;

// Global variables
static int spi_handle;
static int gpio_pin = 18;
static PIDConfig config;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename, PIDConfig *config);
int spi_init();
int read_rtd_resistance();
float calculate_temperature(float resistance);
float pid_control(float setpoint, float actual_temperature, float *integral, float *previous_error, float kp, float ki, float kd);
void set_pwm_duty(float duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from JSON file
int read_config(const char *filename, PIDConfig *config) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        config->target_temperature = 25.0;
        config->kp = 1.0;
        config->ki = 0.1;
        config->kd = 0.01;
        return -1;
    }

    json_t *target_temp = json_object_get(root, "target_temperature");
    json_t *kp = json_object_get(root, "kp");
    json_t *ki = json_object_get(root, "ki");
    json_t *kd = json_object_get(root, "kd");

    if (json_is_real(target_temp)) {
        config->target_temperature = json_real_value(target_temp);
    } else {
        config->target_temperature = 25.0;
    }

    if (json_is_real(kp)) {
        config->kp = json_real_value(kp);
    } else {
        config->kp = 1.0;
    }

    if (json_is_real(ki)) {
        config->ki = json_real_value(ki);
    } else {
        config->ki = 0.1;
    }

    if (json_is_real(kd)) {
        config->kd = json_real_value(kd);
    } else {
        config->kd = 0.01;
    }

    json_decref(root);
    return 0;
}

// Function to initialize SPI communication
int spi_init() {
    spi_handle = spiOpen(0, 500000, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI interface: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read RTD resistance from MAX31865
int read_rtd_resistance() {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int rtd_raw;
    float rtd_resistance;

    // Read RTD value (register 0x01)
    tx_buf[0] = 0x01 | 0x80; // Read command for register 0x01
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI read failed\n");
        return -1;
    }

    rtd_raw = ((rx_buf[0] & 0x03) << 8) | rx_buf[1]; // Extract 14-bit RTD value

    // Check for fault
    if (rx_buf[0] & 0x04) {
        fprintf(stderr, "Error: MAX31865 fault detected (FAULT = %02x)\n", rx_buf[0]);
        return -1;
    }

    // Calculate resistance (assuming 430 ohm reference resistor)
    rtd_resistance = ((float)rtd_raw / 32768.0) * 430.0;

    return (int)rtd_resistance;
}

// Function to calculate temperature from resistance
float calculate_temperature(float resistance) {
    // Linear approximation for PT100 (adjust as needed)
    // This is a very rough approximation.  A proper RTD calculation
    // would involve a more complex formula.
    return (resistance - 100.0) / 0.385; // Example linear approximation
}

// Function to implement PID control
float pid_control(float setpoint, float actual_temperature, float *integral, float *previous_error, float kp, float ki, float kd) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;

    // Clamp the output to the range 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty(float duty_cycle) {
    int pwm_range = 1000;
    int pwm_value = (int)(duty_cycle * pwm_range / 100.0);
    gpioPWM(gpio_pin, pwm_value);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    set_pwm_duty(0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    float integral = 0.0;
    float previous_error = 0.0;
    float duty_cycle;
    int rtd_resistance;
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Read configuration
    if (read_config("config.json", &config) != 0) {
        fprintf(stderr, "Warning: Using default configuration values\n");
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 to PWM output mode
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioSetPWMfrequency(gpio_pin, 1000); // 1 kHz
    gpioSetPWMrange(gpio_pin, 1000);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting temperature regulation...\n");

    while (!terminate) {
        // Read RTD resistance
        rtd_resistance = read_rtd_resistance();
        if (rtd_resistance < 0) {
            fprintf(stderr, "Error: Failed to read RTD resistance\n");
            cleanup();
            return 1;
        }

        // Calculate temperature
        temperature = calculate_temperature((float)rtd_resistance);

        // Check for failsafe conditions
        if (temperature > 80.0) {
            fprintf(stderr, "Error: Temperature exceeds failsafe threshold (80°C)\n");
            cleanup();
            return 1;
        }

        // Implement PID control
        duty_cycle = pid_control(config.target_temperature, temperature, &integral, &previous_error, config.kp, config.ki, config.kd);

        // Set PWM duty cycle
        set_pwm_duty(duty_cycle);

        // Print current state (for debugging)
        printf("Target: %.2f°C, Actual: %.2f°C, Duty Cycle: %.2f%%\n", config.target_temperature, temperature, duty_cycle);

        // Wait for 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

