#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
short ac1, ac2, ac3, b1, b2, mb, mc, md;
unsigned short ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(long *raw_temperature);
int read_raw_pressure(long *raw_pressure);
double calculate_temperature(long raw_temperature);
double calculate_pressure(long raw_pressure, long raw_temperature);
int log_breach(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Helper function to read a short (2 bytes) from I2C
int read_short(int handle, char reg, short *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Helper function to read an unsigned short (2 bytes) from I2C
int read_ushort(int handle, char reg, unsigned short *value)
{
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0)
    {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0)
    {
        fprintf(stderr, "Failed to read calibration data\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate)
    {
        long raw_temperature, raw_pressure;
        double temperature, pressure;

        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temperature) != 0)
        {
            fprintf(stderr, "Failed to read raw temperature\n");
            continue; // Continue to the next iteration
        }
        if (read_raw_pressure(&raw_pressure) != 0)
        {
            fprintf(stderr, "Failed to read raw pressure\n");
            continue; // Continue to the next iteration
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, raw_temperature);

        // Check for breaches
        if (temperature > 30.0 || pressure < 950.0)
        {
            log_breach(temperature, pressure);
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int init_i2c()
{
    int retries = 3;
    while (retries > 0)
    {
        i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
        if (i2c_handle >= 0)
        {
            return 0; // Success
        }
        else
        {
            fprintf(stderr, "Failed to open I2C device, retrying...\n");
            retries--;
            time_sleep(0.1); // Wait before retrying
        }
    }
    fprintf(stderr, "Failed to open I2C device after multiple retries\n");
    return -1; // Failure
}

int read_calibration_data()
{
    if (read_short(i2c_handle, BMP180_REG_CAL_AC1, &ac1) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_AC2, &ac2) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_AC3, &ac3) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC4, &ac4) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC5, &ac5) != 0) return -1;
    if (read_ushort(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
    if (read_short(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

    return 0;
}

int read_raw_temperature(long *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) return -1;
    time_sleep(0.005); // Wait 4.5ms
    if (read_short(i2c_handle, BMP180_REG_MSB, (short*)raw_temperature) != 0) return -1;
    return 0;
}

int read_raw_pressure(long *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) return -1;
    time_sleep(0.004 + (0.002 * BMP180_OSS)); // Wait for conversion

    char msb, lsb, xlsb;
    char reg = BMP180_REG_MSB;

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) return -1;
    if (i2cReadDevice(i2c_handle, &msb, 1) != 1) return -1;
    if (i2cReadDevice(i2c_handle, &lsb, 1) != 1) return -1;
    if (i2cReadDevice(i2c_handle, &xlsb, 1) != 1) return -1;

    *raw_pressure = ((long)msb << 16 | (long)lsb << 8 | (long)xlsb) >> (8 - BMP180_OSS);
    return 0;
}

double calculate_temperature(long raw_temperature)
{
    long X1 = ((raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long X2 = ((long)mc << 11) / (X1 + (long)md);
    long B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

double calculate_pressure(long raw_pressure, long raw_temperature)
{
    long X1 = ((raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long X2 = ((long)mc << 11) / (X1 + (long)md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) >> 12) >> 11;
    long X4 = ((long)ac2 * B6) >> 11;
    long B3 = (((((long)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;

    unsigned long X1_pressure = ((unsigned long)ac3 * B6) >> 13;
    unsigned long X2_pressure = ((unsigned long)b1 * ((B6 * B6) >> 12)) >> 16;
    unsigned long B4 = X1_pressure + X2_pressure + 32768;
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> BMP180_OSS);

    long p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
