float calculate_pressure(int raw_pressure, int raw_temperature)
{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;
    float pressure;

    long ut = raw_temperature;
    long up = raw_pressure;

    x1 = (((long)ut - (long)ac6) * (long)ac5) >> 15;
    x2 = ((long)mc << 11) / (x1 + md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (unsigned long)(x3 + 32768)) >> 15;

    b7 = ((unsigned long)up - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    pressure = p + ((x1 + x2 + 3791) >> 4);

    return pressure;
}

// Function to store a reading in the circular buffer
void store_reading(float temperature, float pressure)
{
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print a reading to stdout
void print_reading(float temperature, float pressure)
{
    time_t now;
    time(&now);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(stdout); // Ensure data is written to stdout immediately
}

// Function to control the cooling fan
void control_fan(float temperature)
{
    if (temperature > 30.0) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback()
{
    int raw_temperature, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, raw_temperature);

        store_reading(temperature, pressure);
        print_reading(temperature, pressure);
        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data. Skipping this sample.\n");
    }
}

// Signal handler function
void signal_handler(int signal)
{
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan off

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Main loop
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

