    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL);

    // Main loop
    while (program_running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn off the fan
    i2cClose(i2c_handle);
    gpioTerminate();

