#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz

// Define PI controller parameters
#define KP 1.0
#define KI 0.1

// Define safe maximum duty cycle
#define MAX_DUTY_CYCLE 80

// Define target temperature
#define TARGET_TEMPERATURE 25.0

// Global variables
int spi_handle;
FILE *log_file;
double integral = 0.0;
double last_error = 0.0;

// Function prototypes
double read_temperature();
void set_heater_duty_cycle(double duty_cycle);
double calculate_pi_control(double current_temperature, double target_temperature);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set heater pin as output
    gpioSetMode(HEATER_PIN, PI_OUTPUT);

    // Set PWM range (0-1000 for finer resolution)
    gpioSetPWMrange(HEATER_PIN, 1000);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature,Duty Cycle\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed\n");
        log_data(-999.0, 0.0); // Log error
        set_heater_duty_cycle(0.0); // Turn off heater
        return -999.0; // Indicate error
    }

    // Check for fault conditions
    if (buffer[3] & 0x01) {
        fprintf(stderr, "Thermocouple open circuit\n");
        log_data(-999.0, 0.0); // Log error
        set_heater_duty_cycle(0.0); // Turn off heater
        return -999.0; // Indicate error
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "Thermocouple short to GND\n");
        log_data(-999.0, 0.0); // Log error
        set_heater_duty_cycle(0.0); // Turn off heater
        return -999.0; // Indicate error
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "Thermocouple short to VCC\n");
        log_data(-999.0, 0.0); // Log error
        set_heater_duty_cycle(0.0); // Turn off heater
        return -999.0; // Indicate error
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;

    // Anti-windup: Limit duty cycle to MAX_DUTY_CYCLE
    if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    }

    int pwm_value = (int)(duty_cycle * 10.0); // Scale 0-100 to 0-1000
    gpioPWM(HEATER_PIN, pwm_value);
}

// Function to calculate PI control output
double calculate_pi_control(double current_temperature, double target_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;

    // Anti-windup: Limit integral term
    if (integral > 100.0) integral = 100.0;
    if (integral < -100.0) integral = -100.0;

    double derivative = error - last_error;
    double output = KP * error + KI * integral; // + KD * derivative;

    last_error = error;
    return output;
}

// Function to log data to file
void log_data(double temperature, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_heater_duty_cycle(0.0); // Turn off heater
    cleanup();
    exit(0);
}

// Function to cleanup resources
void cleanup() {
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    double current_temperature, duty_cycle;

    while (1) {
        current_temperature = read_temperature();

        if (current_temperature != -999.0) {
            duty_cycle = calculate_pi_control(current_temperature, TARGET_TEMPERATURE);
            set_heater_duty_cycle(duty_cycle);
            log_data(current_temperature, duty_cycle);
        }

        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

