#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature file path
#define TEMPERATURE_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global variable for signal handling
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temperature() {
    FILE *fp;
    int temperature = -1;

    fp = fopen(TEMPERATURE_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fscanf(fp, "%d", &temperature) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: Error reading temperature file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temperature;
}

// Function to set RGB LED color using pigpio
void set_led_color(int red, int green, int blue) {
    int result;

    result = gpioPWM(RED_PIN, 255 - red);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set red PWM value. Error code: %d\n", result);
    }

    result = gpioPWM(GREEN_PIN, 255 - green);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set green PWM value. Error code: %d\n", result);
    }

    result = gpioPWM(BLUE_PIN, 255 - blue);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set blue PWM value. Error code: %d\n", result);
    }
}

// Function to determine LED color based on temperature
void determine_led_color(int temperature, int *red, int *green, int *blue) {
    if (temperature < 40000) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temperature < 60000) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main() {
    int temperature, red, green, blue;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        temperature = read_cpu_temperature();
        if (temperature == -1) {
            fprintf(stderr, "Error: Failed to read CPU temperature. Skipping this iteration.\n");
            sleep(0.5);
            continue;
        }

        // Determine LED color
        determine_led_color(temperature, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Get current timestamp
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Print temperature and PWM values
        printf("%s - Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", timestamp, temperature, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Turn off all LEDs
    set_led_color(255, 255, 255);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

