    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30);

    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1); // Wait 1 us
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 response signal timeout\n");
            return -1; // Timeout error
        }
    }

    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 response signal timeout (low)\n");
            return -1;
        }
    }

    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "DHT22 response signal timeout (high)\n");
            return -1;
        }
    }

    // Read the 40-bit data stream
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 data bit timeout (low)\n");
                return -1;
            }
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "DHT22 data bit timeout (high)\n");
                return -1;
            }
        }
        long end = gpioTick();

        if ((end - start) > 40) { // 40us is considered a '1'
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) & 0xFF != data[4]) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)(((data[0] << 8) | data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) | data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0; // Success
