    int retries;
    char *json_data;
    int result;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        retries = 0;
        result = -1; // Initialize result to failure

        while (retries < MAX_RETRIES && result != 0) {
            result = read_dht22(DHT22_GPIO, &temperature, &humidity);
            if (result != 0) {
                fprintf(stderr, "DHT22 read failed, retry %d/%d\n", retries + 1, MAX_RETRIES);
                retries++;
                sleep(1); // Wait before retrying
            }
        }

        if (result == 0) {
            json_data = format_json(temperature, humidity);
            if (json_data != NULL) {
                if (send_data(json_data) != 0) {
                    fprintf(stderr, "Failed to send data\n");
                }
                free(json_data);
            } else {
                fprintf(stderr, "Failed to format JSON\n");
            }
        } else {
            fprintf(stderr, "DHT22 read failed after %d retries\n", MAX_RETRIES);
        }

        sleep(60); // Wait 60 seconds before next reading
    }

    gpioTerminate();
    return 0;
}

