#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // OSS = 0
#define BMP180_CMD_PRESSURE1 0x74 // OSS = 1
#define BMP180_CMD_PRESSURE2 0xB4 // OSS = 2
#define BMP180_CMD_PRESSURE3 0xF4 // OSS = 3

// Oversampling setting
#define OSS 3

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
static int bmp180_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static unsigned long last_interrupt_time = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int bmp180_init(int fd);
int bmp180_read_calibration_data(int fd);
int bmp180_read_raw_temperature(int fd);
int bmp180_read_raw_pressure(int fd);
double bmp180_calculate_pressure(int raw_temperature, int raw_pressure);
void log_pressure(double pressure);
void toggle_logging(void);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int16_t read_int16(int fd, uint8_t reg)
{
    int16_t msb = wiringPiI2CReadReg8(fd, reg);
    int16_t lsb = wiringPiI2CReadReg8(fd, reg + 1);
    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return (msb << 8) | lsb;
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_uint16(int fd, uint8_t reg)
{
    int16_t msb = wiringPiI2CReadReg8(fd, reg);
    int16_t lsb = wiringPiI2CReadReg8(fd, reg + 1);
    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return (msb << 8) | lsb;
}

// Function to read a 24-bit value from the BMP180
int32_t read_int24(int fd, uint8_t reg)
{
    int16_t msb = wiringPiI2CReadReg8(fd, reg);
    int16_t lsb = wiringPiI2CReadReg8(fd, reg + 1);
    int16_t xlsb = wiringPiI2CReadReg8(fd, reg + 2);
    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading 24-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return (msb << 16) | (lsb << 8) | xlsb;
}

// Initialize the BMP180 sensor
int bmp180_init(int fd)
{
    // Read calibration data
    if (bmp180_read_calibration_data(fd) != 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        return -1;
    }

    return 0;
}

// Read calibration data from the BMP180
int bmp180_read_calibration_data(int fd)
{
    ac1 = read_int16(fd, 0xAA);
    ac2 = read_int16(fd, 0xAC);
    ac3 = read_int16(fd, 0xAE);
    ac4 = read_uint16(fd, 0xB0);
    ac5 = read_uint16(fd, 0xB2);
    ac6 = read_uint16(fd, 0xB4);
    b1 = read_int16(fd, 0xB6);
    b2 = read_int16(fd, 0xB8);
    mb = read_int16(fd, 0xBA);
    mc = read_int16(fd, 0xBC);
    md = read_int16(fd, 0xBE);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        return -1;
    }

    return 0;
}

// Read raw temperature value from the BMP180
int bmp180_read_raw_temperature(int fd)
{
    wiringPiI2CWriteReg8(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP);
    delay(5); // Wait 4.5ms
    return read_int16(fd, BMP180_REG_MSB);
}

// Read raw pressure value from the BMP180
int bmp180_read_raw_pressure(int fd)
{
    wiringPiI2CWriteReg8(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE3);
    delay(26); // Wait 26ms for OSS = 3
    int msb = wiringPiI2CReadReg8(fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(fd, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading raw pressure: %s\n", strerror(errno));
        return -1;
    }

    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
}

// Calculate pressure in hPa
double bmp180_calculate_pressure(int raw_temperature, int raw_pressure)
{
    long X1 = ((long)raw_temperature - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)ac2 * B6) / pow(2, 11);
    long B3 = (((((long)ac1) * 4 + X3) << OSS) + 2) / 4;
    unsigned long B4 = ((unsigned long)ac4 * (unsigned long)(X3 + X4 + 32768)) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);
    long p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (X1 + X2 + 3791) / pow(2, 4);
    return pressure / 100.0; // Convert to hPa
}

// Log pressure to file
void log_pressure(double pressure)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Toggle logging state
void toggle_logging(void)
{
    unsigned long current_time = millis();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;

        if (logging_enabled) {
            printf("Logging enabled.\n");
        } else {
            printf("Logging disabled.\n");
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);

    if (bmp180_fd != -1) {
        close(bmp180_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main(void)
{
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    bmp180_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (bmp180_fd == -1) {
        fprintf(stderr, "Failed to initialize I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize BMP180 sensor
    if (bmp180_init(bmp180_fd) != 0) {
        fprintf(stderr, "Failed to initialize BMP180 sensor.\n");
        close(bmp180_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(bmp180_fd);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt on GPIO 4 (falling edge)
    wiringPiISR(4, INT_EDGE_FALLING, toggle_logging);

    printf("Pressure logger started. Press Ctrl+C to exit.\n");

    while (running) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            int raw_temperature = bmp180_read_raw_temperature(bmp180_fd);
            int raw_pressure = bmp180_read_raw_pressure(bmp180_fd);

            if (raw_temperature != -1 && raw_pressure != -1) {
                // Calculate pressure
                double pressure = bmp180_calculate_pressure(raw_temperature, raw_pressure);

                // Log pressure
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Failed to read raw temperature or pressure.\n");
            }
        }
        delay(2000); // Read every 2 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close(bmp180_fd);
    fclose(log_file);

    return 0;
}

