#include <syslog.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <time.h>
#include <errno.h>

// Configuration
#define DHT22_GPIO 4
#define API_URL "http://your-the-library’s-API-call.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2
#define POST_RETRIES 3

// Global variables
static volatile int running = 1;
static char *api_url = API_URL;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting gracefully.");
    running = 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to read DHT22 sensor data
int read_dht22(DHT22Data *data) {
    int retries = 0;
    int result = -1;

    while (retries < MAX_RETRIES && result != 0) {
        result = read_dht22_data(data);
        if (result != 0) {
            syslog(LOG_WARNING, "DHT22 read failed, retrying in %d seconds.", BACKOFF_DELAY * (retries + 1));
            sleep(BACKOFF_DELAY * (retries + 1));
            retries++;
        }
    }

    if (result != 0) {
        syslog(LOG_ERR, "DHT22 read failed after %d retries.", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Function to read DHT22 data using pigpio
int read_dht22_data(DHT22Data *data) {
    int bit_idx = 0;
    int byte_idx = 0;
    int data_bits[40];
    int i;
    unsigned int pulse_start, pulse_end, pulse_len;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // Changed from 40 to 30 to avoid timeout
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read data
    for (i = 0; i < 40; i++) {
        // Wait for low
        int count = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            count++;
            gpioDelay(1); // Delay 1 us
            if (count > 100) {
                syslog(LOG_ERR, "Timeout waiting for low signal.");
                return -1;
            }
        }

        pulse_start = gpioTick();

        // Wait for high
        count = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            count++;
            gpioDelay(1); // Delay 1 us
            if (count > 100) {
                syslog(LOG_ERR, "Timeout waiting for high signal.");
                return -1;
            }
        }

        pulse_end = gpioTick();

        pulse_len = pulse_end - pulse_start;

        data_bits[i] = (pulse_len > 40) ? 1 : 0; // Adjust threshold
    }

    // Convert to bytes
    unsigned char data_bytes[5];
    for (i = 0; i < 5; i++) {
        data_bytes[i] = 0;
        for (int j = 0; j < 8; j++) {
            data_bytes[i] <<= 1;
            data_bytes[i] |= data_bits[i * 8 + j];
        }
    }

    // Validate checksum
    if (data_bytes[4] != ((data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) & 0xFF)) {
        syslog(LOG_ERR, "Checksum failure.");
        return -1;
    }

    // Convert to temperature and humidity
    data->humidity = (float)(((data_bytes[0] << 8) | data_bytes[1])) / 10.0;
    data->temperature = (float)(((data_bytes[2] << 8) | data_bytes[3])) / 10.0;
    if (data_bytes[2] & 0x80) {
        data->temperature *= -1;
    }

    syslog(LOG_INFO, "Temperature: %.1f°C, Humidity: %.1f%%", data->temperature, data->humidity);

    return 0;
}

// Function to format data as JSON
char *format_json(const DHT22Data *data) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string.");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", data->temperature, data->humidity);
    return json_string;
}

// Function to POST data to API
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    int retries = 0;
    int result = -1;

    while (retries < POST_RETRIES && result != 0) {
        curl_global_init(CURL_GLOBAL_ALL);
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, api_url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, NULL); // Let libcurl handle the headers

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                sleep(BACKOFF_DELAY * (retries + 1));
                retries++;
            } else {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    syslog(LOG_INFO, "Data posted successfully.");
                    result = 0;
                } else {
                    syslog(LOG_ERR, "HTTP request failed with status code: %ld", response_code);
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    sleep(BACKOFF_DELAY * (retries + 1));
                    retries++;
                }
            }
        } else {
            syslog(LOG_ERR, "curl_easy_init() failed");
            result = -1;
            break;
        }
    }

    if (result != 0) {
        syslog(LOG_ERR, "Failed to post data after %d retries.", POST_RETRIES);
    }

    return result;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        DHT22Data data;
        if (read_dht22(&data) == 0) {
            char *json_data = format_json(&data);
            if (json_data != NULL) {
                post_data(json_data);
                free(json_data);
            }
        }
        sleep(10);
    }

    // Cleanup
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

