#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL 5 // seconds

volatile sig_atomic_t program_running = 1;
int max_fan_state = -1; // Initialize to an invalid value

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
}

// Function to read the CPU temperature from the sysfs file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert to degrees Celsius
}

// Function to read the current fan state from the sysfs file
int read_fan_state() {
    FILE *fp;
    int state = -1;

    fp = fopen(FAN_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening fan state file");
        return -1;
    }

    if (fscanf(fp, "%d", &state) != 1) {
        fprintf(stderr, "Error reading fan state from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return state;
}

// Function to read the maximum fan state from the sysfs file
int read_max_fan_state() {
    FILE *fp;
    int max_state = -1;

    fp = fopen(MAX_STATE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening max fan state file");
        return -1;
    }

    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max fan state from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return max_state;
}

// Function to set the fan speed based on the temperature
int set_fan_speed(int temp) {
