#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define PWM parameters
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 100      // 0-100%

// Define PID parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Define temperature limits
#define TEMP_MAX 100.0
#define TEMP_MIN 0.0

// Define target temperature
#define TARGET_TEMP 50.0

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// PID variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
double read_temperature();
void set_pwm_duty_cycle(int duty_cycle);
double calculate_pid(double current_temperature);
void log_data(double temperature, int duty_cycle, double pid_output);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int i;
    double temperature = -1000.0; // Initialize to an invalid value

    // Read 4 bytes from SPI
    if (spiRead(spi_handle, buffer, 4) != 4) {
        fprintf(stderr, "Error reading from SPI\n");
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1000.0;
    }
    if (buffer[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (buffer[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    temperature = raw_temp * 0.25;

    return temperature;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(HEATER_PIN, duty_cycle);
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = TARGET_TEMP - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to log data to file
void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CLK, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_DO, PI_INPUT);

    // Configure PWM
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(0, 500000, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    set_pwm_duty_cycle(0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Temperature control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        double temperature = read_temperature();
        if (temperature < -900.0) {
            fprintf(stderr, "Error reading temperature, skipping PID calculation\n");
            set_pwm_duty_cycle(0); // Turn off heater
            log_data(temperature, 0, 0.0);
        } else {
            if (temperature > TEMP_MAX || temperature < TEMP_MIN) {
                fprintf(stderr, "Temperature out of range, disabling heater\n");
                set_pwm_duty_cycle(0);
                log_data(temperature, 0, 0.0);
                running = 0; // Exit loop
            } else {
                double pid_output = calculate_pid(temperature);
                int duty_cycle = (int)pid_output;
                set_pwm_duty_cycle(duty_cycle);
                log_data(temperature, duty_cycle, pid_output);
            }
        }
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

