#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
float read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    float temp_celsius;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli / 1000.0;
    return temp_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature <= 40.0) {
        duty_cycle = 0;
    } else if (temperature >= 70.0) {
        duty_cycle = 1000000; // 100% duty cycle
    } else {
        duty_cycle = (int)(((temperature - 40.0) / 30.0) * 1000000.0);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle on GPIO18
int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

// Function to log data to cooling_log.csv
int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main() {
    float temperature;
    int duty_cycle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    printf("CPU Temperature-Controlled Fan\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading CPU temperature, using previous value.\n");
            // Consider a default or previous valid temperature here if needed
            continue; // Skip to the next iteration
        }

        // Calculate duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

