// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
float read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    float temp_celsius;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli / 1000.0;
    return temp_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature <= 40.0) {
        duty_cycle = 0;
    } else if (temperature >= 70.0) {
        duty_cycle = 1000000; // 100% duty cycle
    } else {
        duty_cycle = (int)(((temperature - 40.0) / 30.0) * 1000000.0);
    }

    return duty_cycle;
}

