#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define I2C bus
#define I2C_BUS 1

// Define log file name
#define LOG_FILE "flow_log.txt"

// Define retry count
#define RETRY_COUNT 3

// Global variables for I2C handles and log file
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_flow_sensor(int i2c_handle, float *flow_rate);
int log_flow_data(FILE *log_file, float flow1, float flow2);
void signal_handler(int signal);
unsigned char crc8(const unsigned char *data, int len);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow data from a sensor
int read_flow_sensor(int i2c_handle, float *flow_rate) {
    char buf[3];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 3);
        if (result == 3) {
            // CRC check
            unsigned char crc = crc8((unsigned char *)buf, 2);
            if (crc == buf[2]) {
                // Convert raw data to flow rate (example scaling, adjust as needed)
                int raw_flow = (buf[0] << 8) | buf[1];
                *flow_rate = (float)raw_flow / 100.0; // Example scaling
                return 0; // Success
            } else {
                fprintf(stderr, "CRC check failed. Expected: 0x%02X, Calculated: 0x%02X\n", buf[2], crc);
            }
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(10); // Small delay before retrying
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to log flow data to a file
int log_flow_data(FILE *log_file, float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Received signal %d, cleaning up...\n", signal);

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2;

    // Main loop
    while (1) {
        // Read flow data from both sensors
        if (read_flow_sensor(i2c_handle1, &flow1) != 0) {
            flow1 = -1.0; // Indicate error
        }
        if (read_flow_sensor(i2c_handle2, &flow2) != 0) {
            flow2 = -1.0; // Indicate error
        }

        // Log the data
        if (log_flow_data(log_file, flow1, flow2) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    return 0;
}

