#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the state machine states
enum {
    STATE_00,
    STATE_01,
    STATE_11,
    STATE_10
};

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int current_state = STATE_00;
static float current_position = 0.0f;

// Function prototypes
int initialize_gpio();
int read_encoder_a();
int read_encoder_b();
int update_state(int a_value, int b_value);
float calculate_position(int new_state);
int log_position(float position);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);

    gpioSetMode(ENCODER_B_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    return 0;
}

// Read the state of Channel A
int read_encoder_a() {
    return gpioRead(ENCODER_A_PIN);
}

// Read the state of Channel B
int read_encoder_b() {
    return gpioRead(ENCODER_B_PIN);
}

// Update the state machine state based on Channel A and Channel B values
int update_state(int a_value, int b_value) {
    int new_state;

    if (a_value == 0 && b_value == 0) {
        new_state = STATE_00;
    } else if (a_value == 0 && b_value == 1) {
        new_state = STATE_01;
    } else if (a_value == 1 && b_value == 1) {
        new_state = STATE_11;
    } else {
        new_state = STATE_10;
    }

    return new_state;
}

// Calculate the angular position based on the new state
float calculate_position(int new_state) {
    float position = current_position;

    if (current_state == new_state) {
        return position; // No change
    }

    if (current_state == STATE_00) {
        if (new_state == STATE_01) {
            position += 1.0f;
        } else if (new_state == STATE_10) {
            position -= 1.0f;
        }
    } else if (current_state == STATE_01) {
        if (new_state == STATE_11) {
            position += 1.0f;
        } else if (new_state == STATE_00) {
            position -= 1.0f;
        }
    } else if (current_state == STATE_11) {
        if (new_state == STATE_10) {
            position += 1.0f;
        } else if (new_state == STATE_01) {
            position -= 1.0f;
        }
    } else {
        if (new_state == STATE_00) {
            position += 1.0f;
        } else if (new_state == STATE_11) {
            position -= 1.0f;
        }
    }

    // Normalize the position to be between 0.00 and 360.00
    if (position >= 360.0f) {
        position -= 360.0f;
    } else if (position < 0.0f) {
        position += 360.0f;
    }

    return position;
}

// Log the timestamped position change to the log file
int log_position(float position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, position);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int a_value = read_encoder_a();
        int b_value = read_encoder_b();
        int new_state = update_state(a_value, b_value);
        float new_position = calculate_position(new_state);

        if (new_position != current_position) {
            if (log_position(new_position) != 0) {
                fprintf(stderr, "Error logging position.\n");
            }
            current_position = new_position;
        }

        current_state = new_state;
        gpioDelay(1000); // Delay for 1ms (adjust as needed)
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

