#include <signal.h>
#include <string.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18

// Define gain levels
#define GAIN_60DB 0
#define GAIN_30DB 1

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int set_gain(int gain);
int read_audio_level();
int log_event(int level);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
} ProgramState;

ProgramState state = {0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);
    gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT);

    state.gpio_initialized = 1;
    return 0;
}

// Function to set the gain level
int set_gain(int gain) {
    if (!state.gpio_initialized) {
        fprintf(stderr, "GPIO not initialized\n");
        return -1;
    }

    if (gain != GAIN_60DB && gain != GAIN_30DB) {
        fprintf(stderr, "Invalid gain level\n");
        return -1;
    }

    gpioWrite(GAIN_SELECT_PIN, gain);
    return 0;
}

// Function to read the audio level
int read_audio_level() {
    if (!state.gpio_initialized) {
        fprintf(stderr, "GPIO not initialized\n");
        return -1;
    }

    return gpioRead(AUDIO_INPUT_PIN);
}

// Function to log an event to the file
int log_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s LEVEL%d\n", timestamp, level);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set initial gain to 60dB
    if (set_gain(GAIN_60DB) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    int last_level = 0; // Store the last known level

    // Main loop
    while (running) {
        int current_level = read_audio_level();

        if (current_level < 0) {
            fprintf(stderr, "Error reading audio level\n");
            break;
        }

        // Detect rising edge (from 0 to 1)
        if (current_level == 1 && last_level == 0) {
            if (log_event(1) != 0) {
                fprintf(stderr, "Error logging event\n");
                break;
            }
        }

        last_level = current_level;

        gpioDelay(10); // Poll every 10 milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (state.gpio_initialized) {
        gpioTerminate();
    }

    printf("Exiting.\n");
    return 0;
}

