#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_LOG_FILE "flow_log.csv"
#define MEASUREMENT_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_rate(int *raw_flow);
float convert_to_ul_min(int raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, size_t len);

// CRC8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(int *raw_flow) {
    char buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    uint8_t crc = crc8((uint8_t *)buf, 2);
    if (crc != (uint8_t)buf[2]) {
        fprintf(stderr, "CRC check failed! Expected: %02X, Received: %02X\n", crc, (uint8_t)buf[2]);
        return -1;
    }

    *raw_flow = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw flow rate to microLiters per minute
float convert_to_ul_min(int raw_flow) {
    // Conversion factor from datasheet (example, adjust as needed)
    float flow_rate = (float)raw_flow / 120.0; // Example: 120 LSB/uL
    return flow_rate * 60000.0; // Convert to uL/min
}

// Log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);

    return 0;
}

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int raw_flow;
    float flow_rate;

    // Main loop
    while (!terminate) {
        if (read_flow_rate(&raw_flow) == 0) {
            flow_rate = convert_to_ul_min(raw_flow);
            log_flow_rate(flow_rate);
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }

        gpioDelay(MEASUREMENT_INTERVAL_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

