#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    unsigned int tvoc;
    unsigned int eco2;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int process_sensor_data(const sensor_data_t *data, float *iaq, float *tvoc_ppb, float *eco2_ppm);
int log_data(float iaq, float tvoc_ppb, float eco2_ppm);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C interface
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data from the MICS-VZ-89TE
int read_sensor_data(sensor_data_t *data) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char buffer[4]; // Example buffer to store 4 bytes of data
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }

    gpioDelay(100); // Wait for conversion (adjust as needed)

    result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    // Example data parsing (adjust based on sensor datasheet)
    data->tvoc = (buffer[0] << 8) | buffer[1];
    data->eco2 = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Function to process sensor data and calculate IAQ index
int process_sensor_data(const sensor_data_t *data, float *iaq, float *tvoc_ppb, float *eco2_ppm) {
    // Placeholder for IAQ calculation (replace with actual formula)
    *tvoc_ppb = (float)data->tvoc; // Example: directly using raw value
    *eco2_ppm = (float)data->eco2; // Example: directly using raw value
    *iaq = (*tvoc_ppb + *eco2_ppm) / 2.0; // Example: average of TVOC and eCO2

    return 0;
}

// Function to log data to a CSV file
int log_data(float iaq, float tvoc_ppb, float eco2_ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, iaq, tvoc_ppb, eco2_ppm);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    float iaq, tvoc_ppb, eco2_ppm;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Process sensor data
            if (process_sensor_data(&sensor_data, &iaq, &tvoc_ppb, &eco2_ppm) == 0) {
                // Log data
                if (log_data(iaq, tvoc_ppb, eco2_ppm) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Failed to process sensor data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

