#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define ALERT_THRESHOLD_SEC 5

static volatile int running = 1;
static int touch_start_time = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        return -1;
    }
    return value;
}

// Function to check for intrusion and print alert
void check_intrusion(int sensor_value) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    int current_time = ts.tv_sec;

    if (sensor_value == 1) {
        if (touch_start_time == 0) {
            touch_start_time = current_time;
        }

        if (current_time - touch_start_time >= ALERT_THRESHOLD_SEC) {
            printf("Intrusion Alert!\n");
            touch_start_time = 0; // Reset the timer
        }
    } else {
        touch_start_time = 0; // Reset the timer if sensor is released
    }
}

// Function to cleanup resources
void cleanup() {
    gpioTerminate();
    printf("pigpio terminated.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pin
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Tamper detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        check_intrusion(sensor_value);

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup resources before exiting
    cleanup();

    return EXIT_SUCCESS;
}

