#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define constants
#define GPIO_CHANNEL_SELECT 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 16 // bits
#define FORMAT SND_PCM_FORMAT_S16_LE
#define CAPTURE_DEVICE "default"
#define PCM_CAPTURE_DEVICE "hw:0,0"
#define FILE_NAME "audio_capture.pcm"

// Global variables
snd_pcm_t *pcm_handle = NULL;
FILE *file_pointer = NULL;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the ALSA PCM device
int init_alsa(snd_pcm_t **pcm_handle) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    // Open PCM device for capture
    if ((err = snd_pcm_open(pcm_handle, PCM_CAPTURE_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device %s: %s\n", PCM_CAPTURE_DEVICE, snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set format
    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set number of channels
    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set sample rate
    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: Sample rate changed to %d\n", rate);
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Function to set the L/R channel select line
int set_channel_select(int gpio_pin, int channel) {
    if (gpioWrite(gpio_pin, channel) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to capture audio data
int capture_audio(snd_pcm_t *pcm_handle, FILE *file_pointer) {
    int err;
    int frame_size = snd_pcm_frames_to_bytes(pcm_handle, 1); // Number of bytes per frame
    char *buffer = (char *)malloc(frame_size);
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating memory for buffer\n");
        return -1;
    }

    while (!terminate) {
        // Read audio data
        err = snd_pcm_readi(pcm_handle, buffer, 1); // Read one frame at a time
        if (err == -EPIPE) {
            /* EPIPE means overrun */
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err < 0) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            free(buffer);
            return -1;
        } else if (err != 1) {
            fprintf(stderr, "Short read, read %d frames\n", err);
        }

        // Write audio data to file
        size_t bytes_written = fwrite(buffer, 1, frame_size, file_pointer);
        if (bytes_written != frame_size) {
            fprintf(stderr, "Error writing to file\n");
            free(buffer);
            return -1;
        }
    }

    free(buffer);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_CHANNEL_SELECT, PI_OUTPUT);

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    file_pointer = fopen(FILE_NAME, "wb");
    if (file_pointer == NULL) {
        fprintf(stderr, "Error opening file %s\n", FILE_NAME);
        snd_pcm_close(pcm_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Capture audio continuously
    while (!terminate) {
        // Set left channel
        if (set_channel_select(GPIO_CHANNEL_SELECT, 0) != 0) {
            break;
        }
        if (capture_audio(pcm_handle, file_pointer) != 0) {
            break;
        }

        // Set right channel
        if (set_channel_select(GPIO_CHANNEL_SELECT, 1) != 0) {
            break;
        }
        if (capture_audio(pcm_handle, file_pointer) != 0) {
            break;
        }
    }

    // Cleanup
    if (pcm_handle != NULL) {
        snd_pcm_close(pcm_handle);
    }
    if (file_pointer != NULL) {
        fclose(file_pointer);
    }
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

