#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time
#define DEBOUNCE_TIME 50 // milliseconds

// Define timeout time
#define TIMEOUT_TIME 1000 // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int flame_sensor_pin;
    int fan_pin;
    int pwm_frequency;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int i, reading, sum = 0;

    // Read the sensor multiple times for debouncing
    for (i = 0; i < 5; i++) {
        reading = gpioRead(FLAME_SENSOR_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_PIN);
            return -1; // Indicate error
        }
        sum += reading;
        gpioDelay(DEBOUNCE_TIME / 5); // Divide debounce time for multiple reads
    }

    // Return 0 if most readings are 0, 1 otherwise
    return (sum < 3) ? 0 : 1;
}

// Function to control the fan using PWM
void control_fan(int flame_detected) {
    if (flame_detected) {
        gpioPWM(FAN_PIN, 128); // 50% duty cycle
    } else {
        gpioPWM(FAN_PIN, 0);   // 0% duty cycle
    }
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", buf, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to reset GPIO and terminate pigpio
void cleanup() {
    gpioPWM(FAN_PIN, 0); // Stop the fan
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Reset flame sensor pin
    gpioSetMode(FAN_PIN, PI_INPUT); // Reset fan pin
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Log program start
    log_event("Program start");

    int flame_detected = 0;
    int timeout_count = 0;

    while (running) {
        int sensor_reading = read_flame_sensor();

        if (sensor_reading == 0) {
            // Flame detected
            if (!flame_detected) {
                flame_detected = 1;
                control_fan(flame_detected);
                log_event("Flame detected");
                timeout_count = 0; // Reset timeout counter
            }
        } else if (sensor_reading > 0) {
            // No flame detected
            if (flame_detected) {
                flame_detected = 0;
                control_fan(flame_detected);
                log_event("Flame ended");
            }
            timeout_count += 50; // Increment timeout counter
            if (timeout_count >= TIMEOUT_TIME) {
                log_event("Sensor absent");
                timeout_count = 0; // Reset timeout counter
            }
        } else {
            // Error reading sensor
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(50); // Check every 50ms
    }

    // Log program shutdown
    log_event("Program shutdown");

    // Cleanup and exit
    cleanup();
    return 0;
}

