#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONTINUOUS_CONV_MODE 0xCC10
#define LUX_SCALE 0.01
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_sensor();
float read_lux();
char* get_timestamp();
int log_data(char *timestamp, float lux);
void signal_handler(int signal);
void cleanup();

// Structure for configuration
typedef struct {
    int i2c_bus;
    int opt3001_address;
    char *log_file_name;
} config_t;

config_t config = {I2C_BUS, OPT3001_ADDR, LOG_FILE};

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.opt3001_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int config_sensor() {
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, CONTINUOUS_CONV_MODE);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read lux value from the sensor
float read_lux() {
    int raw_data = i2cReadWordData(i2c_handle, RESULT_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading result register: %d\n", raw_data);
        return -1.0;
    }

    // Extract exponent and result from the raw data
    int exponent = (raw_data >> 12) & 0x0F;
    int result = raw_data & 0x0FFF;

    // Calculate lux value
    float lux = LUX_SCALE * result * (1 << exponent);
    return lux;
}

// Get current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(char *timestamp, float lux) {
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fclose(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
