void log_data(int sensor_value) {
    char *timestamp = get_timestamp();
    if (timestamp != NULL) {
        if (sensor_value == 0) {
            printf("%s Flame Detected: YES\n", timestamp);
        } else {
            printf("%s Flame Detected: NO\n", timestamp);
        }
        free(timestamp); // Free the allocated memory
    }
}

