    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistor on the GPIO pin
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set pull-up resistor on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

