    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value != -1) {
            log_data(sensor_value);
        }
        sleep(1);
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

