#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 18
#define RIGHT_SENSOR_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int left_state, center_state, right_state;
    int pigpio_init_result;

    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register SIGINT handler.\n");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register SIGTERM handler.\n");
        return 1;
    }

    // Initialize the pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop to read sensor values
    while (program_running) {
        // Read sensor values
        left_state = gpioRead(LEFT_SENSOR_PIN);
        center_state = gpioRead(CENTER_SENSOR_PIN);
        right_state = gpioRead(RIGHT_SENSOR_PIN);

        // Print sensor values to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

