#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 output channels
const int ttp226_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(ttp226_pins) / sizeof(ttp226_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to read the state of a single GPIO pin
int read_channel(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data with a timestamp
void log_data(int sensor_data[], int num_channels) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: ", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf("%d", sensor_data[i]);
    }
    printf("\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        gpioSetMode(ttp226_pins[i], PI_INPUT);
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to read and log sensor data
    while (program_running) {
        int sensor_data[num_channels];
        for (int i = 0; i < num_channels; i++) {
            int read_result = read_channel(ttp226_pins[i]);
            if (read_result == -1) {
                // Error reading channel, exit the program
                program_running = 0;
                break;
            }
            sensor_data[i] = read_result;
        }

        if (program_running) {
            log_data(sensor_data, num_channels);
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

