#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the TTP226 sensors
#define SENSOR_PINS {2, 3, 4, 5, 6, 7, 8, 9}

// Global variable to store the sensor pins
int sensor_pins[] = SENSOR_PINS;
int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Function prototypes
int read_sensors();
void print_sensor_data(int sensor_values);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to read the sensor values
int read_sensors() {
    int sensor_values = 0;
    for (int i = 0; i < num_sensors; i++) {
        int value = gpioRead(sensor_pins[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor %d: %d\n", i, value);
            return -1; // Indicate an error
        }
        sensor_values |= (value << i);
    }
    return sensor_values;
}

// Function to print the sensor data
void print_sensor_data(int sensor_values) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long timestamp_ms = (ts.tv_sec * 1000LL) + (ts.tv_nsec / 1000000LL);

    printf("[+%lld ms] ", timestamp_ms);
    for (int i = 0; i < num_sensors; i++) {
        int value = (sensor_values >> i) & 1;
        printf("CH%d=%d ", i + 1, value);
    }
    printf("\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs with pull-down resistors
    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int sensor_values = read_sensors();
        if (sensor_values >= 0) {
            print_sensor_data(sensor_values);
        } else {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }
        gpioDelay(100000); // 100ms delay
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

