#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 sensor channels
const int sensor_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to read the sensor data from the specified GPIO pins
int read_sensor_data(int pins[], int num_pins, int *data)
{
    for (int i = 0; i < num_pins; i++)
    {
        int level = gpioRead(pins[i]);
        if (level < 0)
        {
            fprintf(stderr, "Error reading GPIO %d: %d\n", pins[i], level);
            return -1; // Indicate an error
        }
        data[i] = level;
    }
    return 0; // Indicate success
}

// Function to format the sensor data into a CSV string
void format_csv_data(int data[], int num_data, char *buffer, size_t buffer_size)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    for (int i = 0; i < num_data; i++)
    {
        char temp[10];
        snprintf(temp, sizeof(temp), ",%d", data[i]);
        strcat(buffer, temp);
    }
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs with pull-down resistors
    for (int i = 0; i < num_channels; i++)
    {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        int sensor_data[num_channels];
        char csv_data[256]; // Buffer to hold the CSV string

        // Read the sensor data
        if (read_sensor_data(sensor_pins, num_channels, sensor_data) == 0)
        {
            // Format the data into a CSV string
            format_csv_data(sensor_data, num_channels, csv_data, sizeof(csv_data));

            // Print the CSV string to the console
            printf("%s\n", csv_data);
        }
        else
        {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

