#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define the GPIO pin connected to the tilt sensor
#define TILT_SENSOR_GPIO 4

// Global variable to store the previous tilt state
int previous_tilt_state = -1; // Initialize to an invalid state

// Function prototypes
int read_tilt_sensor();
void log_tilt_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        gpioTerminate();
        exit(0);
    }
}

// Function to read the tilt sensor state
int read_tilt_sensor() {
    int current_tilt_state = gpioRead(TILT_SENSOR_GPIO);
    if (current_tilt_state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", TILT_SENSOR_GPIO, current_tilt_state);
        return -1; // Indicate an error
    }
    return current_tilt_state;
}

// Function to log the tilt state to the console
void log_tilt_state(int state) {
    if (state == 0) {
        printf("Tilted\n");
    } else if (state == 1) {
        printf("Not Tilted\n");
    } else {
        fprintf(stderr, "Invalid tilt state: %d\n", state);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin as an input with a pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    // Install the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Print a startup banner
    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int current_tilt_state = read_tilt_sensor();

        if (current_tilt_state == -1) {
            // Error reading the sensor, exit the program
            gpioTerminate();
            return 1;
        }

        // Check if the tilt state has changed
        if (current_tilt_state != previous_tilt_state) {
            // Flush stdout to ensure immediate output
            fflush(stdout);

            // Log the tilt state
            log_tilt_state(current_tilt_state);

            // Update the previous tilt state
            previous_tilt_state = current_tilt_state;
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // The program should never reach here, but it's good practice to include gpioTerminate()
    gpioTerminate();
    return 0;
}

