#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define CSV_FILE "uv_als_log.csv"

// Si1145 Registers
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02

#define REG_UCOEF0 0x13
#define REG_UCOEF1 0x14
#define REG_UCOEF2 0x15
#define REG_UCOEF3 0x16

#define REG_PARAM_WR 0x17
#define REG_COMMAND 0x18

#define REG_RESPONSE0 0x20
#define REG_RESPONSE1 0x21
#define REG_RESPONSE2 0x22
#define REG_RESPONSE3 0x23

#define REG_IRQ_ENABLE 0x03
#define REG_IRQ_MODE1 0x04
#define REG_HW_KEY 0x07

#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_UV_INDEX_DATA0 0x2C
#define REG_UV_INDEX_DATA1 0x2D

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_uv_index();
int read_als_visible();
int log_data(int uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the Si1145 sensor
int si1145_init() {
    // Reset the device
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, REG_UCOEF0, 0x7B) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_UCOEF1, 0x6B) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_UCOEF2, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_UCOEF3, 0x00) < 0) return -1;

    if (i2cWriteByteData(i2c_handle, REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, REG_IRQ_MODE1, 0x00) < 0) return -1;

    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x17) < 0) return -1;

    // Enable ALS force mode
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_FORCE) < 0) return -1;

    return 0;
}

// Function to read the UV index from the sensor
int read_uv_index() {
    int uv_index = i2cReadByteData(i2c_handle, REG_UV_INDEX_DATA0);
    if (uv_index < 0) {
        fprintf(stderr, "Error: Failed to read UV index\n");
        return -1;
    }
    return uv_index;
}

// Function to read the visible ambient light from the sensor
int read_als_visible() {
    int als_visible = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    if (als_visible < 0) {
        fprintf(stderr, "Error: Failed to read ALS visible\n");
        return -1;
    }
    return als_visible;
}

// Function to log the data to a CSV file
int log_data(int uv_index, int als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (Error code: %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (si1145_init() < 0) {
        fprintf(stderr, "Error: Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int uv_index = read_uv_index();
        int als_visible = read_als_visible();

        if (uv_index >= 0 && als_visible >= 0) {
            printf("UV Index: %d, ALS Visible: %d\n", uv_index, als_visible);
            log_data(uv_index, als_visible);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

