#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_LOG_FILE "flow_log.txt"
#define START_COMMAND_1 0x3608
#define START_COMMAND_2 0x0000
#define MEASUREMENT_INTERVAL_MS 1000
#define ALARM_THRESHOLD 0.5 // ml/min

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int start_measurement(int i2c_handle);
int read_flow_rate(int i2c_handle, float *flow_rate);
int validate_crc(const unsigned char *data, int len);
void log_data(float flow_rate1, float flow_rate2, float average_flow_rate);
void set_alarm(int alarm_state);
void signal_handler(int signal);

// CRC polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Function to calculate CRC
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to start measurement
int start_measurement(int i2c_handle) {
    unsigned char command[2];
    command[0] = (START_COMMAND_1 >> 8) & 0xFF;
    command[1] = START_COMMAND_1 & 0xFF;

    int result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing start command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read flow rate
int read_flow_rate(int i2c_handle, float *flow_rate) {
    unsigned char buffer[3];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow rate: %d\n", result);
        return -1;
    }

    // Validate CRC
    if (!validate_crc(buffer, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert to flow rate
    int16_t raw_flow_rate = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow_rate / 100.0; // ml/min

    return 0;
}

// Function to validate CRC
int validate_crc(const unsigned char *data, int len) {
    unsigned char crc = crc8(data, len);
    return (crc == data[len]);
}

// Function to log data
void log_data(float flow_rate1, float flow_rate2, float average_flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow Rate 1: %.2f ml/min, Flow Rate 2: %.2f ml/min, Average Flow Rate: %.2f ml/min\n",
            timestamp, flow_rate1, flow_rate2, average_flow_rate);
    fflush(log_file);
}

// Function to set alarm
void set_alarm(int alarm_state) {
    gpioWrite(ALARM_GPIO, alarm_state);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for alarm
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start measurement
    if (start_measurement(i2c_handle1) != 0 || start_measurement(i2c_handle2) != 0) {
        fprintf(stderr, "Error starting measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Wait for 100ms
    gpioDelay(100000); // 100ms

    // Main loop
    while (!terminate) {
        float flow_rate1 = 0.0, flow_rate2 = 0.0;
        int valid_readings = 0;
        float sum_flow_rate = 0.0;

        // Read flow rate from sensor 1
        if (read_flow_rate(i2c_handle1, &flow_rate1) == 0) {
            sum_flow_rate += flow_rate1;
            valid_readings++;
        } else {
            fprintf(log_file, "Error reading sensor 1\n");
        }

        // Read flow rate from sensor 2
        if (read_flow_rate(i2c_handle2, &flow_rate2) == 0) {
            sum_flow_rate += flow_rate2;
            valid_readings++;
        } else {
            fprintf(log_file, "Error reading sensor 2\n");
        }

        // Calculate average flow rate
        float average_flow_rate = 0.0;
        if (valid_readings > 0) {
            average_flow_rate = sum_flow_rate / valid_readings;
        }

        // Log data
        log_data(flow_rate1, flow_rate2, average_flow_rate);

        // Set alarm
        if (average_flow_rate < ALARM_THRESHOLD) {
            set_alarm(1); // HIGH
        } else {
            set_alarm(0); // LOW
        }

        // Wait for 1 second
        gpioDelay(MEASUREMENT_INTERVAL_MS * 1000); // 1 second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();

    return 0;
}

