#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold the circular buffer data
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer obstacle_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void read_sensor(int gpio_pin, CircularBuffer *buffer);
void emit_alert();
void dump_buffer(const CircularBuffer *buffer);
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Read the sensor value and store it in the circular buffer
void read_sensor(int gpio_pin, CircularBuffer *buffer) {
    int sensor_value = gpioRead(gpio_pin);

    buffer->buffer[buffer->head] = sensor_value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }

    if (sensor_value == 0) {
        emit_alert();
    }
}

// Emit an alert message to stdout
void emit_alert() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("ALERT: Obstacle detected at %s\n", timestamp);
}

// Dump the contents of the circular buffer to stdout with timestamps
void dump_buffer(const CircularBuffer *buffer) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int i;

    printf("\n--- Obstacle Detection Log ---\n");
    for (i = 0; i < buffer->count; i++) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s: Sensor Value = %d\n", timestamp, buffer->buffer[i]);
    }
    printf("--- End of Log ---\n");
}

int main() {
    // Initialize the circular buffer
    init_circular_buffer(&obstacle_buffer);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Obstacle avoidance sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        read_sensor(GPIO_PIN, &obstacle_buffer);
        gpioDelay(50); // Sample every 50 milliseconds
    }

    // Dump the buffer before exiting
    dump_buffer(&obstacle_buffer);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

