#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18

// Define the stall log file name
#define STALL_LOG_FILE "stall_log.txt"

// Define the stall duration threshold (in seconds)
#define STALL_DURATION_THRESHOLD 2

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int validate_sensor_reading(int reading);
int check_stall(int sensor1_reading, int sensor2_reading);
int log_stall_event();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor readings
typedef struct {
    int sensor1;
    int sensor2;
} SensorReadings;

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);

    return 0; // Indicate success
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int reading = gpioRead(gpio_pin);
    return reading;
}

// Function to validate the sensor reading
int validate_sensor_reading(int reading) {
    if (reading == 0 || reading == 1) {
        return 0; // Valid reading
    } else {
        fprintf(stderr, "Invalid sensor reading: %d\n", reading);
        return 1; // Invalid reading
    }
}

// Function to check for a stall condition
int check_stall(int sensor1_reading, int sensor2_reading) {
    return (sensor1_reading == 0 && sensor2_reading == 0);
}

// Function to log a stall event to the log file
int log_stall_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1; // Failure
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(STALL_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", STALL_LOG_FILE);
        cleanup();
        return 1;
    }

    time_t stall_start_time = 0;
    int stall_detected = 0;

    printf("Monitoring conveyor belt for stalls...\n");

    while (running) {
        // Read sensor values
        int sensor1_reading = read_sensor(SENSOR_1_PIN);
        int sensor2_reading = read_sensor(SENSOR_2_PIN);

        // Validate sensor readings
        if (validate_sensor_reading(sensor1_reading) != 0 || validate_sensor_reading(sensor2_reading) != 0) {
            fprintf(stderr, "Invalid sensor reading, skipping stall check.\n");
            gpioDelay(100); // Small delay to avoid spamming the console
            continue;
        }

        // Check for stall condition
        if (check_stall(sensor1_reading, sensor2_reading)) {
            if (!stall_detected) {
                // Start the stall timer
                stall_start_time = time(NULL);
                stall_detected = 1;
            } else {
                // Check if the stall duration has exceeded the threshold
                time_t current_time = time(NULL);
                if (difftime(current_time, stall_start_time) >= STALL_DURATION_THRESHOLD) {
                    // Log the stall event
                    if (log_stall_event() != 0) {
                        fprintf(stderr, "Error logging stall event.\n");
                    }
                    stall_detected = 0; // Reset stall detection
                }
            }
        } else {
            // Reset stall detection if either sensor is HIGH
            stall_detected = 0;
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

