#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define INIT_RETRY_DELAY_SEC 60

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to log an alert message to stdout and flood_log.txt
void log_alert() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    printf("ALERT: Water detected at %s\n", buf);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s ALERT: Water detected\n", buf);
    fclose(fp);
}

// Function to log an error message to flood_log.txt
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s ERROR: %s\n", buf, message);
    fclose(fp);
}

int main() {
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pin
    if (initialize_gpio() != 0) {
        log_error("GPIO initialization failed. Exiting.");
        return 1;
    }

    printf("Water level monitoring daemon started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == PI_BAD_GPIO) {
            log_error("Failed to read sensor value.");
            gpioTerminate();
            sleep(INIT_RETRY_DELAY_SEC);
            if (initialize_gpio() != 0) {
                log_error("GPIO re-initialization failed. Exiting.");
                running = 0; // Exit the loop if re-initialization fails
            }
        } else {
            if (sensor_value == 1) {
                log_alert();
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    // Clean up and exit
    gpioTerminate();
    printf("Water level monitoring daemon stopped.\n");
    return 0;
}

