#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

// Global variables
static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulses);
void log_rpm(double rpm);
void signal_handler(int signal);

// Pulse counter function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data)
{
    if (level == PI_HIGH) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Calculate RPM function
double calculate_rpm(int pulses)
{
    return (double)pulses * 60.0;
}

// Log RPM function
void log_rpm(double rpm)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s %.2f\n", timestamp, rpm);
    printf("%s %.2f\n", timestamp, rpm);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate(); // Terminate pigpio

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(1000); // Wait for 1 second

        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = calculate_rpm(current_pulse_count);
        log_rpm(rpm);
    }

    return 0;
}

