#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the mutex and condition variable
pthread_mutex_t log_mutex;
pthread_cond_t log_cond;

// Define the log file pointer
FILE *log_file = NULL;

// Define the quadrature state
enum {
    STATE_00,
    STATE_01,
    STATE_11,
    STATE_10
} quadrature_state = STATE_00;

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void log_rotation_event(const char *direction);
void signal_handler(int signal);

// Structure to pass data to the ISR
typedef struct {
    int sensor_a_level;
    int sensor_b_level;
} sensor_data_t;

// Sensor A ISR function
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    sensor_data_t *data = (sensor_data_t *)user_data;
    data->sensor_a_level = level;

    int sensor_b_level = gpioRead(SENSOR_B_PIN);
    data->sensor_b_level = sensor_b_level;

    // Update quadrature state
    switch (quadrature_state) {
        case STATE_00:
            if (sensor_b_level == 1) {
                quadrature_state = STATE_01;
                log_rotation_event("clockwise");
            } else {
                quadrature_state = STATE_00;
            }
            break;
        case STATE_01:
            if (sensor_b_level == 0) {
                quadrature_state = STATE_00;
                log_rotation_event("counter-clockwise");
            } else {
                quadrature_state = STATE_01;
            }
            break;
        case STATE_11:
            if (sensor_b_level == 0) {
                quadrature_state = STATE_10;
                log_rotation_event("clockwise");
            } else {
                quadrature_state = STATE_11;
            }
            break;
        case STATE_10:
            if (sensor_b_level == 1) {
                quadrature_state = STATE_11;
                log_rotation_event("counter-clockwise");
            } else {
                quadrature_state = STATE_10;
            }
            break;
    }

    // Signal the main thread
    pthread_mutex_lock(&log_mutex);
    pthread_cond_signal(&log_cond);
    pthread_mutex_unlock(&log_mutex);
}

// Sensor B ISR function
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    sensor_data_t *data = (sensor_data_t *)user_data;
    data->sensor_b_level = level;

    int sensor_a_level = gpioRead(SENSOR_A_PIN);
    data->sensor_a_level = sensor_a_level;

    // Update quadrature state
    switch (quadrature_state) {
        case STATE_00:
            if (sensor_a_level == 1) {
                quadrature_state = STATE_10;
