#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_led(int state);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
    control_led(0); // Turn off the LED
    cleanup_gpio(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    syslog(LOG_INFO, "GPIO initialised successfully");
    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);
    if (sensor_value < 0) {
        syslog(LOG_ERR, "Error reading touch sensor");
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Control the LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    syslog(LOG_INFO, "GPIO terminated");
}

int main() {
    // Open syslog
    openlog("touch_sensor_led", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Program started");

    // Main loop
    while (program_running) {
        int sensor_state = read_touch_sensor();
        if (sensor_state == 1) {
            control_led(1); // Turn on LED
            syslog(LOG_INFO, "Touch detected, LED on");
        } else if (sensor_state == 0) {
            control_led(0); // Turn off LED
            syslog(LOG_INFO, "Touch released, LED off");
        } else {
            syslog(LOG_ERR, "Error reading sensor, skipping LED control");
        }

        gpioDelay(50); // Poll every 50 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    cleanup_gpio();
    closelog();
    return 0;
}

