#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO17 as input for the touch sensor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    // Set GPIO18 as output for the LED
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    // Initialize the LED to LOW
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED state
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    if (gpioWrite(LED_PIN, !current_level) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
    }
}

// Function to apply debounce
void debounce() {
    gpioDelay(DEBOUNCE_TIME * 1000); // Convert milliseconds to microseconds
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the touch sensor
        int touch_detected = read_touch_sensor();

        // If a touch is detected, toggle the LED and apply debounce
        if (touch_detected == 1) {
            toggle_led();
            debounce();
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1ms delay
    }

    // Clean up GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

