#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log events to the file
int log_event(const char *message) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to disk
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

int main() {
    int rain_detected = -1; // Initialize to an invalid state
    int current_state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state == 0 && rain_detected == 0) {
            // Do nothing, rain is still detected
        } else if (current_state == 1 && rain_detected == 1) {
            // Do nothing, no rain is still detected
        } else {
            if (current_state == 0) {
                if (log_event("Rain Detected") != 0) {
                    fprintf(stderr, "Error logging rain event.\n");
                }
            } else {
                if (log_event("No Rain") != 0) {
                    fprintf(stderr, "Error logging no rain event.\n");
                }
            }
            rain_detected = current_state;
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

