#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Log file name
#define LOG_FILE "shaft_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
SensorStates read_sensors();
int debounce(int pin);
int log_data(SensorStates states);
double calculate_rpm(double time_interval);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    return 0;
}

// Function to read the state of both sensors
SensorStates read_sensors() {
    SensorStates states;
    states.sensor1_state = debounce(SENSOR1_PIN);
    states.sensor2_state = debounce(SENSOR2_PIN);
    return states;
}

// Function to debounce a sensor reading
int debounce(int pin) {
    int i;
    int stable_count = 0;
    int current_state = gpioRead(pin);

    for (i = 0; i < 5; i++) {
        if (gpioRead(pin) == current_state) {
            stable_count++;
        }
        gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds
    }

    return (stable_count == 5) ? current_state : !current_state; // Return the stable state or the opposite if not stable
}

// Function to log the sensor data to a file
int log_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to calculate RPM based on the time interval between transitions
double calculate_rpm(double time_interval) {
    if (time_interval > 0) {
        return 60.0 / time_interval; // RPM = 60 / time_interval (in seconds)
    } else {
        return 0.0; // Avoid division by zero
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        running = 0;
    }
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    double start_time, end_time, time_interval;
    SensorStates current_states, previous_states;
    double rpm;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize previous states
    previous_states.sensor1_state = gpioRead(SENSOR1_PIN);
    previous_states.sensor2_state = gpioRead(SENSOR2_PIN);

    start_time = time_time();

    // Main loop
    while (running) {
        current_states = read_sensors();

        // Check for state changes
        if (current_states.sensor1_state != previous_states.sensor1_state ||
            current_states.sensor2_state != previous_states.sensor2_state) {

            end_time = time_time();
            time_interval = end_time - start_time;

            // Calculate RPM
            rpm = calculate_rpm(time_interval);
            printf("RPM: %.2f\n", rpm);

            // Log the data
            if (log_data(current_states) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            // Update previous states and start time
            previous_states = current_states;
            start_time = end_time;
        }

        gpioDelay(1000); // Delay for 1ms to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

