#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define HEART_RATE_REG 0x24 // Example register address
#define SPO2_REG 0x26       // Example register address
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;

// Function prototypes
int read_heart_rate();
int read_spo2();
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCtrl+C pressed. Exiting gracefully...\n");
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Function to read heart rate from the sensor
int read_heart_rate() {
    int heart_rate = -1; // Default to -1 in case of error
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, HEART_RATE_REG, buf, 2);
    if (result >= 0) {
        heart_rate = (buf[0] << 8) | buf[1]; // Assuming 16-bit data
    } else {
        fprintf(stderr, "Error reading heart rate: %d\n", result);
    }
    return heart_rate;
}

// Function to read SpO2 from the sensor
int read_spo2() {
    int spo2 = -1; // Default to -1 in case of error
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, SPO2_REG, buf, 2);
    if (result >= 0) {
        spo2 = (buf[0] << 8) | buf[1]; // Assuming 16-bit data
    } else {
        fprintf(stderr, "Error reading SpO2: %d\n", result);
    }
    return spo2;
}

// Function to log data to a file
int log_data(int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
    return 0;
}

int main() {
