#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define alarm activation time (in seconds)
#define ALARM_ACTIVATION_TIME 2

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
int check_tilt(int sensor1_value, int sensor2_value);
void log_event(const char *event_type);
void activate_alarm(int gpio_pin);
void deactivate_alarm(int gpio_pin);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to check for tilt
int check_tilt(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 1 || sensor2_value == 1) ? 1 : 0;
}

// Function to log events
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate alarm
void activate_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO HIGH
}

// Function to deactivate alarm
void deactivate_alarm(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    deactivate_alarm(ALARM_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int sensor1_value, sensor2_value, tilt_status, alarm_active = 0;
    time_t start_time = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor values
        sensor1_value = read_sensor(SENSOR_1_PIN);
        sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting.\n");
            break;
        }

        // Check for tilt
        tilt_status = check_tilt(sensor1_value, sensor2_value);

        if (tilt_status == 1 && !alarm_active) {
            // Tilt detected and alarm is not active
            if (start_time == 0) {
                // First tilt detected, log event and start timer
                log_event("Tilt Start");
                start_time = time(NULL);
            } else {
                // Check if alarm activation time has elapsed
                if (time(NULL) - start_time >= ALARM_ACTIVATION_TIME) {
                    // Activate alarm
                    activate_alarm(ALARM_PIN);
                    alarm_active = 1;
                    log_event("Threshold Exceeded");
                }
            }
        } else if (tilt_status == 0 && alarm_active) {
            // No tilt detected and alarm is active
            deactivate_alarm(ALARM_PIN);
            alarm_active = 0;
            log_event("Tilt End");
            start_time = 0; // Reset timer
        } else if (tilt_status == 0 && !alarm_active) {
            // No tilt detected and alarm is not active, reset timer
            start_time = 0;
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup (in case the loop exits due to an error)
    deactivate_alarm(ALARM_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

