#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x59
#define LED_GPIO 17
#define THRESHOLD 500
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LED_ON_TIME_S 1

// Sensor Registers
#define CTRL1 0x20
#define X_LSB 0x28
#define X_MSB 0x29
#define Y_LSB 0x2A
#define Y_MSB 0x2B
#define Z_LSB 0x2C
#define Z_MSB 0x2D

// Global Variables
static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function Prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
double calculate_euclidean_magnitude(sensor_data_t data);
void log_event(double magnitude);
void control_led(int on);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize Sensor
int initialize_sensor() {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, CTRL1, 0x01) == 0) { // Enable sensor
            return 0; // Success
        }
        fprintf(stderr, "Error initializing sensor, retrying...\n");
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Read Sensor Data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, X_LSB, buffer, 6) == 6) {
            data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
            data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
            data.z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return data;
        }
        fprintf(stderr, "Error reading sensor data, retrying...\n");
        gpioDelay(RETRY_DELAY_MS * 1000);
        retries--;
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    data.x = 0; data.y = 0; data.z = 0; // Return default values
    return data;
}

// Calculate Euclidean Magnitude
double calculate_euclidean_magnitude(sensor_data_t data) {
    return sqrt(pow(data.x, 2) + pow(data.y, 2) + pow(data.z, 2));
}

// Log Event
void log_event(double magnitude) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s, %.2f\n", timestamp, magnitude);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        double magnitude = calculate_euclidean_magnitude(data);

        if (magnitude > THRESHOLD) {
            log_event(magnitude);
            control_led(1); // Turn LED on
            gpioDelay(LED_ON_TIME_S * 1000000); // Delay in microseconds
            control_led(0); // Turn LED off
        }

        gpioDelay(100000); // Poll every 100ms (100000 microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    return 0;
}

