#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <gpiod.h>

// Define GPIO pins for the flame sensors
#define FLAME_SENSOR_1 2
#define FLAME_SENSOR_2 3
#define FLAME_SENSOR_3 4
#define FLAME_SENSOR_4 17
#define FLAME_SENSOR_5 27

// Define the log file path
#define LOG_FILE "/var/log/flame_events.log"

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int sensor_id;
    struct gpiod_line *line;
    int last_state;
} sensor_data_t;

// Global variables
static struct gpiod_chip *chip = NULL;
static sensor_data_t sensors[5];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(sensor_data_t *sensor);
int debounce(sensor_data_t *sensor);
int log_event(int sensor_id, int gpio_pin);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");

    // Release GPIO lines
    for (int i = 0; i < 5; i++) {
        if (sensors[i].line) {
            gpiod_line_release(sensors[i].line);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close syslog
    closelog();

    syslog(LOG_INFO, "Cleanup complete. Exiting.");
    exit(0);
}

// Initialize GPIO using gpiod
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip %s", GPIO_CHIP);
        return -1;
    }

    // Get GPIO lines
    for (int i = 0; i < 5; i++) {
        sensors[i].line = gpiod_chip_get_line(chip, sensors[i].gpio_pin);
        if (!sensors[i].line) {
            syslog(LOG_ERR, "Failed to get line for GPIO %d", sensors[i].gpio_pin);
            cleanup(); // Release already acquired resources before exiting
            return -1;
        }

        // Request GPIO line for input
        ret = gpiod_line_request_input(sensors[i].line, "flame_monitor");
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request line for GPIO %d", sensors[i].gpio_pin);
            cleanup(); // Release already acquired resources before exiting
            return -1;
        }

        // Initialize last state
        sensors[i].last_state = gpiod_line_get_value(sensors[i].line);
        if (sensors[i].last_state < 0) {
            syslog(LOG_ERR, "Failed to read initial value for GPIO %d", sensors[i].gpio_pin);
            cleanup(); // Release already acquired resources before exiting
            return -1;
        }
    }

    syslog(LOG_INFO, "GPIO initialization complete.");
    return 0;
}

// Read sensor value
int read_sensor(sensor_data_t *sensor) {
    int value = gpiod_line_get_value(sensor->line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read value for GPIO %d", sensor->gpio_pin);
        return -1;
    }
    return value;
}

// Debounce the sensor reading
int debounce(sensor_data_t *sensor) {
    int value = read_sensor(sensor);
    if (value < 0) {
        return -1; // Propagate error
    }

    struct timespec delay = {0, DEBOUNCE_TIME_MS * 1000000L}; // Convert ms to ns
    nanosleep(&delay, NULL);

    int debounced_value = read_sensor(sensor);
    if (debounced_value < 0) {
        return -1; // Propagate error
    }

    return debounced_value;
}

// Log flame event to file
int log_event(int sensor_id, int gpio_pin) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file %s", LOG_FILE);
        return -1;
    }

    // Acquire file lock
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file %s", LOG_FILE);
        fclose(fp);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, gpio_pin);
    fflush(fp);

    // Release file lock
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file %s", LOG_FILE);
    }

    fclose(fp);
    return 0;
}

int main(void) {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    // Initialize sensor data
    sensors[0].gpio_pin = FLAME_SENSOR_1;
    sensors[0].sensor_id = 1;
    sensors[1].gpio_pin = FLAME_SENSOR_2;
    sensors[1].sensor_id = 2;
    sensors[2].gpio_pin = FLAME_SENSOR_3;
    sensors[2].sensor_id = 3;
    sensors[3].gpio_pin = FLAME_SENSOR_4;
    sensors[3].sensor_id = 4;
    sensors[4].gpio_pin = FLAME_SENSOR_5;
    sensors[4].sensor_id = 5;

    syslog(LOG_INFO, "Flame monitor started.");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 5; i++) {
            int current_state = read_sensor(&sensors[i]);
            if (current_state < 0) {
                syslog(LOG_ERR, "Error reading sensor %d, continuing...", sensors[i].sensor_id);
                continue; // Continue to the next sensor
            }

            if (current_state == 0 && sensors[i].last_state == 1) {
                // Flame detected (HIGH to LOW transition)
                int debounced_state = debounce(&sensors[i]);
                if (debounced_state < 0) {
                    syslog(LOG_ERR, "Debounce failed for sensor %d, continuing...", sensors[i].sensor_id);
                    continue; // Continue to the next sensor
                }

                if (debounced_state == 0) {
                    // Confirmed flame detection
                    if (log_event(sensors[i].sensor_id, sensors[i].gpio_pin) != 0) {
                        syslog(LOG_ERR, "Failed to log event for sensor %d", sensors[i].sensor_id);
                    }
                }
            }

            sensors[i].last_state = current_state;
        }

        sleep(1); // Poll every 1 second
    }

    cleanup(); // Call cleanup before exiting
    return 0;
}

