#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 sensor outputs
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Structure to store the previous sensor states
int previous_states[8] = {0};

// Function prototypes
int initialize_gpio();
int read_sensor_state(int pin);
void log_sensor_event(int sensor_index, int pin, int state);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to continuously monitor the sensor states
    while (program_running) {
        for (int i = 0; i < num_sensors; i++) {
            int current_state = read_sensor_state(sensor_pins[i]);

            // Check if the sensor state has changed
            if (current_state != previous_states[i]) {
                log_sensor_event(i, sensor_pins[i], current_state);
                previous_states[i] = current_state;
            }
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Clean up GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize the pigpio library and set up the GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", gpioInitialise());
        return 1;
    }

    // Set each GPIO pin as an input
    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN); // Optional: Set pull-down resistor
    }

    return 0;
}

// Function to read the state of a single sensor pin
int read_sensor_state(int pin) {
    return gpioRead(pin);
}

// Function to log a sensor event to the console
void log_sensor_event(int sensor_index, int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get the current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    // Print the log message
    printf("%s Sensor %d (GPIO %d): %s\n", timestamp, sensor_index, pin, state ? "Touched" : "Released");
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

// Signal handler function to catch SIGINT and exit gracefully
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

