// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_veml7700();
int read_lux();
int map_lux_to_duty_cycle(int lux);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(int lux, int duty_cycle, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure VEML7700
int config_veml7700() {
    // Example configuration: Integration time = 100ms, Gain = 2x
    // Refer to the VEML7700 datasheet for the correct register and value
    char config_data[2];
    config_data[0] = 0x00; // Integration time and gain register
    config_data[1] = 0x02; // 0x02 = 100ms, 2x gain

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error configuring VEML7700: %d\n", result);
        return -1;
    }
    return 0;
}

// Read lux value from VEML7700
int read_lux() {
    char data[2];
    int result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading lux value: %d\n", result);
        return -1;
    }

    // Combine the two bytes to form the lux value
    int lux = (data[0] << 8) | data[1];
    return lux;
}

// Map lux value to PWM duty cycle
int map_lux_to_duty_cycle(int lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(GPIO_LED, duty_cycle);
    return 0;
}

// Log data to file
int log_data(int lux, int duty_cycle, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, lux, duty_cycle, error_code);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    set_pwm_duty_cycle(0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_data(0, 0, 1); // Error code 1: I2C initialization failed
        cleanup();
        return 1;
    }

    // Configure VEML7700
    if (config_veml7700() != 0) {
        log_data(0, 0, 2); // Error code 2: VEML7700 configuration failed
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Adaptive grow light system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value
        int lux = read_lux();
        if (lux < 0) {
            log_data(0, 0, 3); // Error code 3: Failed to read lux value
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Map lux to duty cycle
        int duty_cycle = map_lux_to_duty_cycle(lux);

        // Set PWM duty cycle
        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            log_data(lux, duty_cycle, 4); // Error code 4: Failed to set PWM duty cycle
        }

        // Log data
        log_data(lux, duty_cycle, 0); // No error

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

