#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for touch sensor channels
#define CHANNEL_1_GPIO 2
#define CHANNEL_2_GPIO 3
#define CHANNEL_3_GPIO 4
#define CHANNEL_4_GPIO 5
#define CHANNEL_5_GPIO 6
#define CHANNEL_6_GPIO 7
#define CHANNEL_7_GPIO 8
#define CHANNEL_8_GPIO 9

// Define GPIO pin for alert LED
#define ALERT_LED_GPIO 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int gpio_pin);
int debounce(int gpio_pin, int current_state);
void log_touch_event(int channel);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold previous sensor states
struct {
    int channel1;
    int channel2;
    int channel3;
    int channel4;
    int channel5;
    int channel6;
    int channel7;
    int channel8;
} previous_states = {0, 0, 0, 0, 0, 0, 0, 0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor values
        int channel1_state = read_touch_sensor(CHANNEL_1_GPIO);
        int channel2_state = read_touch_sensor(CHANNEL_2_GPIO);
        int channel3_state = read_touch_sensor(CHANNEL_3_GPIO);
        int channel4_state = read_touch_sensor(CHANNEL_4_GPIO);
        int channel5_state = read_touch_sensor(CHANNEL_5_GPIO);
        int channel6_state = read_touch_sensor(CHANNEL_6_GPIO);
        int channel7_state = read_touch_sensor(CHANNEL_7_GPIO);
        int channel8_state = read_touch_sensor(CHANNEL_8_GPIO);

        // Debounce and log events
        if (debounce(CHANNEL_1_GPIO, channel1_state) != previous_states.channel1) {
            log_touch_event(1);
            previous_states.channel1 = debounce(CHANNEL_1_GPIO, channel1_state);
        }
        if (debounce(CHANNEL_2_GPIO, channel2_state) != previous_states.channel2) {
            log_touch_event(2);
            previous_states.channel2 = debounce(CHANNEL_2_GPIO, channel2_state);
        }
        if (debounce(CHANNEL_3_GPIO, channel3_state) != previous_states.channel3) {
            log_touch_event(3);
            previous_states.channel3 = debounce(CHANNEL_3_GPIO, channel3_state);
        }
        if (debounce(CHANNEL_4_GPIO, channel4_state) != previous_states.channel4) {
            log_touch_event(4);
            previous_states.channel4 = debounce(CHANNEL_4_GPIO, channel4_state);
        }
        if (debounce(CHANNEL_5_GPIO, channel5_state) != previous_states.channel5) {
            log_touch_event(5);
            previous_states.channel5 = debounce(CHANNEL_5_GPIO, channel5_state);
        }
        if (debounce(CHANNEL_6_GPIO, channel6_state) != previous_states.channel6) {
            log_touch_event(6);
            previous_states.channel6 = debounce(CHANNEL_6_GPIO, channel6_state);
        }
        if (debounce(CHANNEL_7_GPIO, channel7_state) != previous_states.channel7) {
            log_touch_event(7);
            previous_states.channel7 = debounce(CHANNEL_7_GPIO, channel7_state);
        }
        if (debounce(CHANNEL_8_GPIO, channel8_state) != previous_states.channel8) {
            log_touch_event(8);
            previous_states.channel8 = debounce(CHANNEL_8_GPIO, channel8_state);
        }

        // Control LED based on any touched channel
        int any_channel_touched = (channel1_state || channel2_state || channel3_state || channel4_state ||
                                   channel5_state || channel6_state || channel7_state || channel8_state);
        control_led(any_channel_touched);

        // Delay
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor channels as inputs with pull-down resistors
    gpioSetMode(CHANNEL_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_1_GPIO, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_2_GPIO, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_3_GPIO, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_3_GPIO, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_4_GPIO, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_4_GPIO, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_5_GPIO, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_5_GPIO, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_6_GPIO, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_6_GPIO, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_7_GPIO, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_7_GPIO, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_8_GPIO, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_8_GPIO, PI_PUD_DOWN);

    // Set alert LED as output
    gpioSetMode(ALERT_LED_GPIO, PI_OUTPUT);

    return 0;
}

// Read touch sensor value
int read_touch_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Debounce touch sensor
int debounce(int gpio_pin, int current_state) {
    int stable_count = 0;
    for (int i = 0; i < 5; i++) {
        if (gpioRead(gpio_pin) == current_state) {
            stable_count++;
        }
        gpioDelay(10000); // 10ms delay
    }
    return (stable_count == 5) ? current_state : !current_state; // Return the stable state
}

// Log touch event to file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s - Channel %d Touched\n", timestamp, channel);
}

// Control alert LED
void control_led(int state) {
    gpioWrite(ALERT_LED_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources.\n");
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
}

