#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_opt3001();
int read_opt3001(float *lux);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for configuration
typedef struct {
    uint16_t config_value;
} opt3001_config_t;

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// OPT3001 initialization function
int init_opt3001() {
    // Configuration value: Continuous conversion mode, 100ms conversion time, 100ms conversion time
    uint16_t config_value = 0xC810; // Continuous mode, 100ms conversion time
    uint8_t buf[2];

    buf[0] = (config_value >> 8) & 0xFF; // MSB
    buf[1] = config_value & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write configuration to OPT3001: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read data from OPT3001
int read_opt3001(float *lux) {
    uint8_t buf[2];
    uint16_t raw_data;

    int result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data from OPT3001: %d\n", result);
        return -1;
    }

    // Byte swap
    raw_data = (buf[1] << 8) | buf[0];

    // Extract exponent and result
    int exponent = (raw_data >> 12) & 0x0F;
    int result_raw = raw_data & 0x0FFF;

    // Calculate lux value
    *lux = 0.01 * pow(2, exponent) * result_raw;

    return 0;
}

// Function to log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    printf("%s, %.2f\n", timestamp, lux);

    fflush(log_file);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Initialize OPT3001
    if (init_opt3001() != 0) {
        fprintf(stderr, "OPT3001 initialization failed, exiting\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    float lux;

    // Main loop
    while (!terminate) {
        if (read_opt3001(&lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read OPT3001 data\n");
        }

        gpioDelay(1000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

