    struct tm *timeinfo;
    char *timestamp = (char*)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log flame detection event to file
void log_flame_event(const char* timestamp) {
    FILE *fp = fopen("flame_events.txt", "a");
    if (fp == NULL) {
        perror("Error opening flame_events.txt");
        return;
    }
    fprintf(fp, "%s - Flame detected!\n", timestamp);
    fclose(fp);
}

// Function to print flame detection event to stdout
void print_flame_event(const char* timestamp) {
    printf("%s - Flame detected!\n", timestamp);
}

