void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected (flame detected)
        char* timestamp = get_timestamp();
        if (timestamp != NULL) {
            log_flame_event(timestamp);
            print_flame_event(timestamp);
            free(timestamp); // Free the allocated memory
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    }
}

