#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip
#define GPIO_CHIP "gpiochip4"

// Define log file name
#define LOG_FILE "touch_log.txt"

// Global variables
static int led_state = 0; // 0 = off, 1 = on
static int log_fd = -1;
static int gpio_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int log_event(const char *event, int led_state);
void signal_handler(int sig);

// GPIO functions
int gpio_export(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

int gpio_write(int pin, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) != strlen(value_str)) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Logging function
int log_event(const char *event, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_fd != -1) {
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "%s - %s - LED: %s\n", timestamp, event, led_state ? "ON" : "OFF");
        if (write(log_fd, log_message, strlen(log_message)) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            return -1;
        }
    } else {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal %d received, terminating...\n", sig);
    terminate = 1;
}

int main() {
    struct gpio_line_request req;
    struct gpio_event_value event;
    int ret;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Export GPIO pins
    if (gpio_export(TOUCH_SENSOR_PIN) < 0 || gpio_export(LED_PIN) < 0) {
        fprintf(stderr, "Error exporting GPIO pins.\n");
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO directions
    if (gpio_set_direction(TOUCH_SENSOR_PIN, "in") < 0 || gpio_set_direction(LED_PIN, "out") < 0) {
        fprintf(stderr, "Error setting GPIO directions.\n");
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_PIN);
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_fd = open("/dev/gpiochip4", O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_PIN);
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line for touch sensor
    memset(&req, 0, sizeof(req));
    req.line = TOUCH_SENSOR_PIN;
    req.consumer = "touch_sensor";
    req.request_type = GPIOLINE_REQUEST_EVENT_RISING_EDGE;

    if (ioctl(gpio_fd, GPIO_GET_LINE_REQUEST, &req) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        close(gpio_fd);
        gpio_unexport(TOUCH_SENSOR_PIN);
        gpio_unexport(LED_SENSOR_PIN);
        close(log_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read touch sensor
        int touch_value = gpio_read(TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Error reading touch sensor.\n");
            break;
        }

        // Check for rising edge
        if (touch_value == 1) {
            // Toggle LED state
            led_state = !led_state;

            // Write LED state to GPIO
            if (gpio_write(LED_PIN, led_state) < 0) {
                fprintf(stderr, "Error writing to LED.\n");
                break;
            }

            // Log event
            if (log_event("Touch detected", led_state) < 0) {
                fprintf(stderr, "Error logging event.\n");
                break;
            }

            // Wait for a short period to avoid multiple triggers
            usleep(500000); // 0.5 seconds
        }

        // Poll for GPIO event
        ret = read(gpio_fd, &event, sizeof(event));
        if (ret < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
                break;
            }
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (gpio_fd != -1) {
        close(gpio_fd);
    }
    gpio_unexport(TOUCH_SENSOR_PIN);
    gpio_unexport(LED_PIN);
    if (log_fd != -1) {
        close(log_fd);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

