#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define log file name
#define LOG_FILE "alert_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize();
void cleanup();
void log_message(const char *message);
void buzzer_on();
void buzzer_off();
void flame_detected_handler();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the system
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Log system started message
    log_message("System started");

    return 0;
}

// Function to cleanup resources
void cleanup() {
    // Turn off buzzer
    buzzer_off();

    // Close log file
    if (log_file != NULL) {
        log_message("System stopped");
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();
}

// Function to log a message to the log file
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written immediately
    }
}

// Function to turn the buzzer on
void buzzer_on() {
    gpioWrite(BUZZER_PIN, 1);
}

// Function to turn the buzzer off
void buzzer_off() {
    gpioWrite(BUZZER_PIN, 0);
}

// Function to handle flame detection
void flame_detected_handler() {
    log_message("FLAME DETECTED");
    buzzer_on();
    gpioDelay(2000000); // 2 seconds
    buzzer_off();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        return 1;
    }

    int last_state = gpioRead(FLAME_SENSOR_PIN);

    // Main loop
    while (running) {
        int current_state = gpioRead(FLAME_SENSOR_PIN);

        if (current_state != last_state) {
            if (current_state == 0) { // Flame detected (LOW signal)
                flame_detected_handler();
            }
            last_state = current_state;
        }

        gpioDelay(100000); // 100 milliseconds
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

