int read_sensor(int gpio_pin);
int log_event(int sensor_id, int state);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int initial_state;
    int current_state;
} sensor_data_t;

// Array of sensor data structures
sensor_data_t sensors[] = {
    {SENSOR1_GPIO, -1, -1},
    {SENSOR2_GPIO, -1, -1},
    {SENSOR3_GPIO, -1, -1}
};

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Read initial states of the sensors
    for (int i = 0; i < sizeof(sensors) / sizeof(sensors[0]); i++) {
        sensors[i].initial_state = read_sensor(sensors[i].gpio_pin);
        if (sensors[i].initial_state == -1) {
            fprintf(stderr, "Error reading sensor %d\n", i + 1);
            running = 0; // Stop the main loop if there's an error
            break;
        }
        sensors[i].current_state = sensors[i].initial_state;
    }

    // Main loop
    while (running) {
        for (int i = 0; i < sizeof(sensors) / sizeof(sensors[0]); i++) {
            int new_state = read_sensor(sensors[i].gpio_pin);
            if (new_state != -1) {
                if (new_state != sensors[i].current_state) {
                    log_event(i + 1, new_state);
                    sensors[i].current_state = new_state;
                }
            } else {
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
            }
        }
        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup and exit
    fclose(log_file);
    gpioTerminate();
    return 0;
}

