    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", SENSOR3_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up on GPIO %d\n", SENSOR3_GPIO);
        return -1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1;
    }
    return state;
}

// Function to log an event to the log file
int log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, state == 0 ? "Magnet Present" : "Magnet Removed");
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the main loop
}

