#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HR_REG 0x24
#define CONFIG_REG 0x02
#define MOVING_AVG_SIZE 5
#define MIN_BPM 30
#define MAX_BPM 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int raw_hr;
    int filtered_hr;
    int bpm;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *raw_hr);
int apply_moving_average(int *data, int size, int new_value);
int validate_bpm(int bpm);
void log_data(int bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1182 sensor
int initialize_sensor() {
    int part_id, hw_rev;

    // Read PART_ID
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    // Read HW_REV
    hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X (expected 0x01)\n", hw_rev);
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONFIG_REG\n");
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read raw heart rate data from the sensor
int read_sensor_data(int *raw_hr) {
    int retries = 3;
    int hr;

    while (retries > 0) {
        hr = i2cReadByteData(i2c_handle, HR_REG);
        if (hr >= 0) {
            *raw_hr = hr;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error, retrying... (%d retries left)\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to apply a moving average filter
int apply_moving_average(int *data, int size, int new_value) {
    int sum = 0;
    for (int i = 0; i < size - 1; i++) {
        data[i] = data[i + 1];
        sum += data[i];
    }
    data[size - 1] = new_value;
    sum += new_value;
    return sum / size;
}

// Function to validate the BPM value
int validate_bpm(int bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM) ? 1 : 0;
}

// Function to log the data to a file
void log_data(int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file);
}

int main() {
    int raw_hr, filtered_hr, bpm;
    int hr_data[MOVING_AVG_SIZE] = {0}; // Initialize moving average buffer
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_hr) == 0) {
            // Apply moving average filter
            filtered_hr = apply_moving_average(hr_data, MOVING_AVG_SIZE, raw_hr);

            // Calculate BPM (example calculation, adjust as needed)
            bpm = filtered_hr * 60; // Example: raw value * 60 = BPM

            // Validate BPM
            if (validate_bpm(bpm)) {
                // Log the data
                log_data(bpm);
                printf("BPM: %d\n", bpm);
            } else {
                fprintf(stderr, "Invalid BPM value: %d\n", bpm);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

