            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error, retrying... (%d retries left)\n", retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to apply a moving average filter
int apply_moving_average(int *data, int size, int new_value) {
    int sum = 0;
    for (int i = 0; i < size - 1; i++) {
        data[i] = data[i + 1];
        sum += data[i];
    }
    data[size - 1] = new_value;
    sum += new_value;
    return sum / size;
}

// Function to validate the BPM value
int validate_bpm(int bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM) ? 1 : 0;
}

// Function to log the data to a file
void log_data(int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file);
}

int main() {
    int raw_hr, filtered_hr, bpm;
    int hr_data[MOVING_AVG_SIZE] = {0}; // Initialize moving average buffer
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
