    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_hr) == 0) {
            // Apply moving average filter
            filtered_hr = apply_moving_average(hr_data, MOVING_AVG_SIZE, raw_hr);

            // Calculate BPM (example calculation, adjust as needed)
            bpm = filtered_hr * 60; // Example: raw value * 60 = BPM

            // Validate BPM
            if (validate_bpm(bpm)) {
                // Log the data
                log_data(bpm);
                printf("BPM: %d\n", bpm);
            } else {
                fprintf(stderr, "Invalid BPM value: %d\n", bpm);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
