#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log flame detection event
void log_flame_detection() {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int last_state = 1; // Assume no flame initially (HIGH)
    int current_state;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state == 0 && last_state == 1) {
            // Flame detected (LOW to HIGH transition)
            printf("FLAME DETECTED\n");
            log_flame_detection();
            // Debounce: Wait for a short period to avoid multiple triggers
            gpioDelay(50000); // 50ms
        }

        last_state = current_state;
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

