#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for touch sensor channels
#define TOUCH_CHANNEL_1 5
#define TOUCH_CHANNEL_2 6
#define TOUCH_CHANNEL_3 7
#define TOUCH_CHANNEL_4 8
#define TOUCH_CHANNEL_5 9
#define TOUCH_CHANNEL_6 10
#define TOUCH_CHANNEL_7 11
#define TOUCH_CHANNEL_8 12

// Define GPIO pins for counter output
#define COUNTER_BIT_0 17
#define COUNTER_BIT_1 18
#define COUNTER_BIT_2 19
#define COUNTER_BIT_3 20
#define COUNTER_BIT_4 21
#define COUNTER_BIT_5 22
#define COUNTER_BIT_6 23
#define COUNTER_BIT_7 24

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_lines[8] = {NULL};
static struct gpiod_line *counter_lines[8] = {NULL};
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
int read_touch_sensor(int channel);
void update_counter(int counter_value);
void log_touch_event(int channel, int counter_value);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Initialize GPIO lines
int init_gpio(void)
{
    int i;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get touch sensor lines
    int touch_pins[] = {TOUCH_CHANNEL_1, TOUCH_CHANNEL_2, TOUCH_CHANNEL_3, TOUCH_CHANNEL_4, TOUCH_CHANNEL_5, TOUCH_CHANNEL_6, TOUCH_CHANNEL_7, TOUCH_CHANNEL_8};
    for (i = 0; i < 8; i++) {
        touch_lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (!touch_lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", touch_pins[i], strerror(errno));
            goto cleanup_lines;
        }

        ret = gpiod_line_request_input(touch_lines[i], "touch_counter");
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", touch_pins[i], strerror(errno));
            goto cleanup_lines;
        }
    }

    // Get counter output lines
    int counter_pins[] = {COUNTER_BIT_0, COUNTER_BIT_1, COUNTER_BIT_2, COUNTER_BIT_3, COUNTER_BIT_4, COUNTER_BIT_5, COUNTER_BIT_6, COUNTER_BIT_7};
    for (i = 0; i < 8; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!counter_lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", counter_pins[i], strerror(errno));
            goto cleanup_lines;
        }

        ret = gpiod_line_request_output(counter_lines[i], "touch_counter", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d as output: %s\n", counter_pins[i], strerror(errno));
            goto cleanup_lines;
        }
    }

    return 0;

cleanup_lines:
    for (i = 0; i < 8; i++) {
        if (touch_lines[i]) {
            gpiod_line_release(touch_lines[i]);
        }
        if (counter_lines[i]) {
            gpiod_line_release(counter_lines[i]);
        }
    }
    gpiod_chip_close(chip);
    return -1;
}

// Cleanup GPIO lines
void cleanup_gpio(void)
{
    int i;

    // Release counter output lines
    for (i = 0; i < 8; i++) {
        if (counter_lines[i]) {
            gpiod_line_set_value(counter_lines[i], 0);
            gpiod_line_release(counter_lines[i]);
        }
    }

    // Release touch sensor lines
    for (i = 0; i < 8; i++) {
        if (touch_lines[i]) {
            gpiod_line_release(touch_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Read touch sensor value
int read_touch_sensor(int channel)
{
    int value;
    int ret;

    if (channel < 1 || channel > 8) {
        fprintf(stderr, "Error: Invalid touch sensor channel %d\n", channel);
        return -1;
    }

    ret = gpiod_line_get_value(touch_lines[channel - 1]);
    if (ret < 0) {
        fprintf(stderr, "Error reading line %d: %s\n", channel, strerror(errno));
        return -1;
    }

    value = ret;
    return value;
}

// Update counter output
void update_counter(int counter_value)
{
    int i;
    int bit;

    for (i = 0; i < 8; i++) {
        bit = (counter_value >> i) & 1;
        if (gpiod_line_set_value(counter_lines[i], bit) < 0) {
            fprintf(stderr, "Error setting line %d to %d: %s\n", i, bit, strerror(errno));
        }
    }
}

// Log touch event
void log_touch_event(int channel, int counter_value)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Warning: Log file not opened.  Logging to stderr.\n");
        fprintf(stderr, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter_value);
}

int main(void)
{
    int counter = 0;
    int i;
    int touch_value;
    int ret;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Warning: Failed to open log file: %s\n", strerror(errno));
    }

    // Stabilization delay
    usleep(200000); // 200ms

    // Main loop
    while (!terminate) {
        for (i = 0; i < 8; i++) {
            touch_value = read_touch_sensor(i + 1);
            if (touch_value == 1) {
                counter = (counter + 1) % 256;
                update_counter(counter);
                log_touch_event(i + 1, counter);
                // Debounce delay
                usleep(50000); // 50ms
            } else if (touch_value < 0) {
                fprintf(stderr, "Error reading touch sensor %d, skipping.\n", i + 1);
            }
        }
        usleep(10000); // 10ms
    }

    // Cleanup and exit
    cleanup_gpio();

    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

