#include <pigpio.h>

// Define GPIO pins for the tilt sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor state and last event time
typedef struct {
    int last_state;
    unsigned long last_event_time;
} sensor_state_t;

static sensor_state_t sensor1_state = {1, 0};
static sensor_state_t sensor2_state = {1, 0};

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int debounce(int gpio, int current_state, unsigned long *last_event_time);
int log_event(int sensor_number);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);

    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce the sensor readings
int debounce(int gpio, int current_state, unsigned long *last_event_time) {
    unsigned long now = gpioTick();
    if (now - *last_event_time > DEBOUNCE_TIME * 1000) {
        *last_event_time = now;
        return current_state;
    } else {
        return !current_state; // Invert the state during debounce
    }
}

// Function to log a tilt event to the log file
int log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file); // Ensure the data is written to the file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int debounced_sensor1_value = debounce(SENSOR_1_GPIO, sensor1_value, &sensor1_state.last_event_time);

        int sensor2_value = read_sensor(SENSOR_2_GPIO);
        int debounced_sensor2_value = debounce(SENSOR_2_GPIO, sensor2_value, &sensor2_state.last_event_time);

        if (sensor1_value != sensor1_state.last_state && debounced_sensor1_value == 0) {
            log_event(1);
            sensor1_state.last_state = sensor1_value;
        }

        if (sensor2_value != sensor2_state.last_state && debounced_sensor2_value == 0) {
            log_event(2);
            sensor2_state.last_state = sensor2_value;
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Clean up resources before exiting
    cleanup();

    return 0;
}

