#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MICROPHONE_PIN 4
#define LED_PIN 17

// Define sampling rate and LED duration
#define SAMPLING_RATE 8000
#define LED_DURATION_MS 100

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping program...\n", signal);
}

// Function to get current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MICROPHONE_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Sample microphone pin
        int microphone_value = gpioRead(MICROPHONE_PIN);

        // Check for errors
        if (microphone_value < 0) {
            fprintf(stderr, "Error reading microphone pin: %d\n", microphone_value);
            break; // Exit loop on error
        }

        // Detect sound peak (HIGH signal)
        if (microphone_value == 1) {
            // Get timestamp
            long long timestamp = get_timestamp_ms();

            // Print timestamp to stdout
            printf("%lld\n", timestamp);

            // Turn on LED
            gpioWrite(LED_PIN, 1);

            // Wait for LED duration
            gpioDelay(LED_DURATION_MS * 1000); // Convert ms to us

            // Turn off LED
            gpioWrite(LED_PIN, 0);
        }

        // Delay to achieve desired sampling rate
        gpioDelay(125); // 125 us delay
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio

    return 0;
}

