        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log sensor data
    while (program_running) {
        int left_sensor_state = read_sensor(LEFT_SENSOR_PIN);
        int center_sensor_state = read_sensor(CENTER_SENSOR_PIN);
        int right_sensor_state = read_sensor(RIGHT_SENSOR_PIN);

        if (left_sensor_state == -1 || center_sensor_state == -1 || right_sensor_state == -1) {
            // Handle read errors (e.g., retry or exit)
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit the loop
        }

        // Log the sensor states to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_sensor_state, center_sensor_state, right_sensor_state);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

