#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_ALS_DATA_LSB 0x22
#define SI1175_REG_ALS_DATA_MSB 0x23

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read ALS data from Si1175
int read_als_data(int i2c_handle) {
    int lsb, msb;

    // Read LSB
    lsb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_DATA_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading ALS LSB: %d\n", lsb);
        return -1;
    }

    // Read MSB
    msb = i2cReadByteData(i2c_handle, SI1175_REG_ALS_DATA_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading ALS MSB: %d\n", msb);
        return -1;
    }

    // Combine LSB and MSB into 16-bit value
    return (msb << 8) | lsb;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int als_value = read_als_data(i2c_handle);
        if (als_value >= 0) {
            printf("ALS Value: %d\n", als_value);
        } else {
            fprintf(stderr, "Failed to read ALS data.\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

