#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for each touch sensor channel
#define TP1_PIN 5
#define TP2_PIN 6
#define TP3_PIN 13
#define TP4_PIN 19
#define TP5_PIN 26
#define TP6_PIN 12
#define TP7_PIN 16
#define TP8_PIN 20

// Structure to hold the state of the touch sensor channels
typedef struct {
    int tp1;
    int tp2;
    int tp3;
    int tp4;
    int tp5;
    int tp6;
    int tp7;
    int tp8;
} touch_state_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a single touch sensor channel
int read_touch_channel(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to read the state of all touch sensor channels
touch_state_t read_touch_sensors() {
    touch_state_t state;
    state.tp1 = read_touch_channel(TP1_PIN);
    state.tp2 = read_touch_channel(TP2_PIN);
    state.tp3 = read_touch_channel(TP3_PIN);
    state.tp4 = read_touch_channel(TP4_PIN);
    state.tp5 = read_touch_channel(TP5_PIN);
    state.tp6 = read_touch_channel(TP6_PIN);
    state.tp7 = read_touch_channel(TP7_PIN);
    state.tp8 = read_touch_channel(TP8_PIN);
    return state;
}

// Function to format the touch sensor data into a string
char* format_touch_data(touch_state_t state) {
    static char buffer[256]; // Static buffer to hold the formatted string
    snprintf(buffer, sizeof(buffer), "CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
             state.tp1, state.tp2, state.tp3, state.tp4, state.tp5, state.tp6, state.tp7, state.tp8);
    return buffer;
}

// Function to get the current timestamp in seconds
double get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(TP1_PIN, PI_INPUT);
    gpioSetMode(TP2_PIN, PI_INPUT);
    gpioSetMode(TP3_PIN, PI_INPUT);
    gpioSetMode(TP4_PIN, PI_INPUT);
    gpioSetMode(TP5_PIN, PI_INPUT);
    gpioSetMode(TP6_PIN, PI_INPUT);
    gpioSetMode(TP7_PIN, PI_INPUT);
    gpioSetMode(TP8_PIN, PI_INPUT);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read the state of the touch sensors
        touch_state_t state = read_touch_sensors();

        // Format the touch sensor data
        char* formatted_data = format_touch_data(state);

        // Get the current timestamp
        double timestamp = get_timestamp();

        // Print the timestamp and touch sensor data to the console
        printf("[%.3fs] %s\n", timestamp, formatted_data);

        // Wait for 200 milliseconds
        gpioDelay(200000); // 200 ms = 200000 us
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

