    return buffer;
}

// Function to get the current timestamp in seconds
double get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(TP1_PIN, PI_INPUT);
    gpioSetMode(TP2_PIN, PI_INPUT);
    gpioSetMode(TP3_PIN, PI_INPUT);
    gpioSetMode(TP4_PIN, PI_INPUT);
    gpioSetMode(TP5_PIN, PI_INPUT);
    gpioSetMode(TP6_PIN, PI_INPUT);
    gpioSetMode(TP7_PIN, PI_INPUT);
    gpioSetMode(TP8_PIN, PI_INPUT);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read the state of the touch sensors
        touch_state_t state = read_touch_sensors();

