typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Function prototypes
RGBColor generateRandomColor();
RGBColor interpolateColor(RGBColor start, RGBColor end, float fraction);
int setRGBColor(int red, int green, int blue);
float readLightLevel();
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to generate a random RGB color
RGBColor generateRandomColor() {
    RGBColor color;
    color.red = rand() % 256;
    color.green = rand() % 256;
    color.blue = rand() % 256;
    return color;
}

// Function to interpolate between two RGB colors
RGBColor interpolateColor(RGBColor start, RGBColor end, float fraction) {
    RGBColor interpolatedColor;
    interpolatedColor.red = start.red + (int)((end.red - start.red) * fraction);
    interpolatedColor.green = start.green + (int)((end.green - start.green) * fraction);
    interpolatedColor.blue = start.blue + (int)((end.blue - start.blue) * fraction);

    // Clamp values to 0-255 range
    if (interpolatedColor.red < 0) interpolatedColor.red = 0;
    if (interpolatedColor.red > 255) interpolatedColor.red = 255;
    if (interpolatedColor.green < 0) interpolatedColor.green = 0;
    if (interpolatedColor.green > 255) interpolatedColor.green = 255;
    if (interpolatedColor.blue < 0) interpolatedColor.blue = 0;
    if (interpolatedColor.blue > 255) interpolatedColor.blue = 255;

    return interpolatedColor;
}

// Function to set the RGB color using pigpio
int setRGBColor(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, 255 - red) != 0) {
        syslog(LOG_ERR, "Failed to set red PWM: %s", strerror(errno));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, 255 - green) != 0) {
        syslog(LOG_ERR, "Failed to set green PWM: %s", strerror(errno));
        return -1;
    }
    if (gpioPWM(BLUE_PIN, 255 - blue) != 0) {
        syslog(LOG_ERR, "Failed to set blue PWM: %s", strerror(errno));
        return -1;
    }
    return 0;
}

