float readLightLevel() {
    unsigned char buf[2];
    int result;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-resolution mode
    if (write(i2c_fd, buf, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        return -1.0;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
        return -1.0;
    }

    // Convert data to lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

