    // Initialize syslog
    openlog("rgb_lighting", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with /dev/urandom
    int urandom_fd = open("/dev/urandom", O_RDONLY);
    if (urandom_fd == -1) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %s", strerror(errno));
        closelog();
        return 1;
    }
    unsigned char seed[4];
    if (read(urandom_fd, seed, sizeof(seed)) != sizeof(seed)) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom: %s", strerror(errno));
        close(urandom_fd);
        closelog();
        return 1;
    }
    close(urandom_fd);
    unsigned int seed_value = (seed[0] << 24) | (seed[1] << 16) | (seed[2] << 8) | seed[3];
    srand(seed_value);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

