        syslog(LOG_ERR, "Failed to set initial RGB color");
        close(i2c_fd);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Generate a new target color
        targetColor = generateRandomColor();

        // Read light level
        lightLevel = readLightLevel();
        if (lightLevel < 0) {
            syslog(LOG_ERR, "Failed to read light level");
            // Continue even if light level reading fails
        }

        // Adjust target color based on light level (example: higher light level -> darker color)
        if (lightLevel > 0) {
            targetColor.red = targetColor.red * (1.0 - (lightLevel / 1000.0)); // Example scaling
            targetColor.green = targetColor.green * (1.0 - (lightLevel / 1000.0));
            targetColor.blue = targetColor.blue * (1.0 - (lightLevel / 1000.0));

            // Clamp values to 0-255 range
            if (targetColor.red < 0) targetColor.red = 0;
            if (targetColor.red > 255) targetColor.red = 255;
            if (targetColor.green < 0) targetColor.green = 0;
            if (targetColor.green > 255) targetColor.green = 255;
            if (targetColor.blue < 0) targetColor.blue = 0;
            if (targetColor.blue > 255) targetColor.blue = 255;
        }

        // Linear interpolation over 5 seconds
        for (i = 0; i <= 50; i++) {
            fraction = (float)i / 50.0;
            RGBColor interpolatedColor = interpolateColor(currentColor, targetColor, fraction);

            if (setRGBColor(interpolatedColor.red, interpolatedColor.green, interpolatedColor.blue) != 0) {
                syslog(LOG_ERR, "Failed to set RGB color during interpolation");
                terminate = 1; // Exit loop on error
                break;
            }

            usleep(100000); // 100ms delay
        }

        // Update current color
        currentColor = targetColor;
    }

    // Turn off the LED
    setRGBColor(0, 0, 0);

    // Close I2C device
    close(i2c_fd);

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

