#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_PON             (0x01)
#define TCS34725_AEN             (0x02)

// Integration Time Values
#define TCS34725_INTEGRATIONTIME_154MS  (0xD5)

// GPIO Pin for LED
#define LED_PIN                  (17)

// Threshold for Red Value
#define RED_THRESHOLD            (200)

// I2C Bus
#define I2C_BUS                  ("/dev/i2c-1")

// Global Variables
static int i2c_fd = -1;
static volatile int running = 1;

// Function Prototypes
int tcs34725_init();
int tcs34725_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// TCS34725 Initialization
int tcs34725_init() {
    uint8_t buf[2];
    int ret;

    // Enable power and RGBC
    buf[0] = TCS34725_ENABLE;
    buf[1] = TCS34725_PON | TCS34725_AEN;
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time
    buf[0] = TCS34725_ATIME;
    buf[1] = TCS34725_INTEGRATIONTIME_154MS;
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Set gain (default is 4x)
    buf[0] = TCS34725_CONTROL;
    buf[1] = 0x00; // Gain = 1x
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// TCS34725 Read Data
int tcs34725_read_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t buf[1];
    uint8_t data[8];
    int ret;

    // Read clear data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_CDATA;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    ret = read(i2c_fd, data, 8);
    if (ret != 8) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *clear = (data[1] << 8) | data[0];
    *red   = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue  = (data[7] << 8) | data[6];

    return 0;
}

int main() {
    uint16_t red, green, blue, clear;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read color data
        if (tcs34725_read_data(&red, &green, &blue, &clear) == 0) {
            // Print color data
            printf("Red: %5u, Green: %5u, Blue: %5u, Clear: %5u\n", red, green, blue, clear);

            // Control LED based on red value
            if (red > RED_THRESHOLD) {
                gpioWrite(LED_PIN, 1); // Turn LED on
            } else {
                gpioWrite(LED_PIN, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading TCS34725 data, re-initializing...\n");
            // Attempt to re-initialize the sensor
            if (tcs34725_init() != 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                running = 0; // Exit loop if re-initialization fails
            }
        }

        // Wait 200ms
        usleep(200000); // 200ms = 200000 microseconds
    }

    // Cleanup
    close(i2c_fd);
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

