#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x23
#define WS2812B_GPIO 18
#define NUM_LEDS 10
#define PWM_FREQUENCY 800000 // 800 kHz
#define PWM_RANGE 1000
#define PWM_DUTYCYCLE_OFF 0
#define PWM_DUTYCYCLE_ON 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750();
float map_lux_to_brightness(int lux);
void set_led_brightness(float brightness);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Stop PWM
    gpioPWM(WS2812B_GPIO, 0);

    // Close I2C
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
int read_bh1750() {
    char config_cmd = 0x10; // Continuous high-resolution mode
    char buffer[2];
    int lux;

    if (i2cWriteByteData(i2c_handle, 0x00, config_cmd) < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(180); // Wait 180ms

    if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", i2c_handle);
        return -1;
    }

    lux = (buffer[0] << 8) | buffer[1];
    return lux;
}

// Map lux value to brightness level (0.0 to 1.0)
float map_lux_to_brightness(int lux) {
    // Use a logarithmic scale for better perceptual response
    float brightness = log10(lux + 1) / log10(10000 + 1); // Map 0-10000 lux to 0-1 brightness

    // Clamp the brightness value to the range [0.0, 1.0]
    if (brightness < 0.0) brightness = 0.0;
    if (brightness > 1.0) brightness = 1.0;

    return brightness;
}

// Set LED brightness using PWM
void set_led_brightness(float brightness) {
    int duty_cycle = (int)(brightness * PWM_RANGE);
    gpioPWM(WS2812B_GPIO, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(WS2812B_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(WS2812B_GPIO, PWM_RANGE);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Starting light sensor and LED control...\n");

    while (!terminate) {
        int lux = read_bh1750();
        if (lux >= 0) {
            float brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);
            printf("Lux: %d, Brightness: %.2f\n", lux, brightness);
        } else {
            fprintf(stderr, "Error reading lux value, retrying...\n");
        }

        gpioDelay(100); // Delay 100ms
    }

    return 0;
}

