#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define NUM_LEDS 30
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define APA102_START_FRAME_SIZE 4
#define APA102_END_FRAME_SIZE 4
#define APA102_LED_FRAME_SIZE 4

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(const char *bus);
int init_spi(const char *bus);
int read_bh1750(int fd);
void set_apa102_brightness(uint8_t *data, int brightness);
void construct_apa102_frame(uint8_t *data, int num_leds);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// SPI initialization function
int init_spi(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI bus");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 sensor reading function
int read_bh1750(int fd) {
    uint8_t config_cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    uint8_t data[2];

    // Set continuous high-resolution mode
    if (write(fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (120ms)
    usleep(120000);

    // Read 2 bytes of data
    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    uint16_t lux = (data[0] << 8) | data[1];
    return lux;
}

// APA102 brightness setting function
void set_apa102_brightness(uint8_t *data, int brightness) {
    // Scale brightness to 0-255 range
    uint8_t scaled_brightness = (uint8_t)(brightness * 255.0 / 1000.0); // Assuming max lux is 1000
    data[0] = 0xE0 | scaled_brightness; // Global brightness
}

// APA102 frame construction function
void construct_apa102_frame(uint8_t *data, int num_leds) {
    // Start frame
    memset(data, 0x00, APA102_START_FRAME_SIZE);
    data += APA102_START_FRAME_SIZE;

    // LED frames
    for (int i = 0; i < num_leds; i++) {
        data[0] = 0x00; // Blue
        data[1] = 0x00; // Green
        data[2] = 0x00; // Red
        data[3] = 0x00; // Global brightness (set later)
        data += APA102_LED_FRAME_SIZE;
    }

    // End frame
    memset(data, 0xFF, APA102_END_FRAME_SIZE);
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);

    // Turn off all LEDs
    uint8_t *led_data = malloc(NUM_LEDS * APA102_LED_FRAME_SIZE + APA102_START_FRAME_SIZE + APA102_END_FRAME_SIZE);
    if (led_data == NULL) {
        perror("Failed to allocate memory for LED data");
        exit(EXIT_FAILURE);
    }
    construct_apa102_frame(led_data, NUM_LEDS);
    for (int i = 0; i < NUM_LEDS; i++) {
        set_apa102_brightness(led_data + APA102_START_FRAME_SIZE + i * APA102_LED_FRAME_SIZE, 0);
    }

    if (spi_fd != -1) {
        spi_transfer(spi_fd, led_data, NULL, NUM_LEDS * APA102_LED_FRAME_SIZE + APA102_START_FRAME_SIZE + APA102_END_FRAME_SIZE);
    }

    free(led_data);

    // Close I2C and SPI devices
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }

    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_BUS);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (program_running) {
        // Read light level
        int lux = read_bh1750(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Failed to read light level. Continuing.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Allocate memory for LED data
        uint8_t *led_data = malloc(NUM_LEDS * APA102_LED_FRAME_SIZE + APA102_START_FRAME_SIZE + APA102_END_FRAME_SIZE);
        if (led_data == NULL) {
            perror("Failed to allocate memory for LED data");
            break; // Exit loop if memory allocation fails
        }

        // Construct APA102 frame
        construct_apa102_frame(led_data, NUM_LEDS);

        // Set brightness for each LED
        for (int i = 0; i < NUM_LEDS; i++) {
            set_apa102_brightness(led_data + APA102_START_FRAME_SIZE + i * APA102_LED_FRAME_SIZE, lux);
        }

        // Send data to APA102
        if (spi_transfer(spi_fd, led_data, NULL, NUM_LEDS * APA102_LED_FRAME_SIZE + APA102_START_FRAME_SIZE + APA102_END_FRAME_SIZE) < 0) {
            fprintf(stderr, "Failed to send data to APA102. Continuing.\n");
        }

        // Free allocated memory
        free(led_data);

        // Wait 100ms
        usleep(100000);
    }

    // Close I2C and SPI devices
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }

    return EXIT_SUCCESS;
}

