#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define sensor addresses
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x29
#define BH1750_ADDR_3 0x2D

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define APA102 parameters
#define APA102_START_FRAME_SIZE 4
#define APA102_END_FRAME_SIZE 4
#define NUM_LEDS 1

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
int i2c_handle_3 = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
float average_light_levels(int light1, int light2, int light3);
void set_apa102_brightness(int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read light level from BH1750 sensor
int read_bh1750(int i2c_handle) {
    if (i2c_handle < 0) {
        return -1; // Indicate error
    }

    // Send start measurement command (high resolution mode)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180ms

    // Read two bytes of light level data
    int light_level = i2cReadWordData(i2c_handle, 0x00);
    if (light_level < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Byte swap if necessary (depends on endianness)
    light_level = ((light_level & 0xFF00) >> 8) | ((light_level & 0x00FF) << 8);

    return light_level;
}

// Function to average light levels
float average_light_levels(int light1, int light2, int light3) {
    int count = 0;
    float sum = 0.0;

    if (light1 >= 0) {
        sum += light1;
        count++;
    }
    if (light2 >= 0) {
        sum += light2;
        count++;
    }
    if (light3 >= 0) {
        sum += light3;
        count++;
    }

    if (count == 0) {
        return 0.0; // Return 0 if no valid readings
    }

    return sum / count;
}

// Function to set APA102 brightness
void set_apa102_brightness(int brightness) {
    if (spi_handle < 0) {
        fprintf(stderr, "SPI not initialized\n");
        return;
    }

    // Start frame (4 bytes of 0x00)
    char start_frame[APA102_START_FRAME_SIZE] = {0x00, 0x00, 0x00, 0x00};
    spiWrite(spi_handle, start_frame, APA102_START_FRAME_SIZE);

    // LED data (brightness, blue, green, red)
    char led_data[4] = {0xE0 | (brightness & 0x1F), brightness, brightness, brightness};
    spiWrite(spi_handle, led_data, 4);

    // End frame (4 bytes of 0xFF)
    char end_frame[APA102_END_FRAME_SIZE] = {0xFF, 0xFF, 0xFF, 0xFF};
    spiWrite(spi_handle, end_frame, APA102_END_FRAME_SIZE);

    // Delay to allow data to be sent
    gpioDelay(1);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C devices
    i2c_handle_1 = i2cOpen(1, BH1750_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle_1);
    }

    i2c_handle_2 = i2cOpen(1, BH1750_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle_2);
    }

    i2c_handle_3 = i2cOpen(1, BH1750_ADDR_3, 0);
    if (i2c_handle_3 < 0) {
        fprintf(stderr, "Error opening I2C device 3: %d\n", i2c_handle_3);
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        // Close I2C devices if they were opened
        if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
        if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
        if (i2c_handle_3 >= 0) i2cClose(i2c_handle_3);
        gpioTerminate();
        return 1;
    }

    int current_brightness = 0;
    int target_brightness = 0;
    float light_level;
    int light1, light2, light3;

    while (!terminate) {
        // Read light levels from sensors
        light1 = read_bh1750(i2c_handle_1);
        light2 = read_bh1750(i2c_handle_2);
        light3 = read_bh1750(i2c_handle_3);

        // Average light levels
        light_level = average_light_levels(light1, light2, light3);

        // Calculate target brightness (logarithmic mapping)
        target_brightness = (int)(255.0 * log10(light_level + 1) / log10(10000 + 1)); // Assuming max light level is 10000 lux
        if (target_brightness < 0) target_brightness = 0;
        if (target_brightness > 255) target_brightness = 255;

        // Fade brightness to target over 500ms
        int step_size = (target_brightness - current_brightness) / 10; // 10 steps
        if (step_size == 0) step_size = (target_brightness > current_brightness) ? 1 : -1; // Ensure movement

        for (int i = 0; i < 10; i++) {
            current_brightness += step_size;
            if (current_brightness < 0) current_brightness = 0;
            if (current_brightness > 255) current_brightness = 255;
            set_apa102_brightness(current_brightness);
            gpioDelay(50); // 50ms delay
        }

        // Delay
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_apa102_brightness(0); // Turn off LED strip

    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    if (i2c_handle_3 >= 0) i2cClose(i2c_handle_3);
    if (spi_handle >= 0) spiClose(spi_handle);

    gpioTerminate();

    return 0;
}

