        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ALS data from VEML7700
int read_veml7700(uint16_t *als_data) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ALS_DATA_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }

    *als_data = (buf[1] << 8) | buf[0];
    return 0;
}

// Calculate lux value (simplified, adjust as needed)
float calculate_lux(uint16_t als_data) {
    // This is a placeholder.  Refer to the VEML7700 datasheet for the correct formula.
    // The gain and integration time settings from the sensor configuration are important.
    return (float)als_data * 0.0576; // Example conversion factor
}

// Gamma correction
float gamma_correct(float lux) {
    return powf(lux, 1.0 / GAMMA);
}

// Set LED brightness using bit-banging
int set_led_brightness(float brightness) {
    if (brightness < 0.0) brightness = 0.0;
    if (brightness > 1.0) brightness = 1.0;

    int on_time = (int)(brightness * LED_DUTY_CYCLE);
    int off_time = LED_DUTY_CYCLE - on_time;

    gpioWrite(LED_GPIO, 1); // LED on
    gpioDelay(on_time);
    gpioWrite(LED_GPIO, 0); // LED off
    gpioDelay(off_time);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    uint16_t als_data;
    float lux, brightness;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    while (!terminate) {
        // Read ALS data with retry
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_veml7700(&als_data) == 0) {
                break; // Success
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "I2C read failed after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        // Calculate lux value
        lux = calculate_lux(als_data);

        // Gamma correction
        brightness = gamma_correct(lux);

        // Set LED brightness
        set_led_brightness(brightness);

        // Get current timestamp
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Print lux reading and brightness value
        printf("%s - Lux: %.2f, Brightness: %.2f\n", timestamp, lux, brightness);

        // Pause
        gpioDelay(200000); // 200 ms
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

