// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Function prototypes
int read_flame_sensor();
void blink_led(int duration_ms);
void rapid_blink_led(int cycles);
void play_buzzer_pattern();
void log_event(const char *message);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Self-test sequence
    log_event("Starting self-test...");
    for (int i = 0; i < 2; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(500000); // 500ms
        gpioWrite(LED_PIN, 0);
        gpioDelay(500000); // 500ms
    }

    int flame_detected = 0;
    for (int i = 0; i < 5; i++) {
        if (read_flame_sensor() == 0) {
            flame_detected = 1;
        }
        gpioDelay(100000); // 100ms
    }

    if (flame_detected) {
        log_event("Self-test failed: Flame detected during test.");
        rapid_blink_led(5);
        play_buzzer_pattern();
        gpioTerminate();
        return 1;
    }

    log_event("Self-test passed.");

    // Main loop
    int flame_state = 1; // 1 = no flame, 0 = flame detected
    while (program_running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0 && flame_state == 1) {
            log_event("Flame detected!");
            gpioWrite(LED_PIN, 1);
            gpioWrite(BUZZER_PIN, 1);
            flame_state = 0;
        } else if (sensor_value == 1 && flame_state == 0) {
            log_event("Flame cleared.");
            gpioWrite(LED_PIN, 0);
            gpioWrite(BUZZER_PIN, 0);
            flame_state = 1;
        }

        gpioDelay(50000); // 50ms
    }

    // Cleanup (should not be reached if signal handler works correctly)
    gpioWrite(LED_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return 0;
}

