int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return 1; // Return 1 to avoid triggering the alarm in case of error
    }
    return value;
}

// Function to blink the LED
void blink_led(int duration_ms) {
    gpioWrite(LED_PIN, 1);
    gpioDelay(duration_ms * 1000); // Convert ms to us
    gpioWrite(LED_PIN, 0);
    gpioDelay(duration_ms * 1000); // Convert ms to us
}

// Function to rapidly blink the LED
void rapid_blink_led(int cycles) {
    for (int i = 0; i < cycles; i++) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(100000); // 100ms
        gpioWrite(LED_PIN, 0);
        gpioDelay(100000); // 100ms
    }
}

// Function to play the buzzer pattern
void play_buzzer_pattern() {
    for (int i = 0; i < 3; i++) {
        gpioWrite(BUZZER_PIN, 1);
        gpioDelay(200000); // 200ms
        gpioWrite(BUZZER_PIN, 0);
        gpioDelay(200000); // 200ms
        gpioWrite(BUZZER_PIN, 1);
        gpioDelay(600000); // 600ms
        gpioWrite(BUZZER_PIN, 0);
        gpioDelay(200000); // 200ms
    }
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] %s\n", timestamp, message);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received SIGINT. Shutting down...");
    gpioWrite(LED_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    exit(0);
}

