#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define MIN_LUX 0
#define MAX_LUX 1000
#define MIN_FREQ 0.5
#define MAX_FREQ 5.0

// Global variables
int i2c_fd;
double lux_buffer[BUFFER_SIZE];
int buffer_index = 0;
double average_lux = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(double *lux);
void update_circular_buffer(double lux);
double calculate_average_lux();
void set_led_frequency(double lux);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    uint8_t config_mode = CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config_mode, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(double *lux) {
    uint8_t buffer[2];
    int retries = 3;

    while (retries > 0) {
        if (read(i2c_fd, buffer, 2) == 2) {
            uint16_t raw_value = (buffer[0] << 8) | buffer[1];
            *lux = (double)raw_value / 1.2; // Convert to lux
            return 0; // Success
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(100000); // Wait 100ms before retrying
        }
    }

    fprintf(stderr, "Failed to read from BH1750 after multiple retries.\n");
    return -1; // Failure
}

// Function to update the circular buffer with the latest lux reading
void update_circular_buffer(double lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average lux value from the circular buffer
double calculate_average_lux() {
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to set the LED frequency based on the average lux value
void set_led_frequency(double lux) {
    double frequency = MIN_FREQ + (lux / MAX_LUX) * (MAX_FREQ - MIN_FREQ);
    if (frequency < MIN_FREQ) frequency = MIN_FREQ;
    if (frequency > MAX_FREQ) frequency = MAX_FREQ;

    // Calculate PWM range based on desired frequency
    int pwm_range = 1000000 / (int)(1000000 / frequency); // Calculate PWM range
    gpioSetPWMrange(GPIO_LED, pwm_range);

    // Set PWM duty cycle to 50%
    gpioPWM(GPIO_LED, pwm_range / 2);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioSetMode(GPIO_LED, PI_INPUT); // Set GPIO back to input
    gpioTerminate(); // Terminate pigpio
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        double lux;
        if (read_bh1750(&lux) == 0) {
            update_circular_buffer(lux);
            average_lux = calculate_average_lux();
            set_led_frequency(average_lux);
            printf("Lux: %.2f, Average Lux: %.2f, Frequency: %.2f Hz\n", lux, average_lux, MIN_FREQ + (average_lux / MAX_LUX) * (MAX_FREQ - MIN_FREQ));
        } else {
            fprintf(stderr, "Failed to read lux value. Skipping.\n");
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

