#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <wiringPi.h>

// Define GPIO pins
#define DATA_PIN   17 // BCM GPIO17
#define CLOCK_PIN  18 // BCM GPIO18
#define LATCH_PIN  27 // BCM GPIO27

// Define segment patterns for digit '5'
const uint8_t segment_patterns[] = {
    0b00110000, // a, b, c, d, e, f
    0b00110000  // a, b, c, d, e, f
};

// Function to shift out data to the 74HC595
void shiftOut(uint8_t data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the bit
        digitalWrite(DATA_PIN, (data >> (7 - i)) & 0x01);

        // Clock the data in
        digitalWrite(CLOCK_PIN, HIGH);
        delayMicroseconds(1); // Short delay for clock stability
        digitalWrite(CLOCK_PIN, LOW);
        delayMicroseconds(1); // Short delay for clock stability
    }
}

// Function to latch the data to the display
void latchData() {
    digitalWrite(LATCH_PIN, HIGH);
    delayMicroseconds(1); // Short delay for latch stability
    digitalWrite(LATCH_PIN, LOW);
}

int main(void) {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi.\n");
        return 1;
    }

    // Set pin modes
    pinMode(DATA_PIN, OUTPUT);
    pinMode(CLOCK_PIN, OUTPUT);
    pinMode(LATCH_PIN, OUTPUT);

    // Main loop
    while (1) {
        // Send the segment pattern to the 74HC595
        for (int i = 0; i < 2; i++) {
            shiftOut(segment_patterns[i]);
        }

        // Latch the data to the display
        latchData();

        // Blink the display on and off
        delay(500); // On for 500ms
        for (int i = 0; i < 2; i++) {
            shiftOut(0x00); // Turn off all segments
        }
        latchData();
        delay(500); // Off for 500ms
    }

    return 0;
}

