#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Global variables for GPIO chip and line handles
int chip_handle = -1;
int led_line_handle = -1;
int button_line_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (led_line_handle >= 0) {
        gpioLineRelease(chip_handle, LED_PIN);
    }
    if (button_line_handle >= 0) {
        gpioLineRelease(chip_handle, BUTTON_PIN);
    }

    // Close GPIO chip
    if (chip_handle >= 0) {
        gpioChipClose(chip_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip 0
    chip_handle = gpioChipOpen(0);
    if (chip_handle < 0) {
        fprintf(stderr, "Failed to open GPIO chip 0: %d\n", chip_handle);
        gpioTerminate();
        return 1;
    }

    // Request LED line as output
    led_line_handle = gpioLineRequest(chip_handle, LED_PIN, PI_OUTPUT);
    if (led_line_handle < 0) {
        fprintf(stderr, "Failed to request LED line: %d\n", led_line_handle);
        gpioChipClose(chip_handle);
        gpioTerminate();
        return 1;
    }

    // Request button line as input with pull-up
    button_line_handle = gpioLineRequest(chip_handle, BUTTON_PIN, PI_INPUT);
    if (button_line_handle < 0) {
        fprintf(stderr, "Failed to request button line: %d\n", button_line_handle);
        gpioLineRelease(chip_handle, LED_PIN);
        gpioChipClose(chip_handle);
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistor on button line
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioLineRelease(chip_handle, LED_PIN);
        gpioLineRelease(chip_handle, BUTTON_PIN);
        gpioChipClose(chip_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Blink LED
        gpioLineWrite(chip_handle, LED_PIN, 1);
        gpioDelay(1000000); // 1 second
        gpioLineWrite(chip_handle, LED_PIN, 0);
        gpioDelay(1000000); // 1 second

        // Check for button press
        if (gpioLineRead(chip_handle, BUTTON_PIN) == 0) {
            printf("Button pressed!\n");
            break;
        }
    }

    // Cleanup (already handled by signal handler, but included for completeness)
    gpioLineRelease(chip_handle, LED_PIN);
    gpioLineRelease(chip_handle, BUTTON_PIN);
    gpioChipClose(chip_handle);
    gpioTerminate();

    return 0;
}

