#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

int main() {
    int button_state = 0; // 0: released, 1: pressed
    int led_state = 0;    // 0: off, 1: on

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return 1;
    }

    // Configure button pin as input with pull-down resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on button pin\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read button state
        int current_button_state = gpioRead(BUTTON_PIN);

        // Check if button is pressed (low signal)
        if (current_button_state == 0) {
            if (button_state == 0) {
                // Button was released, now pressed
                button_state = 1;
                led_state = 1; // Turn LED on
            }
        } else {
            if (button_state == 1) {
                // Button was pressed, now released
                button_state = 0;
                led_state = 0; // Turn LED off
            }
        }

        // Blink LED if button is pressed
        if (led_state == 1) {
            gpioWrite(LED_PIN, 1); // LED on
            gpioDelay(500000);      // 500ms
            gpioWrite(LED_PIN, 0); // LED off
            gpioDelay(500000);      // 500ms
        } else {
            gpioWrite(LED_PIN, 0); // Ensure LED is off when button is released
            gpioDelay(10000);       // Small delay to prevent busy-waiting
        }
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

