#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// Define PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define PWM period in nanoseconds
#define PWM_PERIOD_NS (1000000000 / PWM_FREQUENCY)

// Define color change interval (100 ms)
#define COLOR_CHANGE_INTERVAL_MS 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (gpio_pin < 0 || gpio_pin > 31) {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return;
    }

    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle value: %d\n", duty_cycle);
        return;
    }

    // Calculate the on time in nanoseconds
    long on_time_ns = (long)((double)duty_cycle / 100.0 * PWM_PERIOD_NS);

    // Busy-wait PWM loop
    long start_time_ns = 0;
    long elapsed_time_ns = 0;

    // Turn the pin on
    gpioWrite(gpio_pin, 1);

    // Wait for the on time
    start_time_ns = gpioTick();
    while (elapsed_time_ns < on_time_ns) {
        elapsed_time_ns = gpioTick() - start_time_ns;
    }

    // Turn the pin off
    gpioWrite(gpio_pin, 0);

    // Wait for the off time
    start_time_ns = gpioTick();
    elapsed_time_ns = 0;
    while (elapsed_time_ns < (PWM_PERIOD_NS - on_time_ns)) {
        elapsed_time_ns = gpioTick() - start_time_ns;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set RED_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GREEN_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set BLUE_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate random RGB values
        int red_value = rand() % 101;
        int green_value = rand() % 101;
        int blue_value = rand() % 101;

        // Set PWM duty cycles for each color
        set_pwm_duty_cycle(RED_PIN, red_value);
        set_pwm_duty_cycle(GREEN_PIN, green_value);
        set_pwm_duty_cycle(BLUE_PIN, blue_value);

        // Wait for the color change interval
        usleep(COLOR_CHANGE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup GPIO resources
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

