// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define LSM303_CTRL_REG1_A 0x20
#define LSM303_OUT_X_L_A 0x28

// GPIO pin for interrupt
#define INTERRUPT_PIN 17

// Default G-force threshold
#define DEFAULT_THRESHOLD 2.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
double g_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int init_gpio();
int read_accelerometer_data(accelerometer_data_t *data);
double calculate_g_magnitude(const accelerometer_data_t *data);
void trigger_interrupt();
void log_data(const accelerometer_data_t *data, double g_magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

