    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate G-force magnitude
double calculate_g_magnitude(const accelerometer_data_t *data) {
    double x_g = data->x / 16384.0; // Assuming +/- 2G range
    double y_g = data->y / 16384.0;
    double z_g = data->z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

