#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void control_led(uint16_t als);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the ADPD188BI sensor
int initialize_sensor() {
    // No specific initialization needed for ADPD188BI in this example.
    // The sensor is assumed to be configured properly via hardware.
    return 0; // Success
}

// Read sensor data from ADPD188BI
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[2];
    int result;

    // Read ALS data
    result = i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS data: %d\n", result);
        return -1;
    }
    *als = (buf[1] << 8) | buf[0];

    // Read Red data
    result = i2cReadI2CBlockData(i2c_handle, RED_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Red data: %d\n", result);
        return -1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read Green data
    result = i2cReadI2CBlockData(i2c_handle, GREEN_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Green data: %d\n", result);
        return -1;
    }
    *green = (buf[1] << 8) | buf[0];

    // Read Blue data
    result = i2cReadI2CBlockData(i2c_handle, BLUE_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading Blue data: %d\n", result);
        return -1;
    }
    *blue = (buf[1] << 8) | buf[0];

    return 0; // Success
}

// Log data to CSV file
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED brightness using PWM
void control_led(uint16_t als) {
    // Map ALS value to PWM duty cycle (0-1000000)
    int duty_cycle = (int)(((float)als / 65535.0) * 1000000.0);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;

    gpioPWM(LED_GPIO, duty_cycle);
}

int main() {
    uint16_t als, red, green, blue;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(LED_GPIO, 1000000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < 3) {
            if (read_sensor_data(&als, &red, &green, &blue) == 0) {
                log_data(als, red, green, blue);
                control_led(als);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Retrying sensor read... (%d/3)\n", retries + 1);
                retries++;
                gpioDelay(100); // Wait 100ms before retrying
            }
        }

        if (retries == 3) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait 500ms
    }

    // Cleanup
    gpioPWM(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

