#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define gyroscope registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Define gyroscope parameters
#define GYRO_SENSITIVITY 0.00875 // dps/LSB for +/- 250 dps range
#define SAMPLE_RATE 20 // Hz
#define SAMPLE_PERIOD 50000 // microseconds (50ms)
#define CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD 50.0 // dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_gyro();
int read_gyro_data(gyro_data_t *data);
void calibrate_gyro(gyro_data_t *calibration_data);
void log_data(gyro_data_t data);
void check_alert(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the gyroscope
int initialize_gyro() {
    // Enable the gyroscope and set data rate to 20 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0xD3) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0xD3\n", who_am_i);
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw data to dps
    data->x = (float)x * GYRO_SENSITIVITY;
    data->y = (float)y * GYRO_SENSITIVITY;
    data->z = (float)z * GYRO_SENSITIVITY;

    return 0;
}

// Function to calibrate the gyroscope
void calibrate_gyro(gyro_data_t *calibration_data) {
    gyro_data_t raw_data;
    float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&raw_data) < 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return;
        }
        x_sum += raw_data.x;
        y_sum += raw_data.y;
        z_sum += raw_data.z;
        gpioDelay(SAMPLE_PERIOD / CALIBRATION_SAMPLES); // Distribute reads over the period
    }

    calibration_data->x = x_sum / CALIBRATION_SAMPLES;
    calibration_data->y = y_sum / CALIBRATION_SAMPLES;
    calibration_data->z = z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", calibration_data->x, calibration_data->y, calibration_data->z);
}

// Function to log data to file
void log_data(gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check for alert condition
void check_alert(gyro_data_t data) {
    if (fabs(data.x) > ALERT_THRESHOLD || fabs(data.y) > ALERT_THRESHOLD || fabs(data.z) > ALERT_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,ALERT,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
        fflush(log_file);
        fprintf(stderr, "ALERT: Angular velocity exceeded threshold!\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, 0x69, 0); // I2C bus 1, address 0x69
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (initialize_gyro() < 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate gyroscope
    gyro_data_t calibration_data;
    calibrate_gyro(&calibration_data);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t raw_data, calibrated_data;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_gyro_data(&raw_data) < 0) {
            fprintf(stderr, "Error reading gyro data\n");
            break;
        }

        // Apply calibration offsets
        calibrated_data.x = raw_data.x - calibration_data.x;
        calibrated_data.y = raw_data.y - calibration_data.y;
        calibrated_data.z = raw_data.z - calibration_data.z;

        // Log data
        log_data(calibrated_data);

        // Check for alert condition
        check_alert(calibrated_data);

        // Delay for 50ms
        gpioDelay(SAMPLE_PERIOD);
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

