// Acceleration threshold (g)
#define ACCEL_THRESHOLD 2.0

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_acceleration();
void log_data(accelerometer_data_t data);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the ADXL345
int initialize_adxl345() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, ADXL345_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Set data format to full resolution, ±2g
    int result = i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, ADXL345_FULL_RES_2G);
    if (result < 0) {
        fprintf(stderr, "Error writing data format: %d\n", result);
        return -1;
    }

    // Enable measurement mode
    result = i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08);
    if (result < 0) {
        fprintf(stderr, "Error writing power control: %d\n", result);
        return -1;
    }

    return 0;
}

