accelerometer_data_t read_acceleration() {
    accelerometer_data_t data;
    char raw_data[6];
    int result = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6);

    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
