    return 0;
}

// Read magnetometer data
int read_magnetometer(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, LSM303_MAG_OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        return -1;
    }

    // Combine high and low bytes, convert to gauss
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    *x = (float)raw_x / 1100.0f; // Typical sensitivity for +/- 1.3 Gauss
    *y = (float)raw_y / 1100.0f;
    *z = (float)raw_z / 1100.0f;

    return 0;
}

// Calculate heading using tilt compensation
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float mag_x_comp = mag_x * cos(pitch) + mag_z * sin(pitch);
    float mag_y_comp = mag_x * sin(roll) * sin(pitch) + mag_y * cos(roll) - mag_z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Log data to file
int log_data(float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(log_file);

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }
    rewind(log_file);

    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_accelerometer(&accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }
        if (read_magnetometer(&mag_x, &mag_y, &mag_z) < 0) {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate heading
        heading = calculate_heading(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Log data
        if (log_data(heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay for 100ms
        gpioDelay(100);
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

