#define VL6180X_REG_IDENTIFICATION_MODEL_ID 0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define VL6180X_REG_SYSTEM_MODE_GPIO1 0x010
#define VL6180X_REG_SYSRANGE_START 0x018
#define VL6180X_REG_RESULT_RANGE_VAL 0x062
#define VL6180X_REG_SYSTEM_INTERRUPT_CLEAR 0x015

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl6180x_init();
int read_distance();
void log_data(int distance);
void signal_handler(int signal);

// Structure to hold VL6180X configuration
typedef struct {
    uint8_t system_fresh_out_of_reset;
    uint8_t system_mode_gpio1;
    uint8_t sysrange_start;
    uint8_t system_interrupt_clear;
} vl6180x_config_t;

// VL6180X configuration values
const vl6180x_config_t vl6180x_config = {
    .system_fresh_out_of_reset = 0x00,
    .system_mode_gpio1 = 0x10, // GPIO1 high when sample ready
    .sysrange_start = 0x01,
    .system_interrupt_clear = 0x00
};


// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the VL6180X sensor
int vl6180x_init() {
    // Check sensor ID
    int model_id = i2cReadByteData(i2c_handle, VL6180X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xB4) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Reset the device
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET, vl6180x_config.system_fresh_out_of_reset) < 0) {
        fprintf(stderr, "Error writing to system fresh out of reset register\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Set GPIO1 high when sample ready
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_MODE_GPIO1, vl6180x_config.system_mode_gpio1) < 0) {
        fprintf(stderr, "Error writing to system mode GPIO1 register\n");
        return -1;
    }

    // Start range measurement
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, vl6180x_config.sysrange_start) < 0) {
        fprintf(stderr, "Error writing to sysrange start register\n");
        return -1;
    }

    return 0;
}

// Reads the distance from the VL6180X sensor
int read_distance() {
    int distance = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_VAL);
    if (distance < 0) {
        fprintf(stderr, "Error reading range value: %d\n", distance);
        return -1;
    }

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_INTERRUPT_CLEAR, vl6180x_config.system_interrupt_clear) < 0) {
        fprintf(stderr, "Error writing to system interrupt clear register\n");
        return -1;
    }

    return distance;
}

// Logs the distance data to a file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately

    if (distance < 100) {
        fprintf(log_file, "%s, DOOR_OPEN\n", timestamp);
        fflush(log_file);
    } else {
        fprintf(log_file, "%s, DOOR_CLOSED\n", timestamp);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL6180X sensor
    if (vl6180x_init() < 0) {
        fprintf(stderr, "VL6180X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance, attempting re-initialization\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            gpioInitialise();
            i2c_handle = i2cOpen(1, VL6180X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (vl6180x_init() < 0) {
                    fprintf(stderr, "VL6180X re-initialization failed\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

