    double t2 = data2.timestamp.tv_sec + data2.timestamp.tv_nsec / 1000000000.0;
    return t2 - t1;
}

// Function to log data to CSV file
int log_data(FILE *fp, SensorData data, double tdoa) {
    if (fprintf(fp, "%ld,%09ld,%d,%d,%.6f\n",
                data.timestamp.tv_sec, data.timestamp.tv_nsec,
                data.sensor1_sample, data.sensor2_sample, tdoa) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file for writing\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
    }
    rewind(log_file);

    // Main loop
    SensorData data1, data2;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle1, &data1.sensor1_sample) != 0) {
            fprintf(stderr, "Error reading sensor 1, skipping sample\n");
            continue;
        }
        if (read_sensor_data(i2c_handle2, &data2.sensor2_sample) != 0) {
            fprintf(stderr, "Error reading sensor 2, skipping sample\n");
            continue;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &data1.timestamp) == -1 ||
            clock_gettime(CLOCK_REALTIME, &data2.timestamp) == -1) {
            fprintf(stderr, "Error getting timestamp\n");
            continue;
        }

        // Calculate TDOA
        double tdoa = calculate_tdoa(data1, data2);

        // Log data
        if (log_data(log_file, data1, tdoa) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

