// ADIS16488A Register Addresses
#define ADIS16488A_REG_GYRO_XOUT 0x04
#define ADIS16488A_REG_GYRO_YOUT 0x06
#define ADIS16488A_REG_GYRO_ZOUT 0x08
#define ADIS16488A_REG_ACCL_XOUT 0x0A
#define ADIS16488A_REG_ACCL_YOUT 0x0C
#define ADIS16488A_REG_ACCL_ZOUT 0x0E

// Sensitivity values
#define GYRO_SENSITIVITY 0.005  // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Structure to hold IMU data
typedef struct {
    double timestamp;
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} imu_data_t;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr, int *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
int read_imu_data(int handle, imu_data_t *data);
int convert_data(imu_data_t *data);
int log_data(FILE *fp, imu_data_t *data);
void cleanup(int signal);

// Function to read data from an ADIS16488A register
int spi_read_register(int handle, uint8_t reg_addr, int *data) {
    char tx[2], rx[2];
    tx[0] = 0x80 | reg_addr; // Set MSB to 1 for read
    tx[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = (rx[0] << 8) | rx[1];
    return 0;
}

// Function to write data to an ADIS16488A register
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx[2], rx[2];
    tx[0] = reg_addr & 0x7F; // Clear MSB for write
    tx[1] = data & 0xFF;

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(int handle, imu_data_t *data) {
    int gyro_x_raw, gyro_y_raw, gyro_z_raw;
    int accel_x_raw, accel_y_raw, accel_z_raw;

    if (spi_read_register(handle, ADIS16488A_REG_GYRO_XOUT, &gyro_x_raw) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_GYRO_YOUT, &gyro_y_raw) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_GYRO_ZOUT, &gyro_z_raw) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_ACCL_XOUT, &accel_x_raw) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_ACCL_YOUT, &accel_y_raw) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_ACCL_ZOUT, &accel_z_raw) != 0) return -1;

    data->gyro_x = (float)gyro_x_raw;
    data->gyro_y = (float)gyro_y_raw;
    data->gyro_z = (float)gyro_z_raw;
    data->accel_x = (float)accel_x_raw;
    data->accel_y = (float)accel_y_raw;
    data->accel_z = (float)accel_z_raw;

    return 0;
}

