#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define ADIS16448_REG_GYRO_XOUT 0x04
#define ADIS16448_REG_GYRO_YOUT 0x06
#define ADIS16448_REG_GYRO_ZOUT 0x08
#define ADIS16448_REG_ACCL_XOUT 0x0A
#define ADIS16448_REG_ACCL_YOUT 0x0C
#define ADIS16448_REG_ACCL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CS_PIN 8
#define SPI_SPEED 1000000 // 1 MHz

// Scaling factors
#define GYRO_SCALE 0.02  // dps/LSB
#define ACCL_SCALE 0.00025 // g/LSB

int spi_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit register from the ADIS16448
int16_t read_register(int handle, uint8_t reg_addr) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer (register address with MSB set)
    tx_buf[0] = reg_addr | 0x80; // Set MSB to 1 for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading data

    // Perform the SPI transaction
    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1; // Indicate error
    }

    // Combine the received bytes to form a 16-bit value
    int16_t value = (rx_buf[0] << 8) | rx_buf[1];
    return value;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 3); // SPI mode 3
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read gyroscope data
        int16_t gyro_x = read_register(spi_handle, ADIS16448_REG_GYRO_XOUT);
        int16_t gyro_y = read_register(spi_handle, ADIS16448_REG_GYRO_YOUT);
        int16_t gyro_z = read_register(spi_handle, ADIS16448_REG_GYRO_ZOUT);

        // Read accelerometer data
        int16_t accl_x = read_register(spi_handle, ADIS16448_REG_ACCL_XOUT);
        int16_t accl_y = read_register(spi_handle, ADIS16448_REG_ACCL_YOUT);
        int16_t accl_z = read_register(spi_handle, ADIS16448_REG_ACCL_ZOUT);

        // Check for read errors
        if (gyro_x == -1 || gyro_y == -1 || gyro_z == -1 || accl_x == -1 || accl_y == -1 || accl_z == -1) {
            fprintf(stderr, "Error: Failed to read one or more registers\n");
            continue; // Skip to the next iteration
        }

        // Convert raw data to physical units
        float gyro_x_dps = gyro_x * GYRO_SCALE;
        float gyro_y_dps = gyro_y * GYRO_SCALE;
        float gyro_z_dps = gyro_z * GYRO_SCALE;
        float accl_x_g = accl_x * ACCL_SCALE;
        float accl_y_g = accl_y * ACCL_SCALE;
        float accl_z_g = accl_z * ACCL_SCALE;

        // Print the data to the console
        printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps, Accel X: %.4f g, Accel Y: %.4f g, Accel Z: %.4f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps, accl_x_g, accl_y_g, accl_z_g);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

