#define ADIS16448_REG_ACCL_ZOUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec per LSB
#define ACCL_SCALE 0.00025 // g per LSB

int spi_handle;

// Function prototypes
int adis16448_read_register(uint8_t reg_addr, int *data);
int adis16448_read_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit register from the ADIS16448
int adis16448_read_register(uint8_t reg_addr, int *data) {
    char tx_buf[2];
    char rx_buf[2];
    int status;

    // Construct the transmit buffer (register address with read bit set)
    tx_buf[0] = reg_addr | 0x80; // Set read bit (bit 7)
    tx_buf[1] = 0x00; // Dummy byte for reading data

    // Perform the SPI transaction
    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", status);
        return -1;
    }

    // Combine the two bytes to form the 16-bit data
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

