int adis16448_read_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    int raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (adis16448_read_register(ADIS16448_REG_GYRO_XOUT, &raw_gyro_x) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_GYRO_YOUT, &raw_gyro_y) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_GYRO_ZOUT, &raw_gyro_z) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_ACCL_XOUT, &raw_accel_x) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_ACCL_YOUT, &raw_accel_y) != 0) return -1;
    if (adis16448_read_register(ADIS16448_REG_ACCL_ZOUT, &raw_accel_z) != 0) return -1;

    // Scale the raw data
    *gyro_x = (float)raw_gyro_x * GYRO_SCALE;
    *gyro_y = (float)raw_gyro_y * GYRO_SCALE;
    *gyro_z = (float)raw_gyro_z * GYRO_SCALE;
    *accel_x = (float)raw_accel_x * ACCL_SCALE;
    *accel_y = (float)raw_accel_y * ACCL_SCALE;
    *accel_z = (float)raw_accel_z * ACCL_SCALE;

    return 0;
}

