#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6886 I2C address
#define MPU6886_ADDR 0x68

// MPU6886 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the MPU6886
int16_t read_mpu6886_value(int i2c_handle, uint8_t reg_addr) {
    char buf[2];
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, reg_addr, buf, 2);
        if (result == 2) {
            return (int16_t)((buf[0] << 8) | buf[1]);
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retries remaining: %d\n", reg_addr, result, retries - 1);
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg_addr);
    return 0; // Return 0 on failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU6886 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6886\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read accelerometer values
        int16_t accel_x = read_mpu6886_value(i2c_handle, ACCEL_XOUT_H);
        int16_t accel_y = read_mpu6886_value(i2c_handle, ACCEL_XOUT_H + 2);
        int16_t accel_z = read_mpu6886_value(i2c_handle, ACCEL_XOUT_H + 4);

        // Read gyroscope values
        int16_t gyro_x = read_mpu6886_value(i2c_handle, GYRO_XOUT_H);
        int16_t gyro_y = read_mpu6886_value(i2c_handle, GYRO_XOUT_H + 2);
        int16_t gyro_z = read_mpu6886_value(i2c_handle, GYRO_XOUT_H + 4);

        // Print the values
        printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Delay for 50ms
        gpioDelay(50000);
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

