#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_DEVID 0x00

// LED GPIO pin
#define LED_PIN 17

// Impact threshold
#define IMPACT_THRESHOLD 2.5

// Full-resolution scale factor
#define SCALE_FACTOR 256.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_accelerometer_data();
float calculate_magnitude(accelerometer_data_t data);
void log_impact(accelerometer_data_t data, float magnitude);
void control_led(int on);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize ADXL345
int initialize_adxl345() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%X\n", device_id);
        return -1;
    }

    // Set power control register to start measurement
    int result = i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08);
    if (result < 0) {
        fprintf(stderr, "Error writing to power control register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    int16_t raw_x, raw_y, raw_z;

    // Read raw data from registers
    raw_x = i2cReadWordData(i2c_handle, ADXL345_DATAX0);
    raw_y = i2cReadWordData(i2c_handle, ADXL345_DATAY0);
    raw_z = i2cReadWordData(i2c_handle, ADXL345_DATAZ0);

    if (raw_x < 0 || raw_y < 0 || raw_z < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Convert to g-force units
    data.x = (float)raw_x / SCALE_FACTOR;
    data.y = (float)raw_y / SCALE_FACTOR;
    data.z = (float)raw_z / SCALE_FACTOR;

    return data;
}

// Calculate acceleration magnitude
float calculate_magnitude(accelerometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Log impact event
void log_impact(accelerometer_data_t data, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Magnitude: %.2f g, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
            timestamp, magnitude, data.x, data.y, data.z);
    fflush(log_file);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_magnitude(data);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(data, magnitude);
            control_led(1);
            gpioDelay(500); // 500 ms
            control_led(0);
        }

        gpioDelay(10); // 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

