#include <time.h>
#include <signal.h>
#include <string.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 Register Addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Scaling factors
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE  131.0f   // +/- 250 dps range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the ICM-20602
int init_icm20602() {
    // Wake up the sensor (clear sleep bit)
    int status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0);
    if (status != 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
        return -1;
    }
    return 0;
}

// Function to read IMU data
int read_imu_data(imu_data_t *data) {
    char buffer[12];
    int status = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 12);
    if (status != 12) {
        fprintf(stderr, "Error reading IMU data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    int16_t accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Combine high and low bytes for gyroscope data
    int16_t gyro_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    int16_t gyro_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    int16_t gyro_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    // Convert raw data to g and dps
    data->accel_x = (float)accel_x / ACCEL_SCALE;
    data->accel_y = (float)accel_y / ACCEL_SCALE;
    data->accel_z = (float)accel_z / ACCEL_SCALE;
    data->gyro_x  = (float)gyro_x  / GYRO_SCALE;
    data->gyro_y  = (float)gyro_y  / GYRO_SCALE;
    data->gyro_z  = (float)gyro_z  / GYRO_SCALE;

    return 0;
}

// Function to log IMU data to a file
int log_imu_data(const imu_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ICM-20602
    if (init_icm20602() != 0) {
        fprintf(stderr, "ICM-20602 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    imu_data_t imu_data;

    // Main loop
    while (!terminate) {
        if (read_imu_data(&imu_data) == 0) {
            log_imu_data(&imu_data);
        } else {
            fprintf(stderr, "Failed to read IMU data. Retrying...\n");
        }
        gpioDelay(100); // 10 Hz sampling rate
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

