#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0
#define ACCEL_RANGE 2.0
#define ACCEL_SENSITIVITY 8192.0 // Sensitivity for ±2g range

// MMA8451Q Registers
#define MMA8451Q_REG_STATUS 0x00
#define MMA8451Q_REG_OUT_X_MSB 0x01
#define MMA8451Q_REG_OUT_X_LSB 0x02
#define MMA8451Q_REG_OUT_Y_MSB 0x03
#define MMA8451Q_REG_OUT_Y_LSB 0x04
#define MMA8451Q_REG_OUT_Z_MSB 0x05
#define MMA8451Q_REG_OUT_Z_LSB 0x06
#define MMA8451Q_REG_SYSMOD 0x0B
#define MMA8451Q_REG_INT_SOURCE 0x0C
#define MMA8451Q_REG_WHOAMI 0x0D
#define MMA8451Q_REG_XYZ_DATA_CFG 0x0E
#define MMA8451Q_REG_CTRL_REG1 0x2A
#define MMA8451Q_REG_CTRL_REG2 0x2B

// Global Variables
static int i2c_handle;
static FILE *log_file;
static volatile int running = 1;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function Prototypes
int init_i2c();
int verify_sensor_id();
int configure_sensor();
accelerometer_data_t read_acceleration();
float calculate_magnitude(accelerometer_data_t data);
void control_led(int on);
void log_data(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify Sensor ID
int verify_sensor_id() {
    int whoami = i2cReadByteData(i2c_handle, MMA8451Q_REG_WHOAMI);
    if (whoami < 0) {
        fprintf(stderr, "Error reading WHOAMI register: %d\n", whoami);
        return -1;
    }

    if (whoami != 0x2A) {
        fprintf(stderr, "Incorrect WHOAMI value: 0x%02X\n", whoami);
        return -1;
    }

    printf("MMA8451Q sensor found!\n");
    return 0;
}

// Configure Sensor
int configure_sensor() {
    // Set to active mode, 100Hz data rate
    if (i2cWriteByteData(i2c_handle, MMA8451Q_REG_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set range to ±2g
    if (i2cWriteByteData(i2c_handle, MMA8451Q_REG_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG\n");
        return -1;
    }

    return 0;
}

// Read Acceleration Data
accelerometer_data_t read_acceleration() {
    accelerometer_data_t data;
    char raw_data[6];

    if (i2cReadI2CBlockData(i2c_handle, MMA8451Q_REG_OUT_X_MSB, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine MSB and LSB, and convert to g-force units
    int16_t x = (int16_t)((raw_data[0] << 8) | raw_data[1]) >> 4;
    int16_t y = (int16_t)((raw_data[2] << 8) | raw_data[3]) >> 4;
    int16_t z = (int16_t)((raw_data[4] << 8) | raw_data[5]) >> 4;

    data.x = (float)x / ACCEL_SENSITIVITY * ACCEL_RANGE;
    data.y = (float)y / ACCEL_SENSITIVITY * ACCEL_RANGE;
    data.z = (float)z / ACCEL_SENSITIVITY * ACCEL_RANGE;

    return data;
}

// Calculate Magnitude
float calculate_magnitude(accelerometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log Data
void log_data(accelerometer_data_t data, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.3f, %.3f, %.3f, %.3f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring acceleration...\n");

    // Main loop
    while (running) {
        accelerometer_data_t data = read_acceleration();
        float magnitude = calculate_magnitude(data);

        if (magnitude > ACCEL_THRESHOLD) {
            printf("Impact detected! Magnitude: %.3f g\n", magnitude);
            control_led(1); // Turn LED on
            gpioDelay(500);  // Wait 500ms
            control_led(0); // Turn LED off
        }

        log_data(data, magnitude);
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

