    }

    // Enable free-fall interrupt
    char int_enable_value = 0x40; // Enable free-fall interrupt
    if (write(i2c_fd, &int_enable_value, 1) != 1) {
        perror("Failed to write to INT_ENABLE register");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345 sensor
int read_acceleration(int i2c_fd, int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read acceleration data");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to write a log entry to the CSV file
int write_log_entry(FILE *log_file, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[25];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03ld", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345 sensor
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO interrupt
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    // Main loop
    int freefall_active = 0;
    int16_t x, y, z;
    char int_source;

    while (program_running) {
        // Read interrupt status
        if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
            break;
        }
        if (read(i2c_fd, &int_source, 1) != 1) {
            perror("Failed to read INT_SOURCE register");
            break;
        }

        // Check for free-fall interrupt
        if (int_source & 0x40) {
            // Read acceleration data
            if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
                // Write log entry
                write_log_entry(log_file, x, y, z);
                freefall_active = 1;
            } else {
                fprintf(stderr, "Failed to read acceleration data\n");
                break;
            }
        } else {
            freefall_active = 0;
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Disable free-fall interrupt
    if (i2c_fd != -1) {
        char int_enable_value = 0x00; // Disable all interrupts
        if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
        } else if (write(i2c_fd, &int_enable_value, 1) != 1) {
            perror("Failed to write to INT_ENABLE register");
        }
    }

    // Close I2C bus
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

