#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Scaling factors
#define ACCEL_SCALE 0.061 // mg/LSB for ±2g range
#define GYRO_SCALE 8.75  // mdps/LSB for ±250 dps range

// Fall detection parameters
#define FREEFALL_THRESHOLD 0.2 // g
#define IMPACT_THRESHOLD 2.5  // g
#define WINDOW_SIZE 100       // 100 readings (100ms)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_lsm6dsr();
int read_lsm6dsr(sensor_data_t *data);
float calculate_magnitude(float x, float y, float z);
void log_data(sensor_data_t data);
void fall_detection(float magnitude);
void signal_handler(int signal);
void cleanup();

// State machine variables
enum { IDLE, FREEFALL, IMPACT } state = IDLE;
float accel_history[WINDOW_SIZE];
int history_index = 0;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_lsm6dsr(&sensor_data) == 0) {
            // Calculate acceleration magnitude
            float magnitude = calculate_magnitude(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z);

            // Log data
            log_data(sensor_data);

            // Fall detection
            fall_detection(magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for 10ms (100Hz)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // I2C bus 1, LSM6DSR address, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x69\n", who_am_i);
        return -1;
    }

    return 0;
}

// Initialize LSM6DSR
int init_lsm6dsr() {
    // Configure accelerometer: ±2g, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 0x80 = 104 Hz, ±2g
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: ±250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 0x80 = 104 Hz, ±250 dps
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read LSM6DSR data
int read_lsm6dsr(sensor_data_t *data) {
    char buffer[12];
    int result = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for accelerometer data
    int16_t accel_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t accel_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t accel_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine high and low bytes for gyroscope data
    int16_t gyro_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t gyro_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t gyro_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to g and dps
    data->accel_x = (float)accel_x_raw * ACCEL_SCALE / 1000.0f;
    data->accel_y = (float)accel_y_raw * ACCEL_SCALE / 1000.0f;
    data->accel_z = (float)accel_z_raw * ACCEL_SCALE / 1000.0f;
    data->gyro_x = (float)gyro_x_raw * GYRO_SCALE / 1000.0f;
    data->gyro_y = (float)gyro_y_raw * GYRO_SCALE / 1000.0f;
    data->gyro_z = (float)gyro_z_raw * GYRO_SCALE / 1000.0f;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log data to file
void log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld.%09ld,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            ts.tv_sec, ts.tv_nsec,
            data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(float magnitude) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Update acceleration history
    accel_history[history_index] = magnitude;
    history_index = (history_index + 1) % WINDOW_SIZE;

    // Check for freefall
    if (state == IDLE) {
        if (magnitude < FREEFALL_THRESHOLD) {
            state = FREEFALL;
            printf("%ld.%09ld: Freefall detected\n", ts.tv_sec, ts.tv_nsec);
        }
    }

    // Check for impact
    if (state == FREEFALL) {
        // Check if acceleration magnitude exceeds the threshold within the window
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (accel_history[i] > IMPACT_THRESHOLD) {
                state = IMPACT;
                printf("%ld.%09ld: Impact detected\n", ts.tv_sec, ts.tv_nsec);
                break; // Exit the loop if impact is detected
            }
        }
    }

    // Reset state after impact
    if (state == IMPACT) {
        state = IDLE;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

