#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define WHO_AM_I 0x02
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define SMPL_PRD 0x36
#define GLOB_CMD 0x68
#define SENSOR_DATA_REG_UPDATE 0x80

// ADIS16266 WHO_AM_I Value
#define ADIS16266_WHO_AM_I 0x5642

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_MODE 3
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t address, uint16_t *data);
int spi_write_register(uint8_t address, uint16_t data);
int verify_who_am_i();
int initialize_gyro();
int read_gyro_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Function to read a 16-bit register from the ADIS16266
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx[2], rx[2];
    tx[0] = address | 0x80; // Set MSB for read operation
    tx[1] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI Read Error: %d\n", result);
        return -1;
    }

    *data = (rx[0] << 8) | rx[1];
    return 0;
}

// Function to write a 16-bit register to the ADIS16266
int spi_write_register(uint8_t address, uint16_t data) {
    char tx[2], rx[2];
    tx[0] = address & 0x7F; // Clear MSB for write operation
    tx[1] = data & 0xFF;

    int result = spiXfer(spi_handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI Write Error: %d\n", result);
