#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Define the gyroscope sensitivity (8.75 mdps/LSB)
#define SENSITIVITY 8.75

// Define the sampling interval (10 ms)
#define SAMPLING_INTERVAL 10000 // in microseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful termination
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int result;

    // Enable the gyroscope (100 Hz, normal mode)
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
        if (result >= 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG1: %d, retrying...\n", result);
        gpioDelay(1000); // Wait 1 ms before retrying
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Set the full-scale range to ±250 °/s
    retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
        if (result >= 0) break; // Success
        fprintf(stderr, "Error writing to CTRL_REG4: %d, retrying...\n", result);
        gpioDelay(1000); // Wait 1 ms before retrying
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

