gyro_data_t convert_data(int16_t x, int16_t y, int16_t z) {
    gyro_data_t data;
    data.x = (float)x / 114.285;
    data.y = (float)y / 114.285;
    data.z = (float)z / 114.285;
    return data;
}

// Function to log data to a CSV file
int log_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "%ld,%.6f,%.6f,%.6f\n", timestamp_ns, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

