    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i != 0x0F) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%X, expected 0x0F\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
