#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define SAMPLE_RATE_MS 100
#define CSV_FILE "vibration_log.csv"

// Define sensor data structure
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sensor_data();
char* format_timestamp(char* timestamp_str, size_t timestamp_str_size);
int write_data_to_csv(const char* timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data from the D7S-0001
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        data.x = 0; // Set default values in case of error
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Format the current timestamp as an ISO 8601 string
char* format_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", info);
    return timestamp_str;
}

// Write data to the CSV file
int write_data_to_csv(const char* timestamp, int16_t x, int16_t y, int16_t z) {
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for appending
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header line if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    // Main loop
    char timestamp_str[32];
    while (program_running) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Format timestamp
        format_timestamp(timestamp_str, sizeof(timestamp_str));

        // Write data to CSV file
        write_data_to_csv(timestamp_str, sensor_data.x, sensor_data.y, sensor_data.z);

        // Delay for the specified sample rate
        gpioDelay(SAMPLE_RATE_MS * 1000); // pigpioDelay takes microseconds
    }

    // Close I2C device and CSV file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

