#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the Hall effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_data(int sensor1_state, int sensor2_state);
void halt_conveyor();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorData;

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the state of a Hall effect sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to log the timestamped state of the sensors to a file
int log_data(int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1; // Indicate error
    }

    fprintf(log_file, "%ld,%d,%d\n", timestamp_ms, sensor1_state, sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0; // Indicate success
}

// Function to simulate halting the conveyor
void halt_conveyor() {
    printf("Conveyor halted!\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate(); // Clean up GPIO before exiting
        return 1; // Exit if file opening fails
    }

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensor data, exiting...\n");
            break; // Exit loop on error
        }

        // Log the data
        if (log_data(sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break; // Exit loop on error
        }

        // Check if both sensors are active (logic level 1)
        if (sensor1_state == 1 && sensor2_state == 1) {
            halt_conveyor();
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

