#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and MMA8452Q address
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D

// Define MMA8452Q registers
#define MMA8452Q_WHO_AM_I 0x0D
#define MMA8452Q_CTRL_REG1 0x2A
#define MMA8452Q_OUT_X_MSB 0x01
#define MMA8452Q_OUT_X_LSB 0x02
#define MMA8452Q_OUT_Y_MSB 0x03
#define MMA8452Q_OUT_Y_LSB 0x04
#define MMA8452Q_OUT_Z_MSB 0x05
#define MMA8452Q_OUT_Z_LSB 0x06

// Define the expected WHO_AM_I value
#define MMA8452Q_WHO_AM_I_VALUE 0x2A

// Define the tilt threshold
#define TILT_THRESHOLD 45.0

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer

// Function prototypes
int init_i2c(const char *bus, int addr);
int verify_sensor_id(int fd);
int init_sensor(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt(int16_t x, int16_t y, int16_t z);
int log_fall_event(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (log_file != NULL) {
            fflush(log_file);
            fclose(log_file);
        }
        exit(0);
    }
}

// Initialize I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Verify sensor ID
int verify_sensor_id(int fd) {
    uint8_t who_am_i;
