#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration parameters
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Sensitivity (±4 gauss)
#define SENSITIVITY 0.146 // mG/LSB

// Metal detection threshold
#define METAL_THRESHOLD 800.0 // mG

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_raw_data(int16_t *x, int16_t *y, int16_t *z);
void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_magnitude(float x, float y, float z);
void log_data(float x, float y, float z);
void metal_detection(float magnitude);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LIS3MDL sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Set CTRL_REG1 to 0x70 (10 Hz, continuous conversion)
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70);
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG1: %d, retries remaining: %d\n", status, retries);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set CTRL_REG3 to 0x00 (Continuous conversion mode)
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to CTRL_REG3: %d, retries remaining: %d\n", status, retries);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Initialization successful
        return 0;
    }

    // Initialization failed after multiple retries
    fprintf(stderr, "Failed to initialize LIS3MDL after multiple retries.\n");
    return -1;
}

// Read raw magnetic field data from the sensor
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6);

    if (status != 6) {
        fprintf(stderr, "Error reading data from sensor: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate the raw data using the calibration parameters
void calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = ((float)raw_x - X_OFFSET) * X_SCALE * SENSITIVITY;
    *calibrated_y = ((float)raw_y - Y_OFFSET) * Y_SCALE * SENSITIVITY;
    *calibrated_z = ((float)raw_z - Z_OFFSET) * Z_SCALE * SENSITIVITY;
}

// Calculate the magnitude of the magnetic field vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log the calibrated data to the file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file);
}

// Check for metal detection and print an alert if necessary
void metal_detection(float magnitude) {
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detected! Magnitude: %.2f mG\n", magnitude);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    float calibrated_x, calibrated_y, calibrated_z;
    float magnitude;

    // Main loop
    while (program_running) {
        // Read raw data
        if (read_raw_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Calibrate the data
            calibrate_data(raw_x, raw_y, raw_z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate the magnitude
            magnitude = calculate_magnitude(calibrated_x, calibrated_y, calibrated_z);

            // Log the data
            log_data(calibrated_x, calibrated_y, calibrated_z);

            // Check for metal detection
            metal_detection(magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(100000); // 100ms delay (10 Hz)
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

