#define ADXL354B_REG_XDATA_L 0x09
#define ADXL354B_REG_XDATA_M 0x0A
#define ADXL354B_REG_YDATA_H 0x0B
#define ADXL354B_REG_YDATA_L 0x0C
#define ADXL354B_REG_YDATA_M 0x0D
#define ADXL354B_REG_ZDATA_H 0x0E
#define ADXL354B_REG_ZDATA_L 0x0F
#define ADXL354B_REG_ZDATA_M 0x10
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_RESET 0x1F
#define ADXL354B_REG_PARTID 0x11

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_init(int handle);
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z);
void log_data(FILE *fp, int32_t x, int32_t y, int32_t z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];
    tx_buf[0] = (reg | 0x80) | ((len > 1) ? 0x40 : 0x00); // Set read bit and multi-byte bit if necessary

    if (spiXfer(handle, tx_buf, rx_buf, len + 1) != 0) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = reg & 0x7F; // Clear read bit
    tx_buf[1] = data;

    if (spiWrite(handle, tx_buf, 2) != 0) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    uint8_t status;
    int retries = 3;

    while (retries > 0) {
        if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) == 0) {
            gpioDelay(1000); // 1 ms delay
            return 0;
        } else {
            fprintf(stderr, "Reset write failed, retrying...\n");
            retries--;
            gpioDelay(10000); // 10 ms delay before retry
        }
    }

    fprintf(stderr, "Reset failed after multiple retries\n");
    return -1;
}

// ADXL354B Initialization Function
int adxl354b_init(int handle) {
    uint8_t partid;
    int retries = 3;

    // Reset the device
    if (adxl354b_reset(handle) != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        return -1;
    }

    // Verify PARTID
    while (retries > 0) {
        if (spi_read_register(handle, ADXL354B_REG_PARTID, &partid, 1) == 0) {
            if (partid == 0xAD) {
                return 0; // Initialization successful
            } else {
                fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
                return -1;
            }
        } else {
            fprintf(stderr, "PARTID read failed, retrying...\n");
            retries--;
            gpioDelay(10000); // 10 ms delay before retry
        }
    }

    fprintf(stderr, "Initialization failed after multiple retries\n");
    return -1;
}

// ADXL354B Read Acceleration Data Function
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z) {
    uint8_t x_data[3], y_data[3], z_data[3];
    int retries = 3;

    while (retries > 0) {
        if (spi_read_register(handle, ADXL354B_REG_XDATA_H, x_data, 3) == 0 &&
            spi_read_register(handle, ADXL354B_REG_YDATA_H, y_data, 3) == 0 &&
            spi_read_register(handle, ADXL354B_REG_ZDATA_H, z_data, 3) == 0) {

            // Combine the 3 bytes into a 20-bit signed integer
            *x = ((int32_t)x_data[0] << 12) | ((int32_t)x_data[1] << 4) | ((int32_t)x_data[2] >> 4);
            *y = ((int32_t)y_data[0] << 12) | ((int32_t)y_data[1] << 4) | ((int32_t)y_data[2] >> 4);
            *z = ((int32_t)z_data[0] << 12) | ((int32_t)z_data[1] << 4) | ((int32_t)z_data[2] >> 4);

            // Sign extend to 32 bits
            if (*x & (1 << 19)) *x |= 0xFFF00000;
            if (*y & (1 << 19)) *y |= 0xFFF00000;
            if (*z & (1 << 19)) *z |= 0xFFF00000;

            return 0; // Success
        } else {
            fprintf(stderr, "Acceleration read failed, retrying...\n");
            retries--;
            gpioDelay(10000); // 10 ms delay before retry
        }
    }

    fprintf(stderr, "Acceleration read failed after multiple retries\n");
    return -1;
}

// Log Data Function
void log_data(FILE *fp, int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int32_t x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_CE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354b_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

