#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// ADIS16362 Register Addresses
#define ADIS16362_REG_XGYRO_OUT 0x04
#define ADIS16362_REG_YGYRO_OUT 0x06
#define ADIS16362_REG_ZGYRO_OUT 0x08
#define ADIS16362_REG_XACCEL_OUT 0x0A
#define ADIS16362_REG_YACCEL_OUT 0x0C
#define ADIS16362_REG_ZACCEL_OUT 0x0E
#define ADIS16362_REG_SMPL_PRD  0x36
#define ADIS16362_REG_GLOB_CMD  0x68
#define ADIS16362_REG_DIAG_STS  0x02

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec per LSB
#define ACCEL_SCALE 0.0025 // g per LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3
#define CS_PIN 8 // GPIO 8 (CE0)

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double timestamp;
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} imu_data_t;

// Function prototypes
int initialize_spi();
int initialize_imu();
int read_imu_data(imu_data_t *data);
int log_data(const imu_data_t *data);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the ADIS16362
int initialize_imu() {
    // Reset the device
    char buf[3];
    buf[0] = ADIS16362_REG_GLOB_CMD | 0x80; // Write command
    buf[1] = 0x04; // Reset value
    buf[2] = 0x00;
    if (spiWrite(spi_handle, buf, 3) != 3) {
        fprintf(stderr, "Error resetting IMU\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Set sample period (optional, adjust as needed)
    buf[0] = ADIS16362_REG_SMPL_PRD | 0x80; // Write command
    buf[1] = 0x0A; // Sample period value (adjust for 100Hz)
    buf[2] = 0x00;
    if (spiWrite(spi_handle, buf, 3) != 3) {
        fprintf(stderr, "Error setting sample period\n");
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(imu_data_t *data) {
    char tx_buf[3];
    char rx_buf[3];
    int16_t raw_data[6];

    // Read gyroscope data
    tx_buf[0] = ADIS16362_REG_XGYRO_OUT | 0x80; // Read command
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error reading X Gyro\n");
        return -1;
    }
    raw_data[0] = (rx_buf[1] << 8) | rx_buf[2];

    tx_buf[0] = ADIS16362_REG_YGYRO_OUT | 0x80; // Read command
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error reading Y Gyro\n");
        return -1;
    }
    raw_data[1] = (rx_buf[1] << 8) | rx_buf[2];

    tx_buf[0] = ADIS16362_REG_ZGYRO_OUT | 0x80; // Read command
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error reading Z Gyro\n");
        return -1;
    }
    raw_data[2] = (rx_buf[1] << 8) | rx_buf[2];

    // Read accelerometer data
    tx_buf[0] = ADIS16362_REG_XACCEL_OUT | 0x80; // Read command
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error reading X Accel\n");
        return -1;
    }
    raw_data[3] = (rx_buf[1] << 8) | rx_buf[2];

    tx_buf[0] = ADIS16362_REG_YACCEL_OUT | 0x80; // Read command
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error reading Y Accel\n");
        return -1;
    }
    raw_data[4] = (rx_buf[1] << 8) | rx_buf[2];

    tx_buf[0] = ADIS16362_REG_ZACCEL_OUT | 0x80; // Read command
    tx_buf[1] = 0x00;
    tx_buf[2] = 0x00;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error reading Z Accel\n");
        return -1;
    }
    raw_data[5] = (rx_buf[1] << 8) | rx_buf[2];

    // Convert to physical units
    data->x_gyro = (double)raw_data[0] * GYRO_SCALE;
    data->y_gyro = (double)raw_data[1] * GYRO_SCALE;
    data->z_gyro = (double)raw_data[2] * GYRO_SCALE;
    data->x_accel = (double)raw_data[3] * ACCEL_SCALE;
    data->y_accel = (double)raw_data[4] * ACCEL_SCALE;
    data->z_accel = (double)raw_data[5] * ACCEL_SCALE;

    return 0;
}

// Function to log data to CSV file
int log_data(const imu_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data->timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(log_file, "%.15f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            data->timestamp, data->x_gyro, data->y_gyro, data->z_gyro,
            data->x_accel, data->y_accel, data->z_accel);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    imu_data_t imu_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize IMU
    if (initialize_imu() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
