// Define the GPIO pin for the IR obstacle sensor
#define SENSOR_PIN 17

// Global variable to store the GPIO chip handle
int gpio_chip_handle = -1;

// Function prototypes
int read_sensor();
void log_message(const char *message);
void self_parking_sequence();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int running;
} program_state_t;

program_state_t state = {1}; // Initialize running to 1

// Function to read the sensor value
int read_sensor() {
    int value = gpioRead(SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log a message with a timestamp
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Function to simulate the self-parking sequence
void self_parking_sequence() {
    log_message("Self-parking sequence started");
    // Simulate parking actions (e.g., lowering the sunroof)
    gpioDelay(2000000); // 2 seconds
    log_message("Self-parking sequence completed");
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        log_message("Ctrl+C detected. Exiting gracefully...");
        state.running = 0; // Set running to 0 to exit the main loop
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin as an input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    log_message("Self-parking system started");

    // Main loop
    while (state.running) {
        int sensor_value = read_sensor();
        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            self_parking_sequence();
        } else if (sensor_value < 0) {
            // Error reading sensor, exit loop
            break;
        }
        gpioDelay(1000000); // 1 second delay
    }

    // Clean up and exit
    gpioTerminate();
    log_message("Self-parking system stopped");
    return 0;
}

