#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    int combined_value = gpioRead(SENSOR1_GPIO) | (gpioRead(SENSOR2_GPIO) << 1);

    if (combined_value < 0) {
        fprintf(stderr, "Error reading sensor values: %d\n", combined_value);
        return -1; // Indicate an error
    }

    *sensor1_value = (combined_value & 0x01);
    *sensor2_value = ((combined_value & 0x02) >> 1);

    return 0; // Indicate success
}

// Function to log the sensor data with a timestamp
void log_data(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
           (sensor1_value == 0) ? "Obstacle Detected" : "Path Clear",
           (sensor2_value == 0) ? "Obstacle Detected" : "Path Clear");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    int sensor1_value, sensor2_value;

    // Main loop
    while (program_running) {
        // Read the sensor values
        if (read_sensors(&sensor1_value, &sensor2_value) == 0) {
            // Log the data
            log_data(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Failed to read sensors. Retrying...\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

