#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(uint8_t address, uint16_t *data);
void process_gyro_data(uint16_t raw_data, float *rate);
void log_gyro_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// SPI Read Register Function
int spi_read_register(uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: address with MSB set, followed by dummy bytes
    tx_buf[0] = address | 0x80; // Set MSB to indicate read
    tx_buf[1] = 0x00; // Dummy byte 1
    tx_buf[2] = 0x00; // Dummy byte 2

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Combine the received bytes to form the 16-bit data
    *data = ((uint16_t)rx_buf[1] << 8) | (uint16_t)rx_buf[2];

    return 0;
}

// Process Gyro Data Function
void process_gyro_data(uint16_t raw_data, float *rate) {
    *rate = (float)raw_data * 0.02; // Apply scale factor
}

// Log Gyro Data Function
void log_gyro_data(float x_rate, float y_rate, float z_rate) {
    printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_rate, y_rate, z_rate);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t raw_data;
    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        // Read X-axis data
        if (spi_read_register(ADIS16266_REG_XGYRO_OUT, &raw_data) == 0) {
            process_gyro_data(raw_data, &x_rate);
        } else {
            x_rate = 0.0; // Set to 0 on error
        }

        // Read Y-axis data
        if (spi_read_register(ADIS16266_REG_YGYRO_OUT, &raw_data) == 0) {
            process_gyro_data(raw_data, &y_rate);
        } else {
            y_rate = 0.0; // Set to 0 on error
        }

        // Read Z-axis data
        if (spi_read_register(ADIS16266_REG_ZGYRO_OUT, &raw_data) == 0) {
            process_gyro_data(raw_data, &z_rate);
        } else {
            z_rate = 0.0; // Set to 0 on error
        }

        // Log the data
        log_gyro_data(x_rate, y_rate, z_rate);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

