    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t raw_data;
    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        // Read X-axis data
        if (spi_read_register(ADIS16266_REG_XGYRO_OUT, &raw_data) == 0) {
            process_gyro_data(raw_data, &x_rate);
        } else {
            x_rate = 0.0; // Set to 0 on error
        }

        // Read Y-axis data
        if (spi_read_register(ADIS16266_REG_YGYRO_OUT, &raw_data) == 0) {
            process_gyro_data(raw_data, &y_rate);
        } else {
            y_rate = 0.0; // Set to 0 on error
        }

        // Read Z-axis data
        if (spi_read_register(ADIS16266_REG_ZGYRO_OUT, &raw_data) == 0) {
            process_gyro_data(raw_data, &z_rate);
        } else {
            z_rate = 0.0; // Set to 0 on error
        }

        // Log the data
        log_gyro_data(x_rate, y_rate, z_rate);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
