#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_REG_STATUS 0x00
#define FXOS8700_REG_OUT_X_MSB 0x01
#define FXOS8700_REG_OUT_X_LSB 0x02
#define FXOS8700_REG_OUT_Y_MSB 0x03
#define FXOS8700_REG_OUT_Y_LSB 0x04
#define FXOS8700_REG_OUT_Z_MSB 0x05
#define FXOS8700_REG_OUT_Z_LSB 0x06
#define FXOS8700_REG_OUT_MAG_X_MSB 0x33
#define FXOS8700_REG_OUT_MAG_X_LSB 0x34
#define FXOS8700_REG_OUT_MAG_Y_MSB 0x35
#define FXOS8700_REG_OUT_MAG_Y_LSB 0x36
#define FXOS8700_REG_OUT_MAG_Z_MSB 0x37
#define FXOS8700_REG_OUT_MAG_Z_LSB 0x38
#define FXOS8700_REG_WHOAMI 0x0D
#define FXOS8700_REG_CTRL_REG1 0x2A
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the FXOS8700 sensor
int initialize_sensor(int handle) {
    uint8_t whoami;

    // Check WHOAMI register
    if (read_register(handle, FXOS8700_REG_WHOAMI, &whoami) != 0) {
        fprintf(stderr, "Error reading WHOAMI register\n");
        return -1;
    }

    if (whoami != 0xC7) {
        fprintf(stderr, "Incorrect WHOAMI value: 0x%02X\n", whoami);
        return -1;
    }

    // Set to active mode, 100 Hz ODR
    if (write_register(handle, FXOS8700_REG_CTRL_REG1, 0x01 | (1 << 1)) != 0) {
        fprintf(stderr, "Error writing CTRL_REG1\n");
        return -1;
    }

    // Set range to +/- 2g
    if (write_register(handle, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Error writing XYZ_DATA_CFG\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and magnetometer data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    uint8_t buffer[12];
    int result = i2cReadI2CBlockData(handle, FXOS8700_REG_OUT_X_MSB, (char *)buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine MSB and LSB for accelerometer data
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    // Combine MSB and LSB for magnetometer data
    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Mag: X=%6d, Y=%6d, Z=%6d\n", accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

