#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define WINDOW_MS 5000
#define SAMPLE_MS 1

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    int i;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check command-line argument
    if (argc != 2) {
        fprintf(stderr, "Error: Missing threshold argument. Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    threshold = atoi(argv[1]);

    if (threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Threshold must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    while (program_running) {
        high_count = 0;

        // Sample the GPIO pin over the window
        for (i = 0; i < WINDOW_MS; i += SAMPLE_MS) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_MS * 1000); // pigpioDelay takes microseconds
        }

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Print status or alert
        if (high_count > threshold) {
            printf("%s ALERT\n", timestamp);
        } else {
            printf("%s OK\n", timestamp);
        }

        // Pause for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

