#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_DOOR_A 17
#define GPIO_DOOR_B 27
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ACCESS_LOG_FILE "access_log.txt"
#define UNLOCK_DURATION_MS 5000
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line_a = NULL;
static struct gpiod_line *gpio_line_b = NULL;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_init(void);
int i2c_init(void);
int generate_code(int *code);
int read_code(int *code);
int validate_code(int generated_code, int entered_code);
int unlock_door(int door);
int log_access(int code);
void signal_handler(int sig);
void cleanup(void);

// GPIO initialization function
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    gpio_line_a = gpiod_chip_get_line(gpio_chip, GPIO_DOOR_A);
    if (!gpio_line_a) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_DOOR_A);
        cleanup();
        return -1;
    }

    gpio_line_b = gpiod_chip_get_line(gpio_chip, GPIO_DOOR_B);
    if (!gpio_line_b) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_DOOR_B);
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(gpio_line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output\n", GPIO_DOOR_A);
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(gpio_line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output\n", GPIO_DOOR_B);
        cleanup();
        return -1;
    }

    return 0;
}

// I2C initialization function
int i2c_init(void) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", filename);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: 0x%02x\n", I2C_ADDRESS);
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Code generation function
int generate_code(int *code) {
    *code = (rand() % 900000) + 100000;
    return 0;
}

// Code reading function
int read_code(int *code) {
    char buffer[7];
    int i;

    printf("Enter the six-digit code: ");
    if (fgets(buffer, sizeof(buffer), stdin) == NULL) {
        perror("Error reading from stdin");
        return -1;
    }

    // Remove trailing newline
    for (i = 0; i < sizeof(buffer) - 1; i++) {
        if (buffer[i] == '\n') {
            buffer[i] = '\0';
            break;
        }
    }

    // Check for valid input (6 digits)
    if (strlen(buffer) != 6) {
        fprintf(stderr, "Invalid input: Please enter exactly 6 digits.\n");
        return -1;
    }

    for (i = 0; i < 6; i++) {
        if (buffer[i] < '0' || buffer[i] > '9') {
            fprintf(stderr, "Invalid input: Only digits are allowed.\n");
            return -1;
        }
    }

    *code = atoi(buffer);
    return 0;
}

// Code validation function
int validate_code(int generated_code, int entered_code) {
    return (generated_code == entered_code);
}

// Door unlock function
int unlock_door(int door) {
    struct gpiod_line *line = (door == 1) ? gpio_line_a : gpio_line_b;
    if (!line) {
        fprintf(stderr, "Invalid door number: %d\n", door);
        return -1;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO line %d high\n", (door == 1) ? GPIO_DOOR_A : GPIO_DOOR_B);
        return -1;
    }

    usleep(UNLOCK_DURATION_MS * 1000); // Convert milliseconds to microseconds

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO line %d low\n", (door == 1) ? GPIO_DOOR_A : GPIO_DOOR_B);
        return -1;
    }

    return 0;
}

// Access log function
int log_access(int code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(ACCESS_LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", ACCESS_LOG_FILE);
            return -1;
        }
    }

    fprintf(log_file, "%s,%06d\n", timestamp, code);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (gpio_line_a) {
        gpiod_line_release(gpio_line_a);
    }
    if (gpio_line_b) {
        gpiod_line_release(gpio_line_b);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    int generated_code, entered_code;
    int retries = 0;

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        return EXIT_FAILURE;
    }

    // Initialize I2C
    if (i2c_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Generate code
        if (generate_code(&generated_code) < 0) {
            fprintf(stderr, "Error generating code\n");
            break;
        }
        printf("Generated code: %06d\n", generated_code);

        // Read code
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_code(&entered_code) < 0) {
                retries++;
                usleep(RETRY_DELAY_MS * 1000); // Wait before retrying
                continue;
            }
            break; // Exit retry loop if read is successful
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached. Access denied.\n");
            continue; // Skip to the next iteration
        }

        // Validate code
        if (validate_code(generated_code, entered_code)) {
            printf("Access granted!\n");

            // Unlock door A
            if (unlock_door(1) < 0) {
                fprintf(stderr, "Error unlocking door A\n");
            }

            // Log access
            if (log_access(generated_code) < 0) {
                fprintf(stderr, "Error logging access\n");
            }
        } else {
            printf("Access denied.\n");
        }

        // Delay before next attempt
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

