    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Light sensor logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_value;
        int retries = 0;
        int read_success = 0;

        while (retries < MAX_RETRIES && !read_success) {
            if (read_bh1750(&raw_value) == 0) {
                read_success = 1;
            } else {
                fprintf(stderr, "Retrying I2C read (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(10); // Small delay before retrying
            }
        }

        if (read_success) {
