#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000000
#define TCP_PORT 12345
#define SHARED_SECRET "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define MOTION_COMMAND "MOTION_DETECTED:"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int mpr121_read_touch_status(int i2c_handle);
int authenticate_command(const char *command);
void play_tone(int frequency);
void log_frequency(int frequency);
void signal_handler(int signal);
void cleanup();

// MPR121 Initialization
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Electrode configuration
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode 0 to Touch and Release thresholds
        fprintf(stderr, "Error: Electrode config failed\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x5F, 0x0C) < 0) { // Set Electrode 0 to Touch and Release thresholds
        fprintf(stderr, "Error: Electrode config failed\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Enable electrodes failed\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x5B, 0x06) < 0) { // Set Release threshold
        fprintf(stderr, "Error: Set Release threshold failed\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x5C, 0x06) < 0) { // Set Touch threshold
        fprintf(stderr, "Error: Set Touch threshold failed\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Enable electrodes failed\n");
        return -1;
    }

    return 0;
}

// MPR121 Touch Status Reading
int mpr121_read_touch_status(int i2c_handle) {
    int touch_status = i2cReadWordData(i2c_handle, 0x00);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    return touch_status;
}

// Authentication Function
int authenticate_command(const char *command) {
    if (strncmp(command, MOTION_COMMAND, strlen(MOTION_COMMAND)) != 0) {
        fprintf(stderr, "Error: Command does not start with MOTION_DETECTED:\n");
        return 0;
    }

    char *secret_start = command + strlen(MOTION_COMMAND);
    if (strstr(secret_start, SHARED_SECRET) == NULL) {
        fprintf(stderr, "Error: Shared secret not found in command\n");
        return 0;
    }

    return 1;
}

// PWM Tone Playback
void play_tone(int frequency) {
    gpioPWM(PWM_GPIO, frequency);
}

// Frequency Logging
void log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Frequency: %d Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    // Stop PWM
    gpioPWM(PWM_GPIO, 0);

    // Close I2C
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close socket
    if (new_socket >= 0) {
        close(new_socket);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM GPIO as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("socket failed");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Listening on port %d...\n", TCP_PORT);

    // Accept connections
    int addrlen = sizeof(address);
    while (!terminate) {
        new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            perror("accept failed");
            cleanup();
            return 1;
        }

        fprintf(stderr, "Connection accepted\n");

        char buffer[1024] = {0};
        ssize_t bytes_received = recv(new_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("recv failed");
            close(new_socket);
            new_socket = -1; // Reset new_socket
            continue; // Continue listening
        }
        buffer[bytes_received] = '\0';

        fprintf(stderr, "Received command: %s\n", buffer);

        // Authenticate command
        if (authenticate_command(buffer)) {
            fprintf(stderr, "Command authenticated\n");

            // Play tone
            play_tone(500);

            // Sample touch values and play frequency
            for (int i = 0; i < 5000; ++i) {
                int touch_status = mpr121_read_touch_status(i2c_handle);
                if (touch_status < 0) {
                    fprintf(stderr, "Error reading touch status, stopping tone\n");
                    break;
                }

                // Determine frequency based on touch status
                int frequency = 500 + (touch_status & 0x01) * 100; // 500Hz or 600Hz

                play_tone(frequency);
                log_frequency(frequency);
                gpioDelay(20); // 20ms delay
            }

            // Stop tone
            play_tone(0);

            fprintf(stderr, "Tone playback complete\n");
        } else {
            fprintf(stderr, "Command not authenticated\n");
        }

        close(new_socket);
        new_socket = -1; // Reset new_socket
    }

    cleanup();
    return 0;
}

