#include <math.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define CTRL_REG4_M 0x22
#define OUT_X_L_M 0x08
#define GPIO_LED 17
#define PWM_FREQUENCY 1000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_magnetometer();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_z_magnitude(int16_t x, int16_t y, int16_t z);
void set_led_brightness(float magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Magnetometer configuration function
int configure_magnetometer() {
    // Enable magnetometer, set data rate to 80 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_M, 0x70) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_M\n");
        return -1;
    }

    // Set gain to +/- 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_M\n");
        return -1;
    }

    return 0;
}

// Magnetometer data reading function
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Magnitude calculation function
float calculate_z_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// LED brightness control function
void set_led_brightness(float magnitude) {
    // Map magnitude to PWM duty cycle (0-1000000)
    int duty_cycle = (int)(magnitude * 1000000.0 / 4096.0); // Assuming max magnitude is around 4096
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;

    gpioPWM(GPIO_LED, duty_cycle);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Configure magnetometer
    if (configure_magnetometer() < 0) {
        cleanup();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_LED, 1000000); // Set PWM range to 0-1000000

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate Z-axis magnitude
            magnitude = calculate_z_magnitude(x, y, z);

            // Set LED brightness
            set_led_brightness(magnitude);
        } else {
            fprintf(stderr, "Error reading magnetometer data, skipping sample\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

