#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Configuration values
#define HMC5883L_CONFIG_A_VALUE 0x70 // 8-average, 15 Hz, normal measurement
#define HMC5883L_CONFIG_B_VALUE 0xA0 // Gain = +/- 1.3 Ga
#define HMC5883L_MODE_CONTINUOUS 0x00 // Continuous measurement mode

// Number of samples for offset calculation
#define NUM_SAMPLES 100

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Configure register A
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, HMC5883L_CONFIG_A_VALUE) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, HMC5883L_CONFIG_B_VALUE) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, HMC5883L_MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; // Set to 0 to avoid garbage values
        data.y = 0;
        data.z = 0;
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to calculate the running average of magnetometer data
void calculate_running_average(magnetometer_data_t *samples, int num_samples, int current_index, magnetometer_data_t *average) {
    double sum_x = 0, sum_y = 0, sum_z = 0;

    for (int i = 0; i < num_samples; i++) {
        sum_x += samples[i].x;
        sum_y += samples[i].y;
        sum_z += samples[i].z;
    }

    average->x = (int16_t)(sum_x / num_samples);
    average->y = (int16_t)(sum_y / num_samples);
    average->z = (int16_t)(sum_z / num_samples);
}

// Function to apply hard iron offsets
magnetometer_data_t apply_hard_iron_offsets(magnetometer_data_t raw_data, magnetometer_data_t offsets) {
    magnetometer_data_t corrected_data;
    corrected_data.x = raw_data.x - offsets.x;
    corrected_data.y = raw_data.y - offsets.y;
    corrected_data.z = raw_data.z - offsets.z;
    return corrected_data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Data storage
    magnetometer_data_t samples[NUM_SAMPLES];
    magnetometer_data_t average_offsets = {0, 0, 0};
    int sample_index = 0;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        magnetometer_data_t raw_data = read_magnetometer_data();

        // Store the raw data in the circular buffer
        samples[sample_index] = raw_data;
        sample_index = (sample_index + 1) % NUM_SAMPLES;

        // Calculate running average after enough samples are collected
        if (sample_index == 0) {
            calculate_running_average(samples, NUM_SAMPLES, sample_index, &average_offsets);
        }

        // Apply hard iron offsets
        magnetometer_data_t corrected_data = apply_hard_iron_offsets(raw_data, average_offsets);

        // Print the corrected data
        printf("X: %d, Y: %d, Z: %d\n", corrected_data.x, corrected_data.y, corrected_data.z);

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

