#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define WHO_AM_I 0x0F

// GPIO pin for interrupt
#define INT1_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_data_t;

// Global variables
int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
acceleration_data_t buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_gpio();
int init_lsm303d();
void read_acceleration(acceleration_data_t *data);
void store_data(acceleration_data_t data);
void dump_buffer();
void interrupt_handler(int signum);
void signal_handler(int signum);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(1, LSM303D_ADDR, 0); // Bus 1, address 0x1D, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Verify device identity
    int who_am_i = i2cReadByteData(i2c_fd, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        return -1;
    }
    if (who_am_i != 0x39) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        i2cClose(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, INT1_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(line, "lsm303d_mon") < 0) {
        fprintf(stderr, "Error requesting rising edge events: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to initialize LSM303D
int init_lsm303d() {
    // Enable accelerometer, 100 Hz data rate, normal mode
    if (i2cWriteByteData(i2c_fd, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_fd, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read acceleration data
void read_acceleration(acceleration_data_t *data) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_fd, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        data->x = 0; // Set to zero to avoid garbage values
        data->y = 0;
        data->z = 0;
        return;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);
}

// Function to store data in the circular buffer
void store_data(acceleration_data_t data) {
    buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to dump the last ten samples from the buffer
void dump_buffer() {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    int start_index = (buffer_index - 10 + BUFFER_SIZE) % BUFFER_SIZE;
    printf("%s\n", timestamp);
    for (int i = 0; i < 10; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        printf("  %d, %d, %d\n", buffer[index].x, buffer[index].y, buffer[index].z);
    }
}

// Interrupt handler function
void interrupt_handler(int signum) {
    dump_buffer();
}

// Signal handler function
void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

// Cleanup function
void cleanup() {
    // Disable accelerometer
    i2cWriteByteData(i2c_fd, CTRL_REG1_A, 0x00);

    // Close I2C device
    i2cClose(i2c_fd);

    // Release GPIO line
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() < 0) {
        i2cClose(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    struct sigaction sa;
    sa.sa_handler = interrupt_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGIO, &sa, NULL) == -1) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    // Main loop
    acceleration_data_t data;
    while (program_running) {
        read_acceleration(&data);
        store_data(data);
        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

