#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Global variable to track the active solenoid
static volatile int active_solenoid = 0;

// Function prototypes
int initialize_gpio();
void set_solenoid_state(int solenoid_gpio, int state);
void switch_solenoid();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up and exiting...\n", signal);
    // Set both solenoid lines to LOW
    set_solenoid_state(SOLENOID_1_GPIO, 0);
    set_solenoid_state(SOLENOID_2_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    // Exit the program
    exit(0);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes for solenoid control
    gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to set the state of a solenoid (HIGH or LOW)
void set_solenoid_state(int solenoid_gpio, int state) {
    int result = gpioWrite(solenoid_gpio, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", solenoid_gpio, result);
    }
}

// Function to switch the active solenoid
void switch_solenoid() {
    if (active_solenoid == 0) {
        // Turn off solenoid 1
        set_solenoid_state(SOLENOID_1_GPIO, 0);
        // Turn on solenoid 2
        set_solenoid_state(SOLENOID_2_GPIO, 1);
        active_solenoid = 1;
    } else {
        // Turn off solenoid 2
        set_solenoid_state(SOLENOID_2_GPIO, 0);
        // Turn on solenoid 1
        set_solenoid_state(SOLENOID_1_GPIO, 1);
        active_solenoid = 0;
    }
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Ensure both solenoids are initially LOW
    set_solenoid_state(SOLENOID_1_GPIO, 0);
    set_solenoid_state(SOLENOID_2_GPIO, 0);

    // Main loop to alternately activate solenoids
    while (1) {
        switch_solenoid();
        // Delay for 500 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0; // This line will never be reached due to the infinite loop
}

