#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME_MS 1000
#define CONTINUOUS_HIGH_THRESHOLD_S 10

// Global variables
static volatile int running = 1;
static int failsafe_timer_id = -1;
static int last_pir_state = 0; // 0: LOW, 1: HIGH
static time_t last_pir_high_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int activate_relay(int duration_ms);
int deactivate_relay();
void log_event(int priority, const char *message);
void signal_handler(int signal);
void failsafe_callback(int timer_id, void *user_data);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set PIR sensor pin as input");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay pin as output");
        gpioTerminate();
        return -1;
    }

    // Ensure relay is initially off
    deactivate_relay();

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to activate the relay
int activate_relay(int duration_ms) {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to activate relay");
        return -1;
    }
    log_event(LOG_INFO, "Relay activated");
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
    return 0;
}

// Function to deactivate the relay
int deactivate_relay() {
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay");
        return -1;
    }
    log_event(LOG_INFO, "Relay deactivated");
    return 0;
}

// Function to log events to syslog
void log_event(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event(LOG_INFO, "Received signal, shutting down...");

    // Cancel the failsafe timer if it's running
    if (failsafe_timer_id != -1) {
        gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable the timer
        failsafe_timer_id = -1;
    }

    // Deactivate the relay
    deactivate_relay();

    // Release GPIO resources
    gpioTerminate();

    log_event(LOG_INFO, "Shutdown complete");
    closelog();
    exit(0);
}

// Failsafe callback function
void failsafe_callback(int timer_id, void *user_data) {
    log_event(LOG_WARNING, "PIR sensor malfunction detected! Deactivating relay.");
    deactivate_relay();
    log_event(LOG_WARNING, "Shutdown event");
    running = 0;
    signal_handler(SIGTERM); // Simulate a SIGTERM to trigger shutdown
}

int main() {
    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event(LOG_INFO, "Motion detector started");

    // Main loop
    while (running) {
        int pir_state = read_pir_sensor();

        if (pir_state == 1) {
            if (last_pir_state == 0) {
                log_event(LOG_INFO, "Motion detected!");
                if (activate_relay(RELAY_ON_TIME_MS) != 0) {
                    log_event(LOG_ERR, "Failed to activate relay, shutting down");
                    signal_handler(SIGTERM);
                }
                last_pir_high_time = time(NULL);
            }
            last_pir_state = 1;
        } else {
            last_pir_state = 0;
        }

        // Check for continuous HIGH state
        if (last_pir_state == 1) {
            time_t current_time = time(NULL);
            double time_diff = difftime(current_time, last_pir_high_time);

            if (time_diff >= CONTINUOUS_HIGH_THRESHOLD_S) {
                // Start the failsafe timer if it's not already running
                if (failsafe_timer_id == -1) {
                    failsafe_timer_id = 1; // Dummy ID, not actually used
                    gpioSetTimerFuncEx(0, 1, failsafe_callback, NULL); // Trigger after 1 second
                    log_event(LOG_INFO, "Starting failsafe timer");
                }
            } else {
                // Reset the failsafe timer if the PIR is still HIGH
                if (failsafe_timer_id != -1) {
                    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable the timer
                    failsafe_timer_id = -1;
                    log_event(LOG_INFO, "Resetting failsafe timer");
                }
            }
        } else {
            // Reset the failsafe timer if the PIR is LOW
            if (failsafe_timer_id != -1) {
                gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable the timer
                failsafe_timer_id = -1;
                log_event(LOG_INFO, "Resetting failsafe timer");
            }
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    // This point should not be reached unless running is set to 0 by the signal handler
    closelog();
    return 0;
}

