#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the irrigation cycle duration (seconds)
#define IRRIGATION_DURATION 300

// Define the pause duration between cycles (seconds)
#define PAUSE_DURATION 60

// Define the timer interval (seconds)
#define TIMER_INTERVAL 60

// Global variable to store the current relay state
volatile int current_relay = 0;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
void initialize_gpio();
void deactivate_all_relays();
void log_message(int priority, const char *message);
void timer_callback();
void signal_handler(int signal);

// Function to initialize the GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins as outputs and set them HIGH (OFF) initially
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    log_message(LOG_INFO, "GPIO pins initialized");
}

// Function to deactivate all relays (set them HIGH)
void deactivate_all_relays() {
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);
    log_message(LOG_INFO, "All relays deactivated");
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: %s", timestamp, message);

    syslog(priority, "%s", log_entry);
}

// Timer callback function
void timer_callback() {
    // Activate the current relay
    int relay_pin;
    switch (current_relay) {
        case 0:
            relay_pin = RELAY1_PIN;
            break;
        case 1:
            relay_pin = RELAY2_PIN;
            break;
        case 2:
            relay_pin = RELAY3_PIN;
            break;
        case 3:
            relay_pin = RELAY4_PIN;
            break;
        default:
            log_message(LOG_ERR, "Invalid relay state");
            return;
    }

    char message[64];
    snprintf(message, sizeof(message), "Activating relay %d", current_relay + 1);
    log_message(LOG_INFO, message);
    gpioWrite(relay_pin, 0); // Set LOW to activate the relay

    // Wait for the irrigation duration
    gpioDelay(IRRIGATION_DURATION * 1000000); // Convert seconds to microseconds

    // Deactivate the current relay
    gpioWrite(relay_pin, 1); // Set HIGH to deactivate the relay

    snprintf(message, sizeof(message), "Deactivating relay %d", current_relay + 1);
    log_message(LOG_INFO, message);

    // Increment the current relay state and wrap around if necessary
    current_relay = (current_relay + 1) % 4;

    // Wait for the pause duration
    gpioDelay(PAUSE_DURATION * 1000000); // Convert seconds to microseconds
}

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, terminating program");
    terminate = 1;
}

int main() {
    // Open syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    initialize_gpio();

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer
    if (gpioSetTimerFunc(0, TIMER_INTERVAL, timer_callback) != 0) {
        log_message(LOG_ERR, "Failed to set timer function");
        deactivate_all_relays();
        closelog();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Irrigation system started");

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up and exit
    deactivate_all_relays();
    log_message(LOG_INFO, "Irrigation system stopped");
    closelog();
    gpioTerminate();

    return EXIT_SUCCESS;
}

