#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <sys/types.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_ZOUT_H 0x3F

// Sensor Addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// Circular Buffer Size
#define BUFFER_SIZE 100

// Data Structure for Acceleration Data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelData;

// Circular Buffer Structure
typedef struct {
    AccelData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global Variables
int i2c_fd;
CircularBuffer buffer1, buffer2;
int running = 1;

// Function Prototypes
int init_i2c(int address);
int read_accel_data(int fd, AccelData *data);
void add_to_buffer(CircularBuffer *buffer, AccelData data);
int get_latest_data(CircularBuffer *buffer, AccelData *data);
void signal_handler(int sig);
int create_sysfs_entry(const char *path);
int write_sysfs_entry(const char *path, const char *value);
int remove_sysfs_entry(const char *path);

// I2C Initialization Function
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Wake up the MPU6050
    uint8_t wake_up_value = 0;
    if (write(fd, &wake_up_value, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to Read Acceleration Data from MPU6050
int read_accel_data(int fd, AccelData *data) {
    uint8_t reg = MPU6050_ACCEL_XOUT_H;
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to Add Data to the Circular Buffer
void add_to_buffer(CircularBuffer *buffer, AccelData data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to Get the Latest Data from the Circular Buffer
int get_latest_data(CircularBuffer *buffer, AccelData *data) {
    if (buffer->count == 0) {
        return -1; // Buffer is empty
    }
    int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    *data = buffer->data[index];
    return 0;
}

// Signal Handler Function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

// Function to Create a Sysfs Entry
int create_sysfs_entry(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        perror("Error creating sysfs entry");
        return -1;
    }
    close(fd);
    return 0;
}

// Function to Write to a Sysfs Entry
int write_sysfs_entry(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening sysfs entry for writing");
        return -1;
    }
    ssize_t bytes_written = write(fd, value, strlen(value));
    if (bytes_written < 0) {
        perror("Error writing to sysfs entry");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to Remove a Sysfs Entry
int remove_sysfs_entry(const char *path) {
    if (unlink(path) < 0) {
        perror("Error removing sysfs entry");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize Circular Buffers
    buffer1.head = 0;
    buffer1.count = 0;
    buffer2.head = 0;
    buffer2.count = 0;

    // Register Signal Handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(SENSOR1_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1. Exiting.\n");
        return 1;
    }

    // Create Sysfs Entry
    if (create_sysfs_entry("/sys/kernel/mpu6050_accel/latest") < 0) {
        fprintf(stderr, "Failed to create sysfs entry. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Configure Timer
    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGUSR1;
    sev.sigev_value.sival_int = 0; // Not used in this example

    int timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        perror("Error creating timerfd");
        close(i2c_fd);
        remove_sysfs_entry("/sys/kernel/mpu6050_accel/latest");
        return 1;
    }

    struct itimerspec its;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10ms (100Hz)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10ms (100Hz)

    if (timerfd_settime(timer_fd, 0, &its, NULL) < 0) {
        perror("Error setting timerfd time");
        close(i2c_fd);
        remove_sysfs_entry("/sys/kernel/mpu6050_accel/latest");
        close(timer_fd);
        return 1;
    }

    // Main Loop
    while (running) {
        AccelData data;
        if (read_accel_data(i2c_fd, &data) == 0) {
            add_to_buffer(&buffer1, data);

            // Write data to sysfs
            char buffer[256];
            snprintf(buffer, sizeof(buffer), "%d %d %d", data.x, data.y, data.z);
            if (write_sysfs_entry("/sys/kernel/mpu6050_accel/latest", buffer) < 0) {
                fprintf(stderr, "Error writing to sysfs entry. Continuing.\n");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Continuing.\n");
        }

        // Simulate another sensor
        int sensor2_fd = init_i2c(SENSOR2_ADDR);
        if (sensor2_fd >= 0) {
            if (read_accel_data(sensor2_fd, &data) == 0) {
                add_to_buffer(&buffer2, data);
            } else {
                fprintf(stderr, "Error reading acceleration data from sensor 2. Continuing.\n");
            }
            close(sensor2_fd);
        } else {
            fprintf(stderr, "Failed to initialize I2C for sensor 2. Continuing.\n");
        }

        // Wait for the timer signal
        siginfo_t si;
        sigset_t set;
        sigemptyset(&set);
        sigaddset(&set, SIGUSR1);
        if (sigwaitinfo(&set, &si) < 0) {
            perror("Error waiting for signal");
            break;
        }
    }

    // Cleanup
    close(i2c_fd);
    remove_sysfs_entry("/sys/kernel/mpu6050_accel/latest");
    close(timer_fd);

    return 0;
}

