        remove_sysfs_entry("/sys/kernel/mpu6050_accel/latest");
        return 1;
    }

    struct itimerspec its;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10ms (100Hz)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10ms (100Hz)

    if (timerfd_settime(timer_fd, 0, &its, NULL) < 0) {
        perror("Error setting timerfd time");
        close(i2c_fd);
        remove_sysfs_entry("/sys/kernel/mpu6050_accel/latest");
        close(timer_fd);
        return 1;
    }

    // Main Loop
    while (running) {
        AccelData data;
        if (read_accel_data(i2c_fd, &data) == 0) {
            add_to_buffer(&buffer1, data);

            // Write data to sysfs
            char buffer[256];
            snprintf(buffer, sizeof(buffer), "%d %d %d", data.x, data.y, data.z);
            if (write_sysfs_entry("/sys/kernel/mpu6050_accel/latest", buffer) < 0) {
                fprintf(stderr, "Error writing to sysfs entry. Continuing.\n");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Continuing.\n");
        }

        // Simulate another sensor
        int sensor2_fd = init_i2c(SENSOR2_ADDR);
        if (sensor2_fd >= 0) {
            if (read_accel_data(sensor2_fd, &data) == 0) {
                add_to_buffer(&buffer2, data);
            } else {
                fprintf(stderr, "Error reading acceleration data from sensor 2. Continuing.\n");
            }
            close(sensor2_fd);
        } else {
            fprintf(stderr, "Failed to initialize I2C for sensor 2. Continuing.\n");
        }

        // Wait for the timer signal
        siginfo_t si;
        sigset_t set;
        sigemptyset(&set);
        sigaddset(&set, SIGUSR1);
        if (sigwaitinfo(&set, &si) < 0) {
            perror("Error waiting for signal");
            break;
        }
    }

    // Cleanup
    close(i2c_fd);
    remove_sysfs_entry("/sys/kernel/mpu6050_accel/latest");
    close(timer_fd);

    return 0;
}

