// Define GPIO pins for the relays
#define RELAY1_GPIO 18
#define RELAY2_GPIO 23
#define RELAY3_GPIO 24
#define RELAY4_GPIO 25

// Define prime number intervals
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void toggle_relay(int gpio_pin, int interval_seconds);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold relay information
typedef struct {
    int gpio_pin;
    int interval_seconds;
} RelayConfig;

// Array of relay configurations
RelayConfig relays[] = {
    {RELAY1_GPIO, INTERVAL1},
    {RELAY2_GPIO, INTERVAL2},
    {RELAY3_GPIO, INTERVAL3},
    {RELAY4_GPIO, INTERVAL4}
};

int num_relays = sizeof(relays) / sizeof(relays[0]);

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to toggle relays
    while (program_running) {
        for (int i = 0; i < num_relays; i++) {
            toggle_relay(relays[i].gpio_pin, relays[i].interval_seconds);
        }
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < num_relays; i++) {
        gpioSetMode(relays[i].gpio_pin, PI_OUTPUT);
        gpioWrite(relays[i].gpio_pin, 0); // Initialize all relays to OFF
    }

    return 0;
}

// Function to toggle a relay for a specified interval
void toggle_relay(int gpio_pin, int interval_seconds) {
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Turn the relay ON
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        program_running = 0; // Stop the program on error
        return;
    }

    // Wait for the specified interval
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;
        if (elapsed_time >= interval_seconds) {
            break;
        }
        gpioDelay(1000); // Small delay to avoid busy-waiting
    }

    // Turn the relay OFF
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        program_running = 0; // Stop the program on error
        return;
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // Turn off all relays
    for (int i = 0; i < num_relays; i++) {
        gpioWrite(relays[i].gpio_pin, 0);
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("GPIO resources released. Exiting.\n");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

