#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define POLLING_INTERVAL_MS 100
#define RELAY_ACTIVATION_TIME_S 3
#define DEBOUNCE_COOLDOWN_S 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize();
int read_sound_sensor();
int activate_relay();
int log_event();
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    time_t last_activation_time;
} ProgramState;

ProgramState state = {0};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound-activated relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            time_t now = time(NULL);
            if (difftime(now, state.last_activation_time) >= DEBOUNCE_COOLDOWN_S) {
                if (activate_relay() == 0) {
                    log_event();
                    state.last_activation_time = now;
                } else {
                    fprintf(stderr, "Failed to activate relay.\n");
                }
            } else {
                printf("Sound detected, but debounce/cooldown active.\n");
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("alarm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

int activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(RELAY_ACTIVATION_TIME_S * 1000000); // Wait for 3 seconds
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    return 0;
}

int log_event() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Relay activated\n", buf);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }
}

void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

void cleanup() {
    // Deactivate relay
    gpioWrite(RELAY_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

