#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// MPU6050 Registers
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_ZOUT_H 0x47

// Sensitivity scale factor
#define GYRO_SCALE 131.0f // For +/- 250 degrees/second range

// Circular buffer size
#define BUFFER_SIZE 100

// Threshold for angular velocity
#define THRESHOLD 50.0f

// Global variables
int i2c_fd = -1;
bool running = true;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c(int address);
int read_mpu6050_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float calculate_angular_velocity(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void add_to_buffer(CircularBuffer *cb, float value);
float get_average(CircularBuffer *cb);
void callback_function(float angular_velocity);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Wake up the MPU6050
    uint8_t wake_up_value = 0;
    if (write(fd, &wake_up_value, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Read gyroscope data from MPU6050
int read_mpu6050_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t reg = MPU6050_GYRO_XOUT_H;
    uint8_t data[6];

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, data, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    *gyro_x = (int16_t)((data[0] << 8) | data[1]);
    *gyro_y = (int16_t)((data[2] << 8) | data[3]);
    *gyro_z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Calculate angular velocity magnitude
float calculate_angular_velocity(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    float x = (float)gyro_x / GYRO_SCALE;
    float y = (float)gyro_y / GYRO_SCALE;
    float z = (float)gyro_z / GYRO_SCALE;
    return sqrt(x * x + y * y + z * z);
}

// Add data to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the data in the circular buffer
float get_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Callback function to handle threshold exceedance
void callback_function(float angular_velocity) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("%s: Angular velocity exceeded threshold: %.2f degrees/second\n", buf, angular_velocity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to close I2C and release resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main() {
    // Initialize circular buffer
    CircularBuffer gyro_buffer = {{0.0f}, 0, 0};

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    printf("MPU6050 data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int16_t gyro_x, gyro_y, gyro_z;

        // Read gyroscope data
        if (read_mpu6050_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate angular velocity
            float angular_velocity = calculate_angular_velocity(gyro_x, gyro_y, gyro_z);

            // Add to circular buffer
            add_to_buffer(&gyro_buffer, angular_velocity);

            // Check if threshold is exceeded
            if (angular_velocity > THRESHOLD) {
                callback_function(angular_velocity);
            }
        } else {
            fprintf(stderr, "Failed to read MPU6050 data. Retrying.\n");
        }

        // Sleep for a short interval
        usleep(10000); // 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

