#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/select.h>

// Define the UART device
#define UART_DEVICE "/dev/serial0"

// Define the baud rate
#define BAUD_RATE B9600

// Define the command to initiate a measurement
const unsigned char command[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};

// Define the expected response length
#define EXPECTED_RESPONSE_LENGTH 9

// Define the log file names
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"

// Define the retry timeout in milliseconds
#define RETRY_TIMEOUT_MS 1000

// Define the sampling interval in seconds
#define SAMPLING_INTERVAL_SEC 5

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold the sensor data
typedef struct {
    unsigned int co2;
    int error;
} sensor_data_t;

// Function prototypes
int init_uart(const char *device, speed_t baud_rate);
int send_command(int fd, const unsigned char *command, int command_len);
int read_response(int fd, unsigned char *response, int response_len, int timeout_ms);
unsigned char calculate_checksum(const unsigned char *data, int len);
int validate_checksum(const unsigned char *response);
sensor_data_t parse_response(const unsigned char *response);
char* format_json(unsigned int co2, int error);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize the UART
int init_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Send the measurement command to the sensor
int send_command(int fd, const unsigned char *command, int command_len) {
    ssize_t bytes_written = write(fd, command, command_len);
    if (bytes_written != command_len) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read the sensor response
int read_response(int fd, unsigned char *response, int response_len, int timeout_ms) {
    fd_set readfds;
    struct timeval tv;
    int retval;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    tv.tv_sec = timeout_ms / 1000;
    tv.tv_usec = (timeout_ms % 1000) * 1000;

    retval = select(fd + 1, &readfds, NULL, NULL, &tv);

    if (retval == -1) {
        perror("select()");
        return -1;
    } else if (retval) {
        ssize_t bytes_read = read(fd, response, response_len);
        if (bytes_read != response_len) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        return 0;
    } else {
        fprintf(stderr, "Timeout reading from UART\n");
        return -1;
    }
}

// Calculate the checksum
unsigned char calculate_checksum(const unsigned char *data, int len) {
    unsigned char checksum = 0;
    for (int i = 0; i < len - 1; i++) {
        checksum += data[i];
    }
    return checksum;
}

// Validate the checksum
int validate_checksum(const unsigned char *response) {
    unsigned char checksum = calculate_checksum(response, EXPECTED_RESPONSE_LENGTH);
    return (checksum == response[EXPECTED_RESPONSE_LENGTH - 1]);
}

// Parse the sensor response
sensor_data_t parse_response(const unsigned char *response) {
    sensor_data_t data;
    data.error = 0;

    if (!validate_checksum(response)) {
        data.error = 1;
        data.co2 = 0; // Set CO2 to 0 on checksum error
        return data;
    }

    data.co2 = (response[2] << 8) | response[3];
    return data;
}

// Format the data as a JSON string
char* format_json(unsigned int co2, int error) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv.tv_sec, tv.tv_usec);

    char *json_string = malloc(200); // Allocate memory for the JSON string
    if (json_string == NULL) {
        perror("malloc failed");
        return NULL;
    }

    snprintf(json_string, 200, "{\"timestamp\": \"%s\", \"co2\": %u, \"error\": %d}\n", timestamp, co2, error);
    return json_string;
}

// Log an error message to the error log file
void log_error(const char *message) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv.tv_sec, tv.tv_usec);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to initialize UART. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        return 1;
    }

    // Open the error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Error opening error log file");
        fclose(log_file);
        close(uart_fd);
        return 1;
    }

    printf("CO2 Monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        unsigned char response[EXPECTED_RESPONSE_LENGTH];
        int retry_count = 0;
        int read_success = 0;

        // Retry reading the response until the timeout expires
        while (retry_count < (RETRY_TIMEOUT_MS / 100)) {
            if (send_command(uart_fd, command, sizeof(command)) == 0) {
                if (read_response(uart_fd, response, EXPECTED_RESPONSE_LENGTH, 100) == 0) {
                    read_success = 1;
                    break;
                }
            }
            retry_count++;
            usleep(100000); // Wait 100ms before retrying
        }

        if (read_success) {
            sensor_data_t sensor_data = parse_response(response);

            if (sensor_data.error) {
                log_error("Checksum mismatch or other error");
            } else {
                char *json_string = format_json(sensor_data.co2, sensor_data.error);
                if (json_string != NULL) {
                    fprintf(log_file, "%s", json_string);
                    fflush(log_file);
                    printf("%s", json_string);
                    free(json_string);
                } else {
                    log_error("Failed to format JSON");
                }
            }
        } else {
            log_error("Failed to read response from sensor");
        }

        sleep(SAMPLING_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }

    printf("CO2 Monitor terminated.\n");
    return 0;
}

