#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define GPIO_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Hard iron offsets
#define X_OFFSET 100
#define Y_OFFSET -50

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_hmc5883l();
int16_t read_axis(int axis);
float calculate_heading(int16_t x, int16_t y);
void add_to_buffer(CircularBuffer *cb, float value);
float get_average(CircularBuffer *cb);
void control_gpio(float heading);
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize the HMC5883L magnetometer
int init_hmc5883l() {
    // Set continuous measurement mode
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE register: %s\n", strerror(errno));
        return -1;
    }

    // Set gain (example: +/- 1.3 Ga)
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B register: %s\n", strerror(errno));
        return -1;
    }

    // Set measurement mode (continuous)
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read a single axis value from the HMC5883L
int16_t read_axis(int axis) {
    int16_t msb, lsb;

    msb = wiringPiI2CReadReg8(i2c_fd, axis);
    if (msb < 0) {
        fprintf(stderr, "Error reading MSB from axis 0x%02X: %s\n", axis, strerror(errno));
        return 0; // Return 0 on error
    }

    lsb = wiringPiI2CReadReg8(i2c_fd, axis + 1);
    if (lsb < 0) {
        fprintf(stderr, "Error reading LSB from axis 0x%02X: %s\n", axis + 1, strerror(errno));
        return 0; // Return 0 on error
    }

    return (msb << 8) | lsb;
}

// Calculate the heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y - Y_OFFSET, x - X_OFFSET) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float get_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control the GPIO pin based on the heading
void control_gpio(float heading) {
    float diff = fabs(heading - TARGET_HEADING);
    if (diff > 10.0) {
        digitalWrite(GPIO_PIN, HIGH);
    } else {
        digitalWrite(GPIO_PIN, LOW);
