#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_HIGH 300.0
#define LOG_FILE "lighting_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
float read_bh1750();
void set_relay_state(int gpio, int state);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(RED_GPIO, PI_OUTPUT);
    gpioSetMode(GREEN_GPIO, PI_OUTPUT);
    gpioSetMode(BLUE_GPIO, PI_OUTPUT);

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Failed to set BH1750 mode\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read BH1750 sensor
float read_bh1750() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from BH1750: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return (float)raw_value / 1.2;
}

// Set relay state
void set_relay_state(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log data to file
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%d,%d,%d\n", timestamp, lux, red_state, green_state, blue_state);
    fflush(log_file);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    set_relay_state(RED_GPIO, 0);
    set_relay_state(GREEN_GPIO, 0);
    set_relay_state(BLUE_GPIO, 0);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Starting lighting control...\n");

    while (!terminate) {
        float lux = read_bh1750();
        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            gpioDelay(100000); // 100ms
            continue;
        }

        int red_state = 0, green_state = 0, blue_state = 0;

        if (lux < LUX_THRESHOLD_LOW) {
            red_state = 1;
        } else if (lux >= LUX_THRESHOLD_LOW && lux <= 150.0) {
            green_state = 1;
        } else if (lux > 150.0 && lux <= LUX_THRESHOLD_HIGH) {
            blue_state = 1;
        } else if (lux > LUX_THRESHOLD_HIGH) {
            red_state = 1;
            green_state = 1;
            blue_state = 1;
        }

        set_relay_state(RED_GPIO, red_state);
        set_relay_state(GREEN_GPIO, green_state);
        set_relay_state(BLUE_GPIO, blue_state);

        log_data(lux, red_state, green_state, blue_state);

        gpioDelay(1000000); // 1 second
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

