#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM Frequency
#define PWM_FREQUENCY 1000

// Proportional Gain
#define KP 0.5

// Target Distance
#define TARGET_DISTANCE 50.0

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_motor_speed(int motor_in1, int motor_in2, int speed);
int stop_motor(int motor_in1, int motor_in2);
int cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and cleaning up...\n", signal);
    stop_motor(MOTOR_A_IN1, MOTOR_A_IN2);
    stop_motor(MOTOR_B_IN3, MOTOR_B_IN4);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set motor control pins as outputs
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    return 0;
}

// Set motor speed using PWM
int set_motor_speed(int motor_in1, int motor_in2, int speed) {
    if (speed < 0 || speed > 255) {
        fprintf(stderr, "Invalid speed value: %d\n", speed);
        return -1;
    }

    gpioWrite(motor_in1, 1); // Forward
    gpioPWM(motor_in2, speed);

    return 0;
}

// Stop the motor
int stop_motor(int motor_in1, int motor_in2) {
    gpioWrite(motor_in1, 0);
    gpioPWM(motor_in2, 0);
    return 0;
}

// Cleanup GPIO
int cleanup_gpio() {
    gpioTerminate();
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        return 1;
    }

    float distance_motor_a = atof(argv[1]);
    float distance_motor_b = atof(argv[2]);

    if (distance_motor_a < 10.0 || distance_motor_a > 100.0 || distance_motor_b < 10.0 || distance_motor_b > 100.0) {
        fprintf(stderr, "Distance values must be between 10 and 100 cm\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Motor control started. Press Ctrl+C to stop.\n");

    while (program_running) {
        // Motor A control
        int speed_a = (int)(KP * (TARGET_DISTANCE - distance_motor_a));
        if (speed_a < 0) {
            speed_a = 0;
        } else if (speed_a > 255) {
            speed_a = 255;
        }
        set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, speed_a);

        // Motor B control
        int speed_b = (int)(KP * (TARGET_DISTANCE - distance_motor_b));
        if (speed_b < 0) {
            speed_b = 0;
        } else if (speed_b > 255) {
            speed_b = 255;
        }
        set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, speed_b);

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    stop_motor(MOTOR_A_IN1, MOTOR_A_IN2);
    stop_motor(MOTOR_B_IN3, MOTOR_B_IN4);
    cleanup_gpio();

    return 0;
}

