#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_GYRO_XOUT_H 0x43

// Servo GPIO pin (BCM)
#define SERVO_GPIO 18

// PWM chip and channel
#define PWM_CHIP 2
#define PWM_CHANNEL 0

// PWM period (microseconds)
#define PWM_PERIOD 20000

// PWM duty cycle range (microseconds)
#define PWM_MIN_DUTY 1000
#define PWM_MAX_DUTY 2000

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int init_i2c(int address);
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
double calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z);
double calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z);
int set_servo_angle(int gpio, double angle);
int log_data(double pitch, double roll, int servo_position);
void signal_handler(int signal);

// I2C initialization function
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Wake up the MPU6050
    uint8_t data = 0;
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from MPU6050
int read_mpu6050_data(int fd, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[14];
    uint8_t reg = MPU6050_REG_ACCEL_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, buffer, 14) != 14) {
        perror("Error reading from I2C device");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

// Function to calculate pitch
double calculate_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    double pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    return pitch;
}

// Function to calculate roll
double calculate_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    double roll = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
    return roll;
}

// Function to set servo angle using pigpio
int set_servo_angle(int gpio, double angle) {
    if (angle < -90.0 || angle > 90.0) {
        fprintf(stderr, "Error: Angle out of range (-90 to 90 degrees)\n");
        return -1;
    }

    // Map angle to PWM duty cycle
    int duty_cycle = (int)(((angle + 90.0) / 180.0) * (PWM_MAX_DUTY - PWM_MIN_DUTY) + PWM_MIN_DUTY);

    gpioPWM(gpio, duty_cycle);

    return duty_cycle;
}

// Function to log data to file
int log_data(double pitch, double roll, int servo_position) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_position);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set servo GPIO as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(SERVO_GPIO, 50); // 50 Hz
    gpioSetPWMrange(SERVO_GPIO, PWM_PERIOD);

    // Open log file
    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    double pitch, roll;
    int servo_position;
    int retries = 0;
    const int max_retries = 5;
    int delay_ms = 10;

    // Main loop
    while (running) {
        // Read MPU6050 data with retries
        if (read_mpu6050_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate pitch and roll
            pitch = calculate_pitch(accel_x, accel_y, accel_z);
            roll = calculate_roll(accel_x, accel_y, accel_z);

            // Set servo angle
            servo_position = set_servo_angle(SERVO_GPIO, pitch);

            // Log data
            log_data(pitch, roll, servo_position);

            retries = 0; // Reset retries on success
        } else {
            fprintf(stderr, "Error reading MPU6050 data, retrying...\n");
            retries++;
            if (retries > max_retries) {
                fprintf(stderr, "Max retries reached, exiting...\n");
                running = false;
            } else {
                usleep(delay_ms * 1000); // Exponential backoff
                delay_ms *= 2;
            }
        }

        usleep(50000); // 50ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

