            retries++;
            if (retries > max_retries) {
                fprintf(stderr, "Max retries reached, exiting...\n");
                running = false;
            } else {
                usleep(delay_ms * 1000); // Exponential backoff
                delay_ms *= 2;
            }
        }

        usleep(50000); // 50ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

