int initialize_gpio();
int read_schedule(schedule_entry_t *schedule, int *num_entries);
int parse_schedule_line(char *line, schedule_entry_t *entry);
int set_relay_state(int relay_number, int state);
int fade_lamp(int relay_number, int start_duty_cycle, int end_duty_cycle, int duration_seconds);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
