    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    return 0;
}

// Read schedule from file
int read_schedule(schedule_entry_t *schedule, int *num_entries) {
    FILE *fp = fopen(SCHEDULE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return 1;
    }

    char line[256];
    *num_entries = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (parse_schedule_line(line, &schedule[*num_entries]) != 0) {
            fprintf(stderr, "Error parsing schedule line\n");
            fclose(fp);
            return 1;
        }
        (*num_entries)++;
    }

    fclose(fp);
    return 0;
}

