    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return 1;
    }

    gpioWrite(pin, state);
    return 0;
}

