int fade_lamp(int relay_number, int start_duty_cycle, int end_duty_cycle, int duration_seconds) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return 1;
    }

    int steps = duration_seconds * PWM_FREQUENCY; // Number of PWM steps
    int duty_cycle_increment = (end_duty_cycle - start_duty_cycle) / steps;
    int current_duty_cycle = start_duty_cycle;

    for (int i = 0; i < steps; i++) {
        if (!running) return 0; // Exit if signal received
        gpioPWM(pin, current_duty_cycle);
        current_duty_cycle += duty_cycle_increment;
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for PWM frequency
    }

    gpioPWM(pin, end_duty_cycle); // Ensure final duty cycle is set
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

