    if (initialize_gpio() != 0) {
        return 1;
    }

    // Read schedule
    schedule_entry_t schedule[100]; // Assuming a maximum of 100 entries
    int num_entries;
    if (read_schedule(schedule, &num_entries) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Number of schedule entries: %d\n", num_entries);

    // Main loop
    while (running) {
        time_t now = time(NULL);
        struct tm *current_time = localtime(&now);

        for (int i = 0; i < num_entries; i++) {
            if (schedule[i].hour == current_time->tm_hour &&
                schedule[i].minute == current_time->tm_min &&
                schedule[i].second == current_time->tm_sec) {

                printf("Executing schedule entry: Relay %d, State %d\n", schedule[i].relay_number, schedule[i].state);

                if (schedule[i].state == 1) {
                    // Turn on relay and fade in
                    set_relay_state(schedule[i].relay_number, 1);
                    fade_lamp(schedule[i].relay_number, 0, 100, FADE_DURATION);
                } else {
                    // Fade out and turn off relay
                    fade_lamp(schedule[i].relay_number, 100, 0, FADE_DURATION);
                    set_relay_state(schedule[i].relay_number, 0);
                }
            }
        }

        gpioDelay(1000); // Check every second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

