#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum measurable distance (cm)
#define MAX_DISTANCE 200.0     // Maximum measurable distance (cm)
#define MIN_FREQUENCY 200.0    // Minimum buzzer frequency (Hz)
#define MAX_FREQUENCY 2000.0   // Maximum buzzer frequency (Hz)
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration (µs)
#define MIN_ECHO_DURATION 1000   // Minimum echo duration (µs)
#define MAX_ECHO_DURATION 30000  // Maximum echo duration (µs)
#define MIN_GAP_DURATION 60000  // Minimum gap between measurements (ms)

// Global variables
static volatile int running = 1;
static volatile unsigned int last_trigger_time = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_sensor();
double get_distance();
double map_distance_to_frequency(double distance);
void set_buzzer_frequency(double frequency);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to send a trigger pulse to the HC-SR04
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration and calculate the distance
double get_distance() {
    unsigned int start_time = 0, end_time = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go high (timeout).\n");
        return -1.0; // Indicate an error
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= 10000) {
        fprintf(stderr, "Error: Echo pin did not go low (timeout).\n");
        return -1.0; // Indicate an error
    }

    end_time = gpioTick();

    // Calculate the pulse duration in microseconds
    unsigned int pulse_duration = end_time - start_time;

    // Validate the pulse duration
    if (pulse_duration < MIN_ECHO_DURATION || pulse_duration > MAX_ECHO_DURATION) {
        fprintf(stderr, "Error: Invalid echo pulse duration: %u us\n", pulse_duration);
        return -1.0; // Indicate an error
    }

    // Calculate the distance in centimeters
    double distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to map the distance to a buzzer frequency
double map_distance_to_frequency(double distance) {
    // Clamp the distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Map the distance to the frequency range
    double frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    return frequency;
}

// Function to set the buzzer frequency using PWM
void set_buzzer_frequency(double frequency) {
    // Clamp the frequency to the valid range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    // Set the PWM frequency
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);

    // Set the PWM duty cycle to 50% (full range)
    gpioPWM(BUZZER_PIN, 128); // 128 is half of the range (0-255)
}

// Function to clean up GPIO resources
void cleanup() {
    printf("Cleaning up GPIO resources...\n");
    gpioWrite(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate();          // Terminate the pigpio library
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM frequency (optional, but recommended)
    gpioSetPWMfrequency(BUZZER_PIN, 440); // Initial frequency

    // Register the signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_sensor();

        // Get the distance
        double distance = get_distance();

        if (distance > 0) {
            // Map the distance to a frequency
            double frequency = map_distance_to_frequency(distance);

            // Set the buzzer frequency
            set_buzzer_frequency(frequency);

            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }

        // Delay to enforce the minimum gap between measurements
        unsigned int current_time = gpioTick();
        unsigned int elapsed_time = current_time - last_trigger_time;
        if (elapsed_time < MIN_GAP_DURATION) {
            gpioDelay(MIN_GAP_DURATION - elapsed_time);
        }
        last_trigger_time = gpioTick();
    }

    // Clean up and exit
    cleanup();
    return 0;
}

