#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the PWM duty cycle for a given color
void set_color(int red_pin, int green_pin, int blue_pin, int red_duty, int green_duty, int blue_duty) {
    gpioPWM(red_pin, red_duty);
    gpioPWM(green_pin, green_duty);
    gpioPWM(blue_pin, blue_duty);
}

// Function to map a proximity value (0.0 to 1.0) to RGB color values
void proximity_to_rgb(float proximity, int *red, int *green, int *blue) {
    // Scale proximity to 0-180 degrees (sine wave period)
    float angle = proximity * M_PI * 2.0;

    // Calculate sine and cosine of the angle
    float sin_val = sin(angle);
    float cos_val = cos(angle);

    // Map sine and cosine to RGB values (0-255)
    *red   = (int)((sin_val + 1.0) * 127.5); // Scale sine to 0-255
    *green = (int)((cos_val + 1.0) * 127.5); // Scale cosine to 0-255
    *blue  = 0; // Constant blue value

    // Ensure values are within the valid range (0-255)
    if (*red < 0)   *red   = 0;
    if (*green < 0) *green = 0;
    if (*blue < 0)  *blue  = 0;
    if (*red > 255)   *red   = 255;
    if (*green > 255) *green = 255;
    if (*blue > 255)  *blue  = 255;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate proximity value (0.0 to 1.0)
        float proximity = (float)(rand() % 1001) / 1000.0; // Random value between 0.0 and 1.0

        // Map proximity to RGB color values
        int red, green, blue;
        proximity_to_rgb(proximity, &red, &green, &blue);

        // Set the RGB LED color
        set_color(RED_PIN, GREEN_PIN, BLUE_PIN, red, green, blue);

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Turn off the LED and release PWM resources
    set_color(RED_PIN, GREEN_PIN, BLUE_PIN, 0, 0, 0);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

