#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (set power management register to 0)
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Function to read raw gyroscope data from the MPU6050
int read_raw_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw data to degrees per second
gyro_data_t convert_to_dps(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw) {
    gyro_data_t gyro_data;
    gyro_data.x = (float)gyro_x_raw / GYRO_SCALE;
    gyro_data.y = (float)gyro_y_raw / GYRO_SCALE;
    gyro_data.z = (float)gyro_z_raw / GYRO_SCALE;
    return gyro_data;
}

// Function to log data to a file
int log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error: Could not write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (%s)\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file (%s)\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        // Read raw gyroscope data
        if (read_raw_gyro_data(&gyro_x_raw, &gyro_y_raw, &gyro_z_raw) == 0) {
            // Convert raw data to degrees per second
            gyro_data = convert_to_dps(gyro_x_raw, gyro_y_raw, gyro_z_raw);

            // Log data to file
            if (log_data(gyro_data.x, gyro_data.y, gyro_data.z) != 0) {
                break; // Exit loop if logging fails
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

