#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody notes (frequency, duration in ms)
const int melody[][2] = {
    {440, 250},   // A4
    {494, 250},   // B4
    {523, 250},   // C5
    {587, 250},   // D5
    {659, 250},   // E5
    {698, 250},   // F5
    {784, 250},   // G5
    {880, 250}    // A5
};
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int button_pressed = 0;
volatile int playing = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody(int melody[][2], int length);
void stop_melody();
void signal_handler(int signal);

// Button interrupt service routine
void button_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (level == 0) // Button pressed (active low)
    {
        pthread_mutex_lock(&mutex);
        button_pressed = 1;
        pthread_mutex_unlock(&mutex);
    }
}

// Function to play the melody
void play_melody(int melody[][2], int length)
{
    pthread_mutex_lock(&mutex);
    if (playing) {
        pthread_mutex_unlock(&mutex);
        return; // Already playing, do nothing
    }
    playing = 1;
    pthread_mutex_unlock(&mutex);

    for (int i = 0; i < length; i++)
    {
        int frequency = melody[i][0];
        int duration = melody[i][1];

        gpioSetPWMfrequency(BUZZER_PIN, frequency);
        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
        gpioDelay(duration * 1000); // Convert ms to us
    }

    stop_melody();
}

// Function to stop the melody
void stop_melody()
{
    pthread_mutex_lock(&mutex);
    playing = 0;
    pthread_mutex_unlock(&mutex);
    gpioPWM(BUZZER_PIN, 0); // Turn off buzzer
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable internal pull-up resistor on button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt service routine for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 50, button_isr, NULL) != 0)
    {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1)
    {
        pthread_mutex_lock(&mutex);
        if (button_pressed)
        {
            button_pressed = 0;
            pthread_mutex_unlock(&mutex);
            play_melody((int[][2])melody, melody_length);
        } else {
            pthread_mutex_unlock(&mutex);
        }
        gpioDelay(10000); // Check every 10ms
    }

    return 0;
}

