#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEFAULT_POLL_TIMEOUT_MS 1000
#define WINDOW_SIZE 5

// Structure to hold the sliding window of edge events
typedef struct {
    int events[WINDOW_SIZE];
    int head;
    int count;
} EventWindow;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static EventWindow event_window = {{0}, 0, 0};
static int poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;

// Function prototypes
void signal_handler(int signal);
void log_event(int value);
void update_event_window(int value);
int check_earthquake(void);
void print_earthquake_alert(void);
char* get_iso8601_timestamp(void);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Function to log an edge event to the file
