#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_MAG_OUT_X_L_M 0x08
#define LSM303_MAG_OUT_X_H_M 0x09
#define LSM303_MAG_OUT_Y_L_M 0x0A
#define LSM303_MAG_OUT_Y_H_M 0x0B
#define LSM303_MAG_OUT_Z_L_M 0x0C
#define LSM303_MAG_OUT_Z_H_M 0x0D
#define LSM303_MAG_MR_REG_M 0x02

// Hard iron calibration offsets
#define X_OFFSET 10.0
#define Y_OFFSET -5.0
#define Z_OFFSET 20.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_magnetometer();
int read_magnetometer_data(magnetometer_data_t *data);
void calibrate_magnetometer_data(magnetometer_data_t *data);
float calculate_heading(float x, float y);
char *map_heading_to_direction(float heading);
int log_data(magnetometer_data_t *data, float heading, char *direction);
void print_data(magnetometer_data_t *data, float heading, char *direction);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure the magnetometer
int configure_magnetometer() {
    int status = i2cWriteByteData(i2c_handle, LSM303_MAG_MR_REG_M, 0x00); // Continuous conversion mode
    if (status < 0) {
        fprintf(stderr, "Failed to write to magnetometer configuration register: %d\n", status);
        return -1;
    }
    return 0;
}

// Function to read raw magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, LSM303_MAG_OUT_X_L_M, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Failed to read magnetometer data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes, and apply appropriate sign
    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calibrate the magnetometer data
void calibrate_magnetometer_data(magnetometer_data_t *data) {
    data->x -= X_OFFSET;
    data->y -= Y_OFFSET;
    data->z -= Z_OFFSET;
}

// Function to calculate the heading in degrees
float calculate_heading(float x, float y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to map the heading to a compass direction
char *map_heading_to_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    else if (heading >= 22.5 && heading < 67.5) return "NE";
    else if (heading >= 67.5 && heading < 112.5) return "E";
    else if (heading >= 112.5 && heading < 157.5) return "SE";
    else if (heading >= 157.5 && heading < 202.5) return "S";
    else if (heading >= 202.5 && heading < 247.5) return "SW";
    else if (heading >= 247.5 && heading < 292.5) return "W";
    else return "NW";
}

// Function to log the data to a CSV file
int log_data(magnetometer_data_t *data, float heading, char *direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, data->x, data->y, data->z, heading, direction);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Function to print the data to the console
void print_data(magnetometer_data_t *data, float heading, char *direction) {
    printf("Calibrated X: %.2f, Calibrated Y: %.2f, Calibrated Z: %.2f, Heading: %.2f, Direction: %s\n",
           data->x, data->y, data->z, heading, direction);
}

// Function to clean up resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure magnetometer
    if (configure_magnetometer() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    fseek(log_file, 0, SEEK_END);

    magnetometer_data_t magnetometer_data;
    float heading;
    char *direction;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&magnetometer_data) == 0) {
            // Calibrate magnetometer data
            calibrate_magnetometer_data(&magnetometer_data);

            // Calculate heading
            heading = calculate_heading(magnetometer_data.x, magnetometer_data.y);

            // Map heading to direction
            direction = map_heading_to_direction(heading);

            // Log data
            log_data(&magnetometer_data, heading, direction);

            // Print data
            print_data(&magnetometer_data, heading, direction);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Skipping sample.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up resources
    cleanup();

    return 0;
}

