#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void touch_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int relay_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF

    return 0;
}

// Interrupt handler for touch sensor
void touch_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
        toggle_relay();
        last_touch_time = current_time;
    }
}

// Function to toggle the relay state
int toggle_relay() {
