            log_irrigation_event(2, moisture_level);
            gpioDelay(1000000); // 1 second delay

            activate_relay(RELAY3_PIN, 5);
            log_irrigation_event(3, moisture_level);
            gpioDelay(1000000); // 1 second delay

            activate_relay(RELAY4_PIN, 5);
            log_irrigation_event(4, moisture_level);
        }

        // Wait for 10 seconds
        gpioDelay(10000000); // 10 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

