#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for servo motors
#define VALVE_PIN 17
#define NOZZLE_PIN 18

// Define moisture levels
int moisture_levels[] = {20, 40, 60, 80, 100};
int moisture_index = 0;

// Define servo pulse width ranges
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define valve open pulse width
#define VALVE_OPEN_PULSE_WIDTH 1500

// Define valve close pulse width
#define VALVE_CLOSE_PULSE_WIDTH 500

// Define nozzle sweep pulse widths
int nozzle_pulse_widths[] = {500, 1000, 1500, 2000, 2500};

// Define watering duration
#define WATERING_DURATION 5

// Define delay between watering cycles
#define WATERING_DELAY 5

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to set servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width for GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to open the valve
int open_valve() {
    int retries = 0;
    int result;
    while (retries < 3) {
        result = set_servo_pulse_width(VALVE_PIN, VALVE_OPEN_PULSE_WIDTH);
        if (result == 0) {
            return 0; // Success
        }
        retries++;
        gpioDelay(100000); // 100ms backoff
    }
    fprintf(stderr, "Critical error: Failed to open valve after multiple retries.\n");
    return -1; // Failure
}

// Function to close the valve
int close_valve() {
    int result = set_servo_pulse_width(VALVE_PIN, VALVE_CLOSE_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Warning: Failed to close valve.\n");
        return -1; // Warning, not critical
    }
    return 0;
}

// Function to set nozzle angle
int set_nozzle_angle(int pulse_width) {
    int retries = 0;
    int result;
    while (retries < 3) {
        result = set_servo_pulse_width(NOZZLE_PIN, pulse_width);
        if (result == 0) {
            return 0; // Success
        }
        retries++;
        gpioDelay(100000); // 100ms backoff
    }
    fprintf(stderr, "Warning: Failed to set nozzle angle to %d after multiple retries.\n", pulse_width);
    return -1; // Warning, not critical
}

// Function to simulate reading soil moisture
int read_soil_moisture() {
    int moisture = moisture_levels[moisture_index];
    moisture_index = (moisture_index + 1) % (sizeof(moisture_levels) / sizeof(moisture_levels[0]));
    return moisture;
}

// Function to perform watering cycle
void watering_cycle() {
    if (open_valve() != 0) {
        fprintf(stderr, "Critical error: Failed to open valve, skipping watering cycle.\n");
        return;
    }

    for (int i = 0; i < sizeof(nozzle_pulse_widths) / sizeof(nozzle_pulse_widths[0]); i++) {
        if (set_nozzle_angle(nozzle_pulse_widths[i]) != 0) {
            fprintf(stderr, "Warning: Failed to set nozzle angle, continuing to next angle.\n");
        }
        gpioDelay(2000000); // 2 seconds
    }

    if (close_valve() != 0) {
        fprintf(stderr, "Warning: Failed to close valve.\n");
    }

    gpioDelay(WATERING_DURATION * 1000000); // 5 seconds
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int moisture = read_soil_moisture();
        printf("Soil moisture: %d\n", moisture);

        if (moisture < 50) {
            printf("Moisture below 50, initiating watering cycle...\n");
            watering_cycle();
        } else {
            printf("Moisture above 50, skipping watering cycle.\n");
        }

        gpioDelay(WATERING_DELAY * 1000000); // 5 seconds
    }

    // Stop servos
    gpioServo(VALVE_PIN, 0);
    gpioServo(NOZZLE_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

