#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// Global variable for I2C handle
int i2c_handle;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the MPU6050
int16_t read_raw_data(int i2c_handle, uint8_t reg) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return 0; // Return 0 on error
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU6050 (set power management register to 0)
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read raw gyroscope data
        int16_t gyro_x = read_raw_data(i2c_handle, MPU6050_GYRO_XOUT_H);
        int16_t gyro_y = read_raw_data(i2c_handle, MPU6050_GYRO_XOUT_H + 2);
        int16_t gyro_z = read_raw_data(i2c_handle, MPU6050_GYRO_XOUT_H + 4);

        // Convert to degrees per second
        float gyro_x_dps = (float)gyro_x / GYRO_SCALE;
        float gyro_y_dps = (float)gyro_y / GYRO_SCALE;
        float gyro_z_dps = (float)gyro_z / GYRO_SCALE;

        // Print the values
        printf("Gyro X: %.2f deg/s, Gyro Y: %.2f deg/s, Gyro Z: %.2f deg/s\n", gyro_x_dps, gyro_y_dps, gyro_z_dps);

        // Delay for 100ms
        gpioDelay(100000);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

