#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the watering cycle duration (seconds)
#define WATERING_CYCLE_DURATION 86400 // 24 hours

// Define the relay activation duration (seconds)
#define RELAY_ACTIVATION_DURATION 5

// Define the polling interval (seconds)
#define POLLING_INTERVAL 60

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void log_event(const char *message);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs with active-low semantics
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial state to inactive (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to activate a relay for a specified duration
void activate_relay(int pin) {
    gpioWrite(pin, 0); // Set GPIO pin LOW to activate the relay
    gpioDelay(RELAY_ACTIVATION_DURATION * 1000000); // Delay for the activation duration (in microseconds)
    gpioWrite(pin, 1); // Set GPIO pin HIGH to deactivate the relay
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    gpioWrite(pin, 1); // Set GPIO pin HIGH to deactivate the relay
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    gpioTerminate(); // Terminate the pigpio library
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    log_event("Watering system started.");

    // Main loop
    while (program_running) {
        // Watering cycle
        for (int i = 0; i < 4; i++) {
            int pin;
            switch (i) {
                case 0:
                    pin = RELAY1_PIN;
                    break;
                case 1:
                    pin = RELAY2_PIN;
                    break;
                case 2:
                    pin = RELAY3_PIN;
                    break;
                case 3:
                    pin = RELAY4_PIN;
                    break;
                default:
                    pin = RELAY1_PIN; // Default to first relay in case of error
                    break;
            }

            char message[64];
            snprintf(message, sizeof(message), "Activating relay on GPIO %d", pin);
            log_event(message);
            activate_relay(pin);
            snprintf(message, sizeof(message), "Deactivating relay on GPIO %d", pin);
            log_event(message);
        }

        // Wait for the next watering cycle
        for (int i = 0; i < WATERING_CYCLE_DURATION / POLLING_INTERVAL && program_running; i++) {
            gpioDelay(POLLING_INTERVAL * 1000000); // Delay for polling interval (in microseconds)
        }
    }

    log_event("Watering system stopped.");

    return 0;
}

