#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_PWR_MGMT_1 0x6B

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Gyroscope sensitivity scale factor
#define GYRO_SCALE 131.0

// Structure to hold gyroscope data
typedef struct {
    long long timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
int check_threshold(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Wake up the MPU6050
    if (i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data\n");
        return -1;
    }

    raw_x = (buf[0] << 8) | buf[1];
    raw_y = (buf[2] << 8) | buf[3];
    raw_z = (buf[4] << 8) | buf[5];

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Check if any axis exceeds the threshold
int check_threshold(float x, float y, float z) {
    if (abs(x) > 250.0 || abs(y) > 250.0 || abs(z) > 250.0) {
        return 1; // Threshold exceeded
    }
    return 0; // Threshold not exceeded
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);   // Close I2C connection
    gpioTerminate();        // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize I2C with retry
    int init_attempts = 0;
    while (init_i2c() != 0 && init_attempts < 3) {
        fprintf(stderr, "I2C initialization failed, retrying... (%d/3)\n", init_attempts + 1);
        gpioDelay(1000); // Wait 1 second before retrying
        init_attempts++;
    }
    if (init_attempts == 3) {
        fprintf(stderr, "I2C initialization failed after multiple attempts. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    gyro_data_t data;
    struct timespec ts;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            data.timestamp = ts.tv_sec * 1000000000LL + ts.tv_nsec;
            data.x = x;
            data.y = y;
            data.z = z;

            // Add data to buffer
            add_to_buffer(&gyro_buffer, data);

            // Check threshold and control LED
            if (check_threshold(x, y, z)) {
                gpioWrite(LED_PIN, 1); // Turn on LED
            } else {
                gpioWrite(LED_PIN, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data, retrying I2C initialization...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                program_running = 0; // Exit loop if re-initialization fails
            }
        }

        // Delay for 50ms (20Hz sampling rate)
        gpioDelay(50000); // 50000 microseconds = 50 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

