#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// MPU9250 Registers
#define MPU9250_ADDR_DEFAULT 0x68
#define MPU9250_ADDR_ALT 0x69
#define MPU9250_WHO_AM_I 0x75
#define MPU9250_PWR_MGMT_1 0x6B
#define MPU9250_GYRO_CONFIG 0x1B
#define MPU9250_GYRO_XOUT_H 0x43
#define MPU9250_GYRO_XOUT_L 0x44
#define MPU9250_GYRO_YOUT_H 0x45
#define MPU9250_GYRO_YOUT_L 0x46
#define MPU9250_GYRO_ZOUT_H 0x47
#define MPU9250_GYRO_ZOUT_L 0x48

// SPI Configuration
#define SPI_BUS "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8 // GPIO8, BCM

// Gyroscope Sensitivity
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s for +/- 250 deg/s range

// Global Variables
static int spi_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(const char *bus, int mode, int bits_per_word, int max_speed_hz);
int gpio_init(const char *chip, int line);
int mpu9250_init(int spi_fd, int gpio_line);
int read_gyro_data(int spi_fd, int gpio_line, int *gyro_x, int *gyro_y, int *gyro_z);
char *get_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_data(FILE *log_file, const char *timestamp, int gyro_x, int gyro_y, int gyro_z);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(const char *bus, int mode, int bits_per_word, int max_speed_hz) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
