        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    gpiod_chip_close(gpio_chip);
    return 0;
}

// MPU9250 Initialization
int mpu9250_init(int spi_fd, int gpio_line) {
    unsigned char who_am_i;
    unsigned char data[2];

    // Wake up the MPU9250
    data[0] = MPU9250_PWR_MGMT_1 | 0x80; // Set sleep bit
    if (write(spi_fd, data, 1) != 1) {
        perror("Error writing to SPI device");
        return -1;
    }
    usleep(100000); // Wait for 100ms

    // Verify WHO_AM_I register
    data[0] = MPU9250_WHO_AM_I | 0x80; // Read WHO_AM_I register
    data[1] = 0x00; // Dummy byte for reading
    if (write(spi_fd, data, 2) != 2) {
        perror("Error writing to SPI device");
        return -1;
    }
    lseek(spi_fd, -1, SEEK_CUR); // Reset file pointer to the beginning of the read
    if (read(spi_fd, &who_am_i, 1) != 1) {
        perror("Error reading from SPI device");
        return -1;
    }

    if (who_am_i != 0x71) {
        fprintf(stderr, "Error: MPU9250 not found (WHO_AM_I = 0x%02X)\n", who_am_i);
        return -1;
    }

    // Configure gyroscope range to +/- 250 deg/s
    data[0] = MPU9250_GYRO_CONFIG;
    data[1] = 0x00; // 0x00 = +/- 250 deg/s
    if (write(spi_fd, data, 2) != 2) {
        perror("Error writing to SPI device");
        return -1;
    }

    return 0;
}

// Read Gyroscope Data
int read_gyro_data(int spi_fd, int gpio_line, int *gyro_x, int *gyro_y, int *gyro_z) {
    unsigned char data[14];
    int retries = 3;
    int i;

    while (retries > 0) {
        // Assert chip select
        gpiod_line_set_value(gpio_line, 0);
        usleep(10); // Small delay

        // Read gyroscope data
        data[0] = MPU9250_GYRO_XOUT_H | 0x80; // Read multiple bytes starting from GYRO_XOUT_H
        if (write(spi_fd, data, 1) != 1) {
            perror("Error writing to SPI device");
            goto retry;
        }

        if (read(spi_fd, data, 14) != 14) {
            perror("Error reading from SPI device");
            goto retry;
        }

