    struct timespec ts;
    time_t t;
    struct tm tm;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting time");
        return NULL;
    }

    t = ts.tv_sec;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error converting time to local time");
        return NULL;
    }

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%S", &tm);
    snprintf(timestamp_str + strlen(timestamp_str), timestamp_str_size - strlen(timestamp_str), ".%09ldZ", ts.tv_nsec);

