        return -1;
    }
    return 0;
}

// Read Gyroscope Data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char tx_buf[1];
    char rx_buf[6];

    // Read X, Y, and Z gyro data
    tx_buf[0] = MPU6050_GYRO_XOUT_H | 0x80; // Read multiple bytes
    if (spiXfer(spi_handle, tx_buf, rx_buf, 7) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    *x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    *y = (int16_t)((rx_buf[3] << 8) | rx_buf[4]);
    *z = (int16_t)((rx_buf[5] << 8) | rx_buf[6]);

    return 0;
}

// Add Data to Circular Buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Check Threshold
int check_threshold(int16_t x, int16_t y, int16_t z) {
    if (abs(x) > THRESHOLD || abs(y) > THRESHOLD || abs(z) > THRESHOLD) {
        return 1;
    }
    return 0;
}

// Blink LED
void blink_led(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for duration_ms milliseconds
    gpioWrite(gpio, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay for duration_ms milliseconds
}

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Print Buffer as CSV
void print_buffer(circular_buffer_t *buffer) {
    int i;
    printf("Timestamp,X,Y,Z\n");
    for (i = 0; i < buffer->count; i++) {
        int index = (buffer->tail + i) % BUFFER_SIZE;
        printf("%ld.%09ld,%d,%d,%d\n", buffer->buffer[index].timestamp.tv_sec, buffer->buffer[index].timestamp.tv_nsec, buffer->buffer[index].x, buffer->buffer[index].y, buffer->buffer[index].z);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize Circular Buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    gyro_data_t data;

    printf("Starting data acquisition...\n");

    while (program_running) {
        // Read gyro data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_REALTIME, &data.timestamp);

            // Store data in circular buffer
            data.x = x;
            data.y = y;
            data.z = z;
            add_to_buffer(&gyro_buffer, data);

            // Check threshold and blink LED
            if (check_threshold(x, y, z)) {
                blink_led(LED_GPIO, 500);
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        gpioDelay(10000); // Delay 10ms
    }

    // Print the buffer
    print_buffer(&gyro_buffer);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

