#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scales
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE  131.0f   // +/- 250 deg/s range

// GPIO pin for LED
#define LED_PIN 21

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void convert_to_g(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *accel_x_g, float *accel_y_g, float *accel_z_g);
void convert_to_dps(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps);
void calculate_roll_pitch(float accel_x_g, float accel_y_g, float accel_z_g, float *roll, float *pitch);
void log_data(float roll, float pitch);
void control_led(float roll, float pitch);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Read raw accelerometer and gyroscope data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: Could not read data from MPU6050\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Convert raw accelerometer data to g-force units
void convert_to_g(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *accel_x_g, float *accel_y_g, float *accel_z_g) {
    *accel_x_g = (float)accel_x / ACCEL_SCALE;
    *accel_y_g = (float)accel_y / ACCEL_SCALE;
    *accel_z_g = (float)accel_z / ACCEL_SCALE;
}

// Convert raw gyroscope data to degrees per second
void convert_to_dps(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    *gyro_x_dps = (float)gyro_x / GYRO_SCALE;
    *gyro_y_dps = (float)gyro_y / GYRO_SCALE;
    *gyro_z_dps = (float)gyro_z / GYRO_SCALE;
}

// Calculate roll and pitch angles
void calculate_roll_pitch(float accel_x_g, float accel_y_g, float accel_z_g, float *roll, float *pitch) {
    *roll  = atan2(accel_y_g, accel_z_g) * 180 / M_PI;
    *pitch = atan2(-accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180 / M_PI;
}

// Log data to file
void log_data(float roll, float pitch) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on roll and pitch
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45.0f || fabs(pitch) > 45.0f) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float accel_x_g, accel_y_g, accel_z_g, gyro_x_dps, gyro_y_dps, gyro_z_dps, roll, pitch;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Tilt sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert to g and dps
            convert_to_g(accel_x, accel_y, accel_z, &accel_x_g, &accel_y_g, &accel_z_g);
            convert_to_dps(gyro_x, gyro_y, gyro_z, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Calculate roll and pitch
            calculate_roll_pitch(accel_x_g, accel_y_g, accel_z_g, &roll, &pitch);

            // Print roll and pitch to console
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

            // Log data to file
            log_data(roll, pitch);

            // Control LED
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

