#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define GPIO_LED 17
#define LOG_FILE "biometric_log.txt"

// Si1145 Registers
#define REG_PARTID 0x00
#define REG_REVID 0x01
#define REG_SEQID 0x02

#define REG_UCOEF0 0x13
#define REG_UCOEF1 0x14
#define REG_UCOEF2 0x15
#define REG_UCOEF3 0x16

#define REG_PARAM_WR 0x17
#define REG_COMMAND 0x18

#define REG_RESPONSE0 0x20
#define REG_RESPONSE1 0x21
#define REG_RESPONSE2 0x22
#define REG_RESPONSE3 0x23

#define REG_IRQ_ENABLE 0x03
#define REG_IRQ_MODE1 0x04
#define REG_IRQ_MODE2 0x05

#define REG_HW_KEY 0x07

#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09

#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PS1_DATA0 0x24
#define REG_PS1_DATA1 0x25

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06

// Global Variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
int si1145_init(int fd);
int read_si1145_data(int fd, int *ambient_light, int *proximity);
void log_data(FILE *fp, int ambient_light, int proximity);
void control_led(int proximity);
void signal_handler(int sig);

// I2C Write Byte Function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C Write Failed");
        return -1;
    }
    return 0;
}

// I2C Read Byte Function
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C Write (register select) Failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C Read Failed");
        return -1;
    }
    return 0;
}

// Si1145 Initialization Function
int si1145_init(int fd) {
    // Reset the device
    if (i2c_write_byte(fd, REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2c_write_byte(fd, REG_MEAS_RATE0, 0x08) < 0) return -1; // Measurement rate
    if (i2c_write_byte(fd, REG_MEAS_RATE1, 0x00) < 0) return -1;

    if (i2c_write_byte(fd, REG_IRQ_ENABLE, 0x00) < 0) return -1; // Disable interrupts
    if (i2c_write_byte(fd, REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, REG_IRQ_MODE2, 0x00) < 0) return -1;

    if (i2c_write_byte(fd, REG_HW_KEY, 0x17) < 0) return -1;

    // Enable ALS and Proximity measurements
    if (i2c_write_byte(fd, REG_COMMAND, CMD_ALS_FORCE) < 0) return -1;

    return 0;
}

// Read Si1145 Data Function
int read_si1145_data(int fd, int *ambient_light, int *proximity) {
    uint8_t als_low, als_high, prox_low, prox_high;

    if (i2c_read_byte(fd, REG_ALS_VIS_DATA0, &als_low) < 0) return -1;
    if (i2c_read_byte(fd, REG_ALS_VIS_DATA1, &als_high) < 0) return -1;
    if (i2c_read_byte(fd, REG_PS1_DATA0, &prox_low) < 0) return -1;
    if (i2c_read_byte(fd, REG_PS1_DATA1, &prox_high) < 0) return -1;

    *ambient_light = (als_high << 8) | als_low;
    *proximity = (prox_high << 8) | prox_low;

    return 0;
}

// Log Data Function
