int si1145_init(int fd) {
    // Reset the device
    if (i2c_write_byte(fd, REG_COMMAND, CMD_RESET) < 0) return -1;
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2c_write_byte(fd, REG_MEAS_RATE0, 0x08) < 0) return -1; // Measurement rate
    if (i2c_write_byte(fd, REG_MEAS_RATE1, 0x00) < 0) return -1;

    if (i2c_write_byte(fd, REG_IRQ_ENABLE, 0x00) < 0) return -1; // Disable interrupts
    if (i2c_write_byte(fd, REG_IRQ_MODE1, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, REG_IRQ_MODE2, 0x00) < 0) return -1;

