// ADXRS290 Register Addresses
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02
#define ADXRS290_REG_TEMP   0x04
#define ADXRS290_REG_DIAG   0x06
#define ADXRS290_REG_ID     0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data);
int read_gyro_data(int handle, int16_t *x_rate, int16_t *y_rate);
int log_data(FILE *fp, struct timespec ts, int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);
int initialize_spi(int channel, int ce, int speed, int mode);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data) {
    char tx[2], rx[2];
    tx[0] = reg_addr | 0x80; // Set read bit
    tx[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI Read Error\n");
        return -1;
    }

    *data = rx[1];
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx[2], rx[2];
    tx[0] = reg_addr & 0x7F; // Clear read bit
    tx[1] = data;

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI Write Error\n");
        return -1;
    }

    return 0;
}

// Read Gyro Data Function
int read_gyro_data(int handle, int16_t *x_rate, int16_t *y_rate) {
    uint8_t x_rate_msb, x_rate_lsb, y_rate_msb, y_rate_lsb;

    if (spi_read_register(handle, ADXRS290_REG_X_RATE, &x_rate_msb) != 0) return -1;
    if (spi_read_register(handle, ADXRS290_REG_X_RATE + 1, &x_rate_lsb) != 0) return -1;
    if (spi_read_register(handle, ADXRS290_REG_Y_RATE, &y_rate_msb) != 0) return -1;
    if (spi_read_register(handle, ADXRS290_REG_Y_RATE + 1, &y_rate_lsb) != 0) return -1;

    *x_rate = (int16_t)((x_rate_msb << 8) | x_rate_lsb);
    *y_rate = (int16_t)((y_rate_msb << 8) | y_rate_lsb);

    return 0;
}

// Log Data Function
int log_data(FILE *fp, struct timespec ts, int16_t x_rate, int16_t y_rate) {
    if (fprintf(fp, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, x_rate, y_rate) < 0) {
        fprintf(stderr, "File Write Error\n");
        return -1;
    }
    return 0;
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize SPI Function
int initialize_spi(int channel, int ce, int speed, int mode) {
    int handle = spiOpen(channel, speed, mode);
    if (handle < 0) {
        fprintf(stderr, "SPI Open Error: %d\n", handle);
        return -1;
    }
    return handle;
}

int main() {
    int retries = 0;
    int16_t x_rate, y_rate;
    struct timespec ts;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open CSV file
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "File Open Error\n");
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,x_rate,y_rate\n");

    // Initialize SPI
    spi_handle = initialize_spi(SPI_CHANNEL, SPI_CE, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI Initialization Failed\n");
        fclose(fp);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_gyro_data(spi_handle, &x_rate, &y_rate) == 0) {
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                if (log_data(fp, ts, x_rate, y_rate) != 0) {
                    fprintf(stderr, "Logging Failed\n");
                    break;
                }
            } else {
                fprintf(stderr, "Clock Get Time Error\n");
                break;
            }
        } else {
            fprintf(stderr, "Gyro Data Read Failed\n");
            retries++;
            if (retries > 3) {
                fprintf(stderr, "Too many retries, exiting...\n");
                break;
            }
            spiClose(spi_handle);
            spi_handle = initialize_spi(SPI_CHANNEL, SPI_CE, SPI_SPEED, SPI_MODE);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI Re-Initialization Failed\n");
                break;
            }
            continue; // Retry reading gyro data
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    printf("Closing SPI, file, and terminating pigpio...\n");
    spiClose(spi_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

