#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17

// Define alert duration (seconds)
#define ALERT_DURATION 2

// Define log file name
#define LOG_FILE "seismic_events.txt"

// Global variables
FILE *log_file = NULL;
volatile int sensor1_state = 0;
volatile int sensor2_state = 0;
volatile unsigned long last_event_time = 0;

// Function prototypes
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);
void trigger_alert();
void log_event();
void signal_handler(int signal);

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick)
{
    sensor1_state = level;
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick)
{
    sensor2_state = level;

    // Check if both sensors are HIGH
    if (sensor1_state == 1 && sensor2_state == 1)
    {
        // Get current time
        unsigned long current_time = gpioTick();

        // Check if the event occurred within the 500ms window
        if (current_time - last_event_time > 500000 || last_event_time == 0) //pigpio uses microseconds
        {
            trigger_alert();
            log_event();
            last_event_time = current_time;
        }
    }
}

// Function to trigger the alert
void trigger_alert()
{
    gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
    gpioDelay(ALERT_DURATION * 1000000); // Wait for 2 seconds (microseconds)
    gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
}

// Function to log the event
void log_event()
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Ensure data is written to the file immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
