#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_TEMP 0x02
#define ADXRS290_REG_DIAG 0x04
#define ADXRS290_REG_ID 0x06
#define ADXRS290_REG_RATE_SCALE 0x08
#define ADXRS290_REG_TEMP_SCALE 0x0A
#define ADXRS290_REG_OFFSET 0x0C
#define ADXRS290_REG_FILTER 0x0E
#define ADXRS290_REG_MODE 0x0F

#define LED_GPIO 17
#define THRESHOLD 20.0 // deg/s
#define BUFFER_SIZE 100

// Data structure for circular buffer
typedef struct {
    struct timespec timestamp;
    float rate;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int read_gyro_register(uint8_t reg_addr, uint8_t *data, int len);
int write_gyro_register(uint8_t reg_addr, uint8_t data);
float read_x_axis_rate();
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, float rate);
int check_threshold(float rate, float threshold);
void control_led(int gpio, int state);
void signal_handler(int signal);
void init_circular_buffer(circular_buffer_t *buffer);

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, struct timespec timestamp, float rate) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head].timestamp = timestamp;
    buffer->data[buffer->head].rate = rate;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Initialize SPI interface
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from gyro register
int read_gyro_register(uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read

    if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) != len + 1) {
        fprintf(stderr, "Error reading SPI register 0x%02X\n", reg_addr);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Write data to gyro register
int write_gyro_register(uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    if (spiXfer(spi_handle, tx_buf, NULL, 2) != 2) {
        fprintf(stderr, "Error writing SPI register 0x%02X\n", reg_addr);
        return -1;
    }
    return 0;
}

// Read X-axis rate from gyro
float read_x_axis_rate() {
    uint8_t data[2];
    if (read_gyro_register(ADXRS290_REG_X_RATE, data, 2) != 0) {
        return 0.0; // Return 0 on error
    }

    int16_t raw_rate = (data[0] << 8) | data[1];
    // Assuming a scale factor of 0.03125 degrees/sec/LSB (adjust as needed)
    float rate = (float)raw_rate * 0.03125;
    return rate;
}

// Check if rate exceeds threshold
int check_threshold(float rate, float threshold) {
    return (abs(rate) > threshold) ? 1 : 0;
}

// Control LED state
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read X-axis rate
        float rate = read_x_axis_rate();

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Add data to circular buffer
        add_to_buffer(&gyro_buffer, ts, rate);

        // Check threshold
        int threshold_exceeded = check_threshold(rate, THRESHOLD);

        // Control LED
        control_led(LED_GPIO, threshold_exceeded);

        // Print rate and LED state
        printf("Rate: %.2f deg/s, LED: %s\n", rate, threshold_exceeded ? "ON" : "OFF");

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    control_led(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    pthread_mutex_destroy(&gyro_buffer.mutex);

    return 0;
}

