#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 255

// Global variable to store the total duration
int total_duration = 0;

// Function prototypes
void lamp_on(int gpio);
void lamp_off(int gpio);
void fade_lamp(int gpio, int duration);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    lamp_off(LAMP1_GPIO);
    lamp_off(LAMP2_GPIO);
    lamp_off(LAMP3_GPIO);
    gpioTerminate();
    exit(0);
}

// Function to turn a lamp on (set PWM duty cycle to 255)
void lamp_on(int gpio) {
    gpioPWM(gpio, PWM_RANGE);
}

// Function to turn a lamp off (set PWM duty cycle to 0)
void lamp_off(int gpio) {
    gpioPWM(gpio, 0);
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration) {
    int steps = PWM_RANGE;
    int delay_us = (duration * 1000000) / steps; // Calculate delay in microseconds

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration);

    for (int i = 0; i <= steps; i++) {
        gpioPWM(gpio, i);
        usleep(delay_us);
    }

    printf("Lamp on GPIO %d faded to off.\n", gpio);
}

int main(int argc, char *argv[]) {
    // Check if the total duration is provided as a command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Convert the command-line argument to an integer
    total_duration = atoi(argv[1]);

    // Validate the total duration
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: Total duration must be an integer between 1 and 3600.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sunset simulation started. Total duration: %d seconds\n", total_duration);

    // Simulate sunset sequence
    fade_lamp(LAMP1_GPIO, total_duration / 3);
    fade_lamp(LAMP2_GPIO, total_duration / 3);
    fade_lamp(LAMP3_GPIO, total_duration / 3);

    printf("Sunset simulation complete.\n");

    // Clean up and exit
    lamp_off(LAMP1_GPIO);
    lamp_off(LAMP2_GPIO);
    lamp_off(LAMP3_GPIO);
    gpioTerminate();

    return 0;
}

