#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define LOG_FILE "touch_relay.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status(uint16_t *touch_status);
void debounce_touch(uint16_t touch_status);
void toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);

// Structure to hold debounce state
typedef struct {
    uint16_t last_touch_status;
    time_t last_touch_time;
} DebounceState;

DebounceState debounce_state = {0, 0};

// Function to initialize the MPR121
int initialize_mpr121() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        log_message("Error: Failed to set MPR121 to stop mode.");
        return -1;
    }

    // Electrode configuration
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        log_message("Error: Failed to configure electrodes.");
        return -1;
    }

    // Touch and release thresholds
    for (int i = 0x41; i < 0x53; i++) {
        if (i2cWriteByteData(i2c_handle, i, 0x30) < 0) {
            log_message("Error: Failed to set touch threshold.");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, i + 12, 0x10) < 0) {
            log_message("Error: Failed to set release threshold.");
            return -1;
        }
    }

    // Filter configuration
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) {
        log_message("Error: Failed to configure filter.");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        log_message("Error: Failed to enable electrode 0.");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_message("Error: Failed to read touch status.");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to debounce touch events
void debounce_touch(uint16_t touch_status) {
    time_t now = time(NULL);

    if ((touch_status & 0x01) && !(debounce_state.last_touch_status & 0x01)) {
        if (difftime(now, debounce_state.last_touch_time) * 1000 > DEBOUNCE_DELAY_MS) {
            toggle_relay();
            debounce_state.last_touch_time = now;
        }
    }

    debounce_state.last_touch_status = touch_status;
}

// Function to toggle the relay
void toggle_relay() {
    int current_level = gpioRead(RELAY_GPIO);
    int new_level = !current_level;

    if (gpioWrite(RELAY_GPIO, new_level) != 0) {
        log_message("Error: Failed to write to GPIO.");
    } else {
        char message[100];
        snprintf(message, sizeof(message), "Relay toggled to %d", new_level);
        log_message(message);
    }
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    char message[50];
    snprintf(message, sizeof(message), "Received signal %d, terminating...", signal);
    log_message(message);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error: Failed to open I2C device.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        log_message("Error: MPR121 initialization failed.");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize to LOW

    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            debounce_touch(touch_status);
        } else {
            log_message("Error reading touch status, retrying...");
        }
        gpioDelay(10); // 10ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Set GPIO to LOW before exiting
    gpioSetMode(RELAY_GPIO, PI_INPUT); // Set GPIO to input to avoid spurious signals
    fclose(log_file);
    gpioTerminate();

    return 0;
}

