#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define constants
#define FLAME_DETECTED_THRESHOLD 3
#define FLAME_DETECTED_DURATION 500 // milliseconds
#define LOG_FILE_NAME "flame_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
void log_flame_detection();
void activate_alarm();
void deactivate_alarm();
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to log flame detection to a file
void log_flame_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Flame Detected\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the buzzer and LED
void activate_alarm() {
    gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    gpioWrite(LED_PIN, 1);    // Turn on LED
}

// Function to deactivate the buzzer and LED
void deactivate_alarm() {
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioWrite(LED_PIN, 0);    // Turn off LED
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int flame_count = 0;
    int flame_detected = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (active low)
            flame_count++;
            if (flame_count >= FLAME_DETECTED_THRESHOLD) {
                if (!flame_detected) {
                    log_flame_detection();
                    activate_alarm();
                    flame_detected = 1;
                }
            }
        } else {
            flame_count = 0; // Reset counter if no flame detected
            if (flame_detected) {
                deactivate_alarm();
                flame_detected = 0;
            }
        }

        gpioDelay(50); // Delay 50ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

