#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense interval
#define DISPENSE_INTERVAL 5000 // milliseconds

// Define solenoid activation durations
#define SOLENOID_1_DURATION 500 // milliseconds
#define SOLENOID_2_DURATION 500 // milliseconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int pin, int duration_ms);
int deactivate_solenoid(int pin);
int log_dispense_event(int pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Deactivating solenoids and exiting.\n");
        program_running = 0;
        deactivate_solenoid(SOLENOID_1_PIN);
        deactivate_solenoid(SOLENOID_2_PIN);
        gpioTerminate();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    return 0;
}

// Function to activate a solenoid
int activate_solenoid(int pin, int duration_ms) {
    gpioWrite(pin, 1); // Activate solenoid
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    return 0;
}

// Function to deactivate a solenoid
int deactivate_solenoid(int pin) {
    gpioWrite(pin, 0); // Deactivate solenoid
    return 0;
}

// Function to log dispense event
int log_dispense_event(int pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, GPIO%d, %d ms\n", s, pin, duration_ms);
    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Dispenser program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Dispense using solenoid 1
        if (activate_solenoid(SOLENOID_1_PIN, SOLENOID_1_DURATION) != 0) {
            fprintf(stderr, "Error activating solenoid 1\n");
        }
        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_1_DURATION) != 0) {
            fprintf(stderr, "Error logging solenoid 1 event\n");
        }

        // Dispense using solenoid 2
        if (activate_solenoid(SOLENOID_2_PIN, SOLENOID_2_DURATION) != 0) {
            fprintf(stderr, "Error activating solenoid 2\n");
        }
        if (log_dispense_event(SOLENOID_2_PIN, SOLENOID_2_DURATION) != 0) {
            fprintf(stderr, "Error logging solenoid 2 event\n");
        }

        // Deactivate both solenoids
        if (deactivate_solenoid(SOLENOID_1_PIN) != 0) {
            fprintf(stderr, "Error deactivating solenoid 1\n");
        }
        if (deactivate_solenoid(SOLENOID_2_PIN) != 0) {
            fprintf(stderr, "Error deactivating solenoid 2\n");
        }

        // Wait for the next dispense interval
        gpioDelay(DISPENSE_INTERVAL * 1000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();

    return 0;
}

