#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define ENA 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENB 25

// Obstacle avoidance threshold
#define OBSTACLE_THRESHOLD 20.0

// PID constants
#define KP 0.5
#define KI 0.01
#define KD 0.1

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold motor speeds
typedef struct {
    int motor_a_speed;
    int motor_b_speed;
} MotorSpeeds;

// Function prototypes
float generate_tilt_error();
float generate_distance();
float pid_control(float setpoint, float process_variable, float *integral, float *previous_error, float dt);
MotorSpeeds obstacle_avoidance(float distance);
void set_motor_speeds(int motor_a_speed, int motor_b_speed);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO and pigpio library
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Enable PWM on ENA and ENB
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    // Open log file
    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "timestamp,tilt_error,distance,motor_a_speed,motor_b_speed\n");

    return 0;
}

// Cleanup GPIO and close log file
void cleanup() {
    // Stop motors
    set_motor_speeds(0, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Generate a random tilt error between -10.0 and 10.0
float generate_tilt_error() {
    return ((float)rand() / RAND_MAX) * 20.0 - 10.0;
}

// Generate a random distance between 2.0 and 400.0
float generate_distance() {
    return ((float)rand() / RAND_MAX) * 398.0 + 2.0;
}

// PID control function
float pid_control(float setpoint, float process_variable, float *integral, float *previous_error, float dt) {
    float error = setpoint - process_variable;
    *integral += error * dt;
    float derivative = (error - *previous_error) / dt;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Obstacle avoidance logic
MotorSpeeds obstacle_avoidance(float distance) {
    MotorSpeeds speeds = {0, 0};
    if (distance < OBSTACLE_THRESHOLD) {
        // Reverse both motors at 50% speed
        speeds.motor_a_speed = -128;
        speeds.motor_b_speed = -128;
    }
    return speeds;
}

// Set motor speeds using PWM
void set_motor_speeds(int motor_a_speed, int motor_b_speed) {
    // Clamp motor speeds to -255 and 255
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_a_speed < -255) motor_a_speed = -255;
    if (motor_b_speed > 255) motor_b_speed = 255;
    if (motor_b_speed < -255) motor_b_speed = -255;

    // Motor A
    if (motor_a_speed > 0) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA, motor_a_speed);
    } else if (motor_a_speed < 0) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(ENA, -motor_a_speed);
    } else {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA, 0);
    }

    // Motor B
    if (motor_b_speed > 0) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB, motor_b_speed);
    } else if (motor_b_speed < 0) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(ENB, -motor_b_speed);
    } else {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB, 0);
    }
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    float setpoint = 0.0; // Tilt setpoint (0 degrees)
    float tilt_error, distance;
    float pid_output;
    float integral = 0.0;
    float previous_error = 0.0;
    MotorSpeeds motor_speeds;
    struct timespec start, end;
    double dt;

    // Main loop
    while (program_running) {
        clock_gettime(CLOCK_MONOTONIC, &start);

        // Generate tilt error and distance
        tilt_error = generate_tilt_error();
        distance = generate_distance();

        // Obstacle avoidance
        motor_speeds = obstacle_avoidance(distance);

        // PID control
        if (motor_speeds.motor_a_speed == 0 && motor_speeds.motor_b_speed == 0) {
            pid_output = pid_control(setpoint, tilt_error, &integral, &previous_error, 0.05);
            motor_speeds.motor_a_speed = (int)pid_output;
            motor_speeds.motor_b_speed = (int)pid_output;
        }

        // Set motor speeds
        set_motor_speeds(motor_speeds.motor_a_speed, motor_speeds.motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_speeds.motor_a_speed, motor_speeds.motor_b_speed);

        clock_gettime(CLOCK_MONOTONIC, &end);
        dt = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;

        // Sleep for 50ms
        usleep(50000 - (int)(dt * 1000000)); // Sleep for the remaining time
    }

    // Cleanup
    cleanup();

    return 0;
}

