#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track relay state
static volatile int relay_state = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // De-energize relay
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit program
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read touch sensor value
        int touch_detected = gpioRead(TOUCH_SENSOR_PIN);

        // If touch is detected
        if (touch_detected == 1) {
            // Toggle relay state
            relay_state = !relay_state;
            gpioWrite(RELAY_PIN, relay_state);

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

