#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Configuration
#define SAMPLE_RATE 8000
#define BITS_PER_SAMPLE 16
#define NUM_CHANNELS 1
#define PERIOD_SIZE 1024
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000000  // 1ms period
#define SENSITIVITY_DEFAULT 1.0

// GPIO pins
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static double sensitivity = SENSITIVITY_DEFAULT;

// Function prototypes
void signal_handler(int sig);
int initialize_alsa(snd_pcm_t **pcm_handle);
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames);
double calculate_rms(const short *buffer, int frames);
void map_amplitude_to_color(double rms, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void *audio_processing_thread(void *arg);
void simulate_audio(short *buffer, int frames);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    running = 0;
}

// Initialize ALSA
int initialize_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Capture audio
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames) {
    int err;
    while ((err = snd_pcm_readi(pcm_handle, buffer, frames)) != frames) {
        if (err == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            if ((err = snd_pcm_prepare(pcm_handle)) < 0) {
                fprintf(stderr, "Error preparing PCM device: %s\n", snd_strerror(err));
                return -1;
            }
        } else if (err == -ESTRPIPE) {
            fprintf(stderr, "Stream suspended\n");
            if ((err = snd_pcm_resume(pcm_handle)) < 0) {
                fprintf(stderr, "Error resuming PCM device: %s\n", snd_strerror(err));
                if ((err = snd_pcm_prepare(pcm_handle)) < 0) {
                    fprintf(stderr, "Error preparing PCM device: %s\n", snd_strerror(err));
                    return -1;
                }
            }
        } else {
            fprintf(stderr, "Error reading PCM: %s\n", snd_strerror(err));
            return -1;
        }
    }
    return 0;
}

// Calculate RMS amplitude
double calculate_rms(const short *buffer, int frames) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < frames; i++) {
        sum_of_squares += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_of_squares / frames);
}

// Map amplitude to color
void map_amplitude_to_color(double rms, int *red, int *green, int *blue) {
    // Non-linear mapping (example: logarithmic)
    double scaled_rms = rms * sensitivity;
    double log_rms = log10(scaled_rms + 1.0); // Add 1 to avoid log(0)
    double normalized_rms = log_rms / log10(65536.0); // Max RMS for 16-bit signed

    // Cycle through colors based on normalized RMS
    double hue = normalized_rms * 360.0;

    // Hue to RGB conversion (simplified)
    double c = 1.0; // Saturation
    double x = c * (1 - fabs(fmod(hue / 60.0, 2) - 1));
    double m = 0.0; // Brightness

    double r = 0.0, g = 0.0, b = 0.0;
    if (hue < 60) {
        r = c; g = x; b = 0;
    } else if (hue < 120) {
        r = x; g = c; b = 0;
    } else if (hue < 180) {
        r = 0; g = c; b = x;
    } else if (hue < 240) {
        r = 0; g = x; b = c;
    } else if (hue < 300) {
        r = x; g = 0; b = c;
    } else {
        r = c; g = 0; b = x;
    }

    r = (r + m) * PWM_RANGE;
    g = (g + m) * PWM_RANGE;
    b = (b + m) * PWM_RANGE;

    *red = (int)r;
    *green = (int)g;
    *blue = (int)b;
}

// Set LED color using pigpio
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Audio processing thread
void *audio_processing_thread(void *arg) {
    short *buffer = (short *)arg;
    int red, green, blue;
    double rms;

    while (running) {
        rms = calculate_rms(buffer, PERIOD_SIZE);
        map_amplitude_to_color(rms, &red, &green, &blue);
        set_led_color(red, green, blue);
        usleep(10000); // 10ms
    }

    // Clean up
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    return NULL;
}

// Simulate audio (sine wave)
void simulate_audio(short *buffer, int frames) {
    static double phase = 0.0;
    double increment = (2.0 * M_PI * 440.0) / SAMPLE_RATE; // 440 Hz sine wave

    for (int i = 0; i < frames; i++) {
        buffer[i] = (short)(32767.0 * sin(phase));
        phase += increment;
        if (phase > 2.0 * M_PI) {
            phase -= 2.0 * M_PI;
        }
    }
}

int main(int argc, char *argv[]) {
    pthread_t audio_thread;
    short *audio_buffer;
    int err;

    // Parse command-line arguments
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Invalid sensitivity value. Using default.\n");
            sensitivity = SENSITIVITY_DEFAULT;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Allocate audio buffer
    audio_buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ALSA (if available)
#ifdef ALSA_AVAILABLE
    if (initialize_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed. Continuing with simulation.\n");
        pcm_handle = NULL; // Ensure pcm_handle is NULL for the rest of the program
    }
#else
    fprintf(stderr, "ALSA not available. Continuing with simulation.\n");
    pcm_handle = NULL;
#endif

    // Create audio processing thread
    if (pthread_create(&audio_thread, NULL, audio_processing_thread, (void *)audio_buffer) != 0) {
        fprintf(stderr, "Failed to create audio processing thread\n");
        free(audio_buffer);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop (audio capture/simulation)
    while (running) {
#ifdef ALSA_AVAILABLE
        if (pcm_handle != NULL) {
            if (capture_audio(pcm_handle, audio_buffer, PERIOD_SIZE) != 0) {
                fprintf(stderr, "Audio capture failed, exiting.\n");
                running = 0;
            }
        } else {
            simulate_audio(audio_buffer, PERIOD_SIZE);
        }
#else
        simulate_audio(audio_buffer, PERIOD_SIZE);
#endif
        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }

    // Clean up
    pthread_join(audio_thread, NULL);
    free(audio_buffer);

#ifdef ALSA_AVAILABLE
    if (pcm_handle != NULL) {
        snd_pcm_close(pcm_handle);
    }
#endif

    gpioTerminate();

    return 0;
}

