#ifdef ALSA_AVAILABLE
    if (initialize_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed. Continuing with simulation.\n");
        pcm_handle = NULL; // Ensure pcm_handle is NULL for the rest of the program
    }
#else
    fprintf(stderr, "ALSA not available. Continuing with simulation.\n");
    pcm_handle = NULL;
#endif

    // Create audio processing thread
    if (pthread_create(&audio_thread, NULL, audio_processing_thread, (void *)audio_buffer) != 0) {
        fprintf(stderr, "Failed to create audio processing thread\n");
        free(audio_buffer);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop (audio capture/simulation)
    while (running) {
#ifdef ALSA_AVAILABLE
        if (pcm_handle != NULL) {
            if (capture_audio(pcm_handle, audio_buffer, PERIOD_SIZE) != 0) {
                fprintf(stderr, "Audio capture failed, exiting.\n");
                running = 0;
            }
        } else {
            simulate_audio(audio_buffer, PERIOD_SIZE);
        }
#else
        simulate_audio(audio_buffer, PERIOD_SIZE);
#endif
        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }

    // Clean up
    pthread_join(audio_thread, NULL);
    free(audio_buffer);

#ifdef ALSA_AVAILABLE
    if (pcm_handle != NULL) {
        snd_pcm_close(pcm_handle);
    }
#endif

    gpioTerminate();

    return 0;
}

