#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Integration time (154ms)
#define INTEGRATION_TIME 0xD5

// Gain (1x)
#define GAIN 0x00

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function prototypes
int initialize_sensor();
color_data_t read_color_data();
void log_data(color_data_t data);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable sensor\n");
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, INTEGRATION_TIME) < 0) {
        fprintf(stderr, "Error: Could not set integration time\n");
        return -1;
    }

    // Set gain
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, GAIN) < 0) {
        fprintf(stderr, "Error: Could not set gain\n");
        return -1;
    }

    return 0;
}

// Read color data from the sensor
color_data_t read_color_data() {
    color_data_t data;
    uint8_t buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error: Could not read color data\n");
        data.clear = 0;
        data.red = 0;
        data.green = 0;
        data.blue = 0;
        return data;
    }

    data.clear = buffer[1] << 8 | buffer[0];
    data.red = buffer[3] << 8 | buffer[2];
    data.green = buffer[5] << 8 | buffer[4];
    data.blue = buffer[7] << 8 | buffer[6];

    return data;
}

// Log data to CSV file
void log_data(color_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, data.clear, data.red, data.green, data.blue);
    fflush(fp); // Ensure data is written to file immediately
}

