    i2c_handle = i2cOpen(I2C_BUS, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,C,R,G,B\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        color_data_t data = read_color_data();
        log_data(data);
        gpioDelay(500); // Sample every 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

