#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the total duration of one cycle (in seconds)
#define CYCLE_DURATION 24.0 * 60.0 * 60.0 // 24 hours

// Define the sunrise and sunset durations (in seconds)
#define SUNRISE_DURATION 60.0 * 60.0 // 1 hour
#define SUNSET_DURATION 60.0 * 60.0 // 1 hour

// Define the daytime and nighttime durations (in seconds)
#define DAYTIME_DURATION 6.0 * 60.0 * 60.0 // 6 hours
#define NIGHTTIME_DURATION 14.4 * 60.0 * 60.0 // 14.4 hours

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;

    // Turn off all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to set the duty cycle for all relays
void set_duty_cycle(int duty_cycle) {
    // Calculate the on and off times for each relay
    int on_time = duty_cycle;
    int off_time = 100 - duty_cycle;

    // Simulate PWM by toggling the relays
    gpioWrite(RELAY1_PIN, 0); // Turn on relay 1
    gpioDelay(on_time * 10000); // Delay for on time (microseconds)
    gpioWrite(RELAY1_PIN, 1); // Turn off relay 1
    gpioDelay(off_time * 10000); // Delay for off time (microseconds)

    gpioWrite(RELAY2_PIN, 0); // Turn on relay 2
    gpioDelay(on_time * 10000); // Delay for on time (microseconds)
    gpioWrite(RELAY2_PIN, 1); // Turn off relay 2
    gpioDelay(off_time * 10000); // Delay for off time (microseconds)

    gpioWrite(RELAY3_PIN, 0); // Turn on relay 3
    gpioDelay(on_time * 10000); // Delay for on time (microseconds)
    gpioWrite(RELAY3_PIN, 1); // Turn off relay 3
    gpioDelay(off_time * 10000); // Delay for off time (microseconds)

    gpioWrite(RELAY4_PIN, 0); // Turn on relay 4
    gpioDelay(on_time * 10000); // Delay for on time (microseconds)
    gpioWrite(RELAY4_PIN, 1); // Turn off relay 4
    gpioDelay(off_time * 10000); // Delay for off time (microseconds)
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Sunrise phase
        for (int duty_cycle = 0; duty_cycle <= 100; duty_cycle++) {
            set_duty_cycle(duty_cycle);
            gpioDelay(SUNRISE_DURATION * 1000000 / 101); // Delay for sunrise duration
            if (!program_running) break;
        }
        if (!program_running) break;

        // Daytime phase
        set_duty_cycle(100);
        gpioDelay(DAYTIME_DURATION * 1000000); // Delay for daytime duration
        if (!program_running) break;

        // Sunset phase
        for (int duty_cycle = 100; duty_cycle >= 0; duty_cycle--) {
            set_duty_cycle(duty_cycle);
            gpioDelay(SUNSET_DURATION * 1000000 / 101); // Delay for sunset duration
            if (!program_running) break;
        }
        if (!program_running) break;

        // Nighttime phase
        set_duty_cycle(0);
        gpioDelay(NIGHTTIME_DURATION * 1000000); // Delay for nighttime duration
        if (!program_running) break;
    }

    // Cleanup (should not be reached if signal handler works correctly)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);
    gpioTerminate();

    return 0;
}

