// Function to log motion events to a file
int log_motion_event(const char *timestamp) {
    if (log_fp == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    if (fprintf(log_fp, "%s\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_fp); // Ensure the data is written to the file immediately
    return 0;
}

// Function to capture a video using raspivid
int capture_video(const char *timestamp) {
    char filename[100];
    char command[200];

    // Create the filename
    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    // Construct the raspivid command
    snprintf(command, sizeof(command), "raspivid -o %s -t 5000", filename);

    // Execute the command
    int status = system(command);
    if (status == -1) {
        perror("Error executing raspivid command");
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Active-low sensor
        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            if (log_motion_event(timestamp) == 0) {
                printf("Motion detected at %s. Capturing video...\n", timestamp);
                if (capture_video(timestamp) != 0) {
                    fprintf(stderr, "Failed to capture video.\n");
                }
            } else {
                fprintf(stderr, "Failed to log motion event.\n");
            }
            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Failed to get timestamp.\n");
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up callback function for motion detection
    gpioSetAlertFunc(GPIO_PIN, motion_detected_callback);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();

    return 0;
}

