#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_ZOUT_H 0x47

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    double x;
    double y;
    double z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int wake_up_mpu6050();
int configure_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Wake up the MPU6050
int wake_up_mpu6050() {
    int result = i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to wake up MPU6050: %d\n", result);
        return -1;
    }
    return 0;
}

// Configure the MPU6050
int configure_mpu6050() {
    int result = i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to configure MPU6050: %d\n", result);
        return -1;
    }
    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, buf, 6);

    if (result < 0) {
        fprintf(stderr, "Failed to read gyro data: %d\n", result);
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    int16_t gyro_x = (buf[0] << 8) | buf[1];
    int16_t gyro_y = (buf[2] << 8) | buf[3];
    int16_t gyro_z = (buf[4] << 8) | buf[5];

    data.x = (double)gyro_x / GYRO_SCALE;
    data.y = (double)gyro_y / GYRO_SCALE;
    data.z = (double)gyro_z / GYRO_SCALE;

    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Main loop
    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data();
        log_data(gyro_data);
        gpioDelay(10000); // 10 ms delay
    }

    // Close log file and I2C connection
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

