    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop

    // Deactivate all relays
    control_relay(1, 1);
    control_relay(2, 1);
    control_relay(3, 1);
    control_relay(4, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Clean up GPIO before exiting
        return 1;
    }

    // Main loop
    while (running) {
        // Read moisture sensor
        int moisture_level = read_moisture_sensor();

        // Determine relay states based on moisture level
        int relay1_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay2_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay3_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
        int relay4_state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;

        // Control relays
        control_relay(1, relay1_state);
        control_relay(2, relay2_state);
        control_relay(3, relay3_state);
        control_relay(4, relay4_state);

        // Log data
        log_data(moisture_level, relay1_state, relay2_state, relay3_state, relay4_state);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    signal_handler(0); // Call the signal handler to perform cleanup

    return 0;
}

