#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define MEASUREMENT_INTERVAL 200 // milliseconds
#define MAX_DISTANCE 4.0         // meters
#define MAX_PULSE_WIDTH (int)(MAX_DISTANCE * 29.1 / 0.000001) // microseconds
#define TIMEOUT_THRESHOLD 100 // milliseconds

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_occurred = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pthread_mutex_lock(&mutex);
        echo_start_tick = tick;
        echo_received = 1;
        timeout_occurred = 0; // Reset timeout flag
        pthread_mutex_unlock(&mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&mutex);
        echo_end_tick = tick;
        pthread_mutex_unlock(&mutex);
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width) {
    return (double)pulse_width * 0.000001 * 343.0 / 2.0;
}

// Function to log distance to file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld,%.2f\n", ts.tv_nsec, distance);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        fclose(log_file);
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_count = 0;
        while (!echo_received && !timeout_occurred && running) {
            gpioDelay(1000); // 1 ms delay
            timeout_count++;
            if (timeout_count > TIMEOUT_THRESHOLD) {
                timeout_occurred = 1;
            }
        }

        if (timeout_occurred) {
            fprintf(stderr, "Timeout occurred\n");
        } else if (echo_received) {
            pthread_mutex_lock(&mutex);
            int pulse_width = echo_end_tick - echo_start_tick;
            pthread_mutex_unlock(&mutex);

            if (pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Pulse width exceeds maximum distance\n");
            } else {
                double distance = calculate_distance(pulse_width);
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            }
        }

        echo_received = 0; // Reset flags for next measurement
        timeout_occurred = 0;
        gpioDelay(MEASUREMENT_INTERVAL * 1000); // Delay between measurements
    }

    // Cleanup
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable interrupt
    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

