            }

            // Check for free-fall
            if (magnitude < freefall_threshold) {
                printf("Free-fall detected! Magnitude: %.2f g\n", magnitude);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (init_i2c() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                program_running = 0; // Exit loop if re-initialization fails
            }
            if (init_lis3dh() < 0) {
                fprintf(stderr, "Failed to re-initialize LIS3DH. Exiting.\n");
