#include <pigpio.h>

// Define GPIO pins for Motor 1 (X-axis)
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Define GPIO pins for Motor 2 (Y-axis)
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Define steps per revolution for 28BYJ-48 motor with 1/64 gear ratio
#define STEPS_PER_REVOLUTION 2048

// Define delay between steps in microseconds
#define STEP_DELAY 1000

// Define the size of the square in millimeters
#define SQUARE_SIZE 50

// Define the number of steps for one side of the square
#define STEPS_PER_SIDE (SQUARE_SIZE * 1000 / 500.0) // Assuming 500um per step

// Define the number of steps for the square
#define TOTAL_STEPS (STEPS_PER_SIDE * 4)

// Define the number of steps for a single step
#define STEPS_PER_STEP 1

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, stopping motors and exiting...\n", signal);
    program_running = 0;

    // Stop Motor 1
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);

    // Stop Motor 2
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to set the GPIO pins for a specific step
void set_step(int motor, int step) {
    int in1, in2, in3, in4;

    switch (step) {
        case 0:
            in1 = 1; in2 = 0; in3 = 0; in4 = 0;
            break;
        case 1:
            in1 = 0; in2 = 1; in3 = 0; in4 = 0;
            break;
        case 2:
            in1 = 0; in2 = 0; in3 = 1; in4 = 0;
            break;
        case 3:
            in1 = 0; in2 = 0; in3 = 0; in4 = 1;
            break;
        default:
            fprintf(stderr, "Error: Invalid step number: %d\n", step);
            return;
    }

    if (motor == 1) {
        gpioWrite(MOTOR1_IN1, in1);
        gpioWrite(MOTOR1_IN2, in2);
        gpioWrite(MOTOR1_IN3, in3);
        gpioWrite(MOTOR1_IN4, in4);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_IN1, in1);
        gpioWrite(MOTOR2_IN2, in2);
        gpioWrite(MOTOR2_IN3, in3);
        gpioWrite(MOTOR2_IN4, in4);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
    }
}

// Function to move a motor a specified number of steps
void move_motor(int motor, int steps) {
    int i;
    int current_step = 0;

    for (i = 0; i < steps; i++) {
        if (!program_running) return; // Check for program termination

        set_step(motor, current_step);
        gpioDelay(STEP_DELAY);

        current_step = (current_step + 1) % 4; // Cycle through the steps
    }

    // Ensure the motor is stopped after the movement
    if (motor == 1) {
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 0);
        gpioWrite(MOTOR1_IN3, 0);
        gpioWrite(MOTOR1_IN4, 0);
    } else if (motor == 2) {
        gpioWrite(MOTOR2_IN1, 0);
        gpioWrite(MOTOR2_IN2, 0);
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN4, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Drawing a square... Press Ctrl+C to stop.\n");

    // Move Motor 1 (X-axis) to trace the square
    move_motor(1, STEPS_PER_SIDE); // Move right
    move_motor(2, STEPS_PER_SIDE); // Move up
    move_motor(1, -STEPS_PER_SIDE); // Move left
    move_motor(2, -STEPS_PER_SIDE); // Move down
    move_motor(1, STEPS_PER_SIDE); // Move right (back to start)

    // Stop motors
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Square drawing complete.\n");

    return 0;
}

