#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Global variables
int i2c_handle;
int i2c_address = LIS3DH_ADDR;
float threshold = 2.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
void log_acceleration(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the LIS3DH accelerometer
int init_lis3dh(int i2c_handle) {
    // Configure CTRL_REG1: 100 Hz, Normal mode, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: ±2g range, 12-bit resolution
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes of data starting from OUT_X_L
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0.0;
        *y = 0.0;
        *z = 0.0;
        return -1;
    }

    // Combine low and high bytes to get raw values
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to g (assuming 12-bit resolution and ±2g range)
    *x = (float)raw_x / 16384.0;
    *y = (float)raw_y / 16384.0;
    *z = (float)raw_z / 16384.0;

    return 0;
}

// Function to log acceleration data to a file
void log_acceleration(float x, float y, float z) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    // Write data to log file
    fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, x, y, z);

    // Close log file
    fclose(fp);
}

// Function to shutdown the system
void shutdown_system() {
    printf("Shutting down system...\n");
    system("sudo shutdown -h now");
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int opt;
    float x, y, z;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x03 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x03 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
