#include <unistd.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_LED 22

// Define motor control functions (placeholders)
void moveForward() { printf("Moving Forward\n"); }
void turnLeft() { printf("Turning Left\n"); }
void turnRight() { printf("Turning Right\n"); }
void stop() { printf("Stopping\n"); }

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} sensor_reading_t;

// Circular buffer
sensor_reading_t sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int readSensor(int gpio);
void addToBuffer(int left, int center, int right);
int checkBufferForLine();
void controlRobot(int left, int center, int right);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(ALERT_LED, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read sensor value
int readSensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to add sensor reading to the circular buffer
void addToBuffer(int left, int center, int right) {
    sensor_buffer[buffer_index].left = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check the circular buffer for a line
int checkBufferForLine() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (sensor_buffer[i].center == 1) {
            return 0; // No line detected
        }
    }
    return 1; // Line detected
}

// Function to control the robot based on sensor readings
void controlRobot(int left, int center, int right) {
    if (center == 1) {
        if (left == 0) {
            turnLeft();
        } else if (right == 0) {
            turnRight();
        } else {
            stop();
        }
    } else {
        moveForward();
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_LED, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        // Read sensor values
        int left = readSensor(LEFT_SENSOR);
        int center = readSensor(CENTER_SENSOR);
        int right = readSensor(RIGHT_SENSOR);

        if (left == -1 || center == -1 || right == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break; // Exit loop on error
        }

        // Add sensor readings to the circular buffer
        addToBuffer(left, center, right);

        // Check if the center sensor has detected a line for five consecutive readings
        if (checkBufferForLine()) {
            printf("Line detected for five consecutive readings!\n");
            gpioWrite(ALERT_LED, 1); // Turn on LED
            gpioDelay(2000); // Wait for 2 seconds
            gpioWrite(ALERT_LED, 0); // Turn off LED
        }

        // Control the robot
        controlRobot(left, center, right);

        // Delay for 10 milliseconds
        gpioDelay(10);
    }

    // Cleanup (should not reach here normally due to signal handler)
    gpioWrite(ALERT_LED, 0);
    gpioTerminate();
    return 0;
}

