#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define SI7210_REG_FIELD_DATA 0x01
#define SI7210_REG_CONFIG 0x00
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define SAMPLE_INTERVAL_MS 100
#define POLL_TIMEOUT_MS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
void close_resources();
void signal_handler(int signal);
int read_magnetic_field(float *field);
int control_relay(int state);
int log_event(const char *event);
int log_error(const char *error_message);
int configure_sensor();

// Structure for sensor configuration
typedef struct {
    uint8_t config_value;
} sensor_config_t;

// Function to get current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        return -1;
    }
    return 0;
}

// Function to initialize logging
int init_logging() {
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

// Function to close resources
void close_resources() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received SIGINT, shutting down...");
    close_resources();
    exit(0);
}

// Function to read magnetic field data
int read_magnetic_field(float *field) {
    char buf[2];
    int result;
    int attempts = 0;

    while (attempts < POLL_TIMEOUT_MS) {
        result = i2cReadI2CBlockData(i2c_handle, SI7210_REG_FIELD_DATA, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            int16_t raw_field = (buf[0] << 8) | buf[1];

            // Convert raw value to milliTesla (mT).  Refer to Si7210 datasheet.
            *field = (float)raw_field * 0.01; // Example conversion, adjust as needed
            return 0; // Success
        } else {
            log_error("I2C read failed, retrying...");
            gpioWrite(RELAY_GPIO, 0); // Deactivate relay
            gpioDelay(10); // Wait 10ms
            attempts++;
        }
    }

    log_error("I2C read timeout");
    return -1; // Timeout
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        log_error("Failed to control relay");
        return -1;
    }
    return 0;
}

// Function to log events
int log_event(const char *event) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        perror("Failed to get timestamp");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write
    free(timestamp);
    return 0;
}

// Function to log errors
int log_error(const char *error_message) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        perror("Failed to get timestamp");
        return -1;
    }

    fprintf(log_file, "%s: ERROR: %s\n", timestamp, error_message);
    fflush(log_file);
    free(timestamp);
    return 0;
}

// Function to configure the sensor
int configure_sensor() {
    // Example configuration value (adjust as needed based on datasheet)
    uint8_t config_value = 0x03; // Example: Continuous mode, gain setting
    char buf[1];
    buf[0] = config_value;

    if (i2cWriteI2CBlockData(i2c_handle, SI7210_REG_CONFIG, buf, 1) != 1) {
        log_error("Failed to configure sensor");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize resources
    if (init_logging() != 0 || init_i2c() != 0 || init_gpio() != 0) {
        close_resources();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Configure sensor
    if (configure_sensor() != 0) {
        close_resources();
        return 1;
    }

    float magnetic_field;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        if (read_magnetic_field(&magnetic_field) == 0) {
            char event_message[100];
            snprintf(event_message, sizeof(event_message), "Magnetic field: %.2f mT", magnetic_field);
            log_event(event_message);

            if (magnetic_field > THRESHOLD_MT) {
                if (relay_state == 0) {
                    if (control_relay(1) == 0) {
                        relay_state = 1;
                        log_event("Relay activated");
                    }
                }
            } else {
                if (relay_state == 1) {
                    if (control_relay(0) == 0) {
                        relay_state = 0;
                        log_event("Relay deactivated");
                    }
                }
            }
        } else {
            log_error("Failed to read magnetic field");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close_resources();
    return 0;
}

