    // Initialize resources
    if (init_logging() != 0 || init_i2c() != 0 || init_gpio() != 0) {
        close_resources();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Configure sensor
    if (configure_sensor() != 0) {
        close_resources();
        return 1;
    }

    float magnetic_field;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        if (read_magnetic_field(&magnetic_field) == 0) {
            char event_message[100];
