#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

int server_fd, new_socket;
FILE *log_file;

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    static char timestamp[20]; // Ensure static allocation
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log messages to file
void log_message(const char *message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", get_timestamp(), message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to handle relay control
void handle_relay_control(const char *command) {
    if (strcasecmp(command, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1); // Activate relay
        log_message("Relay activated.");
    } else if (strcasecmp(command, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0); // Deactivate relay
        log_message("Relay deactivated.");
    } else {
        log_message("Invalid command received.");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    log_message("Received signal, shutting down...");

    // Close socket
    if (new_socket > 0) {
        close(new_socket);
    }
    if (server_fd > 0) {
        close(server_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Deactivate relay
    gpioWrite(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(signum);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_message("Socket creation failed.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_message("Socket bind failed.");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        log_message("Socket listen failed.");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_message("Server listening on port 5000...");

    // Accept incoming connections
    while ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept failed");
        log_message("Socket accept failed.");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_message("Client connected.");

    // Receive and process commands
    while (1) {
        memset(buffer, 0, BUFFER_SIZE); // Clear buffer
        ssize_t bytes_received = recv(new_socket, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received < 0) {
            perror("recv failed");
            log_message("Socket recv failed.");
            break;
        } else if (bytes_received == 0) {
            log_message("Client disconnected.");
            break;
        }

        // Remove trailing whitespace
        char *end = buffer + strlen(buffer);
        while (end > buffer && isspace((unsigned char)(end[-1]))) {
            end--;
        }
        *end = '\0';

        handle_relay_control(buffer);
    }

    // Cleanup
    close(new_socket);
    close(server_fd);
    fclose(log_file);
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();

    return 0;
}

