#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define MEASUREMENT_COMMAND 0x3608
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int start_measurement(int handle);
int read_flow_rate(int handle, float *flow_rate);
int validate_crc(uint8_t data[], int len);
int set_relay_state(int gpio, int state);
int log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Start continuous measurement
int start_measurement(int handle) {
    char buf[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read flow rate from sensor
int read_flow_rate(int handle, float *flow_rate) {
    char buf[3];
    int bytes_read = i2cReadDevice(handle, buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    if (validate_crc((uint8_t *)buf, 2) != 0) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    int16_t raw_flow = (buf[0] << 8) | buf[1];
    *flow_rate = (float)raw_flow / 100.0; // Scale factor from datasheet

    return 0;
}

// Validate CRC
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = crc8(data, len);
    if (crc != data[2]) {
        return -1;
    }
    return 0;
}

// Set relay state
int set_relay_state(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

// Log flow data
int log_flow_data(float flow1, float flow2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.2f,%.2f\n", timestamp_ms, flow1, flow2);
    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // De-energize relay
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }
    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Start measurement
    if (start_measurement(i2c_handle1) < 0) {
        cleanup();
        return 1;
    }
    if (start_measurement(i2c_handle2) < 0) {
        cleanup();
        return 1;
    }

    // Configure relay GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    float flow1, flow2;
    int relay_state = 0;

    // Main loop
    while (!terminate) {
        // Read flow rates
        if (read_flow_rate(i2c_handle1, &flow1) == 0 && read_flow_rate(i2c_handle2, &flow2) == 0) {
            // Log flow data
            log_flow_data(flow1, flow2);

            // Control relay
            if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
                relay_state = 1;
            } else {
                relay_state = 0;
            }
            set_relay_state(RELAY_GPIO, relay_state);
        } else {
            fprintf(stderr, "Error reading flow rates\n");
        }

        // Sleep for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

