#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000
#define SHUTDOWN_PULSE_WIDTH 0

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program state for signal handler
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_button(int pin);
int debounce(int pin);
int set_servo_pulse_width(int pulse_width);
void handle_signal(int signal);

// Signal handler function
void handle_signal(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, shutting down...\n", signal);

    // Stop the servo
    if (set_servo_pulse_width(SHUTDOWN_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error stopping servo during shutdown.\n");
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Read button state with debouncing
int read_button(int pin) {
    return gpioRead(pin);
}

// Debounce the button
int debounce(int pin) {
    int count = 0;
    for (int i = 0; i < 5; i++) {
        if (read_button(pin) == 0) {
            count++;
        }
        gpioDelay(1000); // 1ms delay
    }
    if (count == 5) {
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        return 1; // Button is pressed
    } else {
        return 0; // Button is not pressed
    }
}

// Set servo pulse width
int set_servo_pulse_width(int pulse_width) {
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error setting servo pulse width.\n");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Door lock actuator program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (debounce(LOCK_BUTTON_PIN)) {
            printf("Lock button pressed.\n");
            if (set_servo_pulse_width(LOCK_PULSE_WIDTH) == 0) {
                printf("Door locked.\n");
            } else {
                fprintf(stderr, "Error locking door.\n");
            }
        }

        // Check unlock button
        if (debounce(UNLOCK_BUTTON_PIN)) {
            printf("Unlock button pressed.\n");
            if (set_servo_pulse_width(UNLOCK_PULSE_WIDTH) == 0) {
                printf("Door unlocked.\n");
            } else {
                fprintf(stderr, "Error unlocking door.\n");
            }
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

