#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define LED_PIN 17

// Define constants
#define POLLING_INTERVAL_MS 100
#define LED_ON_TIME_SEC 60
#define LOG_FILE "security_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, const char *timestamp, int duration);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int pir_pin;
    int led_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Control LED state
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Log event to file
int log_event(const char *event_type, const char *timestamp, int duration) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    if (strcmp(event_type, "activation") == 0) {
        fprintf(log_file, "%s: Floodlight activated\n", timestamp);
    } else if (strcmp(event_type, "deactivation") == 0) {
        fprintf(log_file, "%s: Floodlight deactivated, duration: %d seconds\n", timestamp, duration);
    } else {
        fprintf(stderr, "Invalid event type: %s\n", event_type);
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        cleanup(); // Cleanup and exit
        return 1;
    }

    printf("Monitoring PIR sensor...\n");

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            // Motion detected
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            printf("Motion detected at %s\n", timestamp);

            // Activate LED
            if (control_led(1) != 0) {
                fprintf(stderr, "Failed to activate LED\n");
                cleanup();
                return 1;
            }

            // Log activation event
            if (log_event("activation", timestamp, LED_ON_TIME_SEC) != 0) {
                fprintf(stderr, "Failed to log activation event\n");
                cleanup();
                return 1;
            }

            // Wait for LED on time
            gpioDelay(LED_ON_TIME_SEC * 1000000); // Convert seconds to microseconds

            // Deactivate LED
            if (control_led(0) != 0) {
                fprintf(stderr, "Failed to deactivate LED\n");
                cleanup();
                return 1;
            }

            // Log deactivation event
            if (log_event("deactivation", timestamp, LED_ON_TIME_SEC) != 0) {
                fprintf(stderr, "Failed to log deactivation event\n");
                cleanup();
                return 1;
            }
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    cleanup(); // Cleanup before exiting
    return 0;
}

