#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <stdarg.h>

#define PIR_GPIO 4
#define SERVO_GPIO 17
#define PORT 5000
#define LOG_FILE "security.log"

// Global variables for signal handling
static volatile int running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
void log_message(int priority, const char *format, ...);
int set_servo_angle(int angle);
int read_pir_sensor();
void handle_client(int client_fd);
void signal_handler(int signal);

// Function to log messages to syslog and file
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    vsyslog(priority, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }

    // Calculate pulse width (1ms - 2ms for 0-180 degrees)
    int pulse_width = 1000 + (angle * 1000 / 180);

    if (gpioServo(SERVO_GPIO, pulse_width) != 0) {
        log_message(LOG_ERR, "Failed to set servo pulse width: %d", pulse_width);
        return -1;
    }

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    int value = gpioRead(PIR_GPIO);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor");
        return -1;
    }
    return value;
}

// Function to handle a client connection
void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_received;

    while (running) {
        bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            log_message(LOG_INFO, "Received command: %s", buffer);

            char *command = strtok(buffer, " ");
            if (command != NULL) {
                if (strcmp(command, "set_servo_angle") == 0) {
                    char *angle_str = strtok(NULL, " ");
                    if (angle_str != NULL) {
                        int angle = atoi(angle_str);
                        if (set_servo_angle(angle) == 0) {
                            char response[32];
                            snprintf(response, sizeof(response), "Servo angle set to %d", angle);
                            send(client_fd, response, strlen(response), 0);
                        } else {
                            send(client_fd, "Failed to set servo angle", strlen("Failed to set servo angle"), 0);
                        }
                    } else {
                        send(client_fd, "Invalid angle", strlen("Invalid angle"), 0);
                    }
                } else if (strcmp(command, "read_pir_sensor") == 0) {
                    int pir_value = read_pir_sensor();
                    if (pir_value >= 0) {
                        char response[32];
                        snprintf(response, sizeof(response), "PIR: %d", pir_value);
                        send(client_fd, response, strlen(response), 0);
                    } else {
                        send(client_fd, "Failed to read PIR sensor", strlen("Failed to read PIR sensor"), 0);
                    }
                } else {
                    send(client_fd, "Invalid command", strlen("Invalid command"), 0);
                }
            } else {
                send(client_fd, "Invalid command", strlen("Invalid command"), 0);
            }
        } else if (bytes_received == 0) {
            log_message(LOG_INFO, "Client disconnected");
            break;
        } else {
            log_message(LOG_ERR, "Error receiving data");
            break;
        }
    }

    close(client_fd);
}

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received: %d. Shutting down...", signal);
    running = 0;

    // Close socket
    if (server_fd != -1) {
        close(server_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        fclose(log_file);
        closelog();
