#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150.0
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750();
float read_lux();
void control_relay(float lux);
void log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750() {
    int result = i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error initializing BH1750: %d\n", result);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
float read_lux() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from BH1750: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return (float)raw_value / 1.2;
}

// Control the grow light relay
void control_relay(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1); // Activate relay
    } else {
        gpioWrite(GPIO_RELAY, 0); // Deactivate relay
    }
}

// Log data to file
void log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Deactivate relay
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            control_relay(lux);
            log_data(lux);
        } else {
            fprintf(stderr, "Error reading lux value, retrying...\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

