#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double tare_value = 0.0;
static double scale_factor = DEFAULT_SCALE;
static double threshold = DEFAULT_THRESHOLD;
static int solenoid_duration = DEFAULT_DURATION;

// Function prototypes
int read_hx711();
double average_readings(int num_readings);
void tare_load_cell();
void activate_solenoid();
void signal_handler(int signal);
void parse_arguments(int argc, char *argv[]);

// Function to read a 24-bit two's complement value from HX711
int read_hx711() {
    int i;
    int data = 0;

    gpioWrite(HX711_SCK, 0);
    // Wait for DOUT to go low
    int timeout = 1000; // 1 second timeout
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "Timeout waiting for HX711 DOUT to go low.");
        return -1; // Indicate error
    }

    // Clock in 24 bits
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Short delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Short delay
    }

    // Clock in one extra pulse to select Channel A gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to average multiple readings
double average_readings(int num_readings) {
    double sum = 0.0;
    int reading;
    for (int i = 0; i < num_readings; i++) {
        reading = read_hx711();
        if (reading == -1) {
            syslog(LOG_ERR, "Error reading HX711, returning average of previous readings.");
            return sum / (i + 1); // Return average of valid readings
        }
        sum += reading;
        gpioDelay(10); // Small delay between readings
    }
    return sum / num_readings;
}

// Function to tare the load cell
void tare_load_cell() {
    syslog(LOG_INFO, "Starting tare procedure.");
    tare_value = average_readings(10);
    syslog(LOG_INFO, "Tare value: %lf", tare_value);
}

// Function to activate the solenoid lock
void activate_solenoid() {
    syslog(LOG_INFO, "Activating solenoid lock.");
    gpioWrite(SOLENOID_PIN, 1); // Set GPIO HIGH
    gpioDelay(solenoid_duration); // Wait for specified duration
    gpioWrite(SOLENOID_PIN, 0); // Set GPIO LOW
    syslog(LOG_INFO, "Solenoid lock deactivated.");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...");
    running = 0;
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

// Function to parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            case 'd':
                solenoid_duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    tare_load_cell();

    // Main loop
    while (running) {
        double weight = (average_readings(5) - tare_value) * scale_factor;
        syslog(LOG_INFO, "Weight: %lf grams", weight);

        if (weight > threshold) {
            activate_solenoid();
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog

    return 0;
}

