    int reading;
    for (int i = 0; i < num_readings; i++) {
        reading = read_hx711();
        if (reading == -1) {
            syslog(LOG_ERR, "Error reading HX711, returning average of previous readings.");
            return sum / (i + 1); // Return average of valid readings
        }
        sum += reading;
        gpioDelay(10); // Small delay between readings
    }
    return sum / num_readings;
}

// Function to tare the load cell
void tare_load_cell() {
    syslog(LOG_INFO, "Starting tare procedure.");
    tare_value = average_readings(10);
    syslog(LOG_INFO, "Tare value: %lf", tare_value);
}

// Function to activate the solenoid lock
void activate_solenoid() {
    syslog(LOG_INFO, "Activating solenoid lock.");
    gpioWrite(SOLENOID_PIN, 1); // Set GPIO HIGH
    gpioDelay(solenoid_duration); // Wait for specified duration
    gpioWrite(SOLENOID_PIN, 0); // Set GPIO LOW
    syslog(LOG_INFO, "Solenoid lock deactivated.");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...");
    running = 0;
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog
    exit(0);
}

// Function to parse command-line arguments
void parse_arguments(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            case 'd':
                solenoid_duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Parse command-line arguments
    parse_arguments(argc, argv);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    tare_load_cell();

    // Main loop
    while (running) {
        double weight = (average_readings(5) - tare_value) * scale_factor;
        syslog(LOG_INFO, "Weight: %lf grams", weight);

        if (weight > threshold) {
            activate_solenoid();
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Release GPIO resources
    closelog(); // Close syslog

    return 0;
}

