#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <pthread.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_KEEPALIVE 60
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17
#define LOG_FACILITY LOG_USER
#define LOG_TAG "mqtt_relay"

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;
static int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
void signal_handler(int sig);
int mqtt_connect_and_subscribe();
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void set_relay_state(int state);

// Signal handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// MQTT connect and subscribe function
int mqtt_connect_and_subscribe() {
    int rc;

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance.");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    return 0;
}

// MQTT message callback function
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            set_relay_state(1);
            syslog(LOG_INFO, "Received ON command, setting relay state to ON.");
        } else if (strcmp(payload, "OFF") == 0) {
            set_relay_state(0);
            syslog(LOG_INFO, "Received OFF command, setting relay state to OFF.");
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received.");
    }
}

// MQTT disconnect callback function
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_WARNING, "Disconnected from MQTT broker.");
    if (rc != 0) {
        syslog(LOG_ERR, "Disconnected with error: %s", mosquitto_strerror(rc));
    }
}

// MQTT connect callback function
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker.");
    } else {
        syslog(LOG_ERR, "Connection failed: %s", mosquitto_strerror(result));
    }
}

// Set relay state function
void set_relay_state(int state) {
    if (state != relay_state) {
        gpioWrite(GPIO_PIN, state);
        relay_state = state;
    }
}

int main() {
    openlog(LOG_TAG, LOG_PID, LOG_FACILITY);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    set_relay_state(0); // Initialize relay to OFF

    while (running) {
        if (!mosq || mosquitto_is_connected(mosq)) {
            if (!mosq) {
                if (mqtt_connect_and_subscribe() != 0) {
                    syslog(LOG_ERR, "Failed to connect to MQTT broker, retrying in 5 seconds...");
                    sleep(5);
                    continue;
                }
            }
            int rc = mosquitto_loop(mosq, -1, 1); // Non-blocking loop
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "MQTT loop error: %s, retrying in 5 seconds...", mosquitto_strerror(rc));
                mosquitto_disconnect(mosq);
                mosquitto_destroy(mosq);
                mosq = NULL;
                sleep(5);
            }
        } else {
            if (mqtt_connect_and_subscribe() != 0) {
                syslog(LOG_ERR, "Failed to connect to MQTT broker, retrying in 5 seconds...");
                sleep(5);
            }
        }
    }

    // Cleanup
    set_relay_state(0); // Ensure relay is OFF on exit
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }
    gpioTerminate();
    closelog();

    return 0;
}

