#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define pulse width limits
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define pulse width target values
const int target_pulse_widths[] = {1000, 1500, 2000, 500, 2500};

// Define servo pins
const int servo_pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to set servo pulse width
void set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d us) for GPIO %d. Must be between %d and %d us.\n", pulse_width, gpio_pin, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return;
    }
    gpioServo(gpio_pin, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency to 50 Hz (20ms period)
    gpioSetPWMfrequency(SERVO1_PIN, 50);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Move servos to target positions
        for (int i = 0; i < 5; i++) {
            set_servo_pulse_width(servo_pins[i], target_pulse_widths[i]);
        }

        // Wait for 3 seconds
        sleep(3);

        // Stop servos
        for (int i = 0; i < 5; i++) {
            gpioServo(servo_pins[i], 0);
        }

        // Wait for 3 seconds
        sleep(3);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

