#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PWM Frequency
#define PWM_FREQUENCY 10000

// Target RPM
#define TARGET_RPM 50

// PI Controller Gains
#define KP 1.0
#define KI 0.1

// Anti-Windup Limit
#define MAX_I 100

// Stall Detection Timeout (seconds)
#define STALL_TIMEOUT 2

// Global Variables
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile int encoder_a_last_ticks = 0;
volatile int encoder_b_last_ticks = 0;
volatile int stall_start_time = 0;
volatile int stalled = 0;

double integral = 0;

// Function Prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double calculate_error(double target_rpm, double current_rpm);
double calculate_control_signal(double error);
void set_motor_speed(int motor_a_pwm, int motor_a_dir, int motor_b_pwm, int motor_b_dir, int pwm_value);
void signal_handler(int signal);

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    int a = gpioRead(ENCODER_A_A);
    int b = gpioRead(ENCODER_A_B);

    if (a == 1 && b == 0) {
        encoder_a_ticks++;
    } else if (a == 0 && b == 1) {
        encoder_a_ticks--;
    }
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    int a = gpioRead(ENCODER_B_A);
    int b = gpioRead(ENCODER_B_B);

    if (a == 1 && b == 0) {
        encoder_b_ticks++;
    } else if (a == 0 && b == 1) {
        encoder_b_ticks--;
    }
}

// Calculate RPM
double calculate_rpm(int ticks) {
    double rpm = (double)ticks * 60.0 / 64.0; // Assuming 64 ticks per revolution
    return rpm;
}

// Calculate Error
double calculate_error(double target_rpm, double current_rpm) {
    return target_rpm - current_rpm;
}

// Calculate Control Signal
double calculate_control_signal(double error) {
    double signal = KP * error;
    integral += KI * error;

    // Anti-Windup
    if (integral > MAX_I) {
        integral = MAX_I;
    } else if (integral < -MAX_I) {
        integral = -MAX_I;
    }

    signal += integral;
    return signal;
}

// Set Motor Speed
void set_motor_speed(int motor_a_pwm, int motor_a_dir, int motor_b_pwm, int motor_b_dir, int pwm_value) {
    if (pwm_value < 0) {
        pwm_value = 0;
    } else if (pwm_value > 255) {
        pwm_value = 255;
    }

    gpioPWM(motor_a_pwm, pwm_value);
    gpioWrite(motor_a_dir, 1); // Forward

    gpioPWM(motor_b_pwm, pwm_value);
    gpioWrite(motor_b_dir, 1); // Forward
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_motor_speed(MOTOR_A_PWM, MOTOR_A_DIR, MOTOR_B_PWM, MOTOR_B_DIR, 0); // Stop motors
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

