#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_DUSK 50
#define LUX_DAWN 200
#define LUX_HYSTERESIS 10
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_bh1750();
float read_lux();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Function to initialize the BH1750 sensor
int init_bh1750() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Set to continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Error setting BH1750 mode: %d\n", i2c_handle);
        i2cClose(i2c_handle);
        return -1;
    }
    gpioDelay(180); // Wait for mode to take effect

    return 0;
}

// Function to read the lux value from the BH1750 sensor
float read_lux() {
    unsigned char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading lux value: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

// Function to log the data to a file
void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_RELAY as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the BH1750 sensor
    if (init_bh1750() != 0) {
        fprintf(stderr, "BH1750 initialization failed!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int relay_state = 0; // 0 = OFF, 1 = ON
    float lux;

    while (program_running) {
        lux = read_lux();

        if (lux < 0) {
            fprintf(log_file, "Error reading lux value. Turning relay OFF.\n");
            control_relay(0);
            relay_state = 0;
        } else {
            if (lux < LUX_DUSK && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                fprintf(log_file, "Lux below dusk threshold (%.2f < %d). Turning relay ON.\n", lux, LUX_DUSK);
            } else if (lux > LUX_DAWN + LUX_HYSTERESIS && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                fprintf(log_file, "Lux above dawn threshold (%.2f > %d). Turning relay OFF.\n", lux, LUX_DAWN + LUX_HYSTERESIS);
            }
        }

        log_data(lux, relay_state);
        gpioDelay(5000); // Poll every 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0); // Turn off relay on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

