#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
int debounce();
int toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, turning relay OFF and exiting.\n");
        gpioWrite(RELAY_PIN, 0); // Turn relay OFF
        gpioTerminate(); // Release pigpio resources
        exit(0);
    }
}

// Function to read the touch sensor
int read_touch_sensor() {
    int touch_value = gpioRead(TOUCH_SENSOR_PIN);
    if (touch_value < 0) {
        fprintf(stderr, "Error reading touch sensor: %d\n", touch_value);
        return -1; // Indicate an error
    }
    return touch_value;
}

// Function to implement debouncing
int debounce() {
    int touch_value = read_touch_sensor();
    if (touch_value < 0) return -1; // Propagate error

    if (touch_value == 1) {
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
        int touch_value_after_delay = read_touch_sensor();
        if (touch_value_after_delay < 0) return -1; // Propagate error

        if (touch_value_after_delay == 1) {
            return 1; // Valid touch detected
        }
    }
    return 0; // No valid touch detected
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state; // Toggle the relay state
    int result = gpioWrite(RELAY_PIN, relay_state);
    if (result != 0) {
        fprintf(stderr, "Error writing to relay: %d\n", result);
        return -1; // Indicate an error
    }
    return 0;
}

// Function to log the relay state with an ISO 8601 timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is %s\n", timestamp, state ? "ON" : "OFF");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;
    log_relay_state(relay_state);

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int touch_detected = debounce();
        if (touch_detected > 0) {
            if (toggle_relay() == 0) {
                log_relay_state(relay_state);
            }
            // Wait for the sensor to return to LOW
            while (gpioRead(TOUCH_SENSOR_PIN) == 1) {
                gpioDelay(1000); // Check every 1ms
            }
        } else if (touch_detected < 0) {
            fprintf(stderr, "Error during debouncing, exiting.\n");
            gpioTerminate();
            return 1;
        }

        gpioDelay(10000); // Sleep for 10ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

