void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Interrupt service routine (ISR) for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data)
{
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the signal
    if (current_tick - last_tick > DEBOUNCE_TIMEOUT * 1000) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
        last_tick = current_tick;
    }
}

// Function to calculate LPM
double calculate_lpm(int pulse_count, double time_interval)
{
    return (double)pulse_count / time_interval * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm, int *solenoid_state)
{
    if (lpm > FLOW_THRESHOLD_HIGH && *solenoid_state == 1) {
        gpioWrite(SOLENOID_PIN, 0); // Close the solenoid
        *solenoid_state = 0;
    } else if (lpm < FLOW_THRESHOLD_LOW && *solenoid_state == 0) {
        gpioWrite(SOLENOID_PIN, 1); // Open the solenoid
        *solenoid_state = 1;
    }
}

// Function to log data to file
void log_data(double lpm, int solenoid_state)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

