        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt handler for flow sensor
    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL);

    int solenoid_state = 1; // 1 = OPEN, 0 = CLOSED
    int previous_pulse_count = 0;
    double time_interval = 1.0; // 1 second
    double lpm;

    // Main loop
    while (1) {
        gpioDelay(1000); // Wait for 1 second

        // Calculate LPM
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next interval
        pthread_mutex_unlock(&pulse_mutex);

        lpm = calculate_lpm(current_pulse_count - previous_pulse_count, time_interval);
        previous_pulse_count = current_pulse_count;

        // Control solenoid
        control_solenoid(lpm, &solenoid_state);

        // Log data
        log_data(lpm, solenoid_state);
    }

    return 0;
}

