#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <jansson.h>
#include <errno.h>

// Configuration
#define HOST_IP "127.0.0.1"
#define HOST_PORT 12345
#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define CALIBRATION_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define API_ENDPOINT "http://localhost:8080/dispensing"
#define API_TIMEOUT 5 // seconds

// Default values
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_TARGET_WEIGHT 0.0
#define DEFAULT_ACTUAL_WEIGHT 0.0

// Global variables
static volatile int running = 1;
static int socket_fd = -1;
static FILE *log_file = NULL;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static double target_weight = DEFAULT_TARGET_WEIGHT;
static double actual_weight = DEFAULT_ACTUAL_WEIGHT;

// Function prototypes
int init_gpio();
int init_socket();
int read_config();
int read_hx711();
int calibrate_weight(int raw_weight);
int map_weight_to_pulse_width(double target_weight);
int send_api_request(double target_weight, double actual_weight);
int log_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);

// HX711 read function with timeout
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    gpioWrite(SCK_PIN, 0);

    // Wait for DATA to go low
    for (i = 0; i < 1000; i++) {
        if (gpioRead(DATA_PIN) == 0) {
            break;
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (i >= 1000) {
        fprintf(stderr, "Error: HX711 DATA pin did not go low within timeout.\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1); // 1 us clock pulse
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1);
        data = data << 1;
        if (gpioRead(DATA_PIN)) {
            data++;
        }
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    data = data ^ 0x800000; // Convert to signed 24-bit integer

    return data;
}

// Calibration function
int calibrate_weight(int raw_weight) {
    return (int)(raw_weight / calibration_factor);
}

// Weight mapping function
int map_weight_to_pulse_width(double target_weight) {
    return (int)((target_weight / 100.0) * 1000.0 + 1000.0); // Map 0-100g to 1000-2000us
}

// API request function
int send_api_request(double target_weight, double actual_weight) {
    char json_string[256];
    snprintf(json_string, sizeof(json_string), "{\"target_weight\": %.2f, \"actual_weight\": %.2f}", target_weight, actual_weight);

    // Placeholder for API call implementation using libcurl or similar
    printf("API Request: %s\n", json_string);
    // In a real implementation, this would involve network communication.
    // For example, using libcurl:
    // curl_easy_setopt(curl, CURLOPT_URL, API_ENDPOINT);
    // curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    // curl_easy_perform(curl);

    return 0; // Placeholder return value
}

// Logging function
int log_event(double target_weight, double actual_weight, const char *error_message) {
    json_t *root = json_object();
    json_t *timestamp = json_string(NULL);
    json_t *target = json_real(target_weight);
    json_t *actual = json_real(actual_weight);
    json_t *error = json_string(error_message);

    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

    json_object_set_new(root, "timestamp", json_string(buf));
    json_object_set_new(root, "target_weight", target);
    json_object_set_new(root, "actual_weight", actual);
    json_object_set_new(root, "error", error);

    char *json_str = json_dumps(root, JSON_INDENT(4));
    if (!json_str) {
        fprintf(stderr, "Error: Could not serialize JSON object.\n");
        json_decref(root);
        return -1;
    }

    fprintf(log_file, "%s\n", json_str);
    fflush(log_file);

    json_decref(root);
    free(json_str);

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Stop pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz PWM frequency
    gpioSetPWMrange(SERVO_PIN, 1000); // PWM range of 0-1000

    return 0;
}

// Initialize socket
int init_socket() {
    struct sockaddr_in server_addr;

    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Error: Could not create socket");
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(HOST_IP);
    server_addr.sin_port = htons(HOST_PORT);

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error: Could not connect to server");
        close(socket_fd);
        socket_fd = -1;
        return -1;
    }

    return 0;
}

// Read configuration from file
int read_config() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open %s, using default calibration factor.\n", CALIBRATION_FILE);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Read configuration
    if (read_config() != 0) {
        calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    }

    // Initialize socket
    if (init_socket() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(socket_fd);
        gpioTerminate();
        return 1;
    }

    char buffer[1024];
    ssize_t bytes_received;

    while (running) {
        // Receive target weight from client
        bytes_received = recv(socket_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            target_weight = atof(buffer);

            printf("Received target weight: %.2f\n", target_weight);

            // Read raw weight from HX711
            int raw_weight = read_hx711();
            if (raw_weight == -1) {
                log_event(target_weight, DEFAULT_ACTUAL_WEIGHT, "HX711 read error");
                fprintf(stderr, "Error: HX711 read error\n");
                continue; // Skip to the next iteration
            }

            // Calibrate weight
            actual_weight = calibrate_weight(raw_weight);

            printf("Actual weight: %.2f\n", actual_weight);

            // Map weight to pulse width
            int pulse_width = map_weight_to_pulse_width(target_weight);

            // Set servo pulse width
            gpioPWM(SERVO_PIN, pulse_width);
            gpioDelay(1000); // Wait 1 second

            // Send API request
            if (send_api_request(target_weight, actual_weight) != 0) {
                log_event(target_weight, actual_weight, "API request failed");
                fprintf(stderr, "Error: API request failed\n");
            }

            // Log event
            if (log_event(target_weight, actual_weight, NULL) != 0) {
                fprintf(stderr, "Error: Logging failed\n");
            }
        } else if (bytes_received == 0) {
            printf("Client disconnected.\n");
            running = 0; // Exit the loop
        } else {
            perror("Error: Receive failed");
            running = 0; // Exit the loop
        }
    }

    // Cleanup
    close(socket_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

