    if (!json_str) {
        fprintf(stderr, "Error: Could not serialize JSON object.\n");
        json_decref(root);
        return -1;
    }

    fprintf(log_file, "%s\n", json_str);
    fflush(log_file);

    json_decref(root);
    free(json_str);

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Stop pigpio
    gpioTerminate();

    exit(0);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz PWM frequency
    gpioSetPWMrange(SERVO_PIN, 1000); // PWM range of 0-1000

    return 0;
}

// Initialize socket
int init_socket() {
    struct sockaddr_in server_addr;

    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Error: Could not create socket");
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(HOST_IP);
    server_addr.sin_port = htons(HOST_PORT);

    if (connect(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error: Could not connect to server");
        close(socket_fd);
        socket_fd = -1;
        return -1;
    }

    return 0;
}

// Read configuration from file
int read_config() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open %s, using default calibration factor.\n", CALIBRATION_FILE);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Read configuration
    if (read_config() != 0) {
        calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    }

    // Initialize socket
    if (init_socket() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(socket_fd);
        gpioTerminate();
        return 1;
    }

    char buffer[1024];
    ssize_t bytes_received;

    while (running) {
        // Receive target weight from client
        bytes_received = recv(socket_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            target_weight = atof(buffer);

            printf("Received target weight: %.2f\n", target_weight);

            // Read raw weight from HX711
            int raw_weight = read_hx711();
            if (raw_weight == -1) {
                log_event(target_weight, DEFAULT_ACTUAL_WEIGHT, "HX711 read error");
                fprintf(stderr, "Error: HX711 read error\n");
                continue; // Skip to the next iteration
            }

            // Calibrate weight
            actual_weight = calibrate_weight(raw_weight);

            printf("Actual weight: %.2f\n", actual_weight);

            // Map weight to pulse width
            int pulse_width = map_weight_to_pulse_width(target_weight);

            // Set servo pulse width
            gpioPWM(SERVO_PIN, pulse_width);
            gpioDelay(1000); // Wait 1 second

            // Send API request
            if (send_api_request(target_weight, actual_weight) != 0) {
                log_event(target_weight, actual_weight, "API request failed");
                fprintf(stderr, "Error: API request failed\n");
            }

            // Log event
            if (log_event(target_weight, actual_weight, NULL) != 0) {
                fprintf(stderr, "Error: Logging failed\n");
            }
        } else if (bytes_received == 0) {
            printf("Client disconnected.\n");
            running = 0; // Exit the loop
        } else {
            perror("Error: Receive failed");
            running = 0; // Exit the loop
        }
    }

    // Cleanup
    close(socket_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

