#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce interval in milliseconds
#define DEFAULT_DEBOUNCE_INTERVAL 50

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile int running = 1;
static int debounce_interval = DEFAULT_DEBOUNCE_INTERVAL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce(int current_state, int *last_state, int interval_ms);
int toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF

    return 0;
}

// Read touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounce function
int debounce(int current_state, int *last_state, int interval_ms) {
    static unsigned int last_tick = 0;
    unsigned int current_tick = gpioTick();

    if (current_state != *last_state) {
        if ((current_tick - last_tick) > (interval_ms * 1000)) { // Convert ms to microseconds
            *last_state = current_state;
            last_tick = current_tick;
            return current_state;
        }
    }
    return *last_state;
}

// Toggle relay state
int toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Log relay state with timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

int main(int argc, char *argv[]) {
    int touch_state = 0;
    int last_touch_state = 0;
    int last_debounced_state = 0;

    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        debounce_interval = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || debounce_interval <= 0) {
            fprintf(stderr, "Invalid debounce interval. Using default: %d ms\n", DEFAULT_DEBOUNCE_INTERVAL);
            debounce_interval = DEFAULT_DEBOUNCE_INTERVAL;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor relay control started. Debounce interval: %d ms\n", debounce_interval);

    // Main loop
    while (running) {
        touch_state = read_touch_sensor();
        last_debounced_state = debounce(touch_state, &last_touch_state, debounce_interval);

        if (last_debounced_state == 1 && last_touch_state == 0) { // Rising edge detected
            toggle_relay();
            log_relay_state(relay_state);
        }

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    return 0;
}

