#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pin for servo control
#define SERVO_PIN 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define pulse width limits (µs)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle limits (degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Global variables
static volatile int angle = 90; // Initial angle (degrees)
static volatile int pulse_width = 1500; // Initial pulse width (µs)
static volatile int running = 1; // Flag to control the main loop

// Structure to hold terminal settings
struct termios orig_termios;

// Function prototypes
int set_pulse_width(int gpio, int pulse_width);
int angle_to_pulse_width(int angle);
int pulse_width_to_angle(int pulse_width);
void signal_handler(int signal);
void cleanup();
int setup();

// Function to set the pulse width on a GPIO pin
int set_pulse_width(int gpio, int pulse_width) {
    int result = gpioServo(gpio, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting pulse width: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert angle to pulse width
int angle_to_pulse_width(int angle) {
    return (int)(500 + (angle / 180.0) * 2000);
}

// Function to convert pulse width to angle
int pulse_width_to_angle(int pulse_width) {
    return (int)(((pulse_width - 500) / 2000.0) * 180);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the main loop
}

// Cleanup function to restore terminal settings and disable PWM
void cleanup() {
    printf("Cleaning up...\n");
    // Restore terminal settings
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);

    // Stop PWM pulses
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
}

// Setup function to initialize pigpio and terminal settings
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Save original terminal settings
    tcgetattr(STDIN_FILENO, &orig_termios);

    // Configure terminal for raw input
    struct termios new_termios = orig_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    new_termios.c_cc[VMIN] = 1; // Read at least one character
    new_termios.c_cc[VTIME] = 0; // No timeout

    tcsetattr(STDIN_FILENO, TCSANOW, &new_termios);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        return 1;
    }

    // Set initial pulse width
    if (set_pulse_width(SERVO_PIN, pulse_width) != 0) {
        cleanup();
        return 1;
    }

    printf("Servo control program. Use '+' and '-' to increase/decrease angle. Press 'q' to quit.\n");

    // Main loop
    while (running) {
        int c = getchar();

        if (c == '+') {
            // Increase angle
            angle += 10;
            if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
            }
            pulse_width = angle_to_pulse_width(angle);
            if (set_pulse_width(SERVO_PIN, pulse_width) != 0) {
                cleanup();
                return 1;
            }
        } else if (c == '-') {
            // Decrease angle
            angle -= 10;
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
            }
            pulse_width = angle_to_pulse_width(angle);
            if (set_pulse_width(SERVO_PIN, pulse_width) != 0) {
                cleanup();
                return 1;
            }
        } else if (c == 'q') {
            // Quit
            running = 0;
        }

        // Print current angle
        printf("Angle: %d°, Pulse Width: %dµs\n", angle, pulse_width);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

