#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define LOG_FILE "motor_rpm.log"
#define DEBOUNCE_WINDOW_NS 2000000 // 2 milliseconds in nanoseconds

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to calculate RPM
double calculate_rpm(int pulses, double time_interval_seconds) {
    return (double)pulses / time_interval_seconds * 60.0;
}

// Callback function for GPIO interrupt
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    static struct timespec last_tick = {0, 0};
    struct timespec current_tick;
    clock_gettime(CLOCK_MONOTONIC, &current_tick);

    // Debounce check
    if (last_tick.tv_sec != 0 || last_tick.tv_nsec != 0) {
        long time_diff_ns = (current_tick.tv_sec - last_tick.tv_sec) * 1000000000L + (current_tick.tv_nsec - last_tick.tv_nsec);
        if (time_diff_ns < DEBOUNCE_WINDOW_NS) {
            return; // Ignore the pulse
        }
    }

    pulse_count++;
    last_tick = current_tick;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    int result;
    double rpm;
    char *timestamp;
    struct timespec start_time, end_time;
    long time_interval_seconds;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt callback
    result = gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to set alert function. pigpio error code: %d\n", result);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring RPM on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        // Reset pulse count
        pulse_count = 0;

        // Get start time
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Wait for 5 seconds
        sleep(5);

        // Get end time
        clock_gettime(CLOCK_MONOTONIC, &end_time);

        // Calculate time interval in seconds
