#define GPIO_PIN 17
#define LOG_FILE "motor_rpm.log"
#define DEBOUNCE_WINDOW_NS 2000000 // 2 milliseconds in nanoseconds

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to calculate RPM
double calculate_rpm(int pulses, double time_interval_seconds) {
    return (double)pulses / time_interval_seconds * 60.0;
}

// Callback function for GPIO interrupt
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    static struct timespec last_tick = {0, 0};
    struct timespec current_tick;
    clock_gettime(CLOCK_MONOTONIC, &current_tick);

    // Debounce check
    if (last_tick.tv_sec != 0 || last_tick.tv_nsec != 0) {
        long time_diff_ns = (current_tick.tv_sec - last_tick.tv_sec) * 1000000000L + (current_tick.tv_nsec - last_tick.tv_nsec);
        if (time_diff_ns < DEBOUNCE_WINDOW_NS) {
            return; // Ignore the pulse
        }
    }

    pulse_count++;
    last_tick = current_tick;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

