    if (result != 0) {
        fprintf(stderr, "Error: Failed to set alert function. pigpio error code: %d\n", result);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring RPM on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        // Reset pulse count
        pulse_count = 0;

        // Get start time
