#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define POLL_INTERVAL_MS 50
#define CONTINUOUS_HIGH_THRESHOLD_S 10

// Global variables
volatile sig_atomic_t program_running = 1;
time_t last_high_time = 0;
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor();
void toggle_relay();
void signal_handler(int signal);

// Function to read the touch sensor state
int read_touch_sensor() {
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading touch sensor: %d\n", sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    int result = gpioWrite(RELAY_PIN, relay_state);
    if (result != 0) {
        fprintf(stderr, "Error writing to relay: %d\n", result);
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_touch_sensor();
        if (sensor_value < 0) {
            // Error reading sensor, exit loop
            break;
        }

        if (sensor_value == 1) {
            // Touch sensor is HIGH
            if (last_high_time == 0) {
                // First time HIGH, record the time
                last_high_time = time(NULL);
            } else {
                // Check if the sensor has been HIGH for more than the threshold
                time_t current_time = time(NULL);
                if (difftime(current_time, last_high_time) >= CONTINUOUS_HIGH_THRESHOLD_S) {
                    // Force relay OFF
                    gpioWrite(RELAY_PIN, 0);
                    relay_state = 0;
                    printf("Touch held for %d seconds, forcing relay OFF.\n", CONTINUOUS_HIGH_THRESHOLD_S);
                    last_high_time = 0; // Reset the timer
                }
            }
        } else {
            // Touch sensor is LOW
            last_high_time = 0; // Reset the timer
        }

        // Toggle relay on rising edge
        if (sensor_value == 1 && gpioRead(TOUCH_SENSOR_PIN) == 0) {
            toggle_relay();
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for polling interval
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio

    printf("Program finished.\n");
    return 0;
}

