#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define proportional gain
#define KP 1.0

// Define target flow rate
#define TARGET_FLOW_RATE 5.0 // L/min

// Define flow rate tolerance
#define FLOW_TOLERANCE 0.1 // L/min

// Define log file name
#define LOG_FILE "flow_log.csv"

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void set_valve_direction(int direction);
void set_valve_pwm(int duty_cycle);
double calculate_flow_rate();
int control_valve(double flow_rate, double target_flow_rate);
int log_data(double flow_rate, int valve_position);
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int valve_pwm_pin;
    int valve_enable_pin;
    int flow_sensor_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    gpio_config_t config = {VALVE_PWM_PIN, VALVE_ENABLE_PIN, FLOW_SENSOR_PIN};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set valve PWM pin as output
    gpioSetMode(config.valve_pwm_pin, PI_OUTPUT);
    gpioSetPWMfrequency(config.valve_pwm_pin, PWM_FREQUENCY);
    gpioSetPWMrange(config.valve_pwm_pin, 255);

    // Set valve enable pin as output
    gpioSetMode(config.valve_enable_pin, PI_OUTPUT);
    gpioWrite(config.valve_enable_pin, 1); // Enable valve initially

    // Set flow sensor pin as input with pull-up resistor
    gpioSetMode(config.flow_sensor_pin, PI_INPUT);
    gpioSetPullUpDown(config.flow_sensor_pin, PI_PUD_UP);

    // Register interrupt handler for flow sensor
    if (gpioSetISRFuncEx(config.flow_sensor_pin, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Set valve direction (0 for open, 1 for close)
void set_valve_direction(int direction) {
    gpioWrite(VALVE_ENABLE_PIN, direction);
}

// Set valve PWM duty cycle
void set_valve_pwm(int duty_cycle) {
    gpioPWM(VALVE_PWM_PIN, duty_cycle);
}

// Calculate flow rate based on pulse count
double calculate_flow_rate() {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();
    uint32_t diff = current_tick - last_tick;

    if (diff > 1000000) { // Handle tick rollover
        diff -= 1000000;
    }

    last_tick = current_tick;

    double flow_rate = (double)pulse_count / (double)diff * 1000000.0; // pulses per second
    pulse_count = 0; // Reset pulse count

    return flow_rate;
}

// Proportional control algorithm
int control_valve(double flow_rate, double target_flow_rate) {
    double error = target_flow_rate - flow_rate;
    double duty_cycle = KP * error;

    // Clamp duty cycle to 0-255 range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return (int)duty_cycle;
}

// Log data to CSV file
int log_data(double flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Flow sensor interrupt handler
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    double target_flow_rate = TARGET_FLOW_RATE;
    int valve_position;
    double flow_rate;

    // Parse command-line arguments
    if (argc > 1) {
        target_flow_rate = atof(argv[1]);
        if (target_flow_rate <= 0) {
            fprintf(stderr, "Invalid target flow rate. Using default value: %.2f L/min\n", TARGET_FLOW_RATE);
            target_flow_rate = TARGET_FLOW_RATE;
        }
    } else {
        printf("Using default target flow rate: %.2f L/min\n", TARGET_FLOW_RATE);
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (running) {
        flow_rate = calculate_flow_rate();
        valve_position = control_valve(flow_rate, target_flow_rate);
        set_valve_pwm(valve_position);
        log_data(flow_rate, valve_position);

        // Check if flow rate is within tolerance
        if (fabs(flow_rate - target_flow_rate) <= FLOW_TOLERANCE) {
            printf("Target flow rate reached: %.2f L/min, Current flow rate: %.2f L/min\n", target_flow_rate, flow_rate);
        }

        gpioDelay(100); // Control loop frequency: 10 Hz
    }

    // Graceful shutdown
    set_valve_pwm(0); // Set PWM to 0
    set_valve_direction(0); // Disable valve
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio

    return 0;
}

