#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

// PWM Frequency
#define PWM_FREQUENCY 100

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target Speed (RPM)
#define TARGET_SPEED 60.0

// PID Sample Time (ms)
#define SAMPLE_TIME 100

// Global Variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

volatile int running = 1; // Flag to control the main loop

FILE *log_file = NULL;

// Function Prototypes
void encoder1_isr(int gpio, int level, uint32_t tick, void *user);
void encoder2_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count);
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error);
void set_motor_speed(int motor_number, double pid_output);
void *encoder1_monitor(void *arg);
void *encoder2_monitor(void *arg);
void signal_handler(int signal);

// Encoder 1 ISR
void encoder1_isr(int gpio, int level, uint32_t tick, void *user)
{
    int b_level = gpioRead(ENCODER1_B);

    pthread_mutex_lock(&encoder1_mutex);
    if (b_level == 1)
    {
        encoder1_count++;
    }
    else
    {
        encoder1_count--;
    }
    pthread_mutex_unlock(&encoder1_mutex);
}

// Encoder 2 ISR
void encoder2_isr(int gpio, int level, uint32_t tick, void *user)
{
    int b_level = gpioRead(ENCODER2_B);

    pthread_mutex_lock(&encoder2_mutex);
    if (b_level == 1)
    {
        encoder2_count++;
    }
    else
    {
        encoder2_count--;
    }
    pthread_mutex_unlock(&encoder2_mutex);
}

// Calculate RPM
double calculate_rpm(int encoder_count)
{
    // Assuming one pulse per revolution
    // and a 100ms sample time (60 pulses per second = 60 RPM)
    return (double)encoder_count * (60.0 / (100.0 / 1000.0));
}

// PID Control
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error)
{
    double error = setpoint - actual_value;
    *integral += error * (SAMPLE_TIME / 1000.0);
    double derivative = (error - *previous_error) / (SAMPLE_TIME / 1000.0);
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Set Motor Speed
void set_motor_speed(int motor_number, double pid_output)
{
    int gpio_ena, gpio_in1, gpio_in2;

    if (motor_number == 1)
    {
        gpio_ena = MOTOR1_ENA;
        gpio_in1 = MOTOR1_IN1;
        gpio_in2 = MOTOR1_IN2;
    }
    else if (motor_number == 2)
    {
        gpio_ena = MOTOR2_ENB;
        gpio_in1 = MOTOR2_IN3;
        gpio_in2 = MOTOR2_IN4;
    }
    else
    {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_number);
        return;
    }

    // Limit PID output to 0-100
    if (pid_output < 0)
    {
        pid_output = 0;
    }
    if (pid_output > 100)
    {
        pid_output = 100;
    }

    // Set PWM duty cycle
    int duty_cycle = (int)pid_output;
    gpioPWM(gpio_ena, duty_cycle);

    // Set motor direction (example: if PID output is positive, forward, otherwise reverse)
    if (pid_output > 50)
    {
        gpioWrite(gpio_in1, 1);
        gpioWrite(gpio_in2, 0);
    }
    else
    {
        gpioWrite(gpio_in1, 0);
        gpioWrite(gpio_in2, 1);
    }
}

// Encoder 1 Monitor Thread
void *encoder1_monitor(void *arg)
{
    while (running)
    {
        pthread_mutex_lock(&encoder1_mutex);
        int count = encoder1_count;
        encoder1_count = 0; // Reset the count
        pthread_mutex_unlock(&encoder1_mutex);
        gpioDelay(SAMPLE_TIME * 1000); // Delay for sample time
    }
    return NULL;
}

// Encoder 2 Monitor Thread
void *encoder2_monitor(void *arg)
{
    while (running)
    {
        pthread_mutex_lock(&encoder2_mutex);
        int count = encoder2_count;
        encoder2_count = 0; // Reset the count
        pthread_mutex_unlock(&encoder2_mutex);
        gpioDelay(SAMPLE_TIME * 1000); // Delay for sample time
    }
    return NULL;
}

// Signal Handler
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the main loop

    // Stop motors
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    // Release GPIO lines
    gpioSetMode(MOTOR1_ENA, PI_INPUT); // Set to input to release
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set PWM range (0-100)
    gpioSetPWMrange(MOTOR1_ENA, 100);
    gpioSetPWMrange(MOTOR2_ENB, 100);

    // Set ISRs
    gpioSetISRFuncEx(ENCODER1_A, RISING_EDGE, 0, encoder1_isr, NULL);
    gpioSetISRFuncEx(ENCODER2_A, RISING_EDGE, 0, encoder2_isr, NULL);

    // Create log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,P,I,D,Motor1_PID,Motor2_PID\n");
    fflush(log_file);

    // Create encoder monitor threads
    pthread_t encoder1_thread, encoder2_thread;
    pthread_create(&encoder1_thread, NULL, encoder1_monitor, NULL);
    pthread_create(&encoder2_thread, NULL, encoder2_monitor, NULL);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID variables
    double motor1_integral = 0, motor2_integral = 0;
    double motor1_previous_error = 0, motor2_previous_error = 0;

    // Main loop
    while (running)
    {
        // Read encoder counts
        pthread_mutex_lock(&encoder1_mutex);
        int encoder1_current_count = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        int encoder2_current_count = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate RPM
        double motor1_rpm = calculate_rpm(encoder1_current_count);
        double motor2_rpm = calculate_rpm(encoder2_current_count);

        // PID control
        double motor1_pid_output = pid_control(TARGET_SPEED, motor1_rpm, &motor1_integral, &motor1_previous_error);
        double motor2_pid_output = pid_control(TARGET_SPEED, motor2_rpm, &motor2_integral, &motor2_previous_error);

        // Set motor speeds
        set_motor_speed(1, motor1_pid_output);
        set_motor_speed(2, motor2_pid_output);

        // Log data
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
                timestamp, motor1_rpm, motor2_rpm,
                KP * (TARGET_SPEED - motor1_rpm), motor1_integral, KD * (0 - (TARGET_SPEED - motor1_rpm)), motor1_pid_output,
                KP * (TARGET_SPEED - motor2_rpm), motor2_integral, KD * (0 - (TARGET_SPEED - motor2_rpm)), motor2_pid_output);
        fflush(log_file);

        gpioDelay(SAMPLE_TIME * 1000); // Delay for sample time
    }

    // Join threads
    pthread_join(encoder1_thread, NULL);
    pthread_join(encoder2_thread, NULL);

    // Cleanup (should not reach here if signal handler works correctly)
    signal_handler(0); // Call signal handler to perform cleanup

    return 0;
}

