        gpio_ena = MOTOR2_ENB;
        gpio_in1 = MOTOR2_IN3;
        gpio_in2 = MOTOR2_IN4;
    }
    else
    {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_number);
        return;
    }

    // Limit PID output to 0-100
    if (pid_output < 0)
    {
        pid_output = 0;
    }
    if (pid_output > 100)
    {
        pid_output = 100;
    }

    // Set PWM duty cycle
    int duty_cycle = (int)pid_output;
    gpioPWM(gpio_ena, duty_cycle);

    // Set motor direction (example: if PID output is positive, forward, otherwise reverse)
    if (pid_output > 50)
    {
        gpioWrite(gpio_in1, 1);
        gpioWrite(gpio_in2, 0);
    }
    else
    {
        gpioWrite(gpio_in1, 0);
        gpioWrite(gpio_in2, 1);
    }
}

// Encoder 1 Monitor Thread
void *encoder1_monitor(void *arg)
{
    while (running)
    {
        pthread_mutex_lock(&encoder1_mutex);
        int count = encoder1_count;
        encoder1_count = 0; // Reset the count
        pthread_mutex_unlock(&encoder1_mutex);
        gpioDelay(SAMPLE_TIME * 1000); // Delay for sample time
    }
    return NULL;
}

// Encoder 2 Monitor Thread
void *encoder2_monitor(void *arg)
{
    while (running)
    {
        pthread_mutex_lock(&encoder2_mutex);
        int count = encoder2_count;
        encoder2_count = 0; // Reset the count
        pthread_mutex_unlock(&encoder2_mutex);
        gpioDelay(SAMPLE_TIME * 1000); // Delay for sample time
    }
    return NULL;
}

// Signal Handler
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the main loop

    // Stop motors
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    // Release GPIO lines
    gpioSetMode(MOTOR1_ENA, PI_INPUT); // Set to input to release
    gpioSetMode(MOTOR1_IN1, PI_INPUT);
    gpioSetMode(MOTOR1_IN2, PI_INPUT);
    gpioSetMode(MOTOR2_ENB, PI_INPUT);
    gpioSetMode(MOTOR2_IN3, PI_INPUT);
    gpioSetMode(MOTOR2_IN4, PI_INPUT);
