#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation durations in milliseconds
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define valve pause durations in seconds
#define VALVE1_PAUSE 5
#define VALVE2_PAUSE 10

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void activate_valve(int gpio_pin, int duration_ms);
void pause_valve(int pause_duration_seconds);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    // Ensure valves are initially closed
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    return 0; // Indicate success
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Activate the valve (HIGH signal)
    gpioDelay(duration_ms * 1000); // Delay for the specified duration (in microseconds)
    gpioWrite(gpio_pin, 0); // Deactivate the valve (LOW signal)
}

// Function to pause for a specified duration
void pause_valve(int pause_duration_seconds) {
    gpioDelay(pause_duration_seconds * 1000000); // Delay for the specified duration (in microseconds)
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");

    // Close the valves
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("valve_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup(); // Clean up GPIO before exiting
        return 1;
    }

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate Valve 1
        log_event("Valve 1 activated");
        activate_valve(VALVE1_GPIO, VALVE1_DURATION);

        // Pause for Valve 1
        log_event("Valve 1 paused");
        pause_valve(VALVE1_PAUSE);

        // Activate Valve 2
        log_event("Valve 2 activated");
        activate_valve(VALVE2_GPIO, VALVE2_DURATION);

        // Pause for Valve 2
        log_event("Valve 2 paused");
        pause_valve(VALVE2_PAUSE);
    }

    // Clean up and exit
    cleanup();
    return 0;
}

