#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define DOOR_STRIKE_PIN 18

// Define constants
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_unlock_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void unlock_door();
void rate_limit();
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int pir_pin;
    int door_strike_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(DOOR_STRIKE_PIN, PI_OUTPUT);
    gpioWrite(DOOR_STRIKE_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Unlock the door
void unlock_door() {
    gpioWrite(DOOR_STRIKE_PIN, 1); // Activate relay
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay for unlock duration
    gpioWrite(DOOR_STRIKE_PIN, 0); // Deactivate relay
}

// Rate limiting function
void rate_limit() {
    last_unlock_time = gpioTick();
}

// Log event to file
void log_event(const char *event_type) {
    if (log_file == NULL) return; // Check if log file is open

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    unsigned long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%s: %lu\n", event_type, timestamp_ms);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(DOOR_STRIKE_PIN, 0); // Ensure relay is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup(); // Clean up GPIO before exiting
        return 1;
    }

    printf("Door monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            // Check if rate limiting is active
            unsigned long current_time = gpioTick();
            if (current_time - last_unlock_time > RATE_LIMIT_MS * 1000) {
                log_event("Motion Detected");
                unlock_door();
                log_event("Door Unlocked");
                rate_limit();
            } else {
                log_event("Rate Limited");
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Poll every 50ms
    }

    cleanup();
    return 0;
}

