    // Set PWM frequency
    if (gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a random integer within a specified range
int generate_random_integer(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to generate a random haptic pattern
HapticPattern generate_random_pattern() {
    HapticPattern pattern;
    int num_steps = generate_random_integer(MIN_PATTERN_LENGTH, MAX_PATTERN_LENGTH);
    pattern.num_steps = num_steps;

    // Allocate memory for the pattern steps
    pattern.steps = (HapticStep *)malloc(num_steps * sizeof(HapticStep));
    if (pattern.steps == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        pattern.num_steps = 0; // Ensure num_steps is 0 if allocation fails
        return pattern; // Return the pattern with steps set to NULL and num_steps to 0
    }

    // Populate the pattern steps with random values
    for (int i = 0; i < num_steps; i++) {
        pattern.steps[i].motor1_duty_cycle = generate_random_integer(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        pattern.steps[i].motor2_duty_cycle = generate_random_integer(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
        pattern.steps[i].duration_ms = generate_random_integer(MIN_STEP_DURATION, MAX_STEP_DURATION);
    }

    return pattern;
}

// Function to play a haptic pattern
void play_pattern(HapticPattern pattern) {
    for (int i = 0; i < pattern.num_steps; i++) {
        // Set PWM duty cycles for both motors
        gpioPWM(MOTOR1_PIN, pattern.steps[i].motor1_duty_cycle);
        gpioPWM(MOTOR2_PIN, pattern.steps[i].motor2_duty_cycle);

        // Wait for the specified duration
        gpioDelay(pattern.steps[i].duration_ms * 1000); // Convert milliseconds to microseconds

        // Check for shutdown signal
        if (shutdown_flag) {
            break;
        }
    }
}

// Function to free the memory allocated for a haptic pattern
void free_pattern(HapticPattern pattern) {
    if (pattern.steps != NULL) {
        free(pattern.steps);
    }
}

int main() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and configure GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop to generate and play haptic patterns
    while (!shutdown_flag) {
        // Generate a random haptic pattern
        HapticPattern pattern = generate_random_pattern();

        // Play the haptic pattern
        play_pattern(pattern);

        // Free the memory allocated for the pattern
        free_pattern(pattern);
    }

    // Stop both motors
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Haptic feedback system stopped.\n");

    return 0;
}

