#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Default calibration values
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0

// Weight threshold in kg
#define WEIGHT_THRESHOLD 10.0

// Calibration file path
#define CALIBRATION_FILE "calibration.txt"

// Log file path
#define LOG_FILE "weight_log.txt"

// Timeout duration in seconds
#define TIMEOUT_DURATION 0.5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double scale_factor = DEFAULT_SCALE;
static double offset = DEFAULT_OFFSET;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void engage_solenoid();
void disengage_solenoid();
void log_weight(double weight);
void load_calibration();
void save_calibration();
void calibrate_load_cell();
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout_count = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_count++;
        if (timeout_count > (int)(TIMEOUT_DURATION * 1000000)) { // Convert seconds to microseconds
            fprintf(stderr, "Error: Timeout waiting for HX711 data.\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high duration
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low duration
    }

    // Pulse the clock pin 25th time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to engage the solenoid
void engage_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Set GPIO high
    printf("Solenoid engaged.\n");
}

// Function to disengage the solenoid
void disengage_solenoid() {
    gpioWrite(SOLENOID_PIN, 0); // Set GPIO low
    printf("Solenoid disengaged.\n");
}

// Function to log weight to file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to load calibration data from file
void load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file. Using default values.\n");
        return;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration file format. Using default values.\n");
        fclose(fp);
        return;
    }

    fclose(fp);
    printf("Calibration data loaded: scale = %.2f, offset = %.2f\n", scale_factor, offset);
}

// Function to save calibration data to file
void save_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return;
    }

    fprintf(fp, "%.2f %.2f", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale = %.2f, offset = %.2f\n", scale_factor, offset);
}

// Function to calibrate the load cell
void calibrate_load_cell() {
    printf("Starting calibration...\n");
    printf("Remove any weight from the load cell.\n");
    gpioDelay(3000); // Wait 3 seconds

    long sum = 0;
    for (int i = 0; i < 100; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error during calibration reading. Skipping calibration.\n");
            return;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    offset = (double)sum / 100.0;
    printf("Calibration complete. Offset: %.2f\n", offset);
    save_calibration();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration();

    // Calibrate the load cell
    calibrate_load_cell();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = calculate_weight(raw_value);
            printf("Raw: %d, Weight: %.2f kg\n", raw_value, weight);
            log_weight(weight);

            if (weight > WEIGHT_THRESHOLD) {
                engage_solenoid();
            } else {
                disengage_solenoid();
            }
        } else {
            fprintf(stderr, "Skipping iteration due to HX711 timeout.\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    fclose(log_file);
    disengage_solenoid(); // Ensure solenoid is disengaged on exit
    gpioTerminate();

    return 0;
}

