#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define RAIN_THRESHOLD 3
#define DEBOUNCE_DELAY_MS 50
#define MOTOR_DURATION_S 5
#define SENSOR_CHECK_INTERVAL_S 60
#define MOTOR_STOP_DELAY_S 60
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int direction, int duration_s);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received signal, stopping motor and exiting.");
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        gpioTerminate();
        program_running = 0;
        exit(0);
    }
}

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int rain_count = 0;
    for (int i = 0; i < 5; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 0) {
            rain_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (rain_count >= RAIN_THRESHOLD) ? 1 : 0;
}

// Function to control the DC motor
void control_motor(int direction, int duration_s) {
    time_t start_time = time(NULL);
    time_t current_time;

    // Set motor direction
    if (direction == 1) { // Close window
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        log_event("Closing window.");
    } else if (direction == -1) { // Open window
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 1);
        log_event("Opening window.");
    } else {
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Stopping motor.");
        return;
    }

    // Set PWM signal
    gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);

    // Run motor for specified duration
    do {
        gpioDelay(1000000); // 1 second delay
        current_time = time(NULL);
    } while (difftime(current_time, start_time) < duration_s && program_running);

    // Stop motor
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    log_event("Motor stopped.");
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    syslog(LOG_INFO, "%s: %s", buf, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);

    // Open syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started.");

    // Main loop
    while (program_running) {
        // Read rain sensor
        int rain_detected = read_rain_sensor();

        if (rain_detected) {
            log_event("Rain detected!");
            control_motor(1, MOTOR_DURATION_S); // Close window
            gpioDelay(MOTOR_STOP_DELAY_S * 1000000); // Delay in microseconds
        } else {
            gpioDelay(SENSOR_CHECK_INTERVAL_S * 1000000); // Delay in microseconds
        }
    }

    // Cleanup
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();

    return 0;
}

