    while (gpioRead(HX711_DT) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
        if (timeout_counter > HX711_TIMEOUT * 1000) { // Check timeout after HX711_TIMEOUT seconds
            log_event("HX711 timeout waiting for data ready.");
            return -1; // Indicate timeout error
