#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_DURATION 5 // seconds
#define TIMEOUT_MS 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
double read_hx711();
double calibrate_hx711();
double convert_to_kg(double raw_value, double calibration_factor);
void control_solenoid(int lock);
void log_event(double weight);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
        control_solenoid(0); // Unlock the solenoid
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Read raw value from HX711
double read_hx711() {
    int i;
    unsigned int data = 0;
    long start_time;

    gpioWrite(HX711_CLOCK_PIN, 0);

    // Wait for data line to go low
    start_time = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (gpioTick() - start_time > TIMEOUT_MS * 1000) {
            fprintf(stderr, "HX711 timeout waiting for data line to go low\n");
            return -1.0; // Indicate timeout error
        }
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Minimum 1us delay
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Minimum 1us delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Minimum 1us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Minimum 1us delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return (double)(long)data;
}

// Calibrate HX711
double calibrate_hx711() {
    double known_weight;
    double sum = 0.0;
    int num_samples = 10;
    int i;

    printf("Place a known weight on the load cell (e.g., 1.0 kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input for known weight.\n");
        return -1.0;
    }

    printf("Reading raw values...\n");
    for (i = 0; i < num_samples; i++) {
        double raw_value = read_hx711();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading HX711 during calibration.\n");
            return -1.0;
        }
        sum += raw_value;
        gpioDelay(100); // Small delay between readings
    }

    double average_raw_value = sum / num_samples;
    double calibration_factor = average_raw_value / known_weight;

    // Save calibration factor to file
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing.\n");
        return -1.0;
    }
    fprintf(fp, "%lf", calibration_factor);
    fclose(fp);

    printf("Calibration factor saved to %s\n", CALIBRATION_FILE);
    return calibration_factor;
}

// Convert raw value to kilograms
double convert_to_kg(double raw_value, double calibration_factor) {
    return raw_value / calibration_factor;
}

// Control the solenoid door lock
void control_solenoid(int lock) {
    if (lock) {
        gpioWrite(SOLENOID_PIN, 1); // Lock the door
        printf("Door locked.\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Unlock the door
        printf("Door unlocked.\n");
    }
}

// Log event to file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(SECURITY_LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file for writing.\n");
            return;
        }
    }

    fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk
}

int main() {
    double calibration_factor;
    double raw_value;
    double weight;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Load calibration factor from file
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp != NULL) {
        if (fscanf(fp, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file.\n");
            fclose(fp);
            calibration_factor = -1.0; // Indicate calibration is needed
        }
        fclose(fp);
        printf("Calibration factor loaded from %s\n", CALIBRATION_FILE);
    } else {
        printf("Calibration file not found, performing calibration...\n");
        calibration_factor = -1.0; // Indicate calibration is needed
    }

    if (calibration_factor == -1.0) {
        calibration_factor = calibrate_hx711();
        if (calibration_factor < 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
    }

    printf("Starting weight monitoring...\n");

    while (running) {
        raw_value = read_hx711();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading HX711. Retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        weight = convert_to_kg(raw_value, calibration_factor);

        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded!\n");
            control_solenoid(1); // Lock the door
            log_event(weight);
            gpioDelay(SOLENOID_DURATION * 1000); // Keep locked for 5 seconds
            control_solenoid(0); // Unlock the door
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_solenoid(0); // Unlock the solenoid
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio

    return 0;
}

