    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor value\n");
        return -1; // Indicate error
    }
    return sensor_value;
}

// Toggle relay state
int toggle_relay(int current_state) {
    int new_state = !current_state;
    gpioWrite(RELAY_PIN, new_state);
    return new_state;
}

// Log event to file
int log_event(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s Relay: %s\n", timestamp, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

