#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"

static volatile int terminate = 0;

// Function to read watering duration from config file
int read_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: Invalid config file format. Expected 'duration=<seconds>'\n");
        return -1;
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid config file format. Expected 'duration=<seconds>'\n");
        return -1;
    }

    char *endptr;
    long duration = strtol(token, &endptr, 10);

    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid duration value in config file.\n");
        return -1;
    }

    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Duration value out of range (1-3600).\n");
        return -1;
    }

    return (int)duration;
}

// Function to control the valve
int control_valve(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set initial valve state to off
    if (control_valve(GPIO_PIN, 0) != 0) {
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int duration = read_duration(CONFIG_FILE);
        if (duration > 0) {
            printf("Watering for %d seconds...\n", duration);

            // Turn valve on
            if (control_valve(GPIO_PIN, 1) != 0) {
                terminate = 1; // Exit loop on error
                break;
            }

            // Sleep for the specified duration
            sleep(duration);

            // Turn valve off
            if (control_valve(GPIO_PIN, 0) != 0) {
                terminate = 1; // Exit loop on error
                break;
            }

            printf("Watering complete.\n");
        } else {
            fprintf(stderr, "Error reading watering duration. Exiting.\n");
            terminate = 1;
        }
    }

    // Ensure valve is off before exiting
    control_valve(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

