#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

#define LEFT_MOTOR_PWM 22
#define LEFT_MOTOR_DIR 24
#define RIGHT_MOTOR_PWM 23
#define RIGHT_MOTOR_DIR 25

// Define motor directions
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0

// Define base speed
#define BASE_SPEED 150

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define sampling interval
#define SAMPLING_INTERVAL 10

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensors();
void control_motors(int sensor_state);
void log_data(int sensor_state, int left_speed, int right_speed);
void stop_motors();
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set sensor pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Set motor control pins as outputs
    gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM, PWM_FREQUENCY);

    return 0;
}

// Function to read sensor values
int read_sensors() {
    int left = gpioRead(LEFT_SENSOR);
    int middle = gpioRead(MIDDLE_SENSOR);
    int right = gpioRead(RIGHT_SENSOR);

    // Convert active-low to active-high
    left = (left == 0) ? 1 : 0;
    middle = (middle == 0) ? 1 : 0;
    right = (right == 0) ? 1 : 0;

    return (left << 2) | (middle << 1) | right;
}

// Function to control motors based on sensor state
void control_motors(int sensor_state) {
    int left_speed = BASE_SPEED;
    int right_speed = BASE_SPEED;

    switch (sensor_state) {
        case 0b010: // Middle sensor
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
            break;
        case 0b100: // Left sensor
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
            break;
        case 0b001: // Right sensor
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
            break;
        case 0b000: // No sensor
            left_speed = 0;
            right_speed = 0;
            break;
        default:
            left_speed = 0;
            right_speed = 0;
            break;
    }

    gpioPWM(LEFT_MOTOR_PWM, left_speed);
    gpioPWM(RIGHT_MOTOR_PWM, right_speed);

    log_data(sensor_state, left_speed, right_speed);
}

// Function to log data to file
void log_data(int sensor_state, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp,
            (sensor_state & 0b100) ? 1 : 0,
            (sensor_state & 0b010) ? 1 : 0,
            (sensor_state & 0b001) ? 1 : 0,
            left_speed, right_speed);
    fflush(log_file);
}

// Function to stop both motors
void stop_motors() {
    gpioPWM(LEFT_MOTOR_PWM, 0);
    gpioPWM(RIGHT_MOTOR_PWM, 0);
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
}

// Function to perform cleanup before exiting
void cleanup() {
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        int sensor_state = read_sensors();
        control_motors(sensor_state);
        gpioDelay(SAMPLING_INTERVAL * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

