#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150.0
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int relay_gpio;
    float lux_threshold;
    char *log_file_name;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read illuminance from BH1750 sensor
int read_bh1750(float *lux) {
    char config_mode = 0x10; // High resolution mode
    if (i2cWriteByte(i2c_handle, config_mode) != 0) {
        fprintf(stderr, "Error writing to I2C.\n");
        return -1;
    }
    gpioDelay(180); // Measurement delay

    int raw_value = i2cReadWordData(i2c_handle, 0x00);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading from I2C.\n");
        return -1;
    }

    *lux = (float)raw_value / 1.2; // Convert to lux
    return 0;
}

// Control the relay connected to GPIO
int control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            log_data(lux, relay_state);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
            log_data(-1.0, relay_state); // Log error
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    control_relay(0); // Turn off relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

