#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_servo_pulse_width(int pulse_width);
int read_button(int gpio_pin);
void debounce(int gpio_pin);
void lock_door();
void unlock_door();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        program_running = 0;
        gpioTerminate();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Set servo pulse width
void set_servo_pulse_width(int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Error: Pulse width out of range (500-2500)\n");
        return;
    }
    gpioServo(SERVO_PIN, pulse_width);
}

// Read button state with debouncing
int read_button(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Debounce function
void debounce(int gpio_pin) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
}

// Lock the door
void lock_door() {
    printf("Locking door...\n");
    set_servo_pulse_width(LOCK_PULSE_WIDTH);
    gpioDelay(500 * 1000); // Wait for servo to move (500ms)
    printf("Door locked.\n");
}

// Unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    set_servo_pulse_width(UNLOCK_PULSE_WIDTH);
    gpioDelay(500 * 1000); // Wait for servo to move (500ms)
    printf("Door unlocked.\n");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (read_button(LOCK_BUTTON_PIN) == 0) {
            debounce(LOCK_BUTTON_PIN);
            lock_door();
        }

        // Check unlock button
        if (read_button(UNLOCK_BUTTON_PIN) == 0) {
            debounce(UNLOCK_BUTTON_PIN);
            unlock_door();
        }

        gpioDelay(50 * 1000); // Small delay to prevent busy-waiting
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

