#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse durations in milliseconds
#define MOTOR1_PULSE_DURATION 200
#define MOTOR2_PULSE_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a pulse on a specified GPIO pin
void generate_pulse(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO%d high\n", gpio);
        return;
    }
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO%d low\n", gpio);
        return;
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop to repeatedly pulse the motors
    while (program_running) {
        generate_pulse(MOTOR1_GPIO, MOTOR1_PULSE_DURATION);
        generate_pulse(MOTOR2_GPIO, MOTOR2_PULSE_DURATION);
    }

    // Stop the motors and release GPIO resources
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);
    gpioTerminate();

    fprintf(stderr, "Haptic feedback system stopped.\n");

    return 0;
}

