void *publisher = NULL;
void *subscriber = NULL;

// Function prototypes
int initialize_gpio();
int initialize_zmq(int mode);
void publish_sound_alert();
void receive_sound_alert();
void cleanup();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int running;
    int mode;
} ProgramState;

ProgramState state = {1, 0}; // Initialize running to 1 and mode to 0 (default)

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Function to initialize ZeroMQ
int initialize_zmq(int mode) {
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Error creating ZeroMQ context: %s\n", zmq_strerror(errno));
        return -1;
    }

    if (mode == 0) { // Sound sensor mode
        publisher = zmq_socket(context, ZMQ_PUB);
        if (!publisher) {
            fprintf(stderr, "Error creating ZeroMQ publisher socket: %s\n", zmq_strerror(errno));
            return -1;
        }

        int bind_result = zmq_bind(publisher, ZMQ_ADDRESS);
        if (bind_result < 0) {
            fprintf(stderr, "Error binding ZeroMQ publisher socket: %s\n", zmq_strerror(errno));
            return -1;
        }
        printf("Publisher bound to %s\n", ZMQ_ADDRESS);
    } else if (mode == 1) { // Alarm node mode
        subscriber = zmq_socket(context, ZMQ_SUB);
        if (!subscriber) {
            fprintf(stderr, "Error creating ZeroMQ subscriber socket: %s\n", zmq_strerror(errno));
            return -1;
        }

        int connect_result = zmq_connect(subscriber, ZMQ_ADDRESS);
        if (connect_result < 0) {
