    if (argc > 1) {
        state.mode = atoi(argv[1]);
        if (state.mode != 0 && state.mode != 1) {
            fprintf(stderr, "Invalid mode. Using default mode 0.\n");
            state.mode = 0;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Initialize ZeroMQ
    if (initialize_zmq(state.mode) < 0) {
        cleanup();
        return 1;
    }

