#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"

// NEC Protocol Constants
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_SPACE_1 1690
#define NEC_SPACE_0 560

// Global Variables
static volatile int pulse_count = 0;
static volatile unsigned int pulse_buffer[100]; // Assuming max 50 pulses per frame
static volatile unsigned int command = 0;
static volatile int nec_state = 0; // 0: idle, 1: receiving
static struct mosquitto *mosq = NULL;
static int running = 1;

// Function Prototypes
void signal_handler(int sig);
void gpio_callback(int gpio, int level, uint32_t tick, void *userdata);
int decode_nec(unsigned int *pulse_buffer, int pulse_count, unsigned int *command);
int validate_checksum(unsigned int command);
char *format_json(unsigned int command);
int publish_mqtt(const char *payload);

// Signal Handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// GPIO Callback Function
void gpio_callback(int gpio, int level, uint32_t tick, void *userdata) {
    static uint32_t last_tick = 0;
    unsigned int pulse_length;

    if (level == FALLING_EDGE) {
        pulse_length = tick - last_tick;
        last_tick = tick;

        if (pulse_count < 100) {
            pulse_buffer[pulse_count++] = pulse_length;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
            pulse_count = 0; // Reset buffer
        }
    }
}

// NEC Decoding Function
int decode_nec(unsigned int *pulse_buffer, int pulse_count, unsigned int *command) {
    if (pulse_count < 68) { // Minimum pulse count for NEC
        syslog(LOG_ERR, "Insufficient pulse count: %d", pulse_count);
        return -1;
    }

    int i;
    unsigned int data = 0;

    // Check for header
    if (pulse_buffer[0] < NEC_HEADER_MARK * 0.8 || pulse_buffer[0] > NEC_HEADER_MARK * 1.2 ||
        pulse_buffer[1] < NEC_HEADER_SPACE * 0.8 || pulse_buffer[1] > NEC_HEADER_SPACE * 1.2) {
        syslog(LOG_ERR, "Invalid NEC header");
        return -1;
    }

    // Decode data bits
    for (i = 2; i < 66; i += 2) {
        if (pulse_buffer[i] > NEC_BIT_MARK * 0.8 && pulse_buffer[i] < NEC_BIT_MARK * 1.2) {
            if (pulse_buffer[i + 1] > NEC_SPACE_1 * 0.8 && pulse_buffer[i + 1] < NEC_SPACE_1 * 1.2) {
                data = (data << 1) | 1;
            } else if (pulse_buffer[i + 1] > NEC_SPACE_0 * 0.8 && pulse_buffer[i + 1] < NEC_SPACE_0 * 1.2) {
                data = (data << 1) | 0;
            } else {
                syslog(LOG_ERR, "Invalid space length at pulse %d", i + 1);
                return -1;
            }
        } else {
            syslog(LOG_ERR, "Invalid mark length at pulse %d", i);
            return -1;
        }
    }

    *command = data;
    return 0;
}

// Checksum Validation
int validate_checksum(unsigned int command) {
    unsigned int address = (command >> 24) & 0xFF;
    unsigned int inv_address = (command >> 16) & 0xFF;
    unsigned int data = (command >> 8) & 0xFF;
    unsigned int inv_data = command & 0xFF;

    if ((address + inv_address) != 0xFF) {
        syslog(LOG_ERR, "Address checksum failure: 0x%X + 0x%X != 0xFF", address, inv_address);
        return -1;
    }

    if ((data + inv_data) != 0xFF) {
        syslog(LOG_ERR, "Data checksum failure: 0x%X + 0x%X != 0xFF", data, inv_data);
        return -1;
    }

    return 0;
}

// JSON Formatting
char *format_json(unsigned int command) {
    char *json_string = malloc(50); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 50, "{\"command\": \"0x%X\"}", command);
    return json_string;
}

// MQTT Publishing
int publish_mqtt(const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting IR decoder...");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO mode and callback
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    gpioSetAlertFuncEx(GPIO_PIN, gpio_callback, NULL);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        if (pulse_count >= 68) {
            unsigned int decoded_command;
            if (decode_nec((unsigned int *)pulse_buffer, pulse_count, &decoded_command) == 0) {
                if (validate_checksum(decoded_command) == 0) {
                    char *json_payload = format_json(decoded_command);
                    if (json_payload != NULL) {
                        syslog(LOG_INFO, "Decoded command: 0x%X", decoded_command);
                        if (publish_mqtt(json_payload) != 0) {
                            syslog(LOG_ERR, "Failed to publish MQTT message");
                        }
                        free(json_payload);
                    }
                }
            }
            pulse_count = 0; // Reset pulse buffer
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

