        syslog(LOG_ERR, "Data checksum failure: 0x%X + 0x%X != 0xFF", data, inv_data);
        return -1;
    }

    return 0;
}

// JSON Formatting
char *format_json(unsigned int command) {
    char *json_string = malloc(50); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 50, "{\"command\": \"0x%X\"}", command);
    return json_string;
}

// MQTT Publishing
int publish_mqtt(const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

int main() {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting IR decoder...");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO mode and callback
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    gpioSetAlertFuncEx(GPIO_PIN, gpio_callback, NULL);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        if (pulse_count >= 68) {
            unsigned int decoded_command;
            if (decode_nec((unsigned int *)pulse_buffer, pulse_count, &decoded_command) == 0) {
                if (validate_checksum(decoded_command) == 0) {
                    char *json_payload = format_json(decoded_command);
                    if (json_payload != NULL) {
                        syslog(LOG_INFO, "Decoded command: 0x%X", decoded_command);
                        if (publish_mqtt(json_payload) != 0) {
                            syslog(LOG_ERR, "Failed to publish MQTT message");
                        }
                        free(json_payload);
                    }
                }
            }
            pulse_count = 0; // Reset pulse buffer
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

