#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x29
#define BH1750_ADDR_3 0x33
#define BH1750_ADDR_4 0x39
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SLEEP_SECONDS 1

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;
int udp_socket = -1;

// Function prototypes
int init_i2c();
int read_bh1750(int address);
float convert_to_lux(int raw_value);
char* format_data(float lux1, float lux2, float lux3, float lux4);
int send_udp_packet(const char* data);
void signal_handler(int sig);
void close_resources();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return 0;
}

// Read data from BH1750 sensor
int read_bh1750(int address) {
    int raw_value = -1;
    unsigned char buffer[2];

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }

    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(180000); // Wait 180ms

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// Convert raw value to lux
float convert_to_lux(int raw_value) {
    if (raw_value < 0) return NAN;
    return (float)raw_value / 1.2;
}

// Format data into a string
char* format_data(float lux1, float lux2, float lux3, float lux4) {
    char* data = (char*)malloc(256 * sizeof(char));
    if (data == NULL) {
        perror("Error allocating memory for data");
        return NULL;
    }
    snprintf(data, 256, "1,%.2f;2,%.2f;3,%.2f;4,%.2f", lux1, lux2, lux3, lux4);
    return data;
}

// Send UDP packet
int send_udp_packet(const char* data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }
    return 0;
}

// Close resources
void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        close_resources();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float lux1, lux2, lux3, lux4;
        int raw1, raw2, raw3, raw4;

        // Read sensor data
        raw1 = read_bh1750(BH1750_ADDR_1);
        raw2 = read_bh1750(BH1750_ADDR_2);
        raw3 = read_bh1750(BH1750_ADDR_3);
        raw4 = read_bh1750(BH1750_ADDR_4);

        // Convert to lux
        lux1 = convert_to_lux(raw1);
        lux2 = convert_to_lux(raw2);
        lux3 = convert_to_lux(raw3);
        lux4 = convert_to_lux(raw4);

        // Format data
        char* data = format_data(lux1, lux2, lux3, lux4);
        if (data == NULL) {
            continue; // Skip to the next iteration if formatting fails
        }

        // Send UDP packet
        if (send_udp_packet(data) < 0) {
            fprintf(stderr, "Failed to send UDP packet.\n");
        }

        free(data);

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    // Close resources before exiting
    close_resources();

    return 0;
}

