#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define FLOW_RATE_SCALE 0.01
#define FLOW_RATE_OFFSET 0.0
#define LOG_FILE "airflow_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(unsigned char *data);
float convert_to_slpm(unsigned char *data);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AWM7300V_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(unsigned char *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Generate start condition
        result = i2cWriteByte(i2c_handle, 0x00);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Read two bytes
        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw data to SLPM
float convert_to_slpm(unsigned char *data) {
    unsigned int raw_flow = ((unsigned int)data[0] << 8) | data[1];
    raw_flow &= 0x3FFF; // Mask to 14 bits
    return (float)raw_flow * FLOW_RATE_SCALE + FLOW_RATE_OFFSET;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned char sensor_data[2];
    float flow_rate;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            flow_rate = convert_to_slpm(sensor_data);
            log_flow_rate(flow_rate);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

