#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define AS7341_ID 0x12
#define AS7341_ENABLE 0x00
#define AS7341_CFG6 0x06
#define AS7341_F1DATAH 0x14
#define AS7341_F1DATAL 0x15

// Expected AS7341 ID value
#define AS7341_EXPECTED_ID 0x39

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold spectral data
typedef struct {
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
} spectral_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the AS7341 sensor
int initialize_sensor() {
    // Check sensor ID
    int id = i2cReadByteData(i2c_handle, AS7341_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }
    if (id != AS7341_EXPECTED_ID) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", id, AS7341_EXPECTED_ID);
        return -1;
    }
    printf("Sensor ID: 0x%02X\n", id);

    // Enable the sensor (PON bit)
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Configure SMUX (example: 100% F1, F2, F3, F4, F5, F6, F7, F8, Clear, NIR)
    if (i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x03) < 0) {
        fprintf(stderr, "Error writing to CFG6 register\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register for spectral measurement\n");
        return -1;
    }

    return 0;
}

// Function to read spectral data from the sensor
int read_spectral_data(spectral_data_t *data) {
    uint8_t buffer[20]; // Buffer to hold all spectral data
