#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x4C
#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define ERROR_LOG_FILENAME "seismic_error.log"
#define RETRY_COUNT 3
#define BACKOFF_DELAY 10 // milliseconds
#define SAMPLE_SIZE 6 // Bytes to read (X, Y, Z - 2 bytes each)

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
char *filename = DEFAULT_FILENAME;
FILE *data_file = NULL;
FILE *error_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *x, int *y, int *z);
int process_sensor_data(int x, int y, int z, float *x_g, float *y_g, float *z_g);
int log_data(float x_g, float y_g, float z_g);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float x_g;
    float y_g;
    float z_g;
} sensor_data_t;

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0); // I2C bus 1
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data with retry logic
int read_sensor_data(int *x, int *y, int *z) {
    char buffer[SAMPLE_SIZE];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buffer, SAMPLE_SIZE);
        if (result == SAMPLE_SIZE) {
            // Success
            *x = (buffer[0] << 8) | buffer[1];
            *y = (buffer[2] << 8) | buffer[3];
            *z = (buffer[4] << 8) | buffer[5];
            return 0;
        } else {
            // Error
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "I2C read failed (attempt %d): %d", retries + 1, result);
            log_error(error_message);
            gpioDelay(BACKOFF_DELAY * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    log_error("I2C read failed after multiple retries");
    return -1;
}

// Function to process sensor data and convert to g
int process_sensor_data(int x, int y, int z, float *x_g, float *y_g, float *z_g) {
    // Conversion factor (adjust based on sensor datasheet)
    float conversion_factor = 0.001; // Example: 1 LSB = 0.001 g

    *x_g = x * conversion_factor;
    *y_g = y * conversion_factor;
    *z_g = z * conversion_factor;

    return 0;
}

// Function to log data to CSV file
int log_data(float x_g, float y_g, float z_g) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(data_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x_g, y_g, z_g);
    fflush(data_file);

    return 0;
}

// Function to log errors to error log file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = atoi(optarg);
                if (sampling_interval <= 0) {
                    fprintf(stderr, "Invalid sampling interval. Using default value.\n");
                    sampling_interval = DEFAULT_SAMPLING_INTERVAL;
                }
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f filename]\n", argv[0]);
                return 1;
        }
    }

    // Open error log file
    error_file = fopen(ERROR_LOG_FILENAME, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        fclose(error_file);
        return 1;
    }

    // Open data log file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        log_error("Failed to open data log file. Exiting.");
        cleanup();
        return 1;
    }

    // Write CSV header
    fprintf(data_file, "timestamp,x_g,y_g,z_g\n");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int x, y, z;
    float x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            if (process_sensor_data(x, y, z, &x_g, &y_g, &z_g) == 0) {
                log_data(x_g, y_g, z_g);
            } else {
                log_error("Failed to process sensor data");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(sampling_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

