#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000

static int i2c_fd = -1;
static int udp_socket = -1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (udp_socket != -1) {
            close(udp_socket);
        }
        exit(0);
    }
}

// Function to read light intensity from BH1750 sensor
float read_bh1750() {
    unsigned char buf[2];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = read(i2c_fd, buf, 2);
        if (bytes_read == 2) {
            unsigned int raw_value = (buf[0] << 8) | buf[1];
            return (float)raw_value / 1.2;
        } else {
            fprintf(stderr, "Error reading from I2C: %s (errno: %d)\n", strerror(errno), errno);
            retries--;
            sleep(1);
        }
    }
    fprintf(stderr, "Failed to read from I2C after multiple retries.\n");
    return -1.0; // Indicate error
}

// Function to send light intensity via UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    char message[50];
    socklen_t addrlen = sizeof(addr);

    // Format the message
    snprintf(message, sizeof(message), "%.2f", lux_value);

    // Configure the address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send the message
    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&addr, addrlen) < 0) {
        fprintf(stderr, "Error sending UDP multicast: %s (errno: %d)\n", strerror(errno), errno);
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s (errno: %d)\n", strerror(errno), errno);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return 1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config_buf[1] = {CONTINUOUS_HIGH_RES_MODE};
    if (write(i2c_fd, config_buf, 1) != 1) {
        fprintf(stderr, "Error configuring BH1750: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating UDP socket: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return 1;
    }

    // Set TTL for multicast
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting TTL: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    // Main loop
    while (1) {
        float lux = read_bh1750();
        if (lux >= 0) {
            if (send_udp_multicast(lux) == 0) {
                printf("Lux: %.2f\n", lux);
            } else {
                fprintf(stderr, "Failed to send UDP multicast.\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        sleep(1);
    }

    return 0;
}

