#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>

// Define UART port and baud rate
#define UART_PORT "/dev/ttyS0"
#define BAUD_RATE 921600

// Define magic word
#define MAGIC_WORD_SIZE 8
const unsigned char magic_word[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

// Define TLV types (example, adjust based on AWR1642 documentation)
#define TLV_TYPE_DETECTED_OBJECTS 1

// Define data structure for detected objects
typedef struct {
    float range;
    float velocity;
} DetectedObject;

// Global variables
int uart_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int uart_init(const char *port, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int max_len);
int find_magic_word(const unsigned char *buffer, int buffer_len);
int validate_tlv(const unsigned char *tlv_data, int tlv_len);
int extract_detected_objects(const unsigned char *tlv_data, int tlv_len, DetectedObject *objects, int max_objects, int *num_objects);
int write_to_csv(FILE *fp, DetectedObject *objects, int num_objects);
void signal_handler(int signum);
void cleanup();

// Signal handler
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// UART initialization function
int uart_init(const char *port, int baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CSIZE;             /* mask the character size bits */
    tty.c_cflag |= CS8;              /* 8-bit data */
    tty.c_cflag &= ~(PARENB | PARODD); /* no parity */
    tty.c_cflag &= ~CSTOPB;            /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;           /* no hardware flowcontrol */

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;      /* read doesn't block */
    tty.c_cc[VTIME] = 5;     /* 0.5 seconds read timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from UART
int read_uart_data(int fd, unsigned char *buffer, int max_len) {
    int bytes_read = read(fd, buffer, max_len);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    }
    return bytes_read;
}

// Function to find the magic word in the buffer
int find_magic_word(const unsigned char *buffer, int buffer_len) {
    if (buffer_len < MAGIC_WORD_SIZE) {
        return -1; // Not enough data to check
    }

    for (int i = 0; i <= buffer_len - MAGIC_WORD_SIZE; ++i) {
        if (memcmp(buffer + i, magic_word, MAGIC_WORD_SIZE) == 0) {
            return i; // Magic word found at index i
        }
    }

    return -1; // Magic word not found
}

// Function to validate TLV payload
int validate_tlv(const unsigned char *tlv_data, int tlv_len) {
    // Implement TLV validation logic based on AWR1642 documentation
    // This is a placeholder, replace with actual validation
    if (tlv_len < 4) {
        fprintf(stderr, "Error: TLV length too short\n");
        return -1;
    }

    unsigned short type = (tlv_data[1] << 8) | tlv_data[0];
    unsigned short length = (tlv_data[3] << 8) | tlv_data[2];

    if (length > tlv_len) {
        fprintf(stderr, "Error: TLV length exceeds buffer size\n");
        return -1;
    }

    // Example: Check if the type is a recognized type
    if (type != TLV_TYPE_DETECTED_OBJECTS) {
        fprintf(stderr, "Error: Unknown TLV type: %d\n", type);
        return -1;
    }

    return 0; // TLV is valid
}

// Function to extract detected objects from TLV payload
int extract_detected_objects(const unsigned char *tlv_data, int tlv_len, DetectedObject *objects, int max_objects, int *num_objects) {
    // Implement object extraction logic based on AWR1642 documentation
    // This is a placeholder, replace with actual extraction
    *num_objects = 0; // Reset number of objects

    // Example: Assuming the payload contains range and velocity pairs
    int offset = 4; // Skip TLV header (type and length)
    while (offset < tlv_len && *num_objects < max_objects) {
        if (offset + 8 > tlv_len) {
            fprintf(stderr, "Error: Incomplete object data\n");
            return -1;
        }

        objects[*num_objects].range = *((float *)(tlv_data + offset));
        objects[*num_objects].velocity = *((float *)(tlv_data + offset + 4));
        offset += 8;
        (*num_objects)++;
    }

    return 0;
}

// Function to write data to CSV file
int write_to_csv(FILE *fp, DetectedObject *objects, int num_objects) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_objects; ++i) {
        fprintf(fp, "%s,%d,%.2f,%.2f\n", timestamp, i, objects[i].range, objects[i].velocity);
    }
    return 0;
}

// Cleanup function
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = uart_init(UART_PORT, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed, exiting\n");
        return 1;
    }

    // Open CSV file for writing
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    // Data buffer
    unsigned char buffer[4096];
    int buffer_len = 0;

    // Detected objects array
    DetectedObject objects[10]; // Assuming a maximum of 10 objects
    int num_objects = 0;

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read data from UART
        int bytes_read = read_uart_data(uart_fd, buffer + buffer_len, sizeof(buffer) - buffer_len);
        if (bytes_read > 0) {
            buffer_len += bytes_read;

            // Find magic word
            int magic_word_index = find_magic_word(buffer, buffer_len);
            if (magic_word_index != -1) {
                // Magic word found, process TLV
                int tlv_len = buffer_len - magic_word_index - MAGIC_WORD_SIZE;
                if (tlv_len >= 4) {
                    unsigned short tlv_type = (buffer[magic_word_index + MAGIC_WORD_SIZE] << 8) | buffer[magic_word_index + MAGIC_WORD_SIZE + 1];
                    unsigned short tlv_length = (buffer[magic_word_index + MAGIC_WORD_SIZE + 3] << 8) | buffer[magic_word_index + MAGIC_WORD_SIZE + 2];

                    if (tlv_len >= tlv_length) {
                        // Validate TLV
                        if (validate_tlv(buffer + magic_word_index + MAGIC_WORD_SIZE, tlv_length) == 0) {
                            // Extract detected objects
                            if (extract_detected_objects(buffer + magic_word_index + MAGIC_WORD_SIZE, tlv_length, objects, 10, &num_objects) == 0) {
                                // Write to CSV file
                                write_to_csv(csv_file, objects, num_objects);
                            }
                        }
                        // Remove processed data from buffer
                        memmove(buffer, buffer + magic_word_index + MAGIC_WORD_SIZE + tlv_length, buffer_len - magic_word_index - MAGIC_WORD_SIZE - tlv_length);
                        buffer_len = buffer_len - magic_word_index - MAGIC_WORD_SIZE - tlv_length;
                    } else {
                        // TLV length exceeds buffer, wait for more data
                        memmove(buffer, buffer + magic_word_index, buffer_len - magic_word_index);
                        buffer_len = buffer_len - magic_word_index;
                    }
                } else {
                    // Not enough data for TLV header, wait for more data
                    memmove(buffer, buffer + magic_word_index, buffer_len - magic_word_index);
                    buffer_len = buffer_len - magic_word_index;
                }
            } else {
                // Magic word not found, shift buffer to the left
                if (buffer_len > sizeof(magic_word)) {
                    memmove(buffer, buffer + sizeof(magic_word), buffer_len - sizeof(magic_word));
                    buffer_len = buffer_len - sizeof(magic_word);
                } else {
                    buffer_len = 0;
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            sleep(1); // Wait before retrying
        } else {
            // No data received, sleep briefly
            usleep(10000); // 10ms
        }
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

