#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC 500000 // 0.5 seconds

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNBRK; // Ignore break condition
    tty.c_oflag = 0; // Raw output
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = TIMEOUT_USEC;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select");
        return -1;
    } else if (retval == 0) {
        fprintf(stderr, "Timeout reading from UART.\n");
        return 0; // Timeout
    } else {
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return (int)bytes_read;
        }
    }
}

int parse_line(const char *line, time_t *timestamp, double *range) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line for strtok
    if (line_copy == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok(line_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing timestamp\n");
        free(line_copy);
        return -1;
    }
    *timestamp = strtoul(token, NULL, 10);

    token = strtok(NULL, ",");
    if (token == NULL) {
        fprintf(stderr, "Error parsing range\n");
        free(line_copy);
        return -1;
    }
    *range = strtod(token, NULL);

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error parsing newline\n");
        free(line_copy);
        return -1;
    }

    free(line_copy);
    return 0;
}

int log_data(time_t timestamp, double range) {
    struct tm *timeinfo;
    char buffer[80];

    timeinfo = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", buffer, range);
    return 0;
}

int main() {
    char buffer[256];
    int bytes_read;
    time_t timestamp;
    double range;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    fprintf(stderr, "UART initialized successfully.\n");

    while (program_running) {
        bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            // Check for newline character
            if (strchr(buffer, '\n') != NULL) {
                if (parse_line(buffer, &timestamp, &range) == 0) {
                    log_data(timestamp, range);
                } else {
                    fprintf(stderr, "Error parsing line: %s\n", buffer);
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting.\n");
            break;
        }
    }

    if (uart_fd != -1) {
        close(uart_fd);
        fprintf(stderr, "UART closed.\n");
    }

    return EXIT_SUCCESS;
}

