#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables
int uart_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
int send_emergency_stop();
void signal_handler(int signal);
int initialize_uart();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log sensor data with timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to send emergency stop message via UART
int send_emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    ssize_t bytes_written = write(uart_fd, message, strlen(message));

    if (bytes_written == -1) {
        perror("Error writing to UART");
        return -1;
    }

    return 0;
}

// Function to initialize UART
int initialize_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios options;
    tcgetattr(uart_fd, &options);
    options.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcflush(uart_fd, TCIFLUSH);
    tcsetattr(uart_fd, TCSANOW, &options);

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        log_sensor_data(left_sensor, middle_sensor, right_sensor);

        if (left_sensor == 0 && middle_sensor == 0 && right_sensor == 0) {
            if (send_emergency_stop() != 0) {
                fprintf(stderr, "Error sending emergency stop message\n");
            }
        }

        gpioDelay(100); // 10 Hz loop
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

